const countryFlag = (code) => code.split('').map((c) => String.fromCodePoint(127397 + c.charCodeAt(0))).join('');

const DTF_CACHE = new Map();
function dtf(opts) {
  const k = JSON.stringify(opts);
  let f = DTF_CACHE.get(k);
  if (!f) {
    try { f = new Intl.DateTimeFormat(undefined, opts); } catch { f = new Intl.DateTimeFormat(); }
    DTF_CACHE.set(k, f);
  }
  return f;
}
const HM_FMT = { hour: 'numeric', minute: '2-digit' };
function fmtHM(d) { try { return dtf(HM_FMT).format(d); } catch { return ''; } }
function fmtDate(d, opts) { try { return dtf(opts).format(d); } catch { return ''; } }

function formatLastSeen(iso) {
  if (!iso) return null;
  const then = new Date(iso);
  const now = new Date();
  const time = fmtHM(then);
  const isToday = then.toDateString() === now.toDateString();
  const yesterday = new Date(now); yesterday.setDate(now.getDate() - 1);
  const isYesterday = then.toDateString() === yesterday.toDateString();
  const diffMin = Math.round((now.getTime() - then.getTime()) / 60000);
  if (diffMin < 1) return 'Last seen just now';
  if (isToday) return `Last seen today at ${time}`;
  if (isYesterday) return `Last seen yesterday at ${time}`;
  const diffDay = Math.round(diffMin / 1440);
  if (diffDay < 7) return `Last seen ${diffDay} day${diffDay === 1 ? '' : 's'} ago`;
  return `Last seen ${fmtDate(then, { month: 'short', day: 'numeric' })}`;
}

function getSavedAccounts() {
  try { return JSON.parse(localStorage.getItem('zchat-accounts') || '[]'); } catch { return []; }
}
function saveAccountEntry(entry) {
  const list = getSavedAccounts().filter((a) => a.id !== entry.id);
  list.push(entry);
  try { localStorage.setItem('zchat-accounts', JSON.stringify(list)); } catch {}
}
function removeAccountEntry(id) {
  const list = getSavedAccounts().filter((a) => a.id !== id);
  try { localStorage.setItem('zchat-accounts', JSON.stringify(list)); } catch {}
}

function sanitizeAvatar(profile, myId) {
  if (!profile) return profile;
  if (profile.hide_photo && profile.id !== myId) return { ...profile, avatar: '' };
  return profile;
}
function sanitizeAvatarList(list, myId) {
  return (list || []).map((p) => sanitizeAvatar(p, myId));
}

function CountryPicker({ value, onSelect, onClose }) {
  useBackClose(true, onClose);
  const { theme } = useTheme();
  const [q, setQ] = useState('');
  const filtered = COUNTRIES.filter(([, name]) => name.toLowerCase().includes(q.toLowerCase()));
  return (
    <FullPage title="Country" subtitle="Shown on your profile" onBack={onClose} zIndex={96}>
      <label style={{ display: 'flex', alignItems: 'center', gap: 8, height: 40, padding: '0 12px', borderRadius: 12, background: theme.rowBg, color: theme.muted, margin: '8px 0 8px' }}>
        <Search size={17} />
        <input value={q} onChange={(e) => setQ(e.target.value)} placeholder="Search countries" aria-label="Search countries" autoCapitalize="none"
          style={{ flex: 1, minWidth: 0, border: 0, outline: 0, background: 'transparent', color: theme.ink, fontFamily: FONT, fontSize: 15 }} />
        {q && <X size={16} style={{ cursor: 'pointer' }} onClick={() => setQ('')} />}
      </label>
      {value && !q && (
        <div role="button" aria-label="Remove country" onClick={() => { onSelect(''); onClose(); }} style={{ display: 'flex', alignItems: 'center', gap: 12, padding: '12px 2px', cursor: 'pointer', color: theme.danger, fontSize: 15, fontWeight: 700 }}>
          <X size={18} />Remove country from my profile
        </div>
      )}
      {filtered.length === 0 && <EmptyState art="search" title="No country matches" text="Try a different spelling." />}
      {filtered.map(([code, name]) => (
        <div key={code} role="button" aria-label={name} onClick={() => { onSelect(code); onClose(); }} style={{
          display: 'flex', alignItems: 'center', gap: 14, padding: '11px 2px', cursor: 'pointer', minHeight: 50,
        }}>
          <span style={{ fontSize: 26, width: 34, textAlign: 'center', lineHeight: 1 }}>{countryFlag(code)}</span>
          <span style={{ fontSize: 15, color: theme.ink, fontWeight: value === code ? 800 : 500, flex: 1 }}>{name}</span>
          {value === code && <Check size={18} color={theme.coral} strokeWidth={2.6} />}
        </div>
      ))}
    </FullPage>
  );
}


function LogoutConfirm({ onCancel, onConfirm }) {
  useBackClose(true, onCancel);
  const { theme } = useTheme();
  return (
    <div style={{
      position: 'absolute', inset: 0, background: 'rgba(10,8,6,0.5)',
      display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 60, padding: 24,
    }} className="zchat-fade">
      <div style={{
        background: theme.panelBg, borderRadius: 20, padding: '24px 22px', width: '100%', maxWidth: 280,
        textAlign: 'center', boxShadow: '0 20px 50px rgba(0,0,0,0.3)',
      }}>
        <div style={{ margin: '0 auto 12px', display: 'flex', justifyContent: 'center', color: theme.danger }}>
          <LogOut size={30} strokeWidth={1.7} />
        </div>
        <div style={{ fontWeight: 800, fontSize: 16, marginBottom: 6, color: theme.ink }}>Log out of ZChat?</div>
        <div style={{ fontSize: 12.5, marginBottom: 20, lineHeight: 1.5, color: theme.muted }}>
          You'll need to sign in again to see your messages.
        </div>
        <div style={{ display: 'flex', gap: 8 }}>
          <button onClick={onCancel} style={{
            flex: 1, padding: 11, borderRadius: 13, border: `1.5px solid ${theme.border}`,
            background: 'transparent', color: theme.ink, fontWeight: 700, fontSize: 13.5, cursor: 'pointer', fontFamily: FONT,
          }}>Cancel</button>
          <button onClick={onConfirm} style={{
            flex: 1, padding: 11, borderRadius: 13, border: 'none', background: theme.danger,
            color: 'white', fontWeight: 700, fontSize: 13.5, cursor: 'pointer', fontFamily: FONT,
          }}>Log out</button>
        </div>
      </div>
    </div>
  );
}


function DeleteAccountConfirm({ onCancel, onConfirm }) {
  useBackClose(true, onCancel);
  const { theme } = useTheme();
  const [text, setText] = useState('');
  const [busy, setBusy] = useState(false);
  const ok = text.trim().toUpperCase() === 'DELETE';
  return (
    <div style={{
      position: 'absolute', inset: 0, background: 'rgba(10,8,6,0.5)',
      display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 60, padding: 24,
    }} className="zchat-fade">
      <div style={{
        background: theme.panelBg, borderRadius: 20, padding: '24px 22px', width: '100%', maxWidth: 300,
        textAlign: 'center', boxShadow: '0 20px 50px rgba(0,0,0,0.3)',
      }}>
        <div style={{ display: 'flex', justifyContent: 'center', margin: '0 auto 12px', color: theme.danger }}>
          <Trash2 size={28} strokeWidth={1.6} />
        </div>
        <div style={{ fontWeight: 800, fontSize: 16, marginBottom: 6, color: theme.ink }}>Delete your account?</div>
        <div style={{ fontSize: 12.5, marginBottom: 16, lineHeight: 1.5, color: theme.muted }}>
          Your profile disappears everywhere, no one can message you, and this can't be undone. Type DELETE to confirm.
        </div>
        <input value={text} onChange={(e) => setText(e.target.value)} placeholder="DELETE"
          style={{ ...inputStyle(theme), textAlign: 'center', marginBottom: 14, fontWeight: 700 }} />
        <div style={{ display: 'flex', gap: 8 }}>
          <button onClick={onCancel} style={{
            flex: 1, padding: 11, borderRadius: 13, border: `1.5px solid ${theme.border}`,
            background: 'transparent', color: theme.ink, fontWeight: 700, fontSize: 13.5, cursor: 'pointer', fontFamily: FONT,
          }}>Cancel</button>
          <button onClick={async () => { setBusy(true); const done = await onConfirm(); if (done === false) setBusy(false); }} disabled={!ok || busy} style={{
            flex: 1, padding: 11, borderRadius: 13, border: 'none', background: theme.danger, opacity: (!ok || busy) ? 0.5 : 1,
            color: 'white', fontWeight: 700, fontSize: 13.5, cursor: (!ok || busy) ? 'default' : 'pointer', fontFamily: FONT,
          }}>{busy ? <Spinner size={13} /> : 'Delete'}</button>
        </div>
      </div>
    </div>
  );
}

function igPalette(theme) {
  return theme.dark
    ? { bg: theme.bgGradient, fg: theme.ink, dim: theme.muted, faint: 'rgba(242,242,244,0.4)', line: theme.border, field: 'rgba(255,255,255,0.07)', track: 'rgba(255,255,255,0.22)', knob: theme.bgGradient }
    : { bg: theme.bgGradient, fg: theme.ink, dim: theme.muted, faint: 'rgba(17,17,19,0.36)', line: theme.border, field: 'rgba(0,0,0,0.05)', track: 'rgba(0,0,0,0.18)', knob: '#ffffff' };
}

function IgRow({ icon, label, sub, onClick, danger, right, value, bold, inset = true }) {
  const { theme } = useTheme();
  const c = igPalette(theme);
  const showChevron = !right && !danger && !!onClick;
  return (
    <div role={onClick ? 'button' : undefined} aria-label={onClick && typeof label === 'string' ? label : undefined} onClick={onClick} className={onClick ? 'zchat-row-press' : undefined} style={{
      display: 'flex', alignItems: 'center', gap: 16, minHeight: sub ? 60 : 52, padding: inset ? '6px 16px' : '6px 0', boxSizing: 'border-box',
      cursor: onClick ? 'pointer' : 'default', color: c.fg, WebkitTapHighlightColor: 'transparent',
    }}>
      {icon && (
        <span style={{ flex: 'none', width: 24, height: 24, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
          {React.isValidElement(icon) ? React.cloneElement(icon, { size: 22, strokeWidth: 1.6 }) : icon}
        </span>
      )}
      <span style={{ flex: 1, minWidth: 0 }}>
        <span style={{ display: 'block', fontSize: 15, lineHeight: '20px', fontWeight: bold || danger ? 700 : 500 }}>{label}</span>
        {sub && <span style={{ display: '-webkit-box', WebkitLineClamp: 2, WebkitBoxOrient: 'vertical', overflow: 'hidden', fontSize: 12.5, lineHeight: '17px', color: c.dim, marginTop: 1 }}>{sub}</span>}
      </span>
      {value != null && value !== '' && <span style={{ flex: 'none', fontSize: 14, color: c.dim }}>{value}</span>}
      {right}
      {showChevron && <ChevronRight size={18} color={c.faint} style={{ flex: 'none' }} />}
    </div>
  );
}

function IgToggle({ on, onClick }) {
  const { theme } = useTheme();
  const c = igPalette(theme);
  return (
    <div role="switch" aria-checked={!!on} onClick={(e) => { hapticTap(); playUiSound('toggle'); if (onClick) onClick(e); }} style={{
      flex: 'none', width: 46, height: 28, borderRadius: 14, position: 'relative', cursor: 'pointer',
      background: on ? c.fg : c.track, transition: 'background 0.2s',
    }}>
      <div style={{
        position: 'absolute', top: 2, left: 2, width: 24, height: 24, borderRadius: '50%',
        background: on ? c.knob : '#ffffff', transform: on ? 'translateX(18px)' : 'none',
        transition: 'transform 0.2s, background 0.2s', boxShadow: '0 1px 2px rgba(0,0,0,0.3)',
      }} />
    </div>
  );
}

function UnderTabs({ tabs, value, onChange, style }) {
  const { theme } = useTheme();
  return (
    <div style={{ display: 'flex', borderBottom: `1px solid ${theme.border}`, ...(style || {}) }}>
      {tabs.map(([k, label, aria]) => {
        const on = value === k;
        return (
          <div key={k} role="button" aria-label={aria || label} aria-pressed={on} onClick={() => { if (!on) onChange(k); }} style={{
            flex: 1, minWidth: 0, textAlign: 'center', padding: '11px 4px 9px', marginBottom: -1, fontSize: 14, fontWeight: on ? 700 : 600, cursor: 'pointer', whiteSpace: 'nowrap',
            color: on ? theme.ink : theme.muted, borderBottom: `2px solid ${on ? theme.ink : 'transparent'}`, transition: 'color 0.15s ease, border-color 0.15s ease',
          }}>{label}</div>
        );
      })}
    </div>
  );
}

function IgHeading({ children }) {
  const { theme } = useTheme();
  const c = igPalette(theme);
  return <div style={{ padding: '22px 16px 6px', fontSize: 13, fontWeight: 600, color: c.dim }}>{children}</div>;
}

function IgTopBar({ title, subtitle, onBack, sticky, bleed = 0, right, line }) {
  const { theme } = useTheme();
  const c = igPalette(theme);
  const rightRef = useRef(null);
  const [rightW, setRightW] = useState(0);
  useLayoutEffect(() => {
    const el = rightRef.current;
    const w = el ? el.offsetWidth : 0;
    setRightW((prev) => (Math.abs(prev - w) < 2 ? prev : w));
  });
  const wideRight = rightW > 56;
  return (
    <div style={{
      position: sticky ? 'sticky' : 'relative', top: 0, zIndex: 4, background: c.bg, flexShrink: 0,
      margin: bleed ? `0 -${bleed}px` : 0, paddingTop: 'env(safe-area-inset-top)',
      borderBottom: line ? `1px solid ${c.line}` : 'none',
    }}>
      <div style={{ position: 'relative', display: 'flex', alignItems: 'center', height: 52, padding: '0 8px' }}>
        <div role="button" aria-label="Back" className="zchat-press" onClick={() => runWithTransition(() => { if (onBack) onBack(); }, 'pop')} style={{ width: 44, height: 44, display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer', color: c.fg, flexShrink: 0 }}>
          <ArrowLeft size={24} strokeWidth={2} />
        </div>
        <div style={{ position: 'absolute', left: wideRight ? 54 : 60, right: wideRight ? rightW + 14 : 60, textAlign: wideRight ? 'left' : 'center', pointerEvents: 'none' }}>
          <div style={{ fontSize: 16, fontWeight: 700, color: c.fg, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis', lineHeight: '20px' }}>{title}</div>
          {subtitle && <div style={{ fontSize: 12, fontWeight: 600, color: c.dim, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis', lineHeight: '15px' }}>{subtitle}</div>}
        </div>
        {right && <div ref={rightRef} style={{ marginLeft: 'auto', display: 'flex', alignItems: 'center', gap: 2, flexShrink: 0, position: 'relative', zIndex: 1 }}>{right}</div>}
      </div>
    </div>
  );
}

function WideDim({ onClose, z }) {
  return <div className="zchat-wide-dim" aria-hidden="true" onClick={onClose} style={{ display: 'none', position: 'fixed', inset: 0, zIndex: z, background: 'rgba(5,8,16,0.55)' }} />;
}

function FullPage({ title, subtitle, onBack, right, zIndex = 60, children, pad = true, portal = true, footer, bodyStyle, scrollRef, covered = false, scrollProps }) {
  const { theme } = useTheme();
  const c = igPalette(theme);
  const edgeBack = useEdgeSwipeBack(true);
  const body = (
    <>
    <WideDim onClose={onBack} z={zIndex} />
    <div {...edgeBack} className="zchat-panel-open zchat-wide-page" style={{ position: 'fixed', left: 0, right: 0, top: 'var(--zvp-top, 0px)', height: 'var(--zvp-h, 100%)', zIndex, background: c.bg, color: c.fg, fontFamily: FONT, display: covered ? 'none' : 'flex', flexDirection: 'column', overflow: 'hidden' }}>
      <IgTopBar title={title} subtitle={subtitle} onBack={onBack} right={right} />
      <div ref={scrollRef} {...(scrollProps || {})} style={{ flex: 1, minHeight: 0, overflowY: 'auto', WebkitOverflowScrolling: 'touch', overscrollBehavior: 'contain', padding: pad ? '4px 16px' : 0, paddingBottom: footer ? 16 : 'calc(28px + env(safe-area-inset-bottom))', ...(bodyStyle || {}) }}>{children}</div>
      {footer && <div style={{ flexShrink: 0, padding: '10px 16px', paddingBottom: 'calc(12px + env(safe-area-inset-bottom))', background: c.bg, borderTop: `1px solid ${c.line}` }}>{footer}</div>}
    </div>
    </>
  );
  return portal ? <Portal>{body}</Portal> : body;
}

function artStarPath(cx, cy, R, r) {
  let d = '';
  for (let i = 0; i < 10; i++) {
    const a = -Math.PI / 2 + (i * Math.PI) / 5;
    const rr = i % 2 ? r : R;
    d += `${i ? 'L' : 'M'}${(cx + rr * Math.cos(a)).toFixed(1)} ${(cy + rr * Math.sin(a)).toFixed(1)} `;
  }
  return `${d}Z`;
}

function SettingsLayer({ onBack, children, z = 2 }) {
  const { theme } = useTheme();
  const swipe = useEdgeSwipeBack(true, onBack);
  return (
    <div {...swipe} className="zchat-panel-open" style={{ position: 'absolute', inset: 0, zIndex: z, background: igPalette(theme).bg, overflowY: 'auto', overscrollBehavior: 'contain', WebkitOverflowScrolling: 'touch' }}>
      <div style={{ padding: '0 16px calc(24px + env(safe-area-inset-bottom))' }}>{children}</div>
    </div>
  );
}

function PageArt({ text, style }) {
  const { theme } = useTheme();
  if (!text) return null;
  return <div style={{ fontSize: 13.5, lineHeight: 1.5, color: theme.muted, padding: '2px 4px 12px', ...(style || {}) }}>{text}</div>;
}

const ART_INK = '#2B2540';
const ART_C = {
  fur: '#9AA0B4', furDark: '#70778F', white: '#FCF9F3', ear: '#F6AAC0', nose: '#E8788F', blush: '#FF9DB6',
  yellow: '#FFD24D', yellowDeep: '#F2B632', coral: '#FF7D6B', coralDeep: '#E8604F', violet: '#8C6CFF', lilac: '#D7CCFF',
  mint: '#46CFA0', mintLight: '#C4F1DF', blue: '#5B8CFF', sky: '#CFE0FF', pink: '#FF96B8', cream: '#FFF3DC',
  card: '#FFFFFF', steel: '#D9DCE8', cardboard: '#E7B47C', cardboardDeep: '#C88E57', night: '#2F3470',
};
const ART_BG = {
  lilac: ['#ECE6FF', '#262142'], mint: ['#DCF4E9', '#13342C'], peach: ['#FFE6D9', '#3A241D'], sky: ['#DFEAFF', '#172447'],
  butter: ['#FFF1C7', '#332A12'], pink: ['#FFE1EB', '#381C29'], night: ['#30356F', '#1C1F45'],
};
const ak = { stroke: ART_INK, strokeWidth: 3, strokeLinecap: 'round', strokeLinejoin: 'round' };
const ArtCtx = createContext(false);
function useArtLine() { return useContext(ArtCtx) ? '#E9E5FF' : ART_INK; }
function useArtBody() { return useContext(ArtCtx) ? '#514A7C' : ART_INK; }

function artTube(d, color, w = 6) {
  return (
    <>
      <path d={d} fill="none" stroke={ART_INK} strokeWidth={w + 5.5} strokeLinecap="round" strokeLinejoin="round" />
      <path d={d} fill="none" stroke={color} strokeWidth={w} strokeLinecap="round" strokeLinejoin="round" />
    </>
  );
}

function ArtCatFace({ eyes = 'happy', look = [0, 0] }) {
  const [lx, ly] = look;
  return (
    <>
      <path d="M44 25 L45.4 31 M50 24 L50 31 M56 25 L54.6 31" stroke={ART_C.furDark} strokeWidth="2.6" strokeLinecap="round" fill="none" />
      <ellipse cx="50" cy="51.5" rx="12.5" ry="8.8" fill={ART_C.white} />
      {eyes === 'happy' && <path d="M35 43 Q39.5 38.5 44 43 M56 43 Q60.5 38.5 65 43" fill="none" stroke={ART_INK} strokeWidth="2.8" strokeLinecap="round" />}
      {eyes === 'sleep' && <path d="M35 41.5 Q39.5 45.5 44 41.5 M56 41.5 Q60.5 45.5 65 41.5" fill="none" stroke={ART_INK} strokeWidth="2.8" strokeLinecap="round" />}
      {(eyes === 'open' || eyes === 'wide') && (
        <>
          <ellipse cx={39.5 + lx} cy={42 + ly} rx={eyes === 'wide' ? 4.6 : 3.7} ry={eyes === 'wide' ? 5.4 : 4.5} fill={ART_INK} />
          <ellipse cx={60.5 + lx} cy={42 + ly} rx={eyes === 'wide' ? 4.6 : 3.7} ry={eyes === 'wide' ? 5.4 : 4.5} fill={ART_INK} />
          <circle cx={41 + lx} cy={40.2 + ly} r="1.5" fill="#FFFFFF" />
          <circle cx={62 + lx} cy={40.2 + ly} r="1.5" fill="#FFFFFF" />
        </>
      )}
      {eyes === 'wink' && (
        <>
          <ellipse cx={39.5 + lx} cy={42 + ly} rx="3.7" ry="4.5" fill={ART_INK} />
          <circle cx={41 + lx} cy={40.2 + ly} r="1.5" fill="#FFFFFF" />
          <path d="M56 43 Q60.5 38.5 65 43" fill="none" stroke={ART_INK} strokeWidth="2.8" strokeLinecap="round" />
        </>
      )}
      <path d="M47 48.4 H53 L50 51.6 Z" fill={ART_C.nose} stroke={ART_C.nose} strokeWidth="1.4" strokeLinejoin="round" />
      <path d={eyes === 'wide' ? 'M46.5 55 Q50 59 53.5 55 Z' : 'M50 51.6 Q50 55 46.6 55.4 M50 51.6 Q50 55 53.4 55.4'} fill={eyes === 'wide' ? ART_INK : 'none'} stroke={ART_INK} strokeWidth="1.9" strokeLinecap="round" strokeLinejoin="round" />
      <ellipse cx="30.5" cy="51" rx="4.2" ry="2.6" fill={ART_C.blush} opacity="0.55" />
      <ellipse cx="69.5" cy="51" rx="4.2" ry="2.6" fill={ART_C.blush} opacity="0.55" />
      <path d="M29 50 L16 48 M29 53.5 L16 55.5 M71 50 L84 48 M71 53.5 L84 55.5" stroke={ART_INK} strokeWidth="1.4" strokeLinecap="round" opacity="0.5" />
    </>
  );
}

function ArtCatHead({ eyes, look }) {
  return (
    <>
      <path d="M29 36 L25 12 C24.6 8.5 27 7.6 29.5 9.6 L45 23" fill={ART_C.fur} {...ak} />
      <path d="M71 36 L75 12 C75.4 8.5 73 7.6 70.5 9.6 L55 23" fill={ART_C.fur} {...ak} />
      <path d="M30.5 28 L29 15.5 L39 23.2 Z" fill={ART_C.ear} />
      <path d="M69.5 28 L71 15.5 L61 23.2 Z" fill={ART_C.ear} />
      <path d="M22 46 C21 31 33 21 50 21 C67 21 79 31 78 46 C77 57 66 64 50 64 C34 64 23 57 22 46 Z" fill={ART_C.fur} {...ak} />
      <ArtCatFace eyes={eyes} look={look} />
    </>
  );
}

function ArtCat({ x, y, s = 1, eyes = 'happy', look, flip = false, wave = false, tail = true, hold = null }) {
  const t = flip ? `translate(${x + 50 * s} ${y - 100 * s}) scale(${-s} ${s})` : `translate(${x - 50 * s} ${y - 100 * s}) scale(${s})`;
  return (
    <g transform={t}>
      {tail && artTube('M68 92 C86 96 96 84 90 71 C88 66 92 61 97 64', ART_C.fur, 6)}
      <path d="M32 57 C25 69 23 84 28 98 C28.6 99.4 30 100 31.6 100 H68.4 C70 100 71.4 99.4 72 98 C77 84 75 69 68 57 Z" fill={ART_C.fur} {...ak} />
      <path d="M43 62 C40 73 41 85 44 96.5 H56 C59 85 60 73 57 62 Z" fill={ART_C.white} />
      <ellipse cx="41" cy="99" rx="8" ry="4.6" fill={ART_C.white} {...ak} />
      {!wave && !hold && <ellipse cx="59" cy="99" rx="8" ry="4.6" fill={ART_C.white} {...ak} />}
      {(wave || hold) && <ellipse cx="59" cy="99" rx="8" ry="4.6" fill={ART_C.white} {...ak} />}
      <ArtCatHead eyes={eyes} look={look || [0, 0]} />
      {wave && (
        <>
          {artTube('M67 70 C77 64 82 55 81 45', ART_C.fur, 7)}
          <ellipse cx="81" cy="42" rx="7" ry="6.4" fill={ART_C.white} {...ak} />
        </>
      )}
      {hold && (
        <>
          {artTube('M64 72 C70 74 76 74 82 71', ART_C.fur, 7)}
          <ellipse cx="84" cy="70" rx="6.6" ry="6" fill={ART_C.white} {...ak} />
        </>
      )}
    </g>
  );
}

function ArtCatLoaf({ x, y, s = 1, flip = false }) {
  const t = flip ? `translate(${x + 60 * s} ${y - 72 * s}) scale(${-s} ${s})` : `translate(${x - 60 * s} ${y - 72 * s}) scale(${s})`;
  return (
    <g transform={t}>
      {artTube('M100 64 C116 66 116 76 98 74 L66 73', ART_C.fur, 7)}
      <path d="M20 66 C16 44 36 30 66 30 C96 30 114 44 110 64 C109 69 105 72 99 72 H28 C23 72 20.6 70 20 66 Z" fill={ART_C.fur} {...ak} />
      <path d="M66 33 L65 40 M77 34 L74.5 40.5 M87 37 L83 42.5 M56 34 L57 40.5" stroke={ART_C.furDark} strokeWidth="2.8" strokeLinecap="round" fill="none" />
      <g transform="translate(-10 12) scale(0.9)">
        <ArtCatHead eyes="sleep" look={[0, 0]} />
      </g>
      <ellipse cx="46" cy="71" rx="9" ry="4.4" fill={ART_C.white} {...ak} />
      <ellipse cx="62" cy="71.5" rx="8" ry="4" fill={ART_C.white} {...ak} />
    </g>
  );
}

function ArtZzz({ x, y, s = 1, color }) {
  const line = useArtLine();
  return (
    <g transform={`translate(${x} ${y}) scale(${s})`} fill="none" stroke={color || line} strokeWidth="2.6" strokeLinecap="round" strokeLinejoin="round">
      <path d="M0 0 H9 L0 10 H9" />
      <path d="M14 -12 H21 L14 -4 H21" opacity="0.8" />
      <path d="M26 -22 H31 L26 -16.5 H31" opacity="0.6" />
    </g>
  );
}

function ArtSpark({ x, y, r = 6, color = ART_C.yellow, stroke = true }) {
  const d = `M${x} ${y - r} Q${x} ${y} ${x + r} ${y} Q${x} ${y} ${x} ${y + r} Q${x} ${y} ${x - r} ${y} Q${x} ${y} ${x} ${y - r} Z`;
  return <path d={d} fill={color} stroke={stroke ? ART_INK : 'none'} strokeWidth="2" strokeLinejoin="round" />;
}

function ArtDot({ x, y, r = 3, color, o = 0.25 }) {
  const line = useArtLine();
  return <circle cx={x} cy={y} r={r} fill={color || line} opacity={o} />;
}

function ArtFloor({ y = 152, color }) {
  const dark = useContext(ArtCtx);
  return <path d={`M-10 ${y} Q80 ${y - 7} 160 ${y} T330 ${y} V190 H-10 Z`} fill={color || (dark ? 'rgba(255,255,255,0.05)' : 'rgba(43,37,64,0.07)')} />;
}

function ArtPhone({ x, y, w = 50, h = 88, screen = ART_C.cream, children }) {
  const body = useArtBody();
  return (
    <g>
      <rect x={x} y={y} width={w} height={h} rx={10} fill={body} {...ak} />
      <rect x={x + 4.5} y={y + 4.5} width={w - 9} height={h - 9} rx={6.5} fill={screen} />
      <rect x={x + w / 2 - 7} y={y + 7} width={14} height={3.4} rx={1.7} fill={ART_INK} opacity="0.9" />
      {children}
    </g>
  );
}

function ArtClock({ x, y, s = 1 }) {
  const line = useArtLine();
  return (
    <g transform={`translate(${x} ${y}) scale(${s})`}>
      {artTube('M22 78 L15 88', ART_C.coralDeep, 4)}
      {artTube('M58 78 L65 88', ART_C.coralDeep, 4)}
      <path d="M6 22 C4 12 12 4 22 6 Z" fill={ART_C.coral} {...ak} />
      <path d="M74 22 C76 12 68 4 58 6 Z" fill={ART_C.coral} {...ak} />
      <circle cx="40" cy="50" r="34" fill={ART_C.coral} {...ak} />
      <circle cx="40" cy="50" r="25" fill={ART_C.card} {...ak} />
      <path d="M40 50 V34 M40 50 L50 56" stroke={ART_INK} strokeWidth="3.4" strokeLinecap="round" />
      <circle cx="40" cy="50" r="3" fill={ART_INK} />
      <path d="M40 28 V31 M62 50 H59 M40 72 V69 M18 50 H21" stroke={ART_INK} strokeWidth="2.4" strokeLinecap="round" />
      <path d="M-4 30 L-12 26 M-6 44 H-14 M84 30 L92 26 M86 44 H94" stroke={line} strokeWidth="3" strokeLinecap="round" />
    </g>
  );
}

function ArtBubble({ x, y, w = 90, h = 40, fill = ART_C.card, tail = 'left', lines = 2, lineColor = 'rgba(43,37,64,0.22)' }) {
  const r = Math.min(16, h / 2.4);
  const bottom = tail === 'left'
    ? `H${x + 30} L${x + 8} ${y + h + 12} L${x + 16} ${y + h}`
    : `H${x + w - 16} L${x + w - 8} ${y + h + 12} L${x + w - 30} ${y + h}`;
  const d = `M${x + r} ${y} H${x + w - r} Q${x + w} ${y} ${x + w} ${y + r} V${y + h - r} Q${x + w} ${y + h} ${x + w - r} ${y + h} ${bottom} H${x + r} Q${x} ${y + h} ${x} ${y + h - r} V${y + r} Q${x} ${y} ${x + r} ${y} Z`;
  const bars = [];
  for (let i = 0; i < lines; i++) {
    const bw = i === lines - 1 && lines > 1 ? (w - 28) * 0.6 : w - 28;
    bars.push(<rect key={i} x={x + 14} y={y + (lines === 1 ? h / 2 - 3 : 12 + i * 11)} width={bw} height="6" rx="3" fill={lineColor} />);
  }
  return (
    <g>
      <path d={d} fill={fill} {...ak} />
      {bars}
    </g>
  );
}

