function getFavoriteStickerKeys() {
  try {
    const raw = localStorage.getItem(`zchat-fav-stickers-${favoriteSync.userId || 'local'}`) ?? localStorage.getItem('zchat-fav-stickers') ?? '[]';
    return new Set(JSON.parse(raw));
  } catch { return new Set(); }
}
function toggleFavoriteSticker(key) {
  const cur = getFavoriteStickerKeys();
  const adding = !cur.has(key);
  let next = cur;
  if (adding) next = new Set([key, ...cur]); else cur.delete(key);
  writeFavoriteKeys(next);
  if (favoriteSync.userId) {
    if (adding) supabase.from('sticker_favorites').upsert({ user_id: favoriteSync.userId, sticker_key: key }, { onConflict: 'user_id,sticker_key' }).then(() => {});
    else supabase.from('sticker_favorites').delete().eq('user_id', favoriteSync.userId).eq('sticker_key', key).then(() => {});
  }
  return next;
}

function orderStickersForPick() {
  const uid = favoriteSync.userId;
  const byKey = new Map(STICKERS.map((x) => [x.key, x]));
  const recent = readRecentStickers(uid).map((r) => byKey.get(r.key)).filter(Boolean);
  const favs = [...getFavoriteStickerKeys()].map((k) => byKey.get(k)).filter(Boolean);
  const seen = new Set();
  const out = [];
  [...recent, ...favs, ...STICKERS].forEach((x) => { if (!seen.has(x.key)) { seen.add(x.key); out.push(x); } });
  return out;
}

function readRecentStickers(uid) {
  try { return JSON.parse(localStorage.getItem(`zchat-recent-stickers-${uid || 'local'}`) || '[]'); } catch { return []; }
}
function pushRecentSticker(uid, sticker) {
  if (!sticker || !sticker.file) return;
  const item = { key: sticker.key, file: sticker.file, label: sticker.label || 'Sticker' };
  const next = [item, ...readRecentStickers(uid).filter((r) => r.key !== item.key)].slice(0, 30);
  try { localStorage.setItem(`zchat-recent-stickers-${uid || 'local'}`, JSON.stringify(next)); } catch {}
  try { window.dispatchEvent(new CustomEvent('zchat-recents')); } catch {}
}
function readMyStickersLocal(uid) {
  try { return JSON.parse(localStorage.getItem(`zchat-my-stickers-${uid || 'local'}`) || '[]'); } catch { return []; }
}
function writeMyStickersLocal(uid, list) {
  try { localStorage.setItem(`zchat-my-stickers-${uid || 'local'}`, JSON.stringify(list.slice(0, 200))); } catch {}
}
async function loadMyStickers(uid) {
  let list = readMyStickersLocal(uid);
  try {
    const { data, error } = await supabase.from('user_stickers').select('id, url, created_at').eq('user_id', uid).order('created_at', { ascending: false }).limit(200);
    if (!error && data) {
      const remoteUrls = new Set(data.map((r) => r.url));
      const localOnly = list.filter((x) => String(x.id).startsWith('local-') && !remoteUrls.has(x.url));
      list = [...localOnly, ...data.map((r) => ({ id: r.id, url: r.url }))];
      writeMyStickersLocal(uid, list);
    }
  } catch {}
  return list;
}

function makeStickerBlob(blob) {
  return new Promise((resolve, reject) => {
    const url = URL.createObjectURL(blob);
    const img = new Image();
    img.onload = () => {
      try {
        const S = 512, B = 16, R = 120, M = 4;
        const canvas = document.createElement('canvas');
        canvas.width = S; canvas.height = S;
        const ctx = canvas.getContext('2d');
        const rr = (x, y, w, h, r) => { ctx.beginPath(); ctx.moveTo(x + r, y); ctx.arcTo(x + w, y, x + w, y + h, r); ctx.arcTo(x + w, y + h, x, y + h, r); ctx.arcTo(x, y + h, x, y, r); ctx.arcTo(x, y, x + w, y, r); ctx.closePath(); };
        ctx.save();
        ctx.shadowColor = 'rgba(0,0,0,0.28)'; ctx.shadowBlur = 8; ctx.fillStyle = '#ffffff';
        rr(M, M, S - 2 * M, S - 2 * M, R); ctx.fill();
        ctx.restore();
        ctx.save();
        rr(M + B, M + B, S - 2 * (M + B), S - 2 * (M + B), R - B); ctx.clip();
        const side = Math.min(img.naturalWidth, img.naturalHeight);
        ctx.drawImage(img, (img.naturalWidth - side) / 2, (img.naturalHeight - side) / 2, side, side, M + B, M + B, S - 2 * (M + B), S - 2 * (M + B));
        ctx.restore();
        canvas.toBlob((out) => { URL.revokeObjectURL(url); if (out) resolve(out); else reject(new Error('sticker')); }, 'image/png');
      } catch (e) { URL.revokeObjectURL(url); reject(e); }
    };
    img.onerror = () => { URL.revokeObjectURL(url); reject(new Error('sticker')); };
    img.src = url;
  });
}

function StickerCreator({ file, userId, onCancel, onSaved }) {
  const { theme } = useTheme();
  const [saving, setSaving] = useState(false);
  const [err, setErr] = useState('');
  const save = async (croppedBlob) => {
    if (saving) return;
    setSaving(true); setErr('');
    try {
      const out = await makeStickerBlob(croppedBlob);
      const upFile = new File([out], `sticker-${Date.now()}.png`, { type: 'image/png' });
      const { url, error } = await uploadMedia(upFile, userId);
      if (error || !url) throw error || new Error('upload');
      let row = null;
      try {
        const { data, error: insertErr } = await supabase.from('user_stickers').insert({ user_id: userId, url }).select('id, url').single();
        if (!insertErr && data) row = { id: data.id, url: data.url };
      } catch {}
      onSaved(row || { id: `local-${Date.now()}`, url });
    } catch {
      setErr("Couldn't make that sticker. Try again.");
      setSaving(false);
    }
  };
  return (
    <>
      <PhotoCropEditor file={file} onCancel={onCancel} onConfirm={save} />
      {err && (
        <div style={{ position: 'fixed', left: 16, right: 16, bottom: 'calc(24px + env(safe-area-inset-bottom))', zIndex: 400, background: theme.panelBg, color: theme.danger, border: `1px solid ${theme.border}`, borderRadius: 14, padding: '12px 14px', fontSize: 13, fontWeight: 700, textAlign: 'center' }}>{err}</div>
      )}
    </>
  );
}

const TEXT_STICKER_STYLES = [['outline', 'Cut out'], ['bubble', 'Bubble'], ['pop', 'Pop'], ['neon', 'Neon'], ['retro', 'Retro']];
const TEXT_STICKER_COLORS = ['#7C5CFC', '#FF4D6D', '#FF8A00', '#FFD60A', '#22C55E', '#14B8E6', '#111114', '#FFFFFF'];
function shadeHex(hex, amt) {
  const h = String(hex || '#000000').replace('#', '');
  const n = parseInt(h.length === 3 ? h.split('').map((x) => x + x).join('') : h, 16);
  const ch = [(n >> 16) & 255, (n >> 8) & 255, n & 255].map((v) => Math.round(amt < 0 ? v * (1 + amt) : v + (255 - v) * amt));
  return `#${ch.map((v) => Math.max(0, Math.min(255, v)).toString(16).padStart(2, '0')).join('')}`;
}
function drawTextSticker(canvas, textIn, style, color) {
  const S = 512;
  canvas.width = S;
  canvas.height = S;
  const ctx = canvas.getContext('2d');
  ctx.clearRect(0, 0, S, S);
  const words = String(textIn || '').trim().split(/\s+/).filter(Boolean);
  if (!words.length) return false;
  const font = (px) => `900 ${px}px ${FONT}`;
  const maxW = S - 120;
  let size = 156;
  let lines = [];
  for (; size >= 34; size -= 6) {
    ctx.font = font(size);
    lines = [];
    let cur = '';
    let fits = true;
    for (const w of words) {
      const t = cur ? `${cur} ${w}` : w;
      if (ctx.measureText(t).width <= maxW) cur = t;
      else {
        if (cur) lines.push(cur);
        cur = w;
        if (ctx.measureText(w).width > maxW) { fits = false; break; }
      }
    }
    if (cur) lines.push(cur);
    if (fits && lines.length <= 4 && lines.length * size * 1.06 <= S - 150) break;
  }
  ctx.font = font(size);
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.lineJoin = 'round';
  ctx.miterLimit = 2;
  const lh = size * 1.06;
  const total = lines.length * lh;
  const blockW = Math.max(...lines.map((l) => ctx.measureText(l).width));
  const white = color.toUpperCase() === '#FFFFFF';
  const dark = color.toUpperCase() === '#111114';
  const tilt = style === 'pop' ? -0.07 : style === 'bubble' ? -0.04 : style === 'retro' ? -0.05 : 0;
  const rr = (x, y, w, h, r) => { ctx.beginPath(); ctx.moveTo(x + r, y); ctx.arcTo(x + w, y, x + w, y + h, r); ctx.arcTo(x + w, y + h, x, y + h, r); ctx.arcTo(x, y + h, x, y, r); ctx.arcTo(x, y, x + w, y, r); ctx.closePath(); };
  ctx.save();
  ctx.translate(S / 2, S / 2);
  ctx.rotate(tilt);
  const y0 = -total / 2 + lh / 2;
  const eachLine = (fn) => lines.forEach((l, i) => fn(l, 0, y0 + i * lh));
  if (style === 'bubble') {
    const bw = blockW + size * 0.9;
    const bh = total + size * 0.62;
    const r = Math.min(bh / 2, size * 0.55);
    ctx.save();
    ctx.shadowColor = 'rgba(0,0,0,0.28)';
    ctx.shadowBlur = 18;
    ctx.shadowOffsetY = 8;
    ctx.fillStyle = white ? '#111114' : '#FFFFFF';
    rr(-bw / 2, -bh / 2, bw, bh, r);
    ctx.fill();
    ctx.restore();
    ctx.fillStyle = white ? '#FFFFFF' : color;
    eachLine((l, x, y) => ctx.fillText(l, x, y));
  } else if (style === 'neon') {
    const bw = blockW + size * 0.8;
    const bh = total + size * 0.6;
    ctx.fillStyle = 'rgba(14,10,30,0.92)';
    rr(-bw / 2, -bh / 2, bw, bh, size * 0.4);
    ctx.fill();
    const glow = dark ? '#7C5CFC' : color;
    ctx.strokeStyle = glow;
    ctx.lineWidth = size * 0.06;
    ctx.shadowColor = glow;
    ctx.shadowBlur = size * 0.35;
    eachLine((l, x, y) => ctx.strokeText(l, x, y));
    ctx.shadowBlur = size * 0.15;
    eachLine((l, x, y) => ctx.strokeText(l, x, y));
    ctx.shadowBlur = 0;
    ctx.fillStyle = shadeHex(glow, 0.75);
    eachLine((l, x, y) => ctx.fillText(l, x, y));
  } else if (style === 'pop') {
    const depth = size * 0.09;
    ctx.fillStyle = dark ? '#7C5CFC' : '#111114';
    ctx.strokeStyle = dark ? '#7C5CFC' : '#111114';
    ctx.lineWidth = size * 0.3;
    eachLine((l, x, y) => { ctx.strokeText(l, x + depth, y + depth); ctx.fillText(l, x + depth, y + depth); });
    ctx.strokeStyle = '#FFFFFF';
    ctx.lineWidth = size * 0.22;
    eachLine((l, x, y) => ctx.strokeText(l, x, y));
    ctx.fillStyle = white ? '#FFD60A' : color;
    eachLine((l, x, y) => ctx.fillText(l, x, y));
  } else if (style === 'retro') {
    const base = white ? '#FF4D6D' : color;
    const side = shadeHex(base, -0.45);
    ctx.strokeStyle = '#FFFFFF';
    ctx.lineWidth = size * 0.2;
    const steps = Math.max(6, Math.round(size * 0.08));
    eachLine((l, x, y) => ctx.strokeText(l, x + steps, y + steps));
    ctx.fillStyle = side;
    for (let s = steps; s >= 1; s--) eachLine((l, x, y) => ctx.fillText(l, x + s, y + s));
    ctx.fillStyle = base;
    eachLine((l, x, y) => ctx.fillText(l, x, y));
    ctx.fillStyle = 'rgba(255,255,255,0.28)';
    ctx.save();
    ctx.beginPath();
    ctx.rect(-S / 2, -total / 2 - size, S, total / 2 + size * 0.55);
    ctx.clip();
    eachLine((l, x, y) => ctx.fillText(l, x, y));
    ctx.restore();
  } else {
    ctx.save();
    ctx.shadowColor = 'rgba(0,0,0,0.3)';
    ctx.shadowBlur = 16;
    ctx.shadowOffsetY = 6;
    ctx.strokeStyle = white ? '#111114' : '#FFFFFF';
    ctx.lineWidth = size * 0.46;
    eachLine((l, x, y) => ctx.strokeText(l, x, y));
    ctx.restore();
    ctx.fillStyle = color;
    eachLine((l, x, y) => ctx.fillText(l, x, y));
  }
  ctx.restore();
  return true;
}
function TextStickerMaker({ userId, onClose, onDone }) {
  useBackClose(true, onClose);
  const [text, setText] = useState('');
  const [style, setStyle] = useState('outline');
  const [color, setColor] = useState('#7C5CFC');
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState('');
  const canvasRef = useRef(null);
  useEffect(() => { if (canvasRef.current) drawTextSticker(canvasRef.current, text.trim() ? text : 'Your text', style, color); }, [text, style, color]);
  const save = async () => {
    if (!text.trim() || busy) return;
    setBusy(true);
    setErr('');
    try {
      const c = document.createElement('canvas');
      drawTextSticker(c, text, style, color);
      const blob = await new Promise((res) => c.toBlob(res, 'image/png'));
      if (!blob) throw new Error('blob');
      const { url, error } = await uploadMedia(new File([blob], `text-sticker-${Date.now()}.png`, { type: 'image/png' }), userId);
      if (error || !url) throw error || new Error('upload');
      let row = null;
      try {
        const { data, error: insertErr } = await supabase.from('user_stickers').insert({ user_id: userId, url }).select('id, url').single();
        if (!insertErr && data) row = { id: data.id, url: data.url };
      } catch {}
      onDone(row || { id: `local-${Date.now()}`, url });
    } catch {
      setErr("Couldn't make that sticker. Try again.");
      setBusy(false);
    }
  };
  const chip = (on) => ({ height: 36, padding: '0 14px', borderRadius: 18, display: 'flex', alignItems: 'center', fontSize: 13.5, fontWeight: 700, cursor: 'pointer', whiteSpace: 'nowrap', flexShrink: 0, background: on ? '#FFFFFF' : 'rgba(255,255,255,0.12)', color: on ? '#111114' : '#FFFFFF' });
  return (
    <Portal>
      <div className="zchat-fade" style={{ position: 'fixed', left: 0, right: 0, top: 'var(--zvp-top, 0px)', height: 'var(--zvp-h, 100%)', zIndex: 420, background: '#0E0C14', color: 'white', display: 'flex', flexDirection: 'column', fontFamily: FONT }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: 10, padding: 'calc(10px + env(safe-area-inset-top)) 12px 6px' }}>
          <div role="button" aria-label="Close text sticker" onClick={onClose} style={{ width: 40, height: 40, borderRadius: '50%', display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer' }}><X size={24} /></div>
          <div style={{ flex: 1, fontSize: 17, fontWeight: 800 }}>Text sticker</div>
        </div>
        <div style={{ flex: 1, minHeight: 0, display: 'flex', alignItems: 'center', justifyContent: 'center', padding: 12 }}>
          <canvas ref={canvasRef} aria-label="Sticker preview" style={{ width: 'min(68vw, 300px, 40vh)', height: 'min(68vw, 300px, 40vh)', opacity: text.trim() ? 1 : 0.45, transition: 'opacity 0.2s ease' }} />
        </div>
        <div style={{ padding: '0 14px calc(14px + env(safe-area-inset-bottom))', display: 'flex', flexDirection: 'column', gap: 12 }}>
          <input value={text} onChange={(e) => setText(e.target.value.slice(0, 40))} placeholder="Type a word or two" aria-label="Sticker text" autoFocus maxLength={40}
            style={{ height: 48, borderRadius: 24, border: 'none', outline: 'none', padding: '0 18px', background: 'rgba(255,255,255,0.12)', color: 'white', fontFamily: FONT, fontSize: 16 }} />
          <div style={{ display: 'flex', gap: 8, overflowX: 'auto', scrollbarWidth: 'none' }}>
            {TEXT_STICKER_STYLES.map(([k, label]) => <div key={k} role="button" aria-label={`Style ${label}`} aria-pressed={style === k} onClick={() => { hapticTap(); setStyle(k); }} style={chip(style === k)}>{label}</div>)}
          </div>
          <div style={{ display: 'flex', gap: 10, justifyContent: 'space-between' }}>
            {TEXT_STICKER_COLORS.map((c) => (
              <div key={c} role="button" aria-label={`Colour ${c}`} aria-pressed={color === c} onClick={() => { hapticTap(); setColor(c); }}
                style={{ width: 30, height: 30, borderRadius: '50%', background: c, cursor: 'pointer', boxSizing: 'border-box', border: color === c ? '3px solid #FFFFFF' : '2px solid rgba(255,255,255,0.3)', transform: color === c ? 'scale(1.12)' : 'none', transition: 'transform 0.15s ease' }} />
            ))}
          </div>
          {err && <div style={{ fontSize: 13, fontWeight: 700, color: '#FF8A8A', textAlign: 'center' }}>{err}</div>}
          <BigButton label={busy ? 'Making your sticker' : 'Send sticker'} disabled={!text.trim() || busy} onClick={save} style={{ height: 52, borderRadius: 16 }} />
          <div style={{ fontSize: 12, color: 'rgba(255,255,255,0.55)', textAlign: 'center' }}>It is saved to My stickers too.</div>
        </div>
      </div>
    </Portal>
  );
}

function StickerPicker({ onPick, onClose, userId, onPickGif, onSharePack }) {
  useBackClose(true, onClose);
  const { theme } = useTheme();
  const [packs, setPacks] = useState(() => readPacks(userId));
  const [packEdit, setPackEdit] = useState(null);
  useEffect(() => {
    let alive = true;
    (async () => {
      const ids = readPacks(userId).map((x) => x.id);
      const [{ data: owned }, { data: added }] = await Promise.all([
        supabase.from('sticker_packs').select('*').eq('owner_id', userId).order('created_at', { ascending: false }).limit(40),
        ids.length ? supabase.from('sticker_packs').select('*').in('id', ids) : Promise.resolve({ data: [] }),
      ]);
      if (!alive) return;
      const byId = new Map();
      [...(owned || []), ...(added || [])].forEach((r) => { if (r && r.id) byId.set(r.id, { id: r.id, name: r.name, stickers: Array.isArray(r.stickers) ? r.stickers : [], owner_id: r.owner_id }); });
      const keep = readPacks(userId).filter((x) => byId.has(x.id) || !added).map((x) => byId.get(x.id) || x);
      const next = [...(owned || []).map((r) => byId.get(r.id)), ...keep.filter((x) => !(owned || []).some((o) => o.id === x.id))];
      setPacks(next);
      writePacks(userId, next.filter((x) => x.owner_id !== userId));
    })();
    return () => { alive = false; };
  }, [userId]);
  const [favKeys, setFavKeys] = useState(() => [...getFavoriteStickerKeys()]);
  const [recents, setRecents] = useState(() => readRecentStickers(userId));
  const [mine, setMine] = useState(() => readMyStickersLocal(userId));
  const [creatorFile, setCreatorFile] = useState(null);
  const [textMaker, setTextMaker] = useState(false);
  const fileRef = useRef(null);
  useEffect(() => {
    const onFav = () => setFavKeys([...getFavoriteStickerKeys()]);
    const onRec = () => setRecents(readRecentStickers(userId));
    window.addEventListener('zchat-favorites', onFav);
    window.addEventListener('zchat-recents', onRec);
    return () => { window.removeEventListener('zchat-favorites', onFav); window.removeEventListener('zchat-recents', onRec); };
  }, [userId]);
  useEffect(() => {
    let alive = true;
    loadMyStickers(userId).then((list) => { if (alive) setMine(list); });
    return () => { alive = false; };
  }, [userId]);
  const [query, setQuery] = useState('');
  const [category, setCategory] = useState(() => (readRecentStickers(userId).length ? 'recent' : getFavoriteStickerKeys().size > 0 ? 'favorites' : 'goma'));

  const mineStickers = mine.map((x) => ({ key: `my:${x.id}`, label: 'My sticker', file: x.url, custom: true, id: x.id }));
  const byKey = new Map([...STICKERS, ...mineStickers].map((x) => [x.key, x]));

  const toggleFav = (e, key) => {
    e.stopPropagation();
    setFavKeys([...toggleFavoriteSticker(key)]);
  };
  const removeMine = async (e, st) => {
    e.stopPropagation();
    const next = mine.filter((x) => x.id !== st.id);
    setMine(next);
    writeMyStickersLocal(userId, next);
    if (!String(st.id).startsWith('local-')) await supabase.from('user_stickers').delete().eq('id', st.id).eq('user_id', userId);
  };
  const onCreated = (row) => {
    const next = [row, ...mine.filter((x) => x.id !== row.id)];
    setMine(next);
    writeMyStickersLocal(userId, next);
    setCreatorFile(null);
    setCategory('mine');
  };

  let list;
  const term = query.trim().toLowerCase();
  if (term) list = [...STICKERS, ...mineStickers].filter((x) => x.label.toLowerCase().includes(term));
  else if (category === 'recent') list = recents.map((r) => byKey.get(r.key) || { key: r.key, label: r.label, file: r.file }).filter((x) => x && x.file);
  else if (category === 'favorites') list = favKeys.map((k) => byKey.get(k)).filter(Boolean);
  else if (category === 'mine') list = mineStickers;
  else if (category === 'gif') list = [];
  else if (category.indexOf('pack:') === 0) {
    const pk = packs.find((x) => `pack:${x.id}` === category);
    list = pk ? pk.stickers.map((u, i) => ({ key: `pk:${pk.id}:${i}`, label: pk.name, file: u })) : [];
  }
  else list = STICKERS.filter((x) => x.category === category);
  const curPack = category.indexOf('pack:') === 0 ? packs.find((x) => `pack:${x.id}` === category) : null;

  const tabs = [{ key: 'recent', label: 'Recent' }, { key: 'favorites', label: 'Favorites' }, ...(onPickGif ? [{ key: 'gif', label: 'GIFs' }] : []), { key: 'mine', label: 'My stickers' }, ...packs.map((x) => ({ key: `pack:${x.id}`, label: x.name })), ...STICKER_CATEGORIES.filter((x) => x.key !== 'favorites')];
  const emptyText = category === 'recent' ? 'Stickers you send show up here' : category === 'favorites' ? 'No favorites yet, tap the star on any sticker' : 'No stickers found';

  return (
    <div style={{
      position: 'absolute', inset: 0, background: 'rgba(20,16,14,0.5)', zIndex: 93,
      display: 'flex', alignItems: 'flex-end', justifyContent: 'center', padding: 0,
    }} className="zchat-fade" onClick={onClose}>
      <div onClick={(e) => e.stopPropagation()} style={{
        background: theme.panelBg, borderRadius: '26px 26px 0 0', padding: '16px 14px 14px', width: '100%', maxWidth: 460, boxSizing: 'border-box',
        height: category === 'gif' ? '72vh' : '48vh', maxHeight: category === 'gif' ? 640 : 430, minHeight: 330, display: 'flex', flexDirection: 'column', transition: 'height 0.22s ease',
        paddingBottom: 'calc(14px + env(safe-area-inset-bottom))',
        border: 'none', borderTop: `1px solid ${theme.border}`,
        boxShadow: '0 -8px 40px rgba(0,0,0,0.18)',
      }}>
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 10, flexShrink: 0 }}>
          <div style={{ fontWeight: 800, fontSize: 15, color: theme.ink }}>Stickers</div>
          <div role="button" aria-label="Close stickers" onClick={onClose} style={{
            width: 26, height: 26, borderRadius: '50%', background: theme.rowBg,
            display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer',
          }}><X size={14} color={theme.muted} /></div>
        </div>
        {category !== 'gif' && (
        <div style={{ position: 'relative', marginBottom: 8, flexShrink: 0 }}>
          <Search size={14} color={theme.muted} style={{ position: 'absolute', left: 11, top: 10 }} />
          <input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Search stickers"
            style={{ ...inputStyle(theme), padding: '8px 12px 8px 32px', fontSize: 13 }} />
        </div>
        )}
        {!term && (
          <div style={{ display: 'flex', gap: 6, marginBottom: 8, overflowX: 'auto', flexShrink: 0, scrollbarWidth: 'none' }}>
            {tabs.map((tb) => (
              <div key={tb.key} role="button" aria-label={`Tab ${tb.label}`} onClick={() => setCategory(tb.key)} style={{
                padding: '6px 13px', borderRadius: 16, fontSize: 12, fontWeight: 700, cursor: 'pointer', whiteSpace: 'nowrap', flexShrink: 0,
                background: category === tb.key ? theme.coral : theme.rowBg, color: category === tb.key ? 'white' : theme.muted,
                display: 'flex', alignItems: 'center', gap: 4,
              }}>
                {tb.key === 'favorites' && <Star_ size={11} color={category === tb.key ? 'white' : '#FFB800'} filled />}
                {tb.key === 'recent' && <Clock size={11} />}
                {tb.key === 'mine' && <Plus size={11} />}
                {tb.key === 'gif' && <GifIcon size={12} />}
                {tb.key.indexOf('pack:') === 0 && <PackIcon size={11} />}
                {tb.label}
              </div>
            ))}
          </div>
        )}
        {category === 'gif' && !term && onPickGif && <GifGrid onPick={(g) => onPickGif(g)} />}
        {curPack && !term && (
          <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 8, flexShrink: 0 }}>
            <span style={{ flex: 1, minWidth: 0, fontSize: 12.5, color: theme.muted, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{curPack.stickers.length} stickers{curPack.owner_id === userId ? ', made by you' : ''}</span>
            {curPack.owner_id === userId && <span role="button" aria-label="Edit sticker pack" onClick={() => setPackEdit(curPack)} style={{ fontSize: 12.5, fontWeight: 800, color: theme.muted, cursor: 'pointer' }}>Edit</span>}
            {onSharePack && <span role="button" aria-label="Share sticker pack" onClick={() => onSharePack(curPack)} style={{ fontSize: 12.5, fontWeight: 800, color: theme.coral, cursor: 'pointer' }}>Share in chat</span>}
            {curPack.owner_id !== userId && <span role="button" aria-label="Remove sticker pack" onClick={() => { const next = packs.filter((x) => x.id !== curPack.id); setPacks(next); writePacks(userId, next.filter((x) => x.owner_id !== userId)); setCategory('mine'); }} style={{ fontSize: 12.5, fontWeight: 800, color: theme.danger, cursor: 'pointer' }}>Remove</span>}
          </div>
        )}
        <div data-testid="sticker-grid" style={{ overflowY: 'auto', flex: 1, minHeight: 0, display: category === 'gif' && !term ? 'none' : 'grid', gridTemplateColumns: 'repeat(5, minmax(0, 1fr))', gap: 8, alignContent: 'start' }}>
          {category === 'mine' && !term && mine.length > 0 && (
            <div role="button" aria-label="Make a sticker pack" onClick={() => setPackEdit({})} style={{
              position: 'relative', width: '100%', paddingBottom: '100%', borderRadius: 12, cursor: 'pointer',
              border: `1.5px dashed ${theme.coral}`, color: theme.coral,
            }}>
              <div style={{ position: 'absolute', inset: 0, display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', gap: 3, fontSize: 10, fontWeight: 800 }}>
                <PackIcon size={18} />Pack
              </div>
            </div>
          )}
          {category === 'mine' && !term && (
            <div role="button" aria-label="Create sticker" onClick={() => fileRef.current && fileRef.current.click()} style={{
              position: 'relative', width: '100%', paddingBottom: '100%', borderRadius: 12, cursor: 'pointer',
              border: `1.5px dashed ${theme.muted}`, color: theme.muted,
            }}>
              <div style={{ position: 'absolute', inset: 0, display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', gap: 3, fontSize: 10, fontWeight: 800 }}>
                <Plus size={20} />Create
              </div>
            </div>
          )}
          {category === 'mine' && !term && (
            <div role="button" aria-label="Make a text sticker" onClick={() => setTextMaker(true)} style={{
              position: 'relative', width: '100%', paddingBottom: '100%', borderRadius: 12, cursor: 'pointer',
              border: `1.5px dashed ${theme.muted}`, color: theme.muted,
            }}>
              <div style={{ position: 'absolute', inset: 0, display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', gap: 2, fontSize: 10, fontWeight: 800 }}>
                <span style={{ fontSize: 17, fontWeight: 900, lineHeight: 1, letterSpacing: '-0.03em' }}>Aa</span>Text
              </div>
            </div>
          )}
          {list.length === 0 && !(category === 'mine' && !term) && (
            <div style={{ gridColumn: '1 / -1', textAlign: 'center', padding: 20, fontSize: 12.5, color: theme.muted }}>{emptyText}</div>
          )}
          {list.map((st) => (
            <div key={st.key} data-sticker-key={st.key} style={{ minWidth: 0 }}>
              <div onClick={() => onPick(st)} style={{
                position: 'relative', width: '100%', paddingBottom: '100%', height: 0,
                borderRadius: 12, background: theme.rowBg, cursor: 'pointer',
                border: `1px solid ${theme.border}`,
              }}>
                <div style={{ position: 'absolute', inset: 0, display: 'flex', alignItems: 'center', justifyContent: 'center', overflow: 'hidden', borderRadius: 12 }}>
                  <img src={st.file} alt={st.label} loading="lazy" draggable={false} onContextMenu={(e) => e.preventDefault()}
                    style={{ width: '78%', height: '78%', objectFit: 'contain' }} />
                </div>
                <div role="button" aria-label="Favourite" onClick={(e) => toggleFav(e, st.key)} style={{
                  position: 'absolute', top: 3, right: 3, width: 17, height: 17, borderRadius: '50%',
                  background: 'rgba(0,0,0,0.38)', display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer',
                }}>
                  <Star_ size={10} color={favKeys.includes(st.key) ? '#FFB800' : 'white'} filled={favKeys.includes(st.key)} />
                </div>
                {st.custom && category === 'mine' && (
                  <div role="button" aria-label="Delete sticker" onClick={(e) => removeMine(e, st)} style={{
                    position: 'absolute', top: 3, left: 3, width: 17, height: 17, borderRadius: '50%',
                    background: 'rgba(0,0,0,0.38)', display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer',
                  }}><X size={10} color="white" /></div>
                )}
              </div>
            </div>
          ))}
        </div>
        <input ref={fileRef} type="file" accept="image/*" style={{ display: 'none' }} data-testid="sticker-file"
          onChange={(e) => { const f = e.target.files && e.target.files[0]; if (f) setCreatorFile(f); e.target.value = ''; }} />
      </div>
      {creatorFile && (
        <div onClick={(e) => e.stopPropagation()} style={{ display: 'contents' }}>
          <StickerCreator file={creatorFile} userId={userId} onCancel={() => setCreatorFile(null)} onSaved={onCreated} />
        </div>
      )}
      {textMaker && (
        <div onClick={(e) => e.stopPropagation()} style={{ display: 'contents' }}>
          <TextStickerMaker userId={userId} onClose={() => setTextMaker(false)} onDone={(row) => { setTextMaker(false); onCreated(row); onPick({ key: `my:${row.id}`, label: 'My sticker', file: row.url, custom: true, id: row.id }); }} />
        </div>
      )}
      {packEdit && (
        <div onClick={(e) => e.stopPropagation()} style={{ display: 'contents' }}>
          <PackEditorPage userId={userId} mine={mine} pack={packEdit.id ? packEdit : null} onClose={() => setPackEdit(null)}
            onSaved={(row) => { const pk = { id: row.id, name: row.name, stickers: Array.isArray(row.stickers) ? row.stickers : [], owner_id: row.owner_id }; setPacks((prev) => [pk, ...prev.filter((x) => x.id !== pk.id)]); setPackEdit(null); setCategory(`pack:${pk.id}`); }} />
        </div>
      )}
    </div>
  );
}

function Star_({ size = 14, color = '#FFB800', filled = false }) {
  return (
    <svg width={size} height={size} viewBox="0 0 24 24" fill={filled ? color : 'none'} stroke={color} strokeWidth="1.6" strokeLinejoin="round">
      <path d="M12 2.5l2.9 6.4 6.9.7-5.2 4.7 1.5 6.8L12 17.8l-6.1 3.3 1.5-6.8-5.2-4.7 6.9-.7z" />
    </svg>
  );
}

function FullEmojiPicker({ onPick, onClose }) {
  useBackClose(true, onClose);
  const { theme } = useTheme();
  return (
    <div style={{
      position: 'absolute', inset: 0, background: 'rgba(20,16,14,0.5)', zIndex: 92,
      display: 'flex', alignItems: 'center', justifyContent: 'center', padding: 18,
    }} className="zchat-fade" onClick={onClose}>
      <div onClick={(e) => e.stopPropagation()} style={{
        background: theme.panelBg, borderRadius: 22, padding: 18, width: '100%', maxWidth: 340, maxHeight: '60vh', display: 'flex', flexDirection: 'column',
      }}>
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 10 }}>
          <div style={{ fontWeight: 800, fontSize: 15, color: theme.ink }}>React with</div>
          <X size={18} style={{ cursor: 'pointer', color: theme.muted }} onClick={onClose} />
        </div>
        <div style={{ overflowY: 'auto', display: 'grid', gridTemplateColumns: 'repeat(6, 1fr)', gap: 6 }}>
          {EXTRA_EMOJIS.map((e, i) => (
            <div key={e + i} onClick={() => onPick(e)} style={{ fontSize: 24, cursor: 'pointer', textAlign: 'center', padding: '6px 0' }}>{e}</div>
          ))}
        </div>
      </div>
    </div>
  );
}

function WhoReactedModal({ reactions, myId, onClose, onRemoveMine }) {
  const { theme } = useTheme();
  const [profiles, setProfiles] = useState(null);

  useEffect(() => {
    (async () => {
      const ids = (reactions || []).map((r) => r.user_id);
      if (!ids.length) { setProfiles([]); return; }
      const { data } = await supabase.from('profiles').select('*').in('id', ids);
      setProfiles((data || []).map((p) => ({ ...p, emoji: reactions.find((r) => r.user_id === p.id)?.emoji })));
    })();
  }, [reactions]);

  return (
    <ListModal title="Reactions" subtitle={profiles && profiles.length ? `${profiles.length} ${profiles.length === 1 ? 'person' : 'people'}` : undefined} onClose={onClose}>
      {profiles === null ? (
        <div style={{ display: 'flex', justifyContent: 'center', padding: 30 }}><Spinner color={theme.ink} /></div>
      ) : profiles.length === 0 ? (
        <EmptyState art="love" title="No reactions yet" />
      ) : (
        profiles.map((p) => {
          const isMine = p.id === myId;
          return (
            <UserListRow key={p.id} profile={p} onClick={isMine ? () => { onRemoveMine(p.emoji); onClose(); } : undefined} rightContent={
              <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                {isMine && <span style={{ fontSize: 12, color: theme.muted, fontWeight: 600 }}>Tap to remove</span>}
                <span style={{ fontSize: 24, lineHeight: 1 }}>{p.emoji}</span>
              </div>
            } />
          );
        })
      )}
    </ListModal>
  );
}

function MailIcon({ m, size }) {
  return <MailBadgeIcon type={m.type} size={size} badgeTier={badgeTierFromTitle(m.title)} />;
}

function MailPanel({ myId, onClose, initialMailId }) {
  useBackClose(true, onClose);
  const edgeBack = useEdgeSwipeBack(true);
  const { theme } = useTheme();
  const [mails, setMails] = useState(null);
  const [selected, setSelected] = useState(null);
  const [pinnedIds, setPinnedIds] = useState(() => {
    try { return new Set(JSON.parse(localStorage.getItem(`zchat-pinned-mails-${myId}`) || '[]')); } catch { return new Set(); }
  });
  const [actionFor, setActionFor] = useState(null);
  const [confirmDeleteId, setConfirmDeleteId] = useState(null);
  const [picking, setPicking] = useState(false);
  const [picked, setPicked] = useState(() => new Set());
  const [confirmBulk, setConfirmBulk] = useState(null);
  useBackClose(!!selected, () => setSelected(null));
  useBackClose(picking, () => { setPicking(false); setPicked(new Set()); });
  useBackClose(!!actionFor, () => setActionFor(null));
  const openedInitialRef = useRef(false);
  const pressTimerRef = useRef(null);
  const longPressFiredRef = useRef(false);

  const savePinned = (next) => {
    setPinnedIds(next);
    try { localStorage.setItem(`zchat-pinned-mails-${myId}`, JSON.stringify([...next])); } catch {}
  };
  const togglePin = (id) => {
    const next = new Set(pinnedIds);
    if (next.has(id)) next.delete(id); else next.add(id);
    savePinned(next);
    setActionFor(null);
  };

  const load = async () => {
    const { data } = await supabase.from('mails').select('*').eq('recipient_id', myId).order('created_at', { ascending: false }).limit(100);
    const senderIds = [...new Set((data || []).map((m) => m.sender_id).filter(Boolean))];
    if (senderIds.length) {
      const { data: profs } = await supabase.from('profiles').select('*').in('id', senderIds);
      const byId = {};
      sanitizeAvatarList(profs, myId).forEach((p) => { byId[p.id] = p; });
      (data || []).forEach((m) => { if (m.sender_id && byId[m.sender_id]) m.sender = byId[m.sender_id]; });
    }
    setMails(data || []);
  };
  useEffect(() => { load(); }, [myId]);
  useEffect(() => {
    if (!mails || !initialMailId || openedInitialRef.current) return;
    const target = mails.find((x) => x.id === initialMailId);
    if (target) { openedInitialRef.current = true; openMail(target); }
  }, [mails, initialMailId]);

  const sortedMails = mails ? [...mails].sort((a, b) => {
    const pa = pinnedIds.has(a.id) ? 1 : 0, pb = pinnedIds.has(b.id) ? 1 : 0;
    if (pa !== pb) return pb - pa;
    return new Date(b.created_at) - new Date(a.created_at);
  }) : null;

  const openMail = async (m) => {
    if (longPressFiredRef.current) { longPressFiredRef.current = false; return; }
    setSelected(m);
    if (!m.read) {
      await supabase.from('mails').update({ read: true }).eq('id', m.id);
      setMails((prev) => prev.map((x) => (x.id === m.id ? { ...x, read: true } : x)));
    }
  };

  const startPress = (m) => {
    longPressFiredRef.current = false;
    clearTimeout(pressTimerRef.current);
    pressTimerRef.current = setTimeout(() => { longPressFiredRef.current = true; setActionFor(m); }, 420);
  };
  const cancelPress = () => clearTimeout(pressTimerRef.current);

  const deleteMail = async (id) => {
    setMails((prev) => (prev || []).filter((x) => x.id !== id));
    const next = new Set(pinnedIds); next.delete(id); savePinned(next);
    setActionFor(null);
    if (selected?.id === id) setSelected(null);
    await supabase.from('mails').delete().eq('id', id);
  };

  const timeAgo = (iso) => {
    const diff = Date.now() - new Date(iso).getTime();
    const mins = Math.round(diff / 60000);
    if (mins < 1) return 'just now';
    if (mins < 60) return `${mins}m`;
    const hrs = Math.round(mins / 60);
    if (hrs < 24) return `${hrs}h`;
    const days = Math.round(hrs / 24);
    if (days < 7) return `${days}d`;
    return fmtDate(new Date(iso), { month: 'short', day: 'numeric' });
  };

  const allIds = (mails || []).map((m) => m.id);
  const togglePick = (id) => {
    setPicked((prev) => { const next = new Set(prev); if (next.has(id)) next.delete(id); else next.add(id); return next; });
  };
  const markAllRead = async () => {
    const unread = (mails || []).filter((m) => !m.read).map((m) => m.id);
    if (!unread.length) return;
    setMails((prev) => prev.map((m) => ({ ...m, read: true })));
    playUiSound('tap');
    await supabase.from('mails').update({ read: true }).in('id', unread);
  };
  const deletePicked = async () => {
    const ids = [...picked];
    if (!ids.length) return;
    setMails((prev) => prev.filter((m) => !picked.has(m.id)));
    setPicked(new Set());
    setPicking(false);
    setConfirmBulk(null);
    playUiSound('delete');
    await supabase.from('mails').delete().in('id', ids);
  };

  return (
    <>
    <WideDim onClose={onClose} z={34} />
    <div {...edgeBack} style={{ position: 'fixed', inset: 0, background: theme.bgGradient, zIndex: 34, display: 'flex', flexDirection: 'column' }} className="zchat-panel-open zchat-wide-page">
      <IgTopBar title={selected ? 'Message' : picking ? `${picked.size} selected` : 'Mail'} onBack={() => (selected ? setSelected(null) : onClose())}
        right={selected ? (
          <div role="button" aria-label="Delete mail" onClick={() => setConfirmDeleteId(selected.id)} style={{ width: 44, height: 44, display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer', color: theme.danger }}><Trash2 size={20} /></div>
        ) : picking ? (
          <>
            <div role="button" onClick={() => setPicked(picked.size === allIds.length ? new Set() : new Set(allIds))} style={{ fontSize: 14, fontWeight: 800, color: theme.coral, cursor: 'pointer', padding: '0 8px', height: 44, display: 'flex', alignItems: 'center' }}>{picked.size === allIds.length && allIds.length ? 'None' : 'All'}</div>
            <div role="button" aria-label="Delete selected mails" onClick={() => picked.size && setConfirmBulk(picked.size)} style={{ width: 40, height: 44, display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: picked.size ? 'pointer' : 'default', color: picked.size ? theme.danger : theme.muted }}><Trash2 size={20} /></div>
            <div role="button" aria-label="Stop selecting" onClick={() => { setPicking(false); setPicked(new Set()); }} style={{ width: 40, height: 44, display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer', color: theme.ink }}><X size={20} /></div>
          </>
        ) : (
          <>
            <div role="button" aria-label="Mark all read" onClick={markAllRead} style={{ width: 40, height: 44, display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer', color: theme.ink }}><CheckCheck size={21} /></div>
            <div role="button" aria-label="Select mails" onClick={() => { setPicking(true); playUiSound('tap'); }} style={{ fontSize: 14, fontWeight: 800, color: theme.coral, cursor: 'pointer', padding: '0 10px', height: 44, display: 'flex', alignItems: 'center' }}>Select</div>
          </>
        )} />
      {selected ? (
        <div key={selected.id} className="zchat-mail-zoom" style={{ flex: 1, minHeight: 0, overflowY: 'auto', padding: '22px 20px', paddingBottom: 'calc(22px + env(safe-area-inset-bottom))' }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: 12, marginBottom: 16 }}>
            <MailIcon m={selected} size={44} />
            <div>
              <div style={{ fontWeight: 800, fontSize: 15.5, color: theme.ink }}>{selected.title}</div>
              <div style={{ display: 'flex', alignItems: 'center', gap: 4, fontSize: 11.5, color: theme.muted, fontWeight: 600 }}>{mailSenderName(selected.type)} <VerifiedTick size={12} /> <span style={{ fontWeight: 400, marginLeft: 2 }}>{new Date(selected.created_at).toLocaleString()}</span></div>
            </div>
          </div>
          <div style={{ fontSize: 14, color: theme.ink, lineHeight: 1.6, wordBreak: 'break-word', whiteSpace: 'pre-wrap' }}>{selected.body}</div>
        </div>
      ) : (
        <div style={{ flex: 1, minHeight: 0, overflowY: 'auto', padding: '6px 10px', paddingBottom: 'calc(6px + env(safe-area-inset-bottom))' }}>
          {sortedMails === null ? (
            <div style={{ display: 'flex', justifyContent: 'center', padding: 30 }}><Spinner color={theme.ink} /></div>
          ) : sortedMails.length === 0 ? (
            <EmptyState art="mail" title="No mail yet" text="Notes from the ZChat team and account notices land here." />
          ) : (
            sortedMails.map((m) => (
              <div key={m.id} onClick={() => (picking ? togglePick(m.id) : openMail(m))}
                onPointerDown={() => !picking && startPress(m)} onPointerUp={cancelPress} onPointerLeave={cancelPress} onPointerCancel={cancelPress}
                style={{
                position: 'relative', display: 'flex', alignItems: 'center', gap: 12, padding: '10px 12px', cursor: 'pointer', borderRadius: 14, marginBottom: 2,
                background: picked.has(m.id) ? `${theme.coral}1A` : pinnedIds.has(m.id) ? `${theme.coral}0F` : 'transparent',
              }}>
                {picking && (
                  <div style={{ width: 22, height: 22, borderRadius: '50%', flexShrink: 0, border: `2px solid ${picked.has(m.id) ? theme.coral : theme.border}`, background: picked.has(m.id) ? theme.coral : 'transparent', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                    {picked.has(m.id) && <Check size={13} color="white" strokeWidth={4} />}
                  </div>
                )}
                <div style={{ position: 'relative', flexShrink: 0 }}>
                  {m.sender
                    ? <div style={{ position: 'relative', width: 46, height: 46, display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0 }}>
                        <Avatar emoji={m.sender.avatar} name={m.sender.name} size={44} />
                        <div style={{ position: 'absolute', right: -4, bottom: -4, width: 20, height: 20, borderRadius: 7, background: theme.panelBg, display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 4 }}><MailIcon m={m} size={16} /></div>
                      </div>
                    : <MailIcon m={m} size={42} />}
                  {!m.read && <div style={{ position: 'absolute', top: -2, right: -2, width: 10, height: 10, borderRadius: '50%', background: theme.coral, border: `2px solid ${theme.panelBg}` }} />}
                </div>
                <div style={{ flex: 1, minWidth: 0 }}>
                  <div style={{ display: 'flex', alignItems: 'center', gap: 4 }}>
                    {pinnedIds.has(m.id) && <Pin_ size={11} />}
                    <div style={{ fontWeight: m.read ? 600 : 800, fontSize: 13.5, color: theme.ink, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis', display: 'flex', alignItems: 'center' }}>
                      {m.sender ? <><span style={{ overflow: 'hidden', textOverflow: 'ellipsis' }}>{m.sender.name}</span><VerifiedBadge tier={m.sender.verified} custom={m.sender.custom_badge} size={12} /><span style={{ color: theme.muted, fontWeight: 600, marginLeft: 6, overflow: 'hidden', textOverflow: 'ellipsis' }}>{m.title.replace(new RegExp(`^${m.sender.name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}\\s*`), '')}</span></> : m.title}
                    </div>
                  </div>
                  <div style={{ fontSize: 12, color: theme.muted, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{m.body}</div>
                </div>
                <div style={{ fontSize: 10.5, color: theme.muted, flexShrink: 0 }}>{timeAgo(m.created_at)}</div>
              </div>
            ))
          )}
        </div>
      )}
      {actionFor && (
        <div onClick={() => setActionFor(null)} style={{
          position: 'absolute', inset: 0, background: 'rgba(20,16,14,0.5)', zIndex: 2,
          display: 'flex', alignItems: 'flex-end', justifyContent: 'center',
        }} className="zchat-fade">
          <div onClick={(e) => e.stopPropagation()} style={{
            background: theme.panelBg, borderRadius: '22px 22px 0 0', padding: '10px 8px', width: '100%', maxWidth: 460, boxSizing: 'border-box',
            paddingBottom: 'calc(10px + env(safe-area-inset-bottom))',
          }}>
            <div onClick={() => togglePin(actionFor.id)} style={{
              padding: '13px 10px', fontSize: 14, fontWeight: 600, color: theme.ink, cursor: 'pointer',
              display: 'flex', alignItems: 'center', gap: 12,
            }}><Pin_ size={16} /> {pinnedIds.has(actionFor.id) ? 'Unpin' : 'Pin'}</div>
            <div onClick={() => { setConfirmDeleteId(actionFor.id); setActionFor(null); }} style={{
              padding: '13px 10px', fontSize: 14, fontWeight: 600, color: theme.danger, cursor: 'pointer',
              display: 'flex', alignItems: 'center', gap: 12,
            }}><Trash2 size={16} color={theme.danger} /> Delete</div>
          </div>
        </div>
      )}
      {confirmDeleteId && (
        <ConfirmDialog title="Delete this mail?" body="It will be removed from your mailbox. This can't be undone."
          onCancel={() => setConfirmDeleteId(null)}
          onConfirm={async () => { const id = confirmDeleteId; setConfirmDeleteId(null); await deleteMail(id); }} />
      )}
      {confirmBulk != null && (
        <ConfirmDialog
          title={`Delete ${confirmBulk} ${confirmBulk === 1 ? 'mail' : 'mails'}?`}
          body="They will be removed from your mail box."
          confirmLabel="Delete"
          danger
          onCancel={() => setConfirmBulk(null)}
          onConfirm={deletePicked} />
      )}
    </div>
    </>
  );
}

function ArchivedChatsPanel({ conversations, onClose, onOpenChat, onUnarchive }) {
  useBackClose(true, onClose);
  const edgeBack = useEdgeSwipeBack(true);
  const { theme } = useTheme();
  return (
    <>
    <WideDim onClose={onClose} z={26} />
    <div {...edgeBack} style={{
      position: 'fixed', inset: 0, background: theme.bgGradient, zIndex: 26,
      display: 'flex', flexDirection: 'column',
    }} className="zchat-panel-open zchat-wide-page">
      <IgTopBar title="Archived chats" subtitle={conversations.length ? `${conversations.length} ${conversations.length === 1 ? 'chat' : 'chats'}` : undefined} onBack={onClose} />
      <div style={{ overflowY: 'auto', flex: 1, minHeight: 0, padding: '4px 18px', paddingBottom: 'calc(4px + env(safe-area-inset-bottom))' }}>
        {conversations.length === 0 ? (
          <EmptyState art="archive" title="Nothing archived" text="Swipe a chat to the left and tap Archive to tuck it away here." />
        ) : (
          conversations.map((c) => (
            <UserListRow key={c.id} profile={c.otherProfile} onClick={() => onOpenChat(c)} rightContent={
              <button onClick={(e) => { e.stopPropagation(); onUnarchive(c.id); }} style={{
                padding: '6px 12px', borderRadius: 10, border: `1px solid ${theme.border}`, background: 'transparent',
                color: theme.ink, fontWeight: 700, fontSize: 11.5, cursor: 'pointer', fontFamily: FONT,
              }}>Unarchive</button>
            } />
          ))
        )}
      </div>
    </div>
    </>
  );
}

