function wallpaperBgStyle(key, dark) {
  if (!key) return null;
  const ct = chatThemeOf(key);
  if (ct) return chatThemeBg(ct, !!dark);
  if (String(key).indexOf('pat:') === 0 || String(key).indexOf('theme:') === 0) return null;
  let url = null;
  if (String(key).indexOf(WALL_PHOTO_PREFIX) === 0) url = wallPhotoData(key);
  else if (String(key).indexOf('url:') === 0) url = wallPhotoCache.get(key) || key.slice(4);
  else {
    const preset = WALLPAPER_PRESETS.find((p) => p.key === key);
    if (preset) url = preset.file;
  }
  if (!url) return null;
  const dim = wallDimFor(key);
  return {
    backgroundImage: dim > 0 ? `linear-gradient(rgba(0,0,0,${dim}), rgba(0,0,0,${dim})), url('${url}')` : `url('${url}')`,
    backgroundSize: 'cover',
    backgroundPosition: 'center',
    backgroundRepeat: 'no-repeat',
  };
}

function ThemeIcon({ size = 20, color = 'currentColor', strokeWidth = 1.8, style }) {
  return (
    <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke={color} strokeWidth={strokeWidth} strokeLinecap="round" strokeLinejoin="round" style={style} aria-hidden="true">
      <circle cx="12" cy="12" r="9" />
      <path d="M12 3a9 9 0 0 1 0 18Z" fill={color} stroke="none" />
    </svg>
  );
}
const THEME_TABS = [['color', 'Colors'], ['pattern', 'Patterns'], ['scene', 'Scenes'], ['photo', 'Photos']];
function ThemeTileArt({ t, dark, label, on, onPick, photoUrl }) {
  const { theme } = useTheme();
  const bg = t ? chatThemeBg(t, dark) : null;
  const sceneUrl = t && t.cat === 'scene' ? t.file : null;
  return (
    <div role="button" aria-label={`Theme ${label}`} aria-pressed={on} onClick={onPick} className="zchat-press" style={{ display: 'flex', flexDirection: 'column', gap: 6, cursor: 'pointer', minWidth: 0 }}>
      <div style={{ position: 'relative', aspectRatio: '3 / 4', borderRadius: 14, overflow: 'hidden', boxShadow: on ? `0 0 0 2.5px ${theme.coral}, 0 0 0 4.5px ${igPalette(theme).bg}` : `inset 0 0 0 1px ${theme.border}`, ...(bg && !sceneUrl ? bg : { background: dark ? '#1A1A1F' : '#F2F2F5' }) }}>
        {(sceneUrl || photoUrl) && <img src={sceneUrl || photoUrl} alt="" loading="lazy" decoding="async" draggable={false} style={{ position: 'absolute', inset: 0, width: '100%', height: '100%', objectFit: 'cover' }} />}
        {sceneUrl && dark && <div style={{ position: 'absolute', inset: 0, background: `rgba(0,0,0,${Math.max(0.28, t.dim || 0)})` }} />}
        {t && (
          <div style={{ position: 'absolute', left: 8, right: 8, bottom: 9, display: 'flex', flexDirection: 'column', gap: 4 }}>
            <div style={{ alignSelf: 'flex-start', width: '58%', height: 12, borderRadius: 7, background: chatThemeThem(t, dark) }} />
            <div style={{ alignSelf: 'flex-end', width: '50%', height: 12, borderRadius: 7, background: themeGradCss(t) }} />
          </div>
        )}
      </div>
      <span style={{ fontSize: 12, fontWeight: on ? 700 : 500, color: on ? theme.ink : theme.muted, textAlign: 'center', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{label}</span>
    </div>
  );
}
function ChatThemePage({ value, onSelect, onClose, title, avatar, group, userId, mineOnly }) {
  useBackClose(true, onClose);
  const { theme } = useTheme();
  const c = igPalette(theme);
  const isCustomWall = (k) => !!k && (String(k).indexOf(WALL_PHOTO_PREFIX) === 0 || String(k).indexOf('url:') === 0);
  const startTheme = chatThemeOf(value);
  const start = startTheme ? `theme:${startTheme.key}` : (value || null);
  const [pick, setPick] = useState(start);
  const [tab, setTab] = useState(() => (startTheme ? startTheme.cat : value ? 'photo' : 'color'));
  const [scope, setScope] = useState(mineOnly ? 'me' : 'both');
  const [dimTick, setDimTick] = useState(0);
  const [photoBusy, setPhotoBusy] = useState(false);
  const [aiOpen, setAiOpen] = useState(false);
  const [customKey, setCustomKey] = useState(() => (isCustomWall(value) ? value : null));
  const photoRef = useRef(null);
  const gridRef = useRef(null);
  const changed = (pick || null) !== (start || null) || (!group && (scope === 'me') !== !!mineOnly);
  const pickedTheme = chatThemeOf(pick);
  const isPhoto = !!pick && !pickedTheme;
  const dim = isPhoto ? wallDimFor(pick) : 0;
  void dimTick;
  const choose = (k) => { hapticTap(); playUiSound('tap'); setPick(k); };
  const pickPhoto = async (e) => {
    const f = e.target.files && e.target.files[0];
    e.target.value = '';
    if (!f) return;
    setPhotoBusy(true);
    const key = await makeWallPhoto(f, userId);
    setPhotoBusy(false);
    if (key) { hapticTap(); setPick(key); setCustomKey(key); } else appAlert('That photo could not be used. Try a different one.');
  };
  const counts = { color: 0, pattern: 0, scene: 0, photo: WALLPAPER_PRESETS.length };
  CHAT_THEMES.forEach((t) => { counts[t.cat] += 1; });
  const items = CHAT_THEMES.filter((t) => t.cat === tab);
  const changeTab = (k) => { if (k === tab) return; hapticTap(); setTab(k); if (gridRef.current) gridRef.current.scrollTop = 0; };
  const circle = (t, label, key, swatch) => {
    const on = (pick || null) === key;
    return (
      <div key={key || 'none'} role="button" aria-label={`Theme ${label}`} aria-pressed={on} onClick={() => choose(key)} className="zchat-press" style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 7, cursor: 'pointer', minWidth: 0 }}>
        <div style={{ width: 60, height: 60, borderRadius: '50%', background: swatch, boxShadow: on ? `0 0 0 2.5px ${c.bg}, 0 0 0 5px ${theme.coral}` : 'none', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
          {on && <Check size={22} color={t && t.ink !== '#FFFFFF' ? t.ink : '#FFFFFF'} strokeWidth={2.6} />}
        </div>
        <span style={{ fontSize: 12, fontWeight: on ? 700 : 500, color: on ? theme.ink : theme.muted, textAlign: 'center', maxWidth: '100%', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{label}</span>
      </div>
    );
  };
  return (
    <FullPage title="Theme" subtitle={group ? 'Everyone in the group sees it' : scope === 'me' ? 'Only you see it' : 'Both of you see it'} onBack={onClose} zIndex={96} pad={false}
      footer={(
        <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
          {!group && (
            <div role="radiogroup" aria-label="Who sees the theme" style={{ display: 'flex', height: 36, borderRadius: 10, background: theme.rowBg, padding: 3 }}>
              {[['both', 'Both of us'], ['me', 'Just me']].map(([k, l]) => (
                <div key={k} role="radio" aria-checked={scope === k} aria-label={l} onClick={() => { hapticTap(); setScope(k); }} style={{ flex: 1, display: 'flex', alignItems: 'center', justifyContent: 'center', borderRadius: 8, fontSize: 13.5, fontWeight: 600, cursor: 'pointer', background: scope === k ? c.bg : 'transparent', color: scope === k ? theme.ink : theme.muted, boxShadow: scope === k ? '0 1px 3px rgba(0,0,0,0.12)' : 'none' }}>{l}</div>
              ))}
            </div>
          )}
          <BigButton label={changed ? 'Use this theme' : 'Done'} onClick={() => { if (changed) onSelect(pick, scope); onClose(); }} />
        </div>
      )}
      bodyStyle={{ display: 'flex', flexDirection: 'column', overflow: 'hidden' }}>
      <div style={{ flexShrink: 0, padding: '6px 16px 0' }}>
        <ChatLookPreview key={`${pick}-${dimTick}`} wallpaper={pick} title={title} avatar={avatar} height={172} />
        {isPhoto && (
          <div style={{ display: 'flex', alignItems: 'center', gap: 10, paddingTop: 10 }}>
            <span style={{ fontSize: 13, fontWeight: 600, color: theme.muted, whiteSpace: 'nowrap' }}>Dim</span>
            <input type="range" min={0} max={70} step={5} value={Math.round(dim * 100)} aria-label="Dim wallpaper" onChange={(e) => { setWallDim(pick, Number(e.target.value) / 100); setDimTick((t) => t + 1); }} style={{ flex: 1, accentColor: theme.coral }} />
            <span style={{ fontSize: 13, fontWeight: 700, color: theme.ink, width: 40, textAlign: 'right' }}>{Math.round(dim * 100)}%</span>
          </div>
        )}
        <div role="tablist" aria-label="Theme kinds" style={{ display: 'flex', gap: 6, padding: '12px 0 10px', overflowX: 'auto', scrollbarWidth: 'none' }}>
          {THEME_TABS.map(([k, l]) => {
            const on = tab === k;
            return (
              <div key={k} role="tab" aria-selected={on} aria-label={`${l}, ${counts[k]}`} onClick={() => changeTab(k)} className="zchat-press" style={{ flex: '1 1 0', minWidth: 0, display: 'flex', alignItems: 'center', justifyContent: 'center', height: 34, padding: '0 8px', borderRadius: 17, cursor: 'pointer', background: on ? theme.ink : theme.rowBg, color: on ? c.bg : theme.ink, fontSize: 14, fontWeight: 600, whiteSpace: 'nowrap' }}>
                {l}
              </div>
            );
          })}
        </div>
      </div>
      <input ref={photoRef} type="file" accept="image/*" style={{ display: 'none' }} onChange={pickPhoto} />
      <div ref={gridRef} style={{ flex: 1, minHeight: 0, overflowY: 'auto', WebkitOverflowScrolling: 'touch', overscrollBehavior: 'contain', padding: '4px 16px 18px' }}>
        {tab === 'color' ? (
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, minmax(0, 1fr))', rowGap: 18, columnGap: 8, paddingTop: 6 }}>
            {circle(null, 'Default', null, theme.dark ? '#3D2F86' : '#E6DEFB')}
            {items.map((t) => circle(t, t.label, `theme:${t.key}`, themeSwatchCss(t)))}
          </div>
        ) : tab === 'photo' ? (
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, minmax(0, 1fr))', rowGap: 14, columnGap: 10, paddingTop: 6 }}>
            <div role="button" aria-label="Wallpaper your photo" onClick={() => { if (!photoBusy && photoRef.current) photoRef.current.click(); }} className="zchat-press" style={{ display: 'flex', flexDirection: 'column', gap: 6, cursor: 'pointer' }}>
              <div style={{ aspectRatio: '3 / 4', borderRadius: 14, display: 'flex', alignItems: 'center', justifyContent: 'center', color: theme.ink, boxShadow: `inset 0 0 0 1px ${theme.border}`, background: theme.rowBg }}>{photoBusy ? <Spinner color={theme.muted} /> : <ImageIcon size={24} />}</div>
              <span style={{ fontSize: 12, fontWeight: 500, color: theme.muted, textAlign: 'center' }}>Your photo</span>
            </div>
            {userId && (
              <div role="button" aria-label="Wallpaper create with AI" onClick={() => setAiOpen(true)} className="zchat-press" style={{ display: 'flex', flexDirection: 'column', gap: 6, cursor: 'pointer' }}>
                <div style={{ aspectRatio: '3 / 4', borderRadius: 14, display: 'flex', alignItems: 'center', justifyContent: 'center', color: theme.ink, boxShadow: `inset 0 0 0 1px ${theme.border}`, background: theme.rowBg }}><AiSparkIcon size={24} /></div>
                <span style={{ fontSize: 12, fontWeight: 500, color: theme.muted, textAlign: 'center' }}>Create with AI</span>
              </div>
            )}
            {customKey && <ThemeTileArt key={customKey} label="Yours" on={pick === customKey} onPick={() => choose(customKey)} photoUrl={String(customKey).indexOf(WALL_PHOTO_PREFIX) === 0 ? wallPhotoData(customKey) : (wallPhotoCache.get(customKey) || String(customKey).slice(4))} dark={theme.dark} />}
            {WALLPAPER_PRESETS.map((p) => <ThemeTileArt key={p.key} label={p.label} on={pick === p.key} onPick={() => choose(p.key)} photoUrl={p.file} dark={theme.dark} />)}
          </div>
        ) : (
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, minmax(0, 1fr))', rowGap: 14, columnGap: 10, paddingTop: 6 }}>
            {items.map((t) => <ThemeTileArt key={t.key} t={t} label={t.label} on={pick === `theme:${t.key}`} onPick={() => choose(`theme:${t.key}`)} dark={theme.dark} />)}
          </div>
        )}
      </div>
      {aiOpen && <AiStudioPage myId={userId} mode="image" startKind="wallpaper" onClose={() => setAiOpen(false)} onUseWallpaper={(key) => { hapticTap(); setPick(key); setCustomKey(key); setTab('photo'); }} />}
    </FullPage>
  );
}

const REPORT_REASONS = [
  'Spam',
  'Nudity or sexual activity',
  'Hate speech or symbols',
  'Bullying or harassment',
  'False information',
  'Scam or fraud',
  'Violence or dangerous organizations',
  'Sale of illegal or regulated goods',
  'Suicide, self harm or eating disorders',
  "I just don't like it",
  'Something else',
];


async function sendReportMail(reportedUserId, reasonLabel) {
  if (!reportedUserId) return;
  const { data: sent, error } = await supabase.rpc('send_report_warning', { p_reported: reportedUserId, p_reason: reasonLabel });
  if (!error && sent) sendPushNotification(reportedUserId, 'ZChat', 'Account warning. Open your mail to see why.', '/?mail=1');
}

function ReportReasonPicker({ reportedUserId, onCancel, onSubmit }) {
  useBackClose(true, onCancel);
  const { theme } = useTheme();
  const [submitting, setSubmitting] = useState(null);

  const choose = async (reason) => {
    if (submitting) return;
    setSubmitting(reason);
    await onSubmit(reason);
    if (reportedUserId) await sendReportMail(reportedUserId, reason);
    setSubmitting(null);
  };

  return (
    <div onClick={onCancel} style={{
      position: 'absolute', inset: 0, background: 'rgba(20,16,14,0.5)', zIndex: 91,
      display: 'flex', alignItems: 'flex-end', justifyContent: 'center',
    }} className="zchat-fade">
      <div onClick={(e) => e.stopPropagation()} style={{
        background: theme.panelBg, borderRadius: '22px 22px 0 0', padding: '20px 18px', width: '100%', maxWidth: 460, boxSizing: 'border-box',
        maxHeight: '78vh', overflowY: 'auto', WebkitOverflowScrolling: 'touch',
        paddingBottom: 'calc(20px + env(safe-area-inset-bottom))',
      }}>
        <div style={{ fontWeight: 800, fontSize: 16, color: theme.ink, marginBottom: 3 }}>Report</div>
        <div style={{ fontSize: 12, color: theme.muted, marginBottom: 14 }}>Why are you reporting this?</div>
        {REPORT_REASONS.map((r) => (
          <div key={r} onClick={() => choose(r)} style={{
            padding: '13px 2px', borderBottom: `1px solid ${theme.border}`, fontSize: 14, fontWeight: 600, color: theme.ink,
            cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'space-between',
          }}>
            {r}
            {submitting === r ? <Spinner size={14} color={theme.ink} /> : <ChevronRight size={16} color={theme.muted} />}
          </div>
        ))}
        <div onClick={onCancel} style={{ textAlign: 'center', padding: '16px 0 4px', fontWeight: 700, color: theme.muted, cursor: 'pointer' }}>Cancel</div>
      </div>
    </div>
  );
}

async function hashPin(pin) {
  const enc = new TextEncoder().encode(pin);
  const buf = await crypto.subtle.digest('SHA-256', enc);
  return Array.from(new Uint8Array(buf)).map((b) => b.toString(16).padStart(2, '0')).join('');
}

function PinPad({ value, onChange, length = 4 }) {
  const { theme } = useTheme();
  return (
    <div style={{ display: 'flex', gap: 10, justifyContent: 'center', marginBottom: 18 }}>
      {Array.from({ length }).map((_, i) => (
        <div key={i} style={{
          width: 16, height: 16, borderRadius: '50%',
          background: i < value.length ? theme.coral : theme.rowBg, border: `1.5px solid ${theme.border}`,
        }} />
      ))}
    </div>
  );
}

function PinKeypad({ onDigit, onBackspace }) {
  const { theme } = useTheme();
  const keys = ['1', '2', '3', '4', '5', '6', '7', '8', '9', '', '0', '\u232B'];
  return (
    <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: 10 }}>
      {keys.map((k, i) => (
        <div key={i} onClick={() => { if (k === '\u232B') onBackspace(); else if (k) onDigit(k); }} style={{
          height: 50, borderRadius: 14, display: 'flex', alignItems: 'center', justifyContent: 'center',
          fontSize: 18, fontWeight: 700, color: theme.ink, background: k ? theme.rowBg : 'transparent',
          cursor: k ? 'pointer' : 'default',
        }}>{k}</div>
      ))}
    </div>
  );
}

function ChatLockSetup({ onCancel, onConfirm }) {
  useBackClose(true, onCancel);
  const { theme } = useTheme();
  const [pin, setPin] = useState('');
  const [confirmPin, setConfirmPin] = useState('');
  const [stage, setStage] = useState('enter');
  const [err, setErr] = useState('');

  const handleDigit = (d) => {
    if (stage === 'enter') {
      if (pin.length < 4) {
        const next = pin + d;
        setPin(next);
        if (next.length === 4) setTimeout(() => setStage('confirm'), 150);
      }
    } else {
      if (confirmPin.length < 4) {
        const next = confirmPin + d;
        setConfirmPin(next);
        if (next.length === 4) {
          if (next === pin) onConfirm(pin);
          else { setErr('PINs did not match'); setTimeout(() => { setPin(''); setConfirmPin(''); setStage('enter'); setErr(''); }, 700); }
        }
      }
    }
  };
  const handleBackspace = () => { if (stage === 'enter') setPin((p) => p.slice(0, -1)); else setConfirmPin((p) => p.slice(0, -1)); };

  return (
    <div onClick={(e) => e.stopPropagation()} style={{
      position: 'absolute', inset: 0, background: theme.panelBg, zIndex: 97,
      display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', padding: 30,
    }} className="zchat-fade">
      <Lock size={28} color={theme.coral} style={{ marginBottom: 10 }} />
      <div style={{ fontWeight: 800, fontSize: 16, color: theme.ink, marginBottom: 4 }}>
        {stage === 'enter' ? 'Set a PIN' : 'Confirm your PIN'}
      </div>
      <div style={{ fontSize: 12, color: err ? theme.danger : theme.muted, marginBottom: 18, minHeight: 16 }}>{err || 'Only you can unlock this chat'}</div>
      <PinPad value={stage === 'enter' ? pin : confirmPin} />
      <div style={{ width: '100%', maxWidth: 220 }}>
        <PinKeypad onDigit={handleDigit} onBackspace={handleBackspace} />
      </div>
      <span style={{ ...ghostBtn(theme), marginTop: 22 }} onClick={onCancel}>Cancel</span>
    </div>
  );
}

function ChatLockUnlock({ onCancel, onUnlock, correctHash }) {
  useBackClose(true, onCancel);
  const { theme } = useTheme();
  const [pin, setPin] = useState('');
  const [err, setErr] = useState('');

  const handleDigit = async (d) => {
    if (pin.length >= 4) return;
    const next = pin + d;
    setPin(next);
    if (next.length === 4) {
      const h = await hashPin(next);
      let ok = h === correctHash;
      let offline = false;
      if (!ok && correctHash && !/^[0-9a-f]{64}$/i.test(correctHash)) {
        try {
          const { data, error } = await supabase.rpc('zchat_check_chat_pin', { p_hash: h });
          if (error) offline = true;
          ok = !error && data === true;
        } catch { offline = true; }
      }
      if (ok) onUnlock();
      else { setErr(offline ? 'No connection. Try again' : 'Incorrect PIN'); setTimeout(() => { setPin(''); setErr(''); }, offline ? 1400 : 600); }
    }
  };

  return (
    <div onClick={(e) => e.stopPropagation()} style={{
      position: 'absolute', inset: 0, background: theme.panelBg, zIndex: 97,
      display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', padding: 30,
    }} className="zchat-fade">
      <Lock size={28} color={theme.coral} style={{ marginBottom: 10 }} />
      <div style={{ fontWeight: 800, fontSize: 16, color: theme.ink, marginBottom: 4 }}>Enter PIN</div>
      <div style={{ fontSize: 12, color: err ? theme.danger : theme.muted, marginBottom: 18, minHeight: 16 }}>{err || 'This chat is locked'}</div>
      <PinPad value={pin} />
      <div style={{ width: '100%', maxWidth: 220 }}>
        <PinKeypad onDigit={handleDigit} onBackspace={() => setPin((p) => p.slice(0, -1))} />
      </div>
      <span style={{ ...ghostBtn(theme), marginTop: 22 }} onClick={onCancel}>Back</span>
    </div>
  );
}


function NicknameEditRow({ avatar, label, currentValue, placeholder, onSave }) {
  const { theme } = useTheme();
  const [editing, setEditing] = useState(false);
  const [val, setVal] = useState('');
  const [saving, setSaving] = useState(false);
  return (
    <div style={{ padding: '14px 0' }}>
      <div role="button" aria-label={`Edit name for ${label}`} onClick={() => { if (!editing) { setVal(currentValue || ''); setEditing(true); } }} style={{ display: 'flex', alignItems: 'center', gap: 14, cursor: editing ? 'default' : 'pointer' }}>
        <Avatar emoji={avatar} name={label} size={48} />
        <div style={{ flex: 1, minWidth: 0 }}>
          <div style={{ fontSize: 12, color: theme.muted, fontWeight: 700, marginBottom: 3 }}>{label}</div>
          {editing ? (
            <input autoFocus value={val} onChange={(e) => setVal(e.target.value.slice(0, 30))} placeholder={placeholder} aria-label={`Nickname for ${label}`}
              onKeyDown={(e) => { if (e.key === 'Enter') e.currentTarget.blur(); }}
              style={{ ...inputStyle(theme), fontSize: 15, padding: '9px 12px' }} />
          ) : (
            <div style={{ fontSize: 15.5, fontWeight: 700, color: currentValue ? theme.ink : theme.muted, fontStyle: currentValue ? 'normal' : 'italic' }}>
              {currentValue || placeholder}
            </div>
          )}
        </div>
        {!editing && <Pencil size={16} color={theme.muted} style={{ flexShrink: 0 }} />}
      </div>
      {editing && (
        <div style={{ display: 'flex', gap: 8, marginTop: 10, justifyContent: 'flex-end', alignItems: 'center' }}>
          <PillButton small label="Cancel" onClick={() => { setVal(''); setEditing(false); }} />
          {currentValue && <PillButton small label="Reset" onClick={async () => { setSaving(true); await onSave(''); setSaving(false); setVal(''); setEditing(false); }} />}
          <PillButton small primary disabled={saving} label={saving ? <Spinner size={12} /> : 'Save'} ariaLabel="Save nickname" onClick={async () => { setSaving(true); await onSave(val); setSaving(false); setVal(''); setEditing(false); }} />
        </div>
      )}
    </div>
  );
}

function NicknamesModal({ conv, myAvatar, myName, currentNickname, currentAlias, onSaveNickname, onSaveAlias, onClose }) {
  useBackClose(true, onClose);
  const { theme } = useTheme();
  const otherRealName = conv.realName || conv.otherProfile.name;
  return (
    <FullPage title="Nicknames" subtitle="Only you see these" onBack={onClose} zIndex={60}>
      <div style={{ padding: '10px 2px 4px', fontSize: 13, color: theme.muted, lineHeight: 1.5 }}>Tap a name to change how it shows in this chat.</div>
      <NicknameEditRow avatar={conv.otherProfile.avatar} label={otherRealName} currentValue={currentNickname} placeholder={otherRealName} onSave={onSaveNickname} />
      <div style={{ height: 1, background: theme.border }} />
      <NicknameEditRow avatar={myAvatar} label="You" currentValue={currentAlias} placeholder={myName} onSave={onSaveAlias} />
    </FullPage>
  );
}

function detailsCardBg(theme) { return theme.dark ? 'rgba(255,255,255,0.045)' : '#F5F5F8'; }
function DetailSection({ title, right, children, flush }) {
  const { theme } = useTheme();
  return (
    <div style={{ margin: '18px 16px 0' }}>
      {(title || right) && (
        <div style={{ display: 'flex', alignItems: 'center', padding: '0 4px 8px' }}>
          <div style={{ flex: 1, minWidth: 0, fontSize: 13, fontWeight: 700, color: theme.muted }}>{title}</div>
          {right}
        </div>
      )}
      {flush ? children : <div style={{ borderRadius: 18, background: detailsCardBg(theme), border: `1px solid ${theme.border}`, overflow: 'hidden' }}>{children}</div>}
    </div>
  );
}
function DetailRow({ icon, label, sub, value, onClick, right, danger, last }) {
  const { theme } = useTheme();
  const color = danger ? theme.danger : theme.ink;
  return (
    <div role={onClick ? 'button' : undefined} aria-label={onClick && typeof label === 'string' ? label : undefined} onClick={onClick} className={onClick ? 'zchat-row-press' : undefined} style={{
      display: 'flex', alignItems: 'center', gap: 12, minHeight: sub ? 58 : 50, padding: '0 14px', cursor: onClick ? 'pointer' : 'default', position: 'relative',
    }}>
      {icon && <span style={{ display: 'flex', color: danger ? theme.danger : theme.ink, flexShrink: 0 }}>{React.cloneElement(icon, { size: 20 })}</span>}
      <div style={{ flex: 1, minWidth: 0, padding: '10px 0' }}>
        <div style={{ fontSize: 15, fontWeight: danger ? 700 : 500, color, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{label}</div>
        {sub && <div style={{ fontSize: 12.5, color: theme.muted, marginTop: 2, lineHeight: 1.35, display: '-webkit-box', WebkitLineClamp: 2, WebkitBoxOrient: 'vertical', overflow: 'hidden' }}>{sub}</div>}
      </div>
      {value && <span style={{ fontSize: 13.5, color: theme.muted, flexShrink: 0, maxWidth: 140, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{value}</span>}
      {right || (onClick && !danger ? <ChevronRight size={18} color={theme.muted} style={{ flexShrink: 0 }} /> : null)}
      {!last && <div style={{ position: 'absolute', left: icon ? 46 : 14, right: 0, bottom: 0, height: 1, background: theme.border }} />}
    </div>
  );
}
function DetailTiles({ items }) {
  const { theme } = useTheme();
  const list = items.filter(Boolean);
  if (!list.length) return null;
  return (
    <div style={{ borderRadius: 18, background: detailsCardBg(theme), border: `1px solid ${theme.border}`, overflow: 'hidden' }}>
      {list.map((t, i) => {
        const name = t.aria || t.label;
        const right = t.badge || t.dot ? (
          <>
            {t.dot ? <span aria-hidden="true" style={{ width: 18, height: 18, borderRadius: '50%', background: t.dot, flexShrink: 0 }} /> : null}
            {t.badge ? <span style={{ minWidth: 20, height: 20, padding: '0 6px', boxSizing: 'border-box', borderRadius: 10, background: theme.danger, color: '#FFFFFF', fontSize: 11, fontWeight: 800, display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0 }}>{t.badge > 99 ? '99+' : t.badge}</span> : null}
            <ChevronRight size={18} color={theme.muted} style={{ flexShrink: 0 }} />
          </>
        ) : undefined;
        return <DetailRow key={name} icon={t.icon} label={name} value={t.value || null} onClick={t.onClick} right={right} last={i === list.length - 1} />;
      })}
    </div>
  );
}

function MediaStrip({ media, onOpen, onSeeAll }) {
  const { theme } = useTheme();
  const list = (media || []).slice(0, 10);
  return (
    <DetailSection title="Media, links and voice" right={<div role="button" aria-label="See all media" onClick={onSeeAll} style={{ fontSize: 13, fontWeight: 800, color: theme.coral, cursor: 'pointer', padding: '2px 0 2px 10px' }}>See all</div>} flush>
      {list.length ? (
        <div style={{ display: 'flex', gap: 6, overflowX: 'auto', scrollbarWidth: 'none', WebkitOverflowScrolling: 'touch', margin: '0 -16px', padding: '0 16px' }}>
          {list.map((m) => (
            <div key={m.id} role="button" aria-label={m.type === 'video' ? 'Open video' : 'Open photo'} onClick={() => onOpen && onOpen(m)} style={{ position: 'relative', width: 78, height: 78, flexShrink: 0, borderRadius: 12, overflow: 'hidden', background: detailsCardBg(theme), cursor: 'pointer' }}>
              {m.type === 'video'
                ? <VideoThumb src={m.media_url} style={{ width: '100%', height: '100%', objectFit: 'cover', pointerEvents: 'none' }} />
                : <MediaImg src={m.media_url} loading="lazy" draggable={false} style={{ width: '100%', height: '100%', objectFit: 'cover', display: 'block' }} />}
              {m.type === 'video' && <Play size={14} color="white" style={{ position: 'absolute', top: 6, right: 6, filter: 'drop-shadow(0 1px 3px rgba(0,0,0,0.6))' }} />}
            </div>
          ))}
        </div>
      ) : (
        <div role="button" aria-label="Open media, links and voice" onClick={onSeeAll} style={{ borderRadius: 18, background: detailsCardBg(theme), border: `1px solid ${theme.border}`, padding: '14px', display: 'flex', alignItems: 'center', gap: 12, cursor: 'pointer' }}>
          <ImageIcon size={20} color={theme.muted} />
          <div style={{ flex: 1, fontSize: 13.5, color: theme.muted }}>Photos, videos, links and voice notes show up here</div>
          <ChevronRight size={18} color={theme.muted} />
        </div>
      )}
    </DetailSection>
  );
}
function DetailActions({ items }) {
  const { theme } = useTheme();
  const c = igPalette(theme);
  return (
    <div style={{ display: 'flex', justifyContent: 'center', gap: 4, marginTop: 14, padding: '0 8px' }}>
      {items.filter(Boolean).map(([icon, label, fn, on]) => (
        <div key={label} role="button" aria-label={label} onClick={fn} className="zchat-press" style={{ flex: '0 1 72px', minWidth: 0, display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 6, padding: '8px 2px 4px', cursor: 'pointer', color: on ? theme.coral : theme.ink }}>
          {React.cloneElement(icon, { size: 24, strokeWidth: 1.6 })}
          <div style={{ fontSize: 12, fontWeight: on ? 700 : 500, color: on ? theme.coral : c.dim, maxWidth: '100%', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{label}</div>
        </div>
      ))}
    </div>
  );
}

function detailRows(rows) {
  const list = rows.filter(Boolean);
  return list.map((r, i) => React.cloneElement(r, { key: i, last: i === list.length - 1 }));
}

function ChatSettingsPanel({ conv, myId, meAvatar, meName, isPinned, isLocked, wallpaper, chatLockAvailable, onClose, onTogglePin, onToggleArchive, onSetWallpaper, onEnableLock, onDisableLock, onDeleteChat, onReportUser, onNicknameSaved, onNeedChatLockSetup, onOpenProfile, isMuted, onSetMute, onCall, disappearSecs, onSetDisappear, tools, messages = [], onOpenMedia }) {
  const [showDisappear, setShowDisappear] = useState(false);
  useBackClose(true, onClose);
  const edgeBack = useEdgeSwipeBack(true);
  const [showMuteOptions, setShowMuteOptions] = useState(false);
  useBackClose(showMuteOptions, () => setShowMuteOptions(false));
  const { theme } = useTheme();
  const [nickname, setNickname] = useState('');
  const [myAlias, setMyAlias] = useState('');
  const [showTheme, setShowTheme] = useState(false);
  const [showNicknames, setShowNicknames] = useState(false);
  const [showReportUser, setShowReportUser] = useState(false);
  const [followerCount, setFollowerCount] = useState(() => { const st = profileStatsCache.get(conv.otherProfile.id); return st && st.followers != null ? st.followers : null; });
  const [followingCount, setFollowingCount] = useState(() => { const st = profileStatsCache.get(conv.otherProfile.id); return st && st.following != null ? st.following : null; });
  const [listModal, setListModal] = useState(null);
  const [note, setNote] = useState(() => contactNoteFor(conv.otherProfile.id));
  const [noteOpen, setNoteOpen] = useState(false);
  const [bioOpen, setBioOpen] = useState(false);

  useEffect(() => {
    let alive = true;
    (async () => {
      const [nickRes, aliasRes, folRes, fingRes] = await Promise.all([
        supabase.from('contact_nicknames').select('nickname').eq('owner_id', myId).eq('contact_id', conv.otherProfile.id).maybeSingle(),
        supabase.from('self_aliases').select('alias').eq('user_id', myId).eq('viewer_id', conv.otherProfile.id).maybeSingle(),
        supabase.from('follows').select('*', { count: 'exact', head: true }).eq('following_id', conv.otherProfile.id).eq('status', 'accepted'),
        supabase.from('follows').select('*', { count: 'exact', head: true }).eq('follower_id', conv.otherProfile.id).eq('status', 'accepted'),
      ]);
      if (!alive) return;
      if (!nickRes.error) setNickname(nickRes.data ? nickRes.data.nickname : '');
      if (!aliasRes.error) setMyAlias(aliasRes.data ? aliasRes.data.alias : '');
      if (!folRes.error) { setFollowerCount(folRes.count || 0); saveProfileStats(conv.otherProfile.id, { followers: folRes.count || 0 }); }
      if (!fingRes.error) { setFollowingCount(fingRes.count || 0); saveProfileStats(conv.otherProfile.id, { following: fingRes.count || 0 }); }
    })();
    return () => { alive = false; };
  }, [conv.otherProfile.id]);

  const saveMyAlias = async (val) => {
    if (val.trim()) {
      await supabase.from('self_aliases').upsert({ user_id: myId, viewer_id: conv.otherProfile.id, alias: val.trim() }, { onConflict: 'user_id,viewer_id' });
    } else {
      await supabase.from('self_aliases').delete().eq('user_id', myId).eq('viewer_id', conv.otherProfile.id);
    }
    await sendMessage(myId, conv.otherProfile.id, 'system', val.trim() ? `Now appears as "${val.trim()}" to you` : 'Reverted to their real name', null);
    setMyAlias(val.trim());
  };
  const saveNickname = async (val) => {
    if (val.trim()) {
      await supabase.from('contact_nicknames').upsert({ owner_id: myId, contact_id: conv.otherProfile.id, nickname: val.trim() }, { onConflict: 'owner_id,contact_id' });
      await sendMessage(myId, conv.otherProfile.id, 'system', `Nickname updated to "${val.trim()}"`, null);
    } else {
      await supabase.from('contact_nicknames').delete().eq('owner_id', myId).eq('contact_id', conv.otherProfile.id);
      await sendMessage(myId, conv.otherProfile.id, 'system', 'Nickname removed', null);
    }
    setNickname(val.trim());
    onNicknameSaved(val.trim() || null, conv.otherProfile.id);
  };

  const otherName = conv.realName || conv.otherProfile.name;
  const p = conv.otherProfile;
  const infoBits = [
    p.pronouns ? p.pronouns : null,
    p.age != null && !p.hide_age ? `${p.age} yrs` : null,
    p.country && !p.hide_country ? countryFlag(p.country) : null,
  ].filter(Boolean);
  const showBio = p.bio && !p.hide_bio;
  const c = igPalette(theme);
  const muteLabel = isMuted === true ? 'Muted' : isMuted ? `Muted until ${fmtDate(new Date(isMuted), { month: 'short', day: 'numeric' })}` : 'Off';
  const dmMedia = messages.filter((m) => !m.deleted && (m.type === 'image' || m.type === 'video') && m.media_url && !parseOnce(m)).slice(-10).reverse();

  return (
    <>
    <WideDim onClose={onClose} z={33} />
    <div {...edgeBack} style={{
      position: 'fixed', inset: 0, background: c.bg, color: c.fg, zIndex: 33, fontFamily: FONT,
      display: 'flex', flexDirection: 'column', overflow: 'hidden',
    }} className="zchat-panel-open zchat-wide-page">
      <IgTopBar title="Chat details" onBack={onClose} />
      <div style={{ flex: 1, minHeight: 0, overflowY: 'auto', WebkitOverflowScrolling: 'touch', paddingBottom: 'calc(28px + env(safe-area-inset-bottom))' }}>
        <div style={{ textAlign: 'center', padding: '6px 20px 0' }}>
          <div role="button" aria-label="Open profile" onClick={() => onOpenProfile(p)} style={{ display: 'flex', justifyContent: 'center', cursor: 'pointer' }}>
            <Avatar emoji={conv.otherProfile.avatar} name={otherName} size={84} />
          </div>
          <div style={{ display: 'flex', justifyContent: 'center', marginTop: 12, padding: '0 6px' }}>
            <NameBadge name={otherName} verified={p.verified} custom={p.custom_badge} size={15} lines={2} style={{ justifyContent: 'center', textAlign: 'center', fontWeight: 700, fontSize: otherName.length > 30 ? 16 : 18 }} />
          </div>
          <div style={{ fontSize: 13, color: c.dim, marginTop: 3, padding: '0 16px', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>@{conv.otherProfile.username}{infoBits.length ? `, ${infoBits.join(', ')}` : ''}</div>
          {tools && tools.headerExtra}
          {showBio && (
            <div onClick={() => setBioOpen(true)} style={{ fontSize: 13.5, marginTop: 8, lineHeight: 1.45, padding: '0 8px', overflow: 'hidden', display: bioOpen ? 'block' : '-webkit-box', WebkitLineClamp: 3, WebkitBoxOrient: 'vertical', cursor: bioOpen ? 'default' : 'pointer' }}>
              <RichText text={p.bio} onMention={onOpenProfile} />
            </div>
          )}
          <div style={{ display: 'flex', justifyContent: 'center', gap: 22, marginTop: 10 }}>
            <div role="button" aria-label="Followers" onClick={conv.otherProfile.is_bot ? undefined : () => setListModal('followers')} style={{ cursor: conv.otherProfile.is_bot ? 'default' : 'pointer' }}>
              <span style={{ fontWeight: 700, fontSize: 14.5 }}>{conv.otherProfile.is_bot ? (BOT_FOLLOWER_BASE + (followerCount || 0)).toLocaleString('en-US') : (followerCount == null ? <span style={{ opacity: 0 }}>0</span> : followerCount)}</span> <span style={{ fontSize: 13, color: c.dim }}>{!conv.otherProfile.is_bot && followerCount === 1 ? 'follower' : 'followers'}</span>
            </div>
            {!conv.otherProfile.is_bot && (
              <div role="button" aria-label="Following" onClick={() => setListModal('following')} style={{ cursor: 'pointer' }}>
                <span style={{ fontWeight: 700, fontSize: 14.5 }}>{followingCount == null ? <span style={{ opacity: 0 }}>0</span> : followingCount}</span> <span style={{ fontSize: 13, color: c.dim }}>following</span>
              </div>
            )}
          </div>
        </div>
        <DetailActions items={[
          [<User size={21} strokeWidth={1.7} />, 'Profile', () => onOpenProfile(p)],
          onCall ? [<Phone size={21} strokeWidth={1.7} />, 'Call', () => onCall('voice')] : null,
          onCall ? [<VideoIcon size={21} strokeWidth={1.7} />, 'Video', () => onCall('video')] : null,
          tools && tools.onSearch ? [<Search size={21} strokeWidth={1.7} />, 'Search', tools.onSearch] : null,
          onSetMute ? [isMuted ? <BellOff size={21} strokeWidth={1.7} /> : <Bell size={21} strokeWidth={1.7} />, isMuted ? 'Muted' : 'Mute', () => setShowMuteOptions(true), !!isMuted] : null,
        ]} />

        {tools && <MediaStrip media={dmMedia} onOpen={onOpenMedia} onSeeAll={tools.onMedia} />}

        {tools && (
          <DetailSection title="In this chat" flush>
            <DetailTiles items={[
              tools.onPinned ? { icon: <Pin_ color="currentColor" />, label: 'Pinned', aria: 'Pinned messages', badge: tools.pinnedCount, onClick: tools.onPinned } : null,
              tools.onJumpDate ? { icon: <CalendarIcon />, label: 'Jump to date', aria: 'Jump to a date', onClick: tools.onJumpDate } : null,
              tools.onScheduled ? { icon: <Clock />, label: 'Scheduled', aria: 'Scheduled messages', badge: tools.scheduledCount, onClick: tools.onScheduled } : null,
              tools.onGame ? { icon: <GamepadIcon />, label: 'Games', aria: 'Play a game', onClick: tools.onGame } : null,
              ...(tools.moreTiles || []),
              { icon: <Activity />, label: 'Insights', aria: 'Chat insights', onClick: tools.onInsights },
              { icon: <Download />, label: 'Export', aria: 'Export chat', onClick: tools.onExport },
            ]} />
          </DetailSection>
        )}

        <DetailSection title="Customize" flush>
          <DetailTiles items={[
            { icon: <ThemeIcon />, label: 'Theme', aria: 'Chat theme', onClick: () => setShowTheme(true) },
            tools ? { icon: <BubblesIcon />, label: 'Bubbles', aria: 'Chat bubbles', onClick: tools.onBubbles } : null,
            { icon: <AtSign />, label: 'Nicknames', onClick: () => setShowNicknames(true) },
            ...((tools && tools.moreCustomize) || []),
          ]} />
        </DetailSection>

        <DetailSection title="Privacy and safety">
          {detailRows([
            onSetMute ? <DetailRow icon={isMuted ? <BellOff /> : <Bell />} label="Mute notifications" value={muteLabel} onClick={() => setShowMuteOptions(true)} /> : null,
            <DetailRow icon={<Timer />} label="Disappearing messages" value={disappearLabel(disappearSecs)} onClick={() => setShowDisappear(true)} />,
            <DetailRow icon={<Lock />} label="Lock this chat" onClick={() => { if (isLocked) onDisableLock(); else if (chatLockAvailable) onEnableLock(); else onNeedChatLockSetup(); }} right={<IgToggle on={!!isLocked} />} />,
            <DetailRow icon={<Pin_ color="currentColor" />} label="Pin chat" onClick={onTogglePin} right={<IgToggle on={!!isPinned} />} />,
            <DetailRow icon={<Archive />} label="Archive chat" onClick={onToggleArchive} />,
            ...((tools && tools.morePrivacy) || []),
          ])}
        </DetailSection>

        <DetailSection title="Private note">
          <DetailRow icon={<Pencil />} label={note ? note.split('\n')[0] : 'Add a private note'} sub={note ? 'Only you can see this. Tap to edit.' : 'Only you can see it'} onClick={() => setNoteOpen(true)} last />
        </DetailSection>

        <DetailSection>
          {detailRows([
            tools && tools.onClear ? <DetailRow icon={<Trash2 />} label="Clear chat" danger onClick={tools.onClear} /> : null,
            tools && tools.onToggleBlock ? <DetailRow icon={<Ban />} label={tools.blocked ? `Unblock ${otherName}` : `Block ${otherName}`} danger onClick={tools.onToggleBlock} /> : null,
            !(tools && tools.isBot) ? <DetailRow icon={<Flag />} label={`Report ${otherName}`} danger onClick={() => setShowReportUser(true)} /> : null,
            !(tools && tools.isBot) ? <DetailRow icon={<Trash2 />} label={`Delete chat with ${otherName}`} danger onClick={onDeleteChat} /> : null,
          ])}
        </DetailSection>
        {showDisappear && <DisappearSheet value={disappearSecs} subject="this chat" onPick={onSetDisappear} onClose={() => setShowDisappear(false)} />}
      </div>
      {showMuteOptions && onSetMute && (
        <div onClick={() => setShowMuteOptions(false)} style={{ position: 'fixed', inset: 0, zIndex: 60, background: 'rgba(0,0,0,0.5)', display: 'flex', alignItems: 'flex-end' }}>
          <div onClick={(e) => e.stopPropagation()} className="zchat-sheet-up" style={{ width: '100%', background: theme.panelBg, borderRadius: '22px 22px 0 0', padding: '18px 18px calc(18px + env(safe-area-inset-bottom))' }}>
            <div style={{ fontWeight: 900, fontSize: 16, color: theme.ink, marginBottom: 12 }}>Mute notifications</div>
            {[['Off', null], ['8 hours', 8 * 3600000], ['1 week', 7 * 86400000], ['Always', 'forever']].map(([label, ms]) => (
              <div key={label} role="button" onClick={() => { onSetMute(ms === 'forever' ? new Date('2999-01-01').toISOString() : ms ? new Date(Date.now() + ms).toISOString() : null); setShowMuteOptions(false); }}
                style={{ padding: '13px 6px', fontSize: 15, fontWeight: 700, color: theme.ink, cursor: 'pointer', borderBottom: `1px solid ${theme.border}` }}>{label}</div>
            ))}
          </div>
        </div>
      )}
      {showTheme && (
        <ChatThemePage value={wallpaper} userId={myId} mineOnly={conv.user_a === myId ? conv.wallpaper_a !== conv.wallpaper_b && !!conv.wallpaper_a : conv.wallpaper_b !== conv.wallpaper_a && !!conv.wallpaper_b} onSelect={onSetWallpaper} onClose={() => setShowTheme(false)} title={conv.otherProfile.name} avatar={conv.otherProfile.avatar} />
      )}
      {showNicknames && (
        <NicknamesModal 
          conv={conv} myAvatar={meAvatar} myName={meName}
          currentNickname={nickname} currentAlias={myAlias}
          onSaveNickname={saveNickname} onSaveAlias={saveMyAlias}
          onClose={() => setShowNicknames(false)}
        />
      )}
      {showReportUser && (
        <ReportReasonPicker
          onCancel={() => setShowReportUser(false)}
          onSubmit={(reason) => { onReportUser(reason); setShowReportUser(false); }}
        />
      )}
      {noteOpen && (
        <ContactNoteSheet name={otherName} value={note} onClose={() => setNoteOpen(false)} onSave={(t) => { saveContactNote(conv.otherProfile.id, t); setNote(contactNoteFor(conv.otherProfile.id)); }} />
      )}
      {listModal && (
        <FollowListModal userId={conv.otherProfile.id} viewerId={myId} mode={listModal} onClose={() => setListModal(null)}
          onOpenProfile={(pf) => { setListModal(null); onOpenProfile(pf); }} />
      )}
    </div>
    </>
  );
}

function Pin_({ size = 16, color = ACCENT.coral }) {
  return <Pin size={size} color={color} strokeWidth={2} fill={color} fillOpacity={0.18} />;
}


function GroupAvatar({ avatar, name, size = 44 }) {
  const { theme } = useTheme();
  if (avatar) {
    return <img src={avatar} alt="" onContextMenu={(e) => e.preventDefault()} draggable={false} style={{ width: size, height: size, borderRadius: '50%', objectFit: 'cover', flexShrink: 0 }} />;
  }
  return (
    <div style={{
      width: size, height: size, borderRadius: '50%', background: theme.coral, flexShrink: 0,
      display: 'flex', alignItems: 'center', justifyContent: 'center',
    }}>
      <Users size={Math.round(size * 0.5)} color="white" />
    </div>
  );
}

function CreateGroupPanel({ myId, onClose, onCreated }) {
  useBackClose(true, onClose);
  const { theme } = useTheme();
  const [step, setStep] = useState('members');
  useBackClose(step === 'details', () => setStep('members'));
  const [q, setQ] = useState('');
  const [results, setResults] = useState([]);
  const [selected, setSelected] = useState([]);
  const [name, setName] = useState('');
  const [bio, setBio] = useState('');
  const [accent, setAccent] = useState(() => GROUP_ACCENTS[Math.floor(Math.random() * GROUP_ACCENTS.length)]);
  const [avatarFile, setAvatarFile] = useState(null);
  const [avatarPreview, setAvatarPreview] = useState(null);
  const [cropFile, setCropFile] = useState(null);
  const [creating, setCreating] = useState(false);
  const [showColour, setShowColour] = useState(false);
  useBackClose(showColour, () => setShowColour(false));
  const [err, setErr] = useState('');
  const timer = useRef(null);

  const [suggested, setSuggested] = useState([]);
  useEffect(() => {
    let alive = true;
    (async () => {
      const { data: f } = await supabase.from('follows').select('following_id').eq('follower_id', myId).eq('status', 'accepted').limit(200);
      const ids = (f || []).map((x) => x.following_id);
      if (!ids.length) return;
      const { data: profs } = await supabase.from('profiles').select('*').in('id', ids).eq('is_deleted', false);
      if (!alive) return;
      const list = sanitizeAvatarList(profs, myId).sort((a, b) => (a.name || '').localeCompare(b.name || ''));
      setSuggested(list);
      setResults(list);
    })();
    return () => { alive = false; };
  }, [myId]);
  const doSearch = (val) => {
    setQ(val);
    clearTimeout(timer.current);
    if (val.trim().length < 2) { setResults(suggested); return; }
    timer.current = setTimeout(async () => {
      const { data } = await searchAccounts(val.trim());
      setResults(sanitizeAvatarList(data, myId).filter((u) => u.id !== myId));
    }, 300);
  };

  const toggleSelect = (p) => {
    setSelected((prev) => (prev.find((s) => s.id === p.id) ? prev.filter((s) => s.id !== p.id) : [...prev, p]));
  };

  const create = async () => {
    if (!name.trim() || creating) return;
    setCreating(true);
    setErr('');
    let avatarUrl = null;
    if (avatarFile) {
      const { url } = await uploadMedia(avatarFile, myId);
      avatarUrl = url || null;
    }
    const { data: group, error } = await supabase.from('groups').insert({ name: name.trim().slice(0, 50), bio: bio.trim() || null, avatar: avatarUrl, created_by: myId }).select().single();
    if (error || !group) { setCreating(false); setErr(friendlyError(error, "Couldn't create the group. Try again.")); return; }
    const { error: memberErr } = await supabase.from('group_members').insert({ group_id: group.id, user_id: myId, role: 'admin', added_by: myId });
    if (memberErr) { setCreating(false); setErr(friendlyError(memberErr, "Couldn't create the group. Try again.")); return; }
    if (selected.length) {
      const { error: inviteErr } = await supabase.from('group_members').insert(selected.slice(0, 49).map((p) => ({ group_id: group.id, user_id: p.id, role: 'member', added_by: myId })));
      if (inviteErr) { setCreating(false); setErr(friendlyError(inviteErr, "Couldn't add those people. Try again.")); return; }
      const { data: creator } = await getProfile(myId);
      selected.slice(0, 49).forEach((p) => sendPushNotification(p.id, 'ZChat', `${creator?.name || 'Someone'} added you to ${group.name}`, `/?group=${group.id}`, creator?.avatar));
    }
    await supabase.from('messages').insert({
      sender_id: myId, group_id: group.id, type: 'system',
      content: selected.length ? `Group created and ${selected.map((p) => p.name).join(', ')} added` : 'Group created',
    });
    let savedAccent = null;
    try {
      const { error: accentErr } = await supabase.from('groups').update({ accent }).eq('id', group.id);
      if (!accentErr) savedAccent = accent;
    } catch {}
    setCreating(false);
    onCreated(savedAccent ? { ...group, accent: savedAccent } : group);
  };

  const isPicked = (id) => !!selected.find((s) => s.id === id);
  const heading = step === 'members' ? 'Choose members' : 'Make it yours';
  const canNext = selected.length > 0;

  return (
    <>
    <WideDim onClose={onClose} z={40} />
    <div style={{ position: 'fixed', inset: 0, background: theme.bgGradient, zIndex: 40, display: 'flex', flexDirection: 'column', fontFamily: FONT }} className="zchat-panel-open zchat-wide-page">
      <IgTopBar title={heading} subtitle={step === 'members' ? 'Step 1 of 2' : 'Step 2 of 2'} onBack={() => (step === 'details' ? setStep('members') : onClose())} />

      {step === 'members' ? (
        <>
          {selected.length > 0 && (
            <div style={{ display: 'flex', flexWrap: 'wrap', gap: 8, padding: '4px 18px 10px', maxHeight: 112, overflowY: 'auto' }}>
              {selected.map((p) => (
                <div key={p.id} role="button" onClick={() => toggleSelect(p)} style={{ display: 'flex', alignItems: 'center', gap: 6, padding: '4px 10px 4px 4px', borderRadius: 18, background: `${accent}26`, border: `1px solid ${accent}66`, cursor: 'pointer' }}>
                  <Avatar emoji={p.avatar} name={p.name} size={24} />
                  <span style={{ fontSize: 12.5, fontWeight: 800, color: theme.ink, maxWidth: 110, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{p.name}</span>
                  <X size={13} color={theme.muted} />
                </div>
              ))}
            </div>
          )}
          <div style={{ padding: '0 18px 10px' }}>
            <div style={{ position: 'relative' }}>
              <Search size={15} color={theme.muted} style={{ position: 'absolute', left: 12, top: 12 }} />
              <input value={q} onChange={(e) => doSearch(e.target.value)} placeholder="Search username" autoCapitalize="none" style={{ ...inputStyle(theme), padding: '9px 12px 9px 34px', fontSize: 13.5 }} />
            </div>
          </div>
          <div style={{ overflowY: 'auto', flex: 1, padding: '0 18px' }}>
            {!q.trim() && suggested.length > 0 && <div style={{ fontSize: 11.5, fontWeight: 800, color: theme.muted, margin: '4px 2px' }}>People you follow</div>}
            {results.map((p) => (
              <div key={p.id} onClick={() => toggleSelect(p)} style={{ display: 'flex', alignItems: 'center', gap: 12, padding: '9px 4px', cursor: 'pointer' }}>
                <Avatar emoji={p.avatar} name={p.name} size={42} />
                <div style={{ flex: 1, minWidth: 0 }}>
                  <div style={{ fontWeight: 800, fontSize: 14, color: theme.ink, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}><NameBadge name={p.name} verified={p.verified} custom={p.custom_badge} size={12} /></div>
                  <div style={{ fontSize: 11.5, color: theme.muted, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>@{p.username}</div>
                </div>
                <div style={{ width: 22, height: 22, borderRadius: '50%', border: `2px solid ${isPicked(p.id) ? accent : theme.border}`, background: isPicked(p.id) ? accent : 'transparent', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                  {isPicked(p.id) && <Check size={13} color="white" />}
                </div>
              </div>
            ))}
          </div>
          <div style={{ padding: 18, paddingBottom: 'calc(18px + env(safe-area-inset-bottom))' }}>
            <button onClick={() => setStep('details')} disabled={!canNext} style={{ ...primaryBtn(theme, !canNext), background: canNext ? accent : undefined }}>
              {canNext ? `Next with ${selected.length} ${selected.length === 1 ? 'person' : 'people'}` : 'Pick at least one person'}
            </button>
          </div>
        </>
      ) : (
        <div style={{ padding: '4px 18px 20px', paddingBottom: 'calc(20px + env(safe-area-inset-bottom))', flex: 1, overflowY: 'auto' }}>
          <div style={{ textAlign: 'center', padding: '6px 0 20px' }}>
            <div onClick={() => document.getElementById('group-avatar-input').click()} style={{ display: 'inline-block', cursor: 'pointer', position: 'relative', padding: 3, borderRadius: 36, border: `2px solid ${accent}` }}>
              {avatarPreview ? (
                <img src={avatarPreview} alt="" onContextMenu={(e) => e.preventDefault()} draggable={false} style={{ width: 96, height: 96, borderRadius: 30, objectFit: 'cover', display: 'block' }} />
              ) : (
                <GroupAvatar avatar={null} name={name || 'New group'} size={96} />
              )}
              <div style={{ position: 'absolute', bottom: -4, right: -4, width: 28, height: 28, borderRadius: '50%', background: theme.ink, color: theme.panelBg, border: `2px solid ${theme.panelBg}`, display: 'flex', alignItems: 'center', justifyContent: 'center' }}><Camera size={13} /></div>
            </div>
            <input id="group-avatar-input" type="file" accept="image/*" style={{ display: 'none' }}
              onChange={(e) => { const f = e.target.files?.[0]; if (f) setCropFile(f); e.target.value = ''; }} />
            <div style={{ fontWeight: 800, fontSize: (name || '').length > 26 ? 19 : 23, color: theme.ink, marginTop: 14, wordBreak: 'break-word', padding: '0 8px' }}>{name.trim() || 'Name your group'}</div>
            <div style={{ display: 'flex', justifyContent: 'center', alignItems: 'center', marginTop: 10 }}>
              {selected.slice(0, 5).map((p, i) => (
                <span key={p.id} style={{ marginLeft: i ? -8 : 0, display: 'inline-flex', borderRadius: '50%', boxShadow: `0 0 0 2px ${theme.panelBg}` }}><Avatar emoji={p.avatar} name={p.name} size={26} /></span>
              ))}
              <span style={{ marginLeft: 8, fontSize: 12, fontWeight: 700, color: theme.muted }}>You and {selected.length} {selected.length === 1 ? 'other' : 'others'}</span>
            </div>
          </div>
          <div style={{ fontSize: 12, color: theme.muted, marginBottom: 6, fontWeight: 800 }}>Group name</div>
          <input value={name} onChange={(e) => setName(e.target.value.slice(0, 50))} placeholder="e.g. Weekend Trip" style={{ ...inputStyle(theme), marginBottom: 16 }} />
          <div style={{ fontSize: 12, color: theme.muted, marginBottom: 6, fontWeight: 800 }}>What is it about? (optional)</div>
          <input value={bio} onChange={(e) => setBio(e.target.value.slice(0, 120))} placeholder="A line about this group" style={{ ...inputStyle(theme), marginBottom: 16 }} />
          <div role="button" onClick={() => setShowColour(true)} style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '14px 4px', marginBottom: 14, cursor: 'pointer', borderTop: `1px solid ${theme.border}`, borderBottom: `1px solid ${theme.border}` }}>
            <span style={{ fontSize: 15, fontWeight: 600, color: theme.ink }}>Group colour</span>
            <span style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
              <span style={{ width: 22, height: 22, borderRadius: '50%', background: accent, border: `2px solid ${theme.border}` }} />
              <ChevronRight size={18} color={theme.muted} />
            </span>
          </div>
          <button onClick={create} disabled={!name.trim() || creating} style={{ ...primaryBtn(theme, !name.trim() || creating), background: name.trim() ? accent : undefined }}>
            {creating ? <Spinner size={14} /> : 'Create group'}
          </button>
          {err && <div style={{ color: theme.danger, fontSize: 12.5, marginTop: 10, textAlign: 'center' }}>{err}</div>}
        </div>
      )}
      {showColour && <GroupColourSheet value={accent} onPick={setAccent} onClose={() => setShowColour(false)} />}
      {cropFile && (
        <PhotoCropEditor file={cropFile} isAvatar onCancel={() => setCropFile(null)} onConfirm={(blob) => {
          const file = new File([blob], 'group.jpg', { type: 'image/jpeg' });
          setAvatarFile(file);
          setAvatarPreview(URL.createObjectURL(blob));
          setCropFile(null);
        }} />
      )}
    </div>
    </>
  );
}

function GroupColourSheet({ value, onPick, onClose }) {
  const { theme } = useTheme();
  return ReactDOM.createPortal(
    <div onClick={onClose} className="zchat-fade" style={{ position: 'fixed', inset: 0, zIndex: 720, background: 'rgba(0,0,0,0.55)', display: 'flex', alignItems: 'flex-end', fontFamily: FONT }}>
      <div onClick={(e) => e.stopPropagation()} className="zchat-sheet-up" style={{ width: '100%', background: theme.panelBg, borderRadius: '22px 22px 0 0', padding: '20px 18px calc(22px + env(safe-area-inset-bottom))' }}>
        <div style={{ fontWeight: 800, fontSize: 16, color: theme.ink }}>Group colour</div>
        <div style={{ fontSize: 12.5, color: theme.muted, margin: '4px 0 16px' }}>Used for the group photo ring and the tabs.</div>
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: 14, justifyItems: 'center' }}>
          {GROUP_ACCENTS.map((col) => (
            <div key={col} role="button" aria-label={`Use colour ${col}`} onClick={() => { onPick(col); onClose(); }} style={{
              width: 52, height: 52, borderRadius: '50%', background: col, cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center',
              border: value === col ? `3px solid ${theme.ink}` : `1px solid ${theme.border}`,
            }}>{value === col && <Check size={20} color="white" />}</div>
          ))}
        </div>
      </div>
    </div>,
    document.body
  );
}

function GroupInfoPanel({ group, members, myId, iFollowIds, privacyAllowed, myRole, isOwner, onClose, onPromote, onDemote, onMute, onUnmute, onKick, onLeave, onOpenProfile, onSaveBio, onSaveName, onSaveAvatar, onAddMembers, onTransferOwnership, onSetWallpaper, onOpenSettings, onOpenMembers, messages = [], onSetAccent, disappearSecs, onSetDisappear, onOpenMedia, onJumpToMessage, tools }) {
  useBackClose(true, onClose);
  const edgeBack = useEdgeSwipeBack(true);
  const { theme } = useTheme();
  const c = igPalette(theme);
  const isAdmin = myRole === 'admin';
  const accent = groupAccent(group);
  const [bioOpen, setBioOpen] = useState(false);
  const [menuFor, setMenuFor] = useState(null);
  const [menuAnchor, setMenuAnchor] = useState(null);
  const [titleFor, setTitleFor] = useState(null);
  const [editingBio, setEditingBio] = useState(false);
  const [bio, setBio] = useState(group.bio || '');
  const [editingName, setEditingName] = useState(false);
  const [name, setName] = useState(group.name);
  const [cropFile, setCropFile] = useState(null);
  const [showAddMembers, setShowAddMembers] = useState(false);
  const [showTheme, setShowTheme] = useState(false);
  const [showDisappear, setShowDisappear] = useState(false);
  const [showColour, setShowColour] = useState(false);
  useBackClose(showColour, () => setShowColour(false));
  const soleAdmin = isAdmin && members.filter((m) => m.role === 'admin').length === 1 && members.length > 1;
  const online = members.filter(isMemberOnline);
  const dayAgo = Date.now() - 86400000;
  const todayCount = messages.filter((m) => m.type !== 'system' && !m.deleted && new Date(m.created_at).getTime() > dayAgo).length;
  const rank = (m) => (m.user_id === group.created_by ? 0 : m.role === 'admin' ? 1 : 2);
  const ranked = members.filter((m) => m.profile).sort((a, b) => rank(a) - rank(b) || (a.profile.name || '').localeCompare(b.profile.name || ''));
  const preview = ranked.length > 6 ? ranked.slice(0, 5) : ranked;
  const media = messages.filter((m) => !m.deleted && (m.type === 'image' || m.type === 'video') && m.media_url && !parseOnce(m)).slice(-10).reverse();
  const chip = (label) => (
    <span style={{ flex: 'none', fontSize: 10.5, fontWeight: 800, padding: '1px 7px', borderRadius: 8, border: `1px solid ${c.line}`, color: c.dim }}>{label}</span>
  );

  const memberRow = (m) => {
    const on = isMemberOnline(m);
    const isOwnerRow = m.user_id === group.created_by;
    return (
      <div key={m.user_id} style={{ display: 'flex', alignItems: 'center', gap: 12, padding: '8px 16px' }}>
        <div onClick={() => onOpenProfile(m.profile)} style={{ display: 'flex', alignItems: 'center', gap: 12, flex: 1, minWidth: 0, cursor: 'pointer' }}>
          <Avatar emoji={m.profile.avatar} name={m.profile.name} online={on ? true : null} size={48} />
          <div style={{ flex: 1, minWidth: 0 }}>
            <div style={{ display: 'flex', alignItems: 'center', minWidth: 0, fontWeight: 700, fontSize: 14.5 }}>
              <NameBadge name={`${m.profile.name}${m.user_id === myId ? ' (you)' : ''}`} verified={m.profile.verified} custom={m.profile.custom_badge} size={13} />
            </div>
            <div style={{ display: 'flex', alignItems: 'center', gap: 6, marginTop: 3, fontSize: 12, color: c.dim, minWidth: 0 }}>
              {isOwnerRow ? chip('Owner') : m.role === 'admin' ? chip('Admin') : null}
              {m.title && chip(m.title)}
              {m.muted && chip('Muted')}
              <span style={{ minWidth: 0, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap', color: on ? '#34d399' : c.dim, fontWeight: on ? 700 : 400 }}>{on ? 'Online now' : `@${m.profile.username}`}</span>
            </div>
          </div>
        </div>
        {isAdmin && m.user_id !== myId && !isOwnerRow && (
          <div role="button" aria-label={`Options for ${m.profile.name}`} onClick={(e) => { e.stopPropagation(); setMenuAnchor(e.currentTarget); setMenuFor(menuFor === m.user_id ? null : m.user_id); }}
            style={{ display: 'flex', padding: 9, margin: -9, cursor: 'pointer', flexShrink: 0 }}><MoreVertical size={18} color={c.dim} /></div>
        )}
      </div>
    );
  };

  const nameLen = (group.name || '').length;

  return (
    <>
    <WideDim onClose={onClose} z={40} />
    <div {...edgeBack} style={{ position: 'fixed', inset: 0, background: c.bg, color: c.fg, zIndex: 40, display: 'flex', flexDirection: 'column', fontFamily: FONT }} className="zchat-panel-open zchat-wide-page">
      <div style={{ paddingTop: 'env(safe-area-inset-top)', flexShrink: 0 }}>
        <div style={{ position: 'relative', display: 'flex', alignItems: 'center', justifyContent: 'space-between', height: 52, padding: '0 8px' }}>
          <div role="button" aria-label="Back" onClick={onClose} style={{ width: 44, height: 44, display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer' }}><ArrowLeft size={24} strokeWidth={2} /></div>
          <div style={{ position: 'absolute', left: 0, right: 0, textAlign: 'center', fontSize: 16, fontWeight: 700, pointerEvents: 'none' }}>Group info</div>
          {onOpenSettings ? <div role="button" aria-label="Group settings" onClick={onOpenSettings} style={{ width: 44, height: 44, display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer' }}><SettingsIcon size={21} strokeWidth={1.8} /></div> : <span style={{ width: 44 }} />}
        </div>
      </div>
      <div style={{ overflowY: 'auto', flex: 1, minHeight: 0, WebkitOverflowScrolling: 'touch', paddingBottom: 'calc(24px + env(safe-area-inset-bottom))' }}>
        <div style={{ textAlign: 'center', padding: '10px 16px 4px' }}>
          <div onClick={() => isAdmin && document.getElementById('group-info-avatar-input').click()} style={{ display: 'inline-block', position: 'relative', cursor: isAdmin ? 'pointer' : 'default', padding: 3, borderRadius: 36, border: `2px solid ${accent}` }}>
            <GroupAvatar avatar={group.avatar} name={group.name} size={100} />
            {isAdmin && (
              <div style={{ position: 'absolute', bottom: -4, right: -4, width: 28, height: 28, borderRadius: '50%', background: c.fg, color: c.bg, border: `2px solid ${c.bg}`, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                <Camera size={13} />
              </div>
            )}
          </div>
          {isAdmin && (
            <input id="group-info-avatar-input" type="file" accept="image/*" style={{ display: 'none' }}
              onChange={(e) => { const f = e.target.files?.[0]; if (f) setCropFile(f); e.target.value = ''; }} />
          )}
          {editingName ? (
            <div style={{ display: 'flex', gap: 6, marginTop: 14, justifyContent: 'center' }}>
              <input value={name} onChange={(e) => setName(e.target.value.slice(0, 50))} style={{ ...inputStyle(theme), fontSize: 14, width: 210 }} />
              <button onClick={() => { onSaveName(name); setEditingName(false); }} style={{ padding: '0 16px', borderRadius: 12, border: 'none', background: c.fg, color: c.bg, fontWeight: 800, fontSize: 12.5, cursor: 'pointer', fontFamily: FONT }}>Save</button>
            </div>
          ) : (
            <div onClick={() => isAdmin && setEditingName(true)} style={{
              marginTop: 14, padding: '0 6px', fontWeight: 800, fontSize: nameLen > 34 ? 18 : nameLen > 20 ? 21 : 25, lineHeight: 1.15, cursor: isAdmin ? 'pointer' : 'default',
              wordBreak: 'break-word', overflow: 'hidden', display: '-webkit-box', WebkitLineClamp: 3, WebkitBoxOrient: 'vertical',
            }}>{group.name}</div>
          )}
          <div style={{ fontSize: 13, color: c.dim, marginTop: 6 }}>
            {members.length} {members.length === 1 ? 'member' : 'members'}{group.created_at ? `, created ${fmtDate(new Date(group.created_at), { month: 'short', year: 'numeric' })}` : ''}
          </div>
          <div style={{ fontSize: 13, color: c.dim, marginTop: 3 }}>
            <span style={{ color: online.length ? '#34d399' : c.dim, fontWeight: 700 }}>{online.length} online now</span>
            {`, ${todayCount} ${todayCount === 1 ? 'message' : 'messages'} today`}
          </div>
        </div>

        {tools && (
          <DetailActions items={[
            [<Search size={21} strokeWidth={1.7} />, 'Search', tools.onSearch],
            tools.onMute ? [tools.muted ? <BellOff size={21} strokeWidth={1.7} /> : <Bell size={21} strokeWidth={1.7} />, tools.muted ? 'Muted' : 'Mute', tools.onMute, !!tools.muted] : null,
            tools.onCall ? [<Phone size={21} strokeWidth={1.7} />, tools.inCall ? 'Join' : 'Call', () => tools.onCall('voice'), !!tools.inCall] : null,
            tools.onCall ? [<VideoIcon size={21} strokeWidth={1.7} />, 'Video', () => tools.onCall('video')] : null,
            isAdmin ? [<UserPlus size={21} strokeWidth={1.7} />, 'Add', () => setShowAddMembers(true)] : null,
          ]} />
        )}

        <DetailSection title="About">
          <div style={{ padding: '12px 14px' }}>
            {editingBio ? (
              <div style={{ display: 'flex', gap: 6 }}>
                <input value={bio} onChange={(e) => setBio(e.target.value.slice(0, 120))} placeholder="What is this group about?" aria-label="Group bio" style={{ ...inputStyle(theme), fontSize: 13 }} />
                <button onClick={() => { onSaveBio(bio); setEditingBio(false); }} style={{ padding: '0 16px', borderRadius: 13, border: 'none', background: c.fg, color: c.bg, fontWeight: 800, fontSize: 12.5, cursor: 'pointer', fontFamily: FONT }}>Save</button>
              </div>
            ) : (
              <div role={isAdmin ? 'button' : undefined} aria-label={isAdmin ? 'Edit group bio' : undefined} onClick={() => { if (isAdmin) setEditingBio(true); else setBioOpen(true); }} style={{ fontSize: 14, lineHeight: 1.5, color: group.bio ? c.fg : c.dim, cursor: 'pointer', wordBreak: 'break-word', overflow: 'hidden', display: bioOpen ? 'block' : '-webkit-box', WebkitLineClamp: 4, WebkitBoxOrient: 'vertical' }}>
                {group.bio ? <RichText text={group.bio} onMention={onOpenProfile} /> : (isAdmin ? 'Add a group bio' : 'No bio yet')}
              </div>
            )}
          </div>
        </DetailSection>

        {tools && <MediaStrip media={media} onOpen={onOpenMedia} onSeeAll={tools.onMedia} />}

        {tools && (
          <DetailSection title="In this chat" flush>
            <DetailTiles items={[
              tools.onPinned ? { icon: <Pin_ color="currentColor" />, label: 'Pinned', aria: 'Pinned messages', badge: tools.pinnedCount, onClick: tools.onPinned } : null,
              tools.onJumpDate ? { icon: <CalendarIcon />, label: 'Jump to date', aria: 'Jump to a date', onClick: tools.onJumpDate } : null,
              tools.onScheduled ? { icon: <Clock />, label: 'Scheduled', aria: 'Scheduled messages', badge: tools.scheduledCount, onClick: tools.onScheduled } : null,
              ...(tools.moreTiles || []),
              { icon: <Activity />, label: 'Insights', aria: 'Chat insights', onClick: tools.onInsights },
              { icon: <Download />, label: 'Export', aria: 'Export chat', onClick: tools.onExport },
            ]} />
          </DetailSection>
        )}

        <DetailSection title="Customize" flush>
          <DetailTiles items={[
            ...((tools && tools.moreCustomize) || []),
            isAdmin ? { icon: <ThemeIcon />, label: 'Theme', aria: 'Chat theme', onClick: () => setShowTheme(true) } : null,
            tools ? { icon: <BubblesIcon />, label: 'Bubbles', aria: 'Chat bubbles', onClick: tools.onBubbles } : null,
            isAdmin ? { icon: <SwatchIcon />, label: 'Colour', aria: 'Group colour', dot: accent, onClick: () => setShowColour(true) } : null,
          ]} />
        </DetailSection>

        <DetailSection title="Group">
          {detailRows([
            <DetailRow icon={<Timer />} label="Disappearing messages" value={disappearLabel(disappearSecs)} onClick={() => setShowDisappear(true)} />,
            onOpenSettings ? <DetailRow icon={<SettingsIcon />} label="Group settings" sub={isAdmin ? 'Who can send, add people, invite link' : 'Notifications, pin and more'} onClick={onOpenSettings} /> : null,
            ...((tools && tools.morePrivacy) || []),
          ])}
        </DetailSection>

        <DetailSection title={`${members.length} ${members.length === 1 ? 'member' : 'members'}`} right={ranked.length > preview.length ? <div role="button" aria-label="See all members" onClick={() => (onOpenMembers ? onOpenMembers() : null)} style={{ fontSize: 13, fontWeight: 800, color: theme.coral, cursor: 'pointer', padding: '2px 0 2px 10px' }}>See all</div> : null}>
          {isAdmin && (
            <div role="button" aria-label="Add people" onClick={() => setShowAddMembers(true)} className="zchat-row-press" style={{ display: 'flex', alignItems: 'center', gap: 12, padding: '10px 16px', cursor: 'pointer', borderBottom: `1px solid ${theme.border}` }}>
              <div style={{ width: 48, height: 48, color: theme.coral, display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0 }}><UserPlus size={24} strokeWidth={1.8} /></div>
              <div style={{ fontSize: 15, fontWeight: 700, color: theme.ink }}>Add people</div>
            </div>
          )}
          <div style={{ padding: '4px 0' }}>{preview.map(memberRow)}</div>
          {ranked.length > preview.length && (
            <div role="button" aria-label="Show all members" onClick={() => (onOpenMembers ? onOpenMembers() : null)} style={{ borderTop: `1px solid ${theme.border}`, padding: '13px 16px', textAlign: 'center', fontSize: 14, fontWeight: 700, color: theme.coral, cursor: 'pointer' }}>
              See all {members.length} members
            </div>
          )}
        </DetailSection>

        <DetailSection>
          {detailRows([
            tools && tools.onClear ? <DetailRow icon={<Trash2 />} label="Clear chat" danger onClick={tools.onClear} /> : null,
            <DetailRow icon={<LogOut />} danger onClick={() => { if (!soleAdmin && !isOwner) onLeave(); }}
              label={isOwner ? 'Transfer ownership before leaving' : soleAdmin ? 'Leave group (assign a new admin first)' : 'Leave group'} />,
          ])}
        </DetailSection>
      </div>

      <SmartMenu anchorEl={menuAnchor} open={!!menuFor} onClose={() => setMenuFor(null)} width={200}>
        {(() => {
          const mm = members.find((x) => x.user_id === menuFor);
          if (!mm || mm.user_id === group.created_by) return null;
          const item = (label, onClick, color, last) => (
            <div onClick={() => { onClick(); setMenuFor(null); }} style={{ padding: '11px 14px', fontSize: 13, fontWeight: 600, color: color || theme.ink, cursor: 'pointer', borderBottom: last ? 'none' : `1px solid ${theme.border}` }}>{label}</div>
          );
          return (
            <div style={{ background: theme.panelBg, borderRadius: 14, boxShadow: '0 8px 24px rgba(0,0,0,0.2)', border: `1px solid ${theme.border}`, overflow: 'hidden' }}>
              {isOwner && (mm.role === 'admin' ? item('Remove as admin', () => onDemote(mm.user_id)) : item('Make admin', () => onPromote(mm.user_id)))}
              {isOwner && item('Transfer ownership', () => onTransferOwnership(mm.user_id), accent)}
              {tools && tools.onSetTitle && item(mm.title ? 'Change title' : 'Give a title', () => setTitleFor(mm))}
              {mm.muted ? item('Unmute member', () => onUnmute(mm.user_id)) : item('Mute member', () => onMute(mm.user_id))}
              {item('Remove from group', () => onKick(mm.user_id), theme.danger, true)}
            </div>
          );
        })()}
      </SmartMenu>
      {titleFor && tools && tools.onSetTitle && <MemberTitleSheet member={titleFor} onClose={() => setTitleFor(null)} onSave={(t) => tools.onSetTitle(titleFor.user_id, t)} />}
      {cropFile && (
        <PhotoCropEditor file={cropFile} isAvatar onCancel={() => setCropFile(null)} onConfirm={(blob) => { onSaveAvatar(blob); setCropFile(null); }} />
      )}
      {showTheme && <ChatThemePage group userId={myId} value={group.wallpaper} onSelect={onSetWallpaper} onClose={() => setShowTheme(false)} title={group.name} avatar={group.avatar} />}
      {showDisappear && <DisappearSheet value={disappearSecs} subject="this group" canEdit={isAdmin} onPick={onSetDisappear} onClose={() => setShowDisappear(false)} />}
      {showColour && <GroupColourSheet value={accent} onPick={(col) => { if (onSetAccent) onSetAccent(col); }} onClose={() => setShowColour(false)} />}
      {showAddMembers && (
        <AddMembersPanel myId={myId} iFollowIds={iFollowIds} privacyAllowed={privacyAllowed} existingIds={members.map((m) => m.user_id)}
          onClose={() => setShowAddMembers(false)}
          onAdd={(people) => { onAddMembers(people); setShowAddMembers(false); }} />
      )}
    </div>
    </>
  );
}

const TOPIC_COLORS = [['#7C5CFC', 'Purple'], ['#3B82F6', 'Blue'], ['#10B981', 'Green'], ['#F59E0B', 'Amber'], ['#EF4444', 'Red'], ['#EC4899', 'Pink'], ['#06B6D4', 'Teal'], ['#F97316', 'Orange']];
function groupTopicsOf(g) {
  const raw = g && Array.isArray(g.topics) ? g.topics : [];
  const out = [];
  raw.forEach((t) => {
    if (!t || typeof t !== 'object') return;
    const id = String(t.id || '').slice(0, 40);
    const n = String(t.n || '').replace(/\s+/g, ' ').trim().slice(0, 24);
    if (!id || !n || out.some((x) => x.id === id)) return;
    out.push({ id, n, c: TOPIC_COLORS.some(([hex]) => hex === t.c) ? t.c : TOPIC_COLORS[0][0] });
  });
  return out.slice(0, 12);
}
function TopicHashIcon({ size = 16, color = 'currentColor', style }) {
  return (
    <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke={color} strokeWidth="2.1" strokeLinecap="round" style={style} aria-hidden="true">
      <path d="M5 9h15M4 15h15M10.5 3.5 8.5 20.5M15.5 3.5l-2 17" />
    </svg>
  );
}
function GroupTopicBar({ topics, value, onChange, unread, canManage, onManage }) {
  const { theme } = useTheme();
  const ref = useRef(null);
  useEffect(() => {
    const box = ref.current;
    const el = box && box.querySelector('[aria-pressed="true"]');
    if (!box || !el) return;
    const l = el.offsetLeft - 12;
    const r = el.offsetLeft + el.offsetWidth + 12;
    if (l < box.scrollLeft) box.scrollTo({ left: l, behavior: 'smooth' });
    else if (r > box.scrollLeft + box.clientWidth) box.scrollTo({ left: r - box.clientWidth, behavior: 'smooth' });
  }, [value]);
  const chip = (key, label, color) => {
    const on = value === key;
    return (
      <div key={key} role="button" aria-label={`Topic ${label}`} aria-pressed={on} onClick={() => onChange(key)} className="zchat-press"
        style={{ flexShrink: 0, display: 'flex', alignItems: 'center', gap: 6, height: 32, padding: '0 13px', borderRadius: 16, fontSize: 13.5, fontWeight: 700, cursor: 'pointer', background: on ? theme.coral : theme.rowBg, color: on ? '#FFFFFF' : theme.ink, transition: 'background 0.15s ease' }}>
        {color && <span style={{ width: 8, height: 8, borderRadius: '50%', background: on ? '#FFFFFF' : color, flexShrink: 0 }} />}
        <span style={{ whiteSpace: 'nowrap' }}>{label}</span>
        {!on && unread && unread[key] && <span aria-label="New messages" style={{ width: 7, height: 7, borderRadius: '50%', background: theme.coral, flexShrink: 0 }} />}
      </div>
    );
  };
  return (
    <div ref={ref} role="group" aria-label="Chat topics" style={{ display: 'flex', gap: 7, overflowX: 'auto', padding: '6px 12px 8px', flexShrink: 0, scrollbarWidth: 'none', WebkitOverflowScrolling: 'touch' }}>
      {chip('all', 'All')}
      {chip('general', 'General')}
      {topics.map((t) => chip(t.id, t.n, t.c))}
      {canManage && (
        <div role="button" aria-label="Manage topics" onClick={onManage} className="zchat-press" style={{ flexShrink: 0, width: 32, height: 32, borderRadius: 16, border: `1px solid ${theme.border}`, boxSizing: 'border-box', display: 'flex', alignItems: 'center', justifyContent: 'center', color: theme.muted, cursor: 'pointer' }}>
          <Plus size={16} />
        </div>
      )}
    </div>
  );
}
function GroupTopicsPage({ group, onClose, onSave }) {
  useBackClose(true, onClose);
  const { theme } = useTheme();
  const [list, setList] = useState(() => groupTopicsOf(group));
  const [edit, setEdit] = useState(null);
  const [del, setDel] = useState(null);
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState('');
  useBackClose(!!edit, () => setEdit(null));
  const commit = async (next, added) => {
    if (busy) return false;
    setBusy(true);
    setErr('');
    const e = await onSave(next, added);
    setBusy(false);
    if (e) { setErr(e); return false; }
    setList(next);
    return true;
  };
  const saveEdit = async () => {
    const n = edit.n.replace(/\s+/g, ' ').trim().slice(0, 24);
    if (!n) return;
    if (list.some((t) => t.id !== edit.id && t.n.toLowerCase() === n.toLowerCase())) { setErr('There is already a topic with that name.'); return; }
    const next = edit.id ? list.map((t) => (t.id === edit.id ? { ...t, n, c: edit.c } : t)) : [...list, { id: `t${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}`, n, c: edit.c }];
    if (await commit(next, edit.id ? null : n)) setEdit(null);
  };
  const startNew = () => { setErr(''); setEdit({ id: null, n: '', c: TOPIC_COLORS[list.length % TOPIC_COLORS.length][0] }); };
  return (
    <FullPage title="Topics" subtitle={group.name} onBack={onClose} zIndex={80}
      footer={!edit && list.length < 12 ? <BigButton label="New topic" onClick={startNew} /> : null}>
      {!edit && !list.length ? (
        <EmptyState art="nothing" title="No topics yet" text="Make topics like Homework or Trips. Members pick one above the chat and new messages land in the topic they have open." />
      ) : (
        <div style={{ fontSize: 13.5, color: theme.muted, lineHeight: 1.5, padding: '4px 2px 14px' }}>Members pick a topic above the chat. New messages land in the topic they have open, and All shows everything.</div>
      )}
      {edit && (
        <div className="zchat-fade" style={{ padding: 14, borderRadius: 18, background: theme.rowBg, marginBottom: 16 }}>
          <div style={{ fontSize: 14, fontWeight: 700, color: theme.ink, marginBottom: 10 }}>{edit.id ? 'Edit topic' : 'New topic'}</div>
          <input value={edit.n} onChange={(e) => setEdit({ ...edit, n: e.target.value.slice(0, 24) })} onKeyDown={(e) => { if (e.key === 'Enter') { e.preventDefault(); saveEdit(); } }} placeholder="Topic name" aria-label="Topic name" autoFocus style={inputStyle(theme)} />
          <div role="radiogroup" aria-label="Topic colour" style={{ display: 'flex', gap: 10, flexWrap: 'wrap', margin: '14px 2px 16px' }}>
            {TOPIC_COLORS.map(([hex, name]) => (
              <div key={hex} role="radio" aria-checked={edit.c === hex} aria-label={name} onClick={() => setEdit({ ...edit, c: hex })} style={{ width: 30, height: 30, borderRadius: '50%', background: hex, cursor: 'pointer', boxShadow: edit.c === hex ? `0 0 0 2px ${theme.panelBg}, 0 0 0 4px ${hex}` : 'none', transition: 'box-shadow 0.15s ease' }} />
            ))}
          </div>
          <div style={{ display: 'flex', gap: 8 }}>
            <BigButton label="Cancel" tone="plain" onClick={() => { setEdit(null); setErr(''); }} style={{ flex: '0 0 110px' }} />
            <BigButton label={busy ? 'Saving' : edit.id ? 'Save' : 'Add topic'} disabled={busy || !edit.n.trim()} onClick={saveEdit} />
          </div>
        </div>
      )}
      {err && <div role="alert" style={{ fontSize: 13, fontWeight: 700, color: theme.danger, padding: '0 2px 12px' }}>{err}</div>}
      {list.map((t, i) => (
        <div key={t.id} style={{ display: 'flex', alignItems: 'center', gap: 12, padding: '12px 2px', borderBottom: i < list.length - 1 ? `1px solid ${theme.border}` : 'none' }}>
          <span style={{ width: 12, height: 12, borderRadius: '50%', background: t.c, flexShrink: 0 }} />
          <span style={{ flex: 1, minWidth: 0, fontSize: 15.5, fontWeight: 600, color: theme.ink, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{t.n}</span>
          <div role="button" aria-label={`Edit ${t.n}`} onClick={() => { setErr(''); setEdit({ id: t.id, n: t.n, c: t.c }); }} className="zchat-press" style={{ width: 38, height: 38, display: 'flex', alignItems: 'center', justifyContent: 'center', color: theme.ink, cursor: 'pointer' }}><Pencil size={17} /></div>
          <div role="button" aria-label={`Delete ${t.n}`} onClick={() => setDel(t)} className="zchat-press" style={{ width: 38, height: 38, display: 'flex', alignItems: 'center', justifyContent: 'center', color: theme.danger, cursor: 'pointer' }}><Trash2 size={17} /></div>
        </div>
      ))}
      {del && <ConfirmSheet title={`Delete ${del.n}?`} text="Its messages stay in the chat and move to General." confirmLabel="Delete topic" onCancel={() => setDel(null)} onConfirm={async () => { const t = del; setDel(null); await commit(list.filter((x) => x.id !== t.id)); }} zIndex={140} />}
    </FullPage>
  );
}
function JoinRequestsPage({ group, onClose, onReview }) {
  useBackClose(true, onClose);
  const { theme } = useTheme();
  const [rows, setRows] = useState(null);
  const [busyId, setBusyId] = useState(null);
  useEffect(() => {
    let alive = true;
    (async () => {
      const { data, error } = await supabase.from('group_join_requests').select('user_id, created_at, status').eq('group_id', group.id).eq('status', 'pending').order('created_at', { ascending: true }).limit(200);
      if (!alive) return;
      if (error || !data || !data.length) { setRows([]); return; }
      const ids = data.map((r) => r.user_id);
      const { data: profs } = await supabase.from('profiles').select('id, name, username, avatar, avatar_frame, nameplate, verified, custom_badge').in('id', ids);
      if (!alive) return;
      const byId = {};
      (profs || []).forEach((pr) => { byId[pr.id] = pr; });
      setRows(data.map((r) => ({ ...r, profile: byId[r.user_id] })).filter((r) => r.profile));
    })();
    return () => { alive = false; };
  }, [group.id]);
  const act = async (r, ok) => {
    if (busyId) return;
    setBusyId(r.user_id);
    const done = await onReview(r.profile, ok);
    setBusyId(null);
    if (done) setRows((prev) => (prev || []).filter((x) => x.user_id !== r.user_id));
  };
  const approveAll = async () => {
    for (const r of rows || []) {
      setBusyId(r.user_id);
      const done = await onReview(r.profile, true);
      if (done) setRows((prev) => (prev || []).filter((x) => x.user_id !== r.user_id));
    }
    setBusyId(null);
  };
  return (
    <FullPage title="Join requests" subtitle={group.name} onBack={onClose} zIndex={80}
      footer={rows && rows.length > 1 ? <BigButton label={busyId ? 'Approving' : `Approve all ${rows.length}`} disabled={!!busyId} onClick={approveAll} /> : null}>
      {rows === null && <div style={{ display: 'flex', justifyContent: 'center', padding: 34 }}><Spinner size={18} color={theme.muted} /></div>}
      {rows && !rows.length && <EmptyState art="requests" title="No one is waiting" text="When someone opens your invite link, their request shows up here." />}
      {(rows || []).map((r) => (
        <div key={r.user_id} style={{ display: 'flex', alignItems: 'center', gap: 12, padding: '10px 0' }}>
          <Avatar emoji={r.profile.avatar} name={r.profile.name} size={46} />
          <div style={{ flex: 1, minWidth: 0 }}>
            <div style={{ fontSize: 15, fontWeight: 700, color: theme.ink, minWidth: 0 }}><NameBadge name={r.profile.name} verified={r.profile.verified} custom={r.profile.custom_badge} size={13} /></div>
            <div style={{ fontSize: 12.5, color: theme.muted, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis', marginTop: 1 }}>{timeAgoLong(r.created_at)}</div>
          </div>
          {busyId === r.user_id ? <Spinner size={16} color={theme.muted} /> : (
            <>
              <div role="button" aria-label={`Decline ${r.profile.name}`} onClick={() => act(r, false)} className="zchat-press" style={{ width: 36, height: 36, borderRadius: '50%', border: `1px solid ${theme.border}`, boxSizing: 'border-box', display: 'flex', alignItems: 'center', justifyContent: 'center', color: theme.ink, cursor: 'pointer', flexShrink: 0 }}><X size={16} /></div>
              <div role="button" aria-label={`Approve ${r.profile.name}`} onClick={() => act(r, true)} className="zchat-press" style={{ height: 36, padding: '0 15px', borderRadius: 18, background: theme.coral, color: '#FFFFFF', fontSize: 13.5, fontWeight: 700, display: 'flex', alignItems: 'center', cursor: 'pointer', flexShrink: 0 }}>Approve</div>
            </>
          )}
        </div>
      ))}
    </FullPage>
  );
}

function GroupSettingsPanel({ group, myId, isAdmin, isOwner, isMuted, onSetMute, isPinned, onTogglePin, onClose, onLeave, onDeleteGroup, onOpenAdmins, onOpenEdit, disappearSecs, onSetDisappear, topicsCount, onOpenTopics, pendingJoins, onOpenJoinRequests, onJoinApproval }) {
  useBackClose(true, onClose);
  const [showDisappear, setShowDisappear] = useState(false);
  const { theme } = useTheme();
  const [showMuteOptions, setShowMuteOptions] = useState(false);
  useBackClose(showMuteOptions, () => setShowMuteOptions(false));
  const [addPolicy, setAddPolicy] = useState(group.add_members_policy || 'everyone');
  const [sendPolicy, setSendPolicy] = useState(group.send_policy || 'everyone');
  const [slowSecs, setSlowSecs] = useState(Number(group.slow_secs || 0));
  const [mentionAll, setMentionAll] = useState(group.mention_all || 'everyone');
  const [slowSheet, setSlowSheet] = useState(false);
  const [mentionSheet, setMentionSheet] = useState(false);
  const [inviteCode, setInviteCode] = useState(group.invite_code || '');
  const [inviteEnabled, setInviteEnabled] = useState(group.invite_enabled !== false);
  const [joinApproval, setJoinApproval] = useState(!!group.join_approval);
  const [copied, setCopied] = useState(false);
  const [activity, setActivity] = useState(null);
  const [confirmDelete, setConfirmDelete] = useState(false);
  const [busy, setBusy] = useState(false);

  useEffect(() => {
    let alive = true;
    (async () => {
      const since = new Date(Date.now() - 7 * 86400000).toISOString();
      const { data } = await supabase.from('messages').select('sender_id, created_at').eq('group_id', group.id).gte('created_at', since).order('created_at', { ascending: false }).limit(500);
      if (!alive) return;
      const rows = data || [];
      const counts = {};
      rows.forEach((r) => { if (r.sender_id) counts[r.sender_id] = (counts[r.sender_id] || 0) + 1; });
      const topId = Object.keys(counts).sort((a, b) => counts[b] - counts[a])[0] || null;
      let topProfile = null;
      if (topId) {
        const { data: prof } = await supabase.from('profiles').select('id, name, username').eq('id', topId).maybeSingle();
        topProfile = prof;
      }
      setActivity({
        weekCount: rows.length,
        top: topProfile ? { name: topProfile.name || topProfile.username, count: counts[topId] } : null,
        lastActivity: rows[0] ? rows[0].created_at : null,
      });
    })();
    return () => { alive = false; };
  }, [group.id]);

  const savePolicy = async (field, value, setter) => {
    setter(value);
    const { error } = await supabase.from('groups').update({ [field]: value }).eq('id', group.id);
    if (error) appAlert(friendlyError(error, "Couldn't save that. Try again."));
  };
  const resetInvite = async () => {
    const fresh = Math.random().toString(36).slice(2, 10);
    setInviteCode(fresh);
    await supabase.from('groups').update({ invite_code: fresh }).eq('id', group.id);
  };
  const toggleInvite = async () => {
    const next = !inviteEnabled;
    setInviteEnabled(next);
    await supabase.from('groups').update({ invite_enabled: next }).eq('id', group.id);
  };
  const copyInvite = async () => {
    const link = `${siteOrigin()}/?join=${inviteCode}`;
    try { if (navigator.share) await navigator.share({ title: `Join ${group.name} on ZChat`, text: `Join the group ${group.name} on ZChat`, url: link }); else { await navigator.clipboard.writeText(link); setCopied(true); setTimeout(() => setCopied(false), 1800); } } catch {}
  };
  const doDelete = async () => {
    if (busy) return;
    setBusy(true);
    await onDeleteGroup();
  };

  const muteLabel = isMuted === true ? 'Muted' : isMuted ? `Muted until ${fmtDate(new Date(isMuted), { month: 'short', day: 'numeric' })}` : 'Off';

  const c = igPalette(theme);
  const segRow = (label, value, onPick) => (
    <div style={{ padding: '12px 14px' }}>
      <div style={{ fontSize: 15, fontWeight: 500, marginBottom: 9 }}>{label}</div>
      <div style={{ display: 'flex', gap: 8 }}>
        {[['everyone', 'Everyone'], ['admins', 'Admins only']].map(([val, lab]) => (
          <div key={val} role="button" aria-label={`${label} ${lab}`} aria-pressed={value === val} onClick={() => onPick(val)} style={{
            flex: 1, textAlign: 'center', padding: '9px 6px', borderRadius: 11, fontSize: 13.5, fontWeight: 700, cursor: 'pointer',
            background: value === val ? theme.coral : c.field, color: value === val ? '#FFFFFF' : c.fg,
          }}>{lab}</div>
        ))}
      </div>
    </div>
  );
  return (
    <>
    <WideDim onClose={onClose} z={34} />
    <div style={{ position: 'fixed', inset: 0, background: c.bg, color: c.fg, zIndex: 34, display: 'flex', flexDirection: 'column', overflow: 'hidden', fontFamily: FONT }} className="zchat-panel-open zchat-wide-page">
      <IgTopBar title="Group settings" onBack={onClose} />
      <div style={{ flex: 1, minHeight: 0, overflowY: 'auto', WebkitOverflowScrolling: 'touch', paddingBottom: 'calc(28px + env(safe-area-inset-bottom))' }}>
        <DetailSection title="Your settings">
          {detailRows([
            <DetailRow icon={isMuted ? <BellOff /> : <Bell />} label="Mute notifications" value={muteLabel} onClick={() => setShowMuteOptions(true)} />,
            <DetailRow icon={<Pin_ color="currentColor" />} label="Pin group" onClick={onTogglePin} right={<IgToggle on={!!isPinned} />} />,
            <DetailRow icon={<Timer />} label="Disappearing messages" value={disappearLabel(disappearSecs)} onClick={() => setShowDisappear(true)} />,
          ])}
        </DetailSection>
        {showDisappear && <DisappearSheet value={disappearSecs} subject="this group" canEdit={isAdmin} onPick={onSetDisappear} onClose={() => setShowDisappear(false)} />}

        {isAdmin && (
          <>
            <DetailSection title="Admin controls">
              {detailRows([
                <DetailRow icon={<Pencil />} label="Edit name, photo and description" onClick={onOpenEdit} />,
                <DetailRow icon={<ShieldCheck />} label="Manage members and admins" onClick={onOpenAdmins} />,
                <DetailRow icon={<TopicHashIcon />} label="Topics" sub="Split the chat into subjects" value={topicsCount ? String(topicsCount) : 'Off'} onClick={onOpenTopics} />,
              ])}
            </DetailSection>
            <DetailSection title="Permissions">
              {segRow('Who can add members', addPolicy, (val) => savePolicy('add_members_policy', val, setAddPolicy))}
              <div style={{ height: 1, background: theme.border, marginLeft: 14 }} />
              {segRow('Who can send messages', sendPolicy, (val) => savePolicy('send_policy', val, setSendPolicy))}
              <div style={{ height: 1, background: theme.border, marginLeft: 14 }} />
              <DetailRow icon={<Timer />} label="Slow mode" sub="Members wait between messages" value={slowModeLabel(slowSecs)} onClick={() => setSlowSheet(true)} />
              <DetailRow icon={<AtSign />} label="Mention everyone" sub="Who can use @everyone" value={mentionAll === 'admins' ? 'Admins only' : 'Everyone'} onClick={() => setMentionSheet(true)} last />
            </DetailSection>
            <DetailSection title="Invite link">
              <DetailRow icon={<LinkIcon />} label="Invite link" sub={inviteEnabled ? 'Anyone with the link can join' : 'Turned off'} onClick={toggleInvite} right={<IgToggle on={inviteEnabled} />} last={!inviteEnabled} />
              {inviteEnabled && (
                <div style={{ padding: '2px 14px 14px 46px' }}>
                  <div style={{ fontSize: 12.5, color: c.dim, marginBottom: 9, wordBreak: 'break-all' }}>{siteOrigin()}/?join={inviteCode}</div>
                  <div style={{ display: 'flex', gap: 8 }}>
                  <div role="button" aria-label="Share invite link" onClick={copyInvite} style={{ flex: 1, textAlign: 'center', padding: '9px 6px', borderRadius: 10, fontSize: 13.5, fontWeight: 700, cursor: 'pointer', background: theme.coral, color: '#FFFFFF' }}>{copied ? 'Copied' : 'Share link'}</div>
                  <div role="button" aria-label="Reset invite link" onClick={resetInvite} style={{ flex: 1, textAlign: 'center', padding: '9px 6px', borderRadius: 10, fontSize: 13.5, fontWeight: 700, cursor: 'pointer', background: c.field, color: c.fg }}>Reset link</div>
                  </div>
                </div>
              )}
            </DetailSection>
            <DetailSection title="New members">
              <DetailRow icon={<UserPlus />} label="Approve new members" sub="An admin says yes before people join with the link" onClick={async () => { const next = !joinApproval; setJoinApproval(next); const ok = await onJoinApproval(next); if (!ok) setJoinApproval(!next); }} right={<IgToggle on={joinApproval} />} last={!joinApproval} />
              {joinApproval && <DetailRow icon={<Users />} label="Join requests" value={pendingJoins ? String(pendingJoins) : 'None'} onClick={onOpenJoinRequests} last />}
            </DetailSection>
          </>
        )}

        <DetailSection title="Activity">
          {activity === null ? (
            <div style={{ padding: 20, textAlign: 'center' }}><Spinner size={18} color={c.dim} /></div>
          ) : detailRows([
            activity.top ? <DetailRow icon={<Users />} label="Most active this week" sub={`${activity.top.name}, ${activity.top.count} messages`} /> : null,
            <DetailRow icon={<Clock />} label="Last activity" sub={activity.lastActivity ? timeAgoLong(activity.lastActivity) : 'No messages this week'} />,
          ])}
        </DetailSection>

        <DetailSection>
          {detailRows([
            <DetailRow icon={<LogOut />} label="Leave group" danger onClick={onLeave} />,
            isOwner ? <DetailRow icon={<Trash2 />} label="Delete group" danger onClick={() => setConfirmDelete(true)} /> : null,
          ])}
        </DetailSection>
      </div>

      {showMuteOptions && (
        <div onClick={() => setShowMuteOptions(false)} style={{ position: 'fixed', inset: 0, zIndex: 60, background: 'rgba(0,0,0,0.5)', display: 'flex', alignItems: 'flex-end' }}>
          <div onClick={(e) => e.stopPropagation()} className="zchat-sheet-up" style={{ width: '100%', background: theme.panelBg, borderRadius: '22px 22px 0 0', padding: '18px 18px calc(18px + env(safe-area-inset-bottom))' }}>
            <div style={{ fontWeight: 900, fontSize: 16, color: theme.ink, marginBottom: 12 }}>Mute notifications</div>
            {[['Off', null], ['8 hours', 8 * 3600000], ['1 week', 7 * 86400000], ['Always', 'forever']].map(([label, ms]) => (
              <div key={label} role="button" onClick={() => { onSetMute(ms === 'forever' ? new Date('2999-01-01').toISOString() : ms ? new Date(Date.now() + ms).toISOString() : null); setShowMuteOptions(false); }}
                style={{ padding: '13px 6px', fontSize: 15, fontWeight: 700, color: theme.ink, cursor: 'pointer', borderBottom: `1px solid ${theme.border}` }}>{label}</div>
            ))}
          </div>
        </div>
      )}

      {slowSheet && <SlowModeSheet value={slowSecs} onClose={() => setSlowSheet(false)} onPick={(v) => savePolicy('slow_secs', v, setSlowSecs)} />}
      {mentionSheet && <MentionAllSheet value={mentionAll} onClose={() => setMentionSheet(false)} onPick={(v) => savePolicy('mention_all', v, setMentionAll)} />}
      {confirmDelete && (
        <ConfirmDialog
          title={`Delete ${group.name}?`}
          body="This removes the group and its messages for everyone. This can't be undone."
          confirmLabel="Delete group"
          danger
          onCancel={() => setConfirmDelete(false)}
          onConfirm={doDelete}
        />
      )}
    </div>
    </>
  );
}

function GroupMembersPanel({ group, members, myId, isAdmin, isOwner, onClose, onOpenProfile, onAddMembers, onPromote, onDemote, onKick, onMute, onUnmute, onTransferOwnership, onSetTitle }) {
  useBackClose(true, onClose);
  const { theme } = useTheme();
  const [q, setQ] = useState('');
  const [tab, setTab] = useState('all');
  const [sheetFor, setSheetFor] = useState(null);
  const [titleFor, setTitleFor] = useState(null);
  useBackClose(!!sheetFor, () => setSheetFor(null));

  const isOnline = (m) => m.profile && !m.profile.hide_activity && m.profile.last_seen && Date.now() - new Date(m.profile.last_seen).getTime() < 3 * 60 * 1000;
  const onlineCount = members.filter(isOnline).length;
  const adminCount = members.filter((m) => m.role === 'admin' || m.user_id === group.created_by).length;

  const filtered = members
    .filter((m) => (tab === 'online' ? isOnline(m) : tab === 'admins' ? (m.role === 'admin' || m.user_id === group.created_by) : true))
    .filter((m) => !q.trim() || (m.profile.name || '').toLowerCase().includes(q.trim().toLowerCase()) || (m.profile.username || '').toLowerCase().includes(q.trim().toLowerCase()))
    .sort((a, b) => {
      const rank = (m) => (m.user_id === group.created_by ? 0 : m.role === 'admin' ? 1 : 2);
      return rank(a) - rank(b) || (a.profile.name || '').localeCompare(b.profile.name || '');
    });

  const sheetMember = sheetFor ? members.find((m) => m.user_id === sheetFor) : null;

  return (
    <>
    <WideDim onClose={onClose} z={35} />
    <div style={{ position: 'fixed', inset: 0, background: theme.bgGradient, zIndex: 35, display: 'flex', flexDirection: 'column', overflow: 'hidden' }} className="zchat-panel-open zchat-wide-page">
      <IgTopBar title="Members" onBack={onClose} right={isAdmin ? <div role="button" aria-label="Add members" onClick={onAddMembers} style={{ fontSize: 14, fontWeight: 800, color: theme.coral, cursor: 'pointer', padding: '0 10px', height: 44, display: 'flex', alignItems: 'center' }}>Add</div> : null} />
      <div style={{ padding: '12px 18px 0', flexShrink: 0 }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: 8, height: 40, borderRadius: 13, background: theme.rowBg, border: `1px solid ${theme.border}`, padding: '0 12px' }}>
          <Search size={15} color={theme.muted} />
          <input value={q} onChange={(e) => setQ(e.target.value)} placeholder="Search members" style={{ flex: 1, border: 'none', outline: 'none', background: 'transparent', color: theme.ink, fontSize: 14, fontFamily: FONT }} />
        </div>
        <div style={{ display: 'flex', gap: 6, marginTop: 10, overflowX: 'auto', scrollbarWidth: 'none' }}>
          {[['all', `All ${members.length}`], ['online', `Online ${onlineCount}`], ['admins', `Admins ${adminCount}`]].map(([k, label]) => {
            const on = tab === k;
            return (
              <div key={k} role="button" onClick={() => setTab(k)} style={{ flexShrink: 0, padding: '8px 14px', borderRadius: 12, fontSize: 12.5, fontWeight: 800, cursor: 'pointer', background: on ? theme.coral : theme.rowBg, color: on ? 'white' : theme.ink, border: `1px solid ${on ? theme.coral : theme.border}` }}>{label}</div>
            );
          })}
        </div>
      </div>
      <div style={{ flex: 1, minHeight: 0, overflowY: 'auto', WebkitOverflowScrolling: 'touch', padding: '10px 18px', paddingBottom: 'calc(10px + env(safe-area-inset-bottom))' }}>
        {filtered.length === 0 ? (
          <div style={{ textAlign: 'center', padding: 30, color: theme.muted, fontSize: 13.5 }}>No members match.</div>
        ) : filtered.map((m) => (
          <div key={m.user_id} role="button" onClick={() => (isAdmin && m.user_id !== myId && m.user_id !== group.created_by ? setSheetFor(m.user_id) : onOpenProfile(m.profile))}
            style={{ display: 'flex', alignItems: 'center', gap: 10, padding: '10px 4px', cursor: 'pointer' }}>
            <Avatar emoji={m.profile.avatar} name={m.profile.name} size={42} />
            <div style={{ flex: 1, minWidth: 0 }}>
              <div style={{ fontWeight: 700, fontSize: 14, color: theme.ink, display: 'flex', alignItems: 'center', gap: 6 }}>
                <span style={{ whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{m.profile.name}</span><VerifiedBadge tier={m.profile.verified} custom={m.profile.custom_badge} size={12} />
                {m.title && <span style={{ flexShrink: 0, fontSize: 10, fontWeight: 800, padding: '1px 6px', borderRadius: 7, background: theme.rowBg, color: theme.muted }}>{m.title}</span>}
              </div>
              <div style={{ fontSize: 11.5, color: theme.muted, display: 'flex', gap: 6, alignItems: 'center' }}>
                {isOnline(m) ? <span style={{ color: '#22c55e', fontWeight: 700 }}>Online</span> : (m.profile.last_seen ? timeAgoLong(m.profile.last_seen) : '')}
              </div>
            </div>
            {m.user_id === group.created_by ? (
              <span style={{ fontSize: 9.5, fontWeight: 900, padding: '2px 7px', borderRadius: 8, background: 'rgba(251,191,36,0.15)', color: '#fbbf24' }}>Owner</span>
            ) : m.role === 'admin' && <span style={{ fontSize: 9.5, fontWeight: 900, padding: '2px 7px', borderRadius: 8, background: 'rgba(96,165,250,0.15)', color: '#60a5fa' }}>Admin</span>}
          </div>
        ))}
      </div>

      {titleFor && onSetTitle && <MemberTitleSheet member={titleFor} onClose={() => setTitleFor(null)} onSave={(t) => onSetTitle(titleFor.user_id, t)} />}
      {sheetMember && (
        <div onClick={() => setSheetFor(null)} style={{ position: 'fixed', inset: 0, zIndex: 60, background: 'rgba(0,0,0,0.5)', display: 'flex', alignItems: 'flex-end' }}>
          <div onClick={(e) => e.stopPropagation()} className="zchat-sheet-up" style={{ width: '100%', background: theme.panelBg, borderRadius: '22px 22px 0 0', padding: '18px 18px calc(18px + env(safe-area-inset-bottom))' }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: 10, marginBottom: 14 }}>
              <Avatar emoji={sheetMember.profile.avatar} name={sheetMember.profile.name} size={42} />
              <div>
                <div style={{ fontWeight: 900, fontSize: 15, color: theme.ink }}>{sheetMember.profile.name}</div>
                <div style={{ fontSize: 12, color: theme.muted }}>@{sheetMember.profile.username}</div>
              </div>
            </div>
            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 8 }}>
              <div role="button" onClick={() => { setSheetFor(null); onOpenProfile(sheetMember.profile); }} style={{ padding: '12px 8px', borderRadius: 13, background: theme.rowBg, textAlign: 'center', fontSize: 13, fontWeight: 700, color: theme.ink, cursor: 'pointer' }}>View profile</div>
              {isOwner && (sheetMember.role === 'admin' ? (
                <div role="button" onClick={() => { onDemote(sheetMember.user_id); setSheetFor(null); }} style={{ padding: '12px 8px', borderRadius: 13, background: theme.rowBg, textAlign: 'center', fontSize: 13, fontWeight: 700, color: theme.ink, cursor: 'pointer' }}>Remove admin</div>
              ) : (
                <div role="button" onClick={() => { onPromote(sheetMember.user_id); setSheetFor(null); }} style={{ padding: '12px 8px', borderRadius: 13, background: theme.rowBg, textAlign: 'center', fontSize: 13, fontWeight: 700, color: theme.ink, cursor: 'pointer' }}>Make admin</div>
              ))}
              {sheetMember.muted ? (
                <div role="button" onClick={() => { onUnmute(sheetMember.user_id); setSheetFor(null); }} style={{ padding: '12px 8px', borderRadius: 13, background: theme.rowBg, textAlign: 'center', fontSize: 13, fontWeight: 700, color: theme.ink, cursor: 'pointer' }}>Unmute in group</div>
              ) : (
                <div role="button" onClick={() => { onMute(sheetMember.user_id); setSheetFor(null); }} style={{ padding: '12px 8px', borderRadius: 13, background: theme.rowBg, textAlign: 'center', fontSize: 13, fontWeight: 700, color: theme.ink, cursor: 'pointer' }}>Mute in group</div>
              )}
              {onSetTitle && <div role="button" aria-label="Give a title" onClick={() => { setTitleFor(sheetMember); setSheetFor(null); }} style={{ padding: '12px 8px', borderRadius: 13, background: theme.rowBg, textAlign: 'center', fontSize: 13, fontWeight: 700, color: theme.ink, cursor: 'pointer' }}>{sheetMember.title ? 'Change title' : 'Give a title'}</div>}
              <div role="button" onClick={() => { onKick(sheetMember.user_id); setSheetFor(null); }} style={{ padding: '12px 8px', borderRadius: 13, background: `${theme.danger}1A`, textAlign: 'center', fontSize: 13, fontWeight: 700, color: theme.danger, cursor: 'pointer' }}>Remove</div>
            </div>
          </div>
        </div>
      )}
    </div>
    </>
  );
}
function AddMembersPanel({ myId, existingIds, onClose, onAdd, iFollowIds, privacyAllowed }) {
  useBackClose(true, onClose);
  const { theme } = useTheme();
  const [q, setQ] = useState('');
  const [results, setResults] = useState([]);
  const [selected, setSelected] = useState([]);
  const timer = useRef(null);

  const [suggested, setSuggested] = useState([]);
  useEffect(() => {
    let alive = true;
    (async () => {
      const { data: f } = await supabase.from('follows').select('following_id').eq('follower_id', myId).eq('status', 'accepted').limit(200);
      const ids = (f || []).map((x) => x.following_id);
      if (!ids.length) return;
      const { data: profs } = await supabase.from('profiles').select('*').in('id', ids).eq('is_deleted', false);
      if (!alive) return;
      const list = sanitizeAvatarList(profs, myId)
        .filter((u) => !existingIds.includes(u.id))
        .filter((u) => privacyAllows(u, 'privacy_groups', myId, iFollowIds, privacyAllowed))
        .sort((a, b) => (a.name || '').localeCompare(b.name || ''));
      setSuggested(list);
      setResults(list);
    })();
    return () => { alive = false; };
  }, [myId]);
  const doSearch = (val) => {
    setQ(val);
    clearTimeout(timer.current);
    if (val.trim().length < 2) { setResults(suggested); return; }
    timer.current = setTimeout(async () => {
      const { data } = await searchAccounts(val.trim());
      setResults(sanitizeAvatarList(data, myId).filter((u) => u.id !== myId && !existingIds.includes(u.id) && !selected.find((s) => s.id === u.id)));
    }, 300);
  };

  const toggleSelect = (p) => {
    setSelected((prev) => (prev.find((s) => s.id === p.id) ? prev.filter((s) => s.id !== p.id) : [...prev, p]));
  };

  return (
    <>
    <WideDim onClose={onClose} z={45} />
    <div style={{ position: 'fixed', inset: 0, background: theme.bgGradient, zIndex: 45, display: 'flex', flexDirection: 'column' }} className="zchat-panel-open zchat-wide-page">
      <IgTopBar title="Add members" subtitle={selected.length ? `${selected.length} selected` : undefined} onBack={onClose} />
      <div style={{ padding: '14px 18px 8px' }}>
        <div style={{ position: 'relative' }}>
          <Search size={15} color={theme.muted} style={{ position: 'absolute', left: 12, top: 12 }} />
          <input value={q} onChange={(e) => doSearch(e.target.value)} placeholder="Search username" autoCapitalize="none"
            style={{ ...inputStyle(theme), padding: '9px 12px 9px 34px', fontSize: 13.5 }} />
        </div>
      </div>
      <div style={{ overflowY: 'auto', flex: 1, padding: '0 18px' }}>
        {results.map((p) => (
          <div key={p.id} onClick={() => toggleSelect(p)} style={{ display: 'flex', alignItems: 'center', gap: 12, padding: '9px 4px', cursor: 'pointer' }}>
            <Avatar emoji={p.avatar} name={p.name} size={40} />
            <div style={{ flex: 1, minWidth: 0 }}>
              <div style={{ fontWeight: 700, fontSize: 14, color: theme.ink, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}><NameBadge name={p.name} verified={p.verified} custom={p.custom_badge} size={12} /></div>
              <div style={{ fontSize: 11.5, color: theme.muted, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>@{p.username}</div>
            </div>
            <div style={{
              width: 20, height: 20, borderRadius: '50%', border: `2px solid ${selected.find((s) => s.id === p.id) ? theme.coral : theme.border}`,
              background: selected.find((s) => s.id === p.id) ? theme.coral : 'transparent',
            }} />
          </div>
        ))}
      </div>
      <div style={{ padding: 18, paddingBottom: 'calc(18px + env(safe-area-inset-bottom))' }}>
        <button onClick={() => onAdd(selected)} disabled={selected.length === 0} style={primaryBtn(theme, selected.length === 0)}>
          Add {selected.length || ''}
        </button>
      </div>
    </div>
    </>
  );
}


function PrivacyField({ label, hidden, onToggle, last }) {
  const { theme } = useTheme();
  return (
    <div role="button" aria-label={label} onClick={onToggle} style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '13px 2px', borderBottom: last ? 'none' : `1px solid ${theme.border}`, cursor: 'pointer' }}>
      <span style={{ fontSize: 15, fontWeight: 600, color: theme.ink }}>{label}</span>
      <ToggleSwitch on={!hidden} onClick={(e) => { e.stopPropagation(); onToggle(); }} />
    </div>
  );
}

function AccountPrivacyPanel({ profile, onClose, onSaved }) {
  useBackClose(true, onClose);
  const { theme } = useTheme();
  const [isPrivate, setIsPrivate] = useState(profile.is_private || false);
  const [hidePhoto, setHidePhoto] = useState(profile.hide_photo || false);
  const [hideBio, setHideBio] = useState(profile.hide_bio || false);
  const [hideGender] = useState(profile.hide_gender || false);
  const [hideAge, setHideAge] = useState(profile.hide_age || false);
  const [hideCountry, setHideCountry] = useState(profile.hide_country || false);
  const [saving, setSaving] = useState(false);

  const save = async () => {
    setSaving(true);
    const { data } = await updateProfile(profile.id, {
      is_private: isPrivate, hide_photo: hidePhoto, hide_bio: hideBio,
      hide_gender: hideGender, hide_age: hideAge, hide_country: hideCountry,
    });
    setSaving(false);
    if (data) { onSaved(data); onClose(); }
  };

  const dirty = isPrivate !== !!profile.is_private || hidePhoto !== !!profile.hide_photo || hideBio !== !!profile.hide_bio || hideGender !== !!profile.hide_gender || hideAge !== !!profile.hide_age || hideCountry !== !!profile.hide_country;
  return (
    <FullPage title="Privacy" onBack={onClose} zIndex={60}
      footer={<button onClick={save} disabled={saving || !dirty} className="zchat-press" style={{ ...primaryBtn(theme, saving || !dirty) }}>{saving ? <Spinner /> : 'Save changes'}</button>}>
      <div style={{ marginTop: 6 }}>
        <div role="button" aria-label="Private account" onClick={() => setIsPrivate((s) => !s)} style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 12, padding: '13px 2px', cursor: 'pointer' }}>
          <div style={{ minWidth: 0 }}>
            <div style={{ fontSize: 15, fontWeight: 700, color: theme.ink }}>Private account</div>
            <div style={{ fontSize: 12.5, color: theme.muted, marginTop: 2, lineHeight: 1.4 }}>New followers need your approval before they see your posts</div>
          </div>
          <ToggleSwitch on={isPrivate} onClick={(e) => { e.stopPropagation(); setIsPrivate((s) => !s); }} />
        </div>
      </div>
      <div style={{ padding: '22px 2px 4px', fontSize: 13, fontWeight: 600, color: theme.muted }}>Visible to others</div>
      <div>
        <PrivacyField label="Profile photo" hidden={hidePhoto} onToggle={() => setHidePhoto((s) => !s)} />
        <PrivacyField label="Bio" hidden={hideBio} onToggle={() => setHideBio((s) => !s)} />
        <PrivacyField label="Age" hidden={hideAge} onToggle={() => setHideAge((s) => !s)} />
        <PrivacyField label="Country" hidden={hideCountry} onToggle={() => setHideCountry((s) => !s)} last />
      </div>
      <div style={{ padding: '14px 2px 0', fontSize: 12.5, color: theme.muted, lineHeight: 1.6 }}>Switch something off and it disappears from your profile for everyone except you.</div>
    </FullPage>
  );
}

const PROFILE_LINK_REGEX = /^https?:\/\/[^\s/]+\/\?profile=([0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})$/i;

const CHAT_HISTORY_LIMIT = 800;
const CHAT_MEDIA_LIMIT = 3000;
const PUBLIC_SITE_URL = 'https://getzchat.com';
function siteOrigin() {
  if (typeof window === 'undefined') return PUBLIC_SITE_URL;
  const host = window.location.hostname;
  if (host === 'localhost' || host === '127.0.0.1' || host.endsWith('.local')) return window.location.origin;
  return PUBLIC_SITE_URL;
}

function profileShareLink(profileId) {
  const origin = siteOrigin();
  return `${origin}/?profile=${profileId}`;
}

function parseProfileLink(text) {
  if (!text) return null;
  const match = String(text).trim().match(PROFILE_LINK_REGEX);
  return match ? match[1] : null;
}

async function copyTextToClipboard(text) {
  try {
    if (navigator.clipboard?.writeText) { await navigator.clipboard.writeText(text); return true; }
  } catch {}
  try {
    const ta = document.createElement('textarea');
    ta.value = text;
    ta.style.position = 'fixed';
    ta.style.opacity = '0';
    document.body.appendChild(ta);
    ta.select();
    const ok = document.execCommand('copy');
    document.body.removeChild(ta);
    return ok;
  } catch {
    return false;
  }
}

const sharedProfileCache = new Map();

function ProfileLinkCard({ profileId, onOpen }) {
  const { theme } = useTheme();
  const [p, setP] = useState(() => sharedProfileCache.get(profileId));

  useEffect(() => {
    if (sharedProfileCache.has(profileId)) { setP(sharedProfileCache.get(profileId)); return undefined; }
    let cancelled = false;
    getProfile(profileId)
      .then(({ data }) => {
        const value = data && !data.is_deleted ? data : null;
        sharedProfileCache.set(profileId, value);
        if (!cancelled) setP(value);
      })
      .catch(() => { if (!cancelled) setP(null); });
    return () => { cancelled = true; };
  }, [profileId]);

  if (p === undefined) {
    return (
      <div style={{ width: 210, height: 176, borderRadius: 16, background: theme.rowBg, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
        <Spinner size={16} color={theme.muted} />
      </div>
    );
  }
  if (p === null) {
    return (
      <div style={{ width: 210, borderRadius: 16, background: theme.rowBg, padding: '18px 14px', textAlign: 'center', fontSize: 12.5, color: theme.muted }}>
        This profile is not available
      </div>
    );
  }
  const photo = p.hide_photo ? '' : p.avatar;
  const hasPhoto = typeof photo === 'string' && photo.startsWith('http');
  return (
    <div style={{ width: 210, borderRadius: 16, overflow: 'hidden', background: theme.rowBg }}>
      <div style={{ height: 110, position: 'relative', background: hasPhoto ? '#000' : colorForName(p.name) }}>
        {hasPhoto ? (
          <img src={photo} alt="" draggable={false} onContextMenu={(e) => e.preventDefault()} style={{ width: '100%', height: '100%', objectFit: 'cover', display: 'block' }} />
        ) : (
          <div style={{ position: 'absolute', inset: 0, display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 44, fontWeight: 800, color: 'rgba(255,255,255,0.92)' }}>
            {(p.name || '?').trim().charAt(0).toUpperCase()}
          </div>
        )}
        <div style={{ position: 'absolute', left: 0, right: 0, bottom: 0, padding: '18px 10px 6px', background: 'linear-gradient(180deg, rgba(0,0,0,0) 0%, rgba(0,0,0,0.7) 100%)', color: 'white' }}>
          <div style={{ fontSize: 14, fontWeight: 800, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}><NameBadge name={p.name} verified={p.verified} custom={p.custom_badge} size={12} /></div>
          <div style={{ fontSize: 11, opacity: 0.85, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>@{p.username}</div>
        </div>
      </div>
      <div onPointerDown={(e) => e.stopPropagation()} onClick={(e) => { e.stopPropagation(); if (onOpen) onOpen(p); }} style={{
        margin: 8, padding: '8px 0', borderRadius: 12, background: theme.coral, color: 'white', textAlign: 'center',
        fontSize: 12.5, fontWeight: 700, cursor: 'pointer',
      }}>View profile</div>
    </div>
  );
}

const QR_ECC_PER_BLOCK = [-1, 10, 16, 26, 18, 24, 16, 18, 22, 22, 26, 30, 22, 22, 24, 24, 28, 28, 26, 26, 26];
const QR_BLOCKS = [-1, 1, 1, 1, 2, 2, 4, 4, 4, 5, 5, 5, 8, 9, 9, 10, 10, 11, 13, 14, 16];
function qrRawModules(ver) {
  let result = (16 * ver + 128) * ver + 64;
  if (ver >= 2) {
    const n = Math.floor(ver / 7) + 2;
    result -= (25 * n - 10) * n - 55;
    if (ver >= 7) result -= 36;
  }
  return result;
}
function qrDataCodewords(ver) { return Math.floor(qrRawModules(ver) / 8) - QR_ECC_PER_BLOCK[ver] * QR_BLOCKS[ver]; }
function qrMul(x, y) {
  let z = 0;
  for (let i = 7; i >= 0; i--) {
    z = (z << 1) ^ ((z >>> 7) * 0x11D);
    z ^= ((y >>> i) & 1) * x;
  }
  return z & 0xFF;
}
function qrDivisor(degree) {
  const result = [];
  for (let i = 0; i < degree - 1; i++) result.push(0);
  result.push(1);
  let root = 1;
  for (let i = 0; i < degree; i++) {
    for (let j = 0; j < result.length; j++) {
      result[j] = qrMul(result[j], root);
      if (j + 1 < result.length) result[j] ^= result[j + 1];
    }
    root = qrMul(root, 0x02);
  }
  return result;
}
function qrRemainder(data, divisor) {
  const result = divisor.map(() => 0);
  data.forEach((b) => {
    const factor = b ^ result.shift();
    result.push(0);
    divisor.forEach((coef, i) => { result[i] ^= qrMul(coef, factor); });
  });
  return result;
}
function qrAlignments(ver) {
  if (ver === 1) return [];
  const n = Math.floor(ver / 7) + 2;
  const step = Math.ceil((ver * 4 + 4) / (n * 2 - 2)) * 2;
  const result = [6];
  for (let pos = ver * 4 + 10; result.length < n; pos -= step) result.splice(1, 0, pos);
  return result;
}
function qrMatrix(text) {
  const bytes = Array.from(new TextEncoder().encode(String(text || '')));
  let ver = 1;
  while (ver <= 20 && qrDataCodewords(ver) * 8 < 4 + (ver <= 9 ? 8 : 16) + bytes.length * 8) ver += 1;
  if (ver > 20) return null;
  const bits = [];
  const put = (val, len) => { for (let i = len - 1; i >= 0; i--) bits.push((val >>> i) & 1); };
  put(4, 4);
  put(bytes.length, ver <= 9 ? 8 : 16);
  bytes.forEach((b) => put(b, 8));
  const cap = qrDataCodewords(ver) * 8;
  put(0, Math.min(4, cap - bits.length));
  put(0, (8 - (bits.length % 8)) % 8);
  for (let pad = 0xEC; bits.length < cap; pad ^= 0xEC ^ 0x11) put(pad, 8);
  const data = [];
  for (let i = 0; i < bits.length; i += 8) {
    let v = 0;
    for (let j = 0; j < 8; j++) v = (v << 1) | bits[i + j];
    data.push(v);
  }
  const numBlocks = QR_BLOCKS[ver];
  const eccLen = QR_ECC_PER_BLOCK[ver];
  const raw = Math.floor(qrRawModules(ver) / 8);
  const numShort = numBlocks - (raw % numBlocks);
  const shortLen = Math.floor(raw / numBlocks);
  const div = qrDivisor(eccLen);
  const blocks = [];
  for (let i = 0, k = 0; i < numBlocks; i++) {
    const dat = data.slice(k, k + shortLen - eccLen + (i < numShort ? 0 : 1));
    k += dat.length;
    const ecc = qrRemainder(dat, div);
    if (i < numShort) dat.push(0);
    blocks.push(dat.concat(ecc));
  }
  const words = [];
  for (let i = 0; i < blocks[0].length; i++) {
    blocks.forEach((block, j) => { if (i !== shortLen - eccLen || j >= numShort) words.push(block[i]); });
  }
  const size = ver * 4 + 17;
  const mods = [];
  const fn = [];
  for (let y = 0; y < size; y++) { mods.push(new Array(size).fill(false)); fn.push(new Array(size).fill(false)); }
  const setF = (x, y, dark) => { mods[y][x] = dark; fn[y][x] = true; };
  for (let i = 0; i < size; i++) { setF(6, i, i % 2 === 0); setF(i, 6, i % 2 === 0); }
  const finder = (cx, cy) => {
    for (let dy = -4; dy <= 4; dy++) {
      for (let dx = -4; dx <= 4; dx++) {
        const d = Math.max(Math.abs(dx), Math.abs(dy));
        const x = cx + dx;
        const y = cy + dy;
        if (x >= 0 && x < size && y >= 0 && y < size) setF(x, y, d !== 2 && d !== 4);
      }
    }
  };
  finder(3, 3);
  finder(size - 4, 3);
  finder(3, size - 4);
  const al = qrAlignments(ver);
  const last = al.length - 1;
  al.forEach((ax, i) => al.forEach((ay, j) => {
    if ((i === 0 && j === 0) || (i === 0 && j === last) || (i === last && j === 0)) return;
    for (let dy = -2; dy <= 2; dy++) for (let dx = -2; dx <= 2; dx++) setF(ax + dx, ay + dy, Math.max(Math.abs(dx), Math.abs(dy)) !== 1);
  }));
  const formatBits = (mask) => {
    const d = (0 << 3) | mask;
    let rem = d;
    for (let i = 0; i < 10; i++) rem = (rem << 1) ^ ((rem >>> 9) * 0x537);
    const b = ((d << 10) | rem) ^ 0x5412;
    const bit = (i) => ((b >>> i) & 1) !== 0;
    for (let i = 0; i <= 5; i++) setF(8, i, bit(i));
    setF(8, 7, bit(6));
    setF(8, 8, bit(7));
    setF(7, 8, bit(8));
    for (let i = 9; i < 15; i++) setF(14 - i, 8, bit(i));
    for (let i = 0; i < 8; i++) setF(size - 1 - i, 8, bit(i));
    for (let i = 8; i < 15; i++) setF(8, size - 15 + i, bit(i));
    setF(8, size - 8, true);
  };
  formatBits(0);
  if (ver >= 7) {
    let rem = ver;
    for (let i = 0; i < 12; i++) rem = (rem << 1) ^ ((rem >>> 11) * 0x1F25);
    const vb = (ver << 12) | rem;
    for (let i = 0; i < 18; i++) {
      const dark = ((vb >>> i) & 1) !== 0;
      const a = size - 11 + (i % 3);
      const c = Math.floor(i / 3);
      setF(a, c, dark);
      setF(c, a, dark);
    }
  }
  let idx = 0;
  for (let right = size - 1; right >= 1; right -= 2) {
    if (right === 6) right = 5;
    for (let vert = 0; vert < size; vert++) {
      for (let j = 0; j < 2; j++) {
        const x = right - j;
        const upward = ((right + 1) & 2) === 0;
        const y = upward ? size - 1 - vert : vert;
        if (!fn[y][x] && idx < words.length * 8) {
          mods[y][x] = ((words[idx >>> 3] >>> (7 - (idx & 7))) & 1) !== 0;
          idx += 1;
        }
      }
    }
  }
  const flip = (mask) => {
    for (let y = 0; y < size; y++) {
      for (let x = 0; x < size; x++) {
        if (fn[y][x]) continue;
        let inv = false;
        if (mask === 0) inv = (x + y) % 2 === 0;
        else if (mask === 1) inv = y % 2 === 0;
        else if (mask === 2) inv = x % 3 === 0;
        else if (mask === 3) inv = (x + y) % 3 === 0;
        else if (mask === 4) inv = (Math.floor(x / 3) + Math.floor(y / 2)) % 2 === 0;
        else if (mask === 5) inv = ((x * y) % 2) + ((x * y) % 3) === 0;
        else if (mask === 6) inv = (((x * y) % 2) + ((x * y) % 3)) % 2 === 0;
        else inv = (((x + y) % 2) + ((x * y) % 3)) % 2 === 0;
        if (inv) mods[y][x] = !mods[y][x];
      }
    }
  };
  const penalty = () => {
    let score = 0;
    const runs = (get) => {
      for (let a = 0; a < size; a++) {
        let color = get(a, 0);
        let len = 1;
        for (let b = 1; b <= size; b++) {
          const cur = b < size ? get(a, b) : null;
          if (cur === color) { len += 1; continue; }
          if (len >= 5) score += 3 + (len - 5);
          color = cur;
          len = 1;
        }
        for (let b = 0; b + 6 < size; b++) {
          if (get(a, b) && !get(a, b + 1) && get(a, b + 2) && get(a, b + 3) && get(a, b + 4) && !get(a, b + 5) && get(a, b + 6)) {
            const before = b >= 4 && !get(a, b - 1) && !get(a, b - 2) && !get(a, b - 3) && !get(a, b - 4);
            const after = b + 10 < size && !get(a, b + 7) && !get(a, b + 8) && !get(a, b + 9) && !get(a, b + 10);
            if (before || after) score += 40;
          }
        }
      }
    };
    runs((a, b) => mods[a][b]);
    runs((a, b) => mods[b][a]);
    let dark = 0;
    for (let y = 0; y < size; y++) {
      for (let x = 0; x < size; x++) {
        if (mods[y][x]) dark += 1;
        if (y < size - 1 && x < size - 1) {
          const c = mods[y][x];
          if (c === mods[y][x + 1] && c === mods[y + 1][x] && c === mods[y + 1][x + 1]) score += 3;
        }
      }
    }
    const total = size * size;
    score += (Math.ceil(Math.abs(dark * 20 - total * 10) / total) - 1) * 10;
    return score;
  };
  let best = 0;
  let bestScore = Infinity;
  for (let m = 0; m < 8; m++) {
    flip(m);
    formatBits(m);
    const s = penalty();
    if (s < bestScore) { bestScore = s; best = m; }
    flip(m);
  }
  flip(best);
  formatBits(best);
  return mods;
}
function qrDataUrl(text, px = 360, dark = '#111114', light = '#FFFFFF') {
  try {
    const mods = qrMatrix(text);
    if (!mods || typeof document === 'undefined') return '';
    const size = mods.length;
    const quiet = 3;
    const cells = size + quiet * 2;
    const scale = Math.max(2, Math.floor(px / cells));
    const canvas = document.createElement('canvas');
    canvas.width = cells * scale;
    canvas.height = cells * scale;
    const g = canvas.getContext('2d');
    g.fillStyle = light;
    g.fillRect(0, 0, canvas.width, canvas.height);
    g.fillStyle = dark;
    for (let y = 0; y < size; y++) {
      for (let x = 0; x < size; x++) {
        if (mods[y][x]) g.fillRect((x + quiet) * scale, (y + quiet) * scale, scale, scale);
      }
    }
    return canvas.toDataURL('image/png');
  } catch {
    return '';
  }
}

function ShareProfileSheet({ profile, myId, conversations, groups, onSend, onClose }) {
  useBackClose(true, onClose);
  const { theme } = useTheme();
  const link = profileShareLink(profile.id);
  const qrUrl = useMemo(() => qrDataUrl(link, 360) || `https://api.qrserver.com/v1/create-qr-code/?size=360x360&margin=10&data=${encodeURIComponent(link)}`, [link]);
  const [q, setQ] = useState('');
  const [results, setResults] = useState([]);
  const [selected, setSelected] = useState([]);
  const [note, setNote] = useState('');
  const [sending, setSending] = useState(false);
  const [toast, setToast] = useState('');
  const timer = useRef(null);
  const toastTimer = useRef(null);

  const flash = (msg) => {
    setToast(msg);
    clearTimeout(toastTimer.current);
    toastTimer.current = setTimeout(() => setToast(''), 1800);
  };

  const userItem = (p) => ({ key: 'u-' + p.id, kind: 'user', id: p.id, name: p.name, avatar: p.avatar, sub: '@' + p.username });
  const groupItem = (g) => ({ key: 'g-' + g.id, kind: 'group', id: g.id, name: g.name, avatar: g.avatar, sub: 'Group' });

  const baseItems = [
    ...(conversations || []).filter((c) => !c.otherProfile.is_deleted).map((c) => userItem(c.otherProfile)),
    ...(groups || []).map(groupItem),
  ];

  const [suggested, setSuggested] = useState([]);
  useEffect(() => {
    let alive = true;
    (async () => {
      const { data: f } = await supabase.from('follows').select('following_id').eq('follower_id', myId).eq('status', 'accepted').limit(200);
      const ids = (f || []).map((x) => x.following_id);
      if (!ids.length) return;
      const { data: profs } = await supabase.from('profiles').select('*').in('id', ids).eq('is_deleted', false);
      if (!alive) return;
      const list = sanitizeAvatarList(profs, myId).sort((a, b) => (a.name || '').localeCompare(b.name || ''));
      setSuggested(list);
      setResults(list);
    })();
    return () => { alive = false; };
  }, [myId]);
  const doSearch = (val) => {
    setQ(val);
    clearTimeout(timer.current);
    if (val.trim().length < 2) { setResults(suggested); return; }
    timer.current = setTimeout(async () => {
      const { data } = await searchAccounts(val.trim());
      const people = sanitizeAvatarList(data, myId).filter((u) => u.id !== myId && !u.is_deleted).map(userItem);
      const term = val.trim().toLowerCase();
      const groupMatches = (groups || []).filter((g) => (g.name || '').toLowerCase().includes(term)).map(groupItem);
      setResults([...groupMatches, ...people]);
    }, 300);
  };

  const list = q.trim().length >= 2 ? results : baseItems;
  const isSelected = (item) => selected.some((s) => s.key === item.key);
  const toggle = (item) => setSelected((prev) => (prev.some((s) => s.key === item.key) ? prev.filter((s) => s.key !== item.key) : [...prev, item]));

  const doCopy = async () => {
    const ok = await copyTextToClipboard(link);
    flash(ok ? 'Link copied' : "Couldn't copy the link");
  };

  const doNativeShare = async () => {
    if (navigator.share) {
      try {
        await navigator.share({ title: `${profile.name} on ZChat`, text: `Check out ${profile.name} (@${profile.username}) on ZChat`, url: link });
      } catch {}
      return;
    }
    doCopy();
  };

  const send = async () => {
    if (!selected.length || sending) return;
    setSending(true);
    await onSend(selected, note.trim(), link);
    setSending(false);
    flash(selected.length === 1 ? `Sent to ${selected[0].name}` : `Sent to ${selected.length} chats`);
    setSelected([]);
    setNote('');
  };

  const actionBtn = (icon, label, onClick) => (
    <div onClick={onClick} style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 6, cursor: 'pointer', flex: 1 }}>
      <div style={{ height: 34, display: 'flex', alignItems: 'center', justifyContent: 'center', color: theme.ink }}>{React.cloneElement(icon, { size: 24, strokeWidth: 1.6 })}</div>
      <span style={{ fontSize: 12, color: theme.ink, fontWeight: 500 }}>{label}</span>
    </div>
  );

  return (
    <div onClick={onClose} style={{
      position: 'absolute', inset: 0, background: 'rgba(10,8,6,0.55)', zIndex: 60,
      display: 'flex', alignItems: 'flex-end', justifyContent: 'center',
    }} className="zchat-fade">
      <div onClick={(e) => e.stopPropagation()} style={{
        background: theme.panelBg, borderRadius: '26px 26px 0 0', width: '100%', maxWidth: 480, maxHeight: '90vh',
        overflowY: 'auto', WebkitOverflowScrolling: 'touch', overscrollBehavior: 'contain', position: 'relative',
      }}>
        <div style={{ display: 'flex', justifyContent: 'center', padding: '10px 0 4px' }}>
          <div style={{ width: 40, height: 4, borderRadius: 2, background: theme.border }} />
        </div>
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '4px 18px 12px' }}>
          <div style={{ fontWeight: 800, fontSize: 17, color: theme.ink }}>Share profile</div>
          <X size={20} style={{ cursor: 'pointer', color: theme.muted }} onClick={onClose} />
        </div>

        <div style={{ margin: '0 18px', borderRadius: 24, background: theme.coral, padding: '20px 18px', display: 'flex', flexDirection: 'column', alignItems: 'center' }}>
          <div style={{ background: 'white', borderRadius: 18, padding: 10 }}>
            <img src={qrUrl} alt="" width={170} height={170} draggable={false} onContextMenu={(e) => e.preventDefault()} style={{ display: 'block', width: 170, height: 170 }} />
          </div>
          <div style={{ color: 'white', fontWeight: 800, fontSize: 18, marginTop: 12 }}>@{profile.username}</div>
          <div style={{ color: 'rgba(255,255,255,0.85)', fontSize: 12.5, marginTop: 2 }}>{profile.name} on ZChat</div>
        </div>

        <div style={{ display: 'flex', padding: '16px 18px 6px' }}>
          {actionBtn(<Copy size={20} />, 'Copy link', doCopy)}
          {actionBtn(<Share2 size={20} />, 'Share to', doNativeShare)}
          {actionBtn(<Download size={20} />, 'Save QR', () => silentDownload(qrUrl, `zchat-${profile.username}-qr.png`))}
        </div>

        <div style={{ padding: '12px 18px 4px', fontSize: 13, fontWeight: 800, color: theme.ink }}>Send in ZChat</div>
        <div style={{ padding: '4px 18px 8px' }}>
          <div style={{ position: 'relative' }}>
            <Search size={15} color={theme.muted} style={{ position: 'absolute', left: 12, top: 12 }} />
            <input value={q} onChange={(e) => doSearch(e.target.value)} placeholder="Search people or groups" autoCapitalize="none"
              style={{ ...inputStyle(theme), padding: '9px 12px 9px 34px', fontSize: 13.5 }} />
          </div>
        </div>
        <div style={{ padding: '0 12px', paddingBottom: selected.length ? 8 : 'calc(18px + env(safe-area-inset-bottom))' }}>
          {list.length === 0 && (
            <div style={{ textAlign: 'center', padding: 18, fontSize: 13, color: theme.muted }}>
              {q.trim().length >= 2 ? 'No one found' : 'Your chats will show here'}
            </div>
          )}
          {list.map((item) => (
            <div key={item.key} onClick={() => toggle(item)} style={{ display: 'flex', alignItems: 'center', gap: 12, padding: '8px 6px', cursor: 'pointer', borderRadius: 12 }}>
              {item.kind === 'group' ? <GroupAvatar avatar={item.avatar} name={item.name} size={42} /> : <Avatar emoji={item.avatar} name={item.name} size={42} />}
              <div style={{ flex: 1, minWidth: 0 }}>
                <div style={{ fontWeight: 700, fontSize: 14, color: theme.ink, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{item.name}</div>
                <div style={{ fontSize: 11.5, color: theme.muted, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{item.sub}</div>
              </div>
              <div style={{
                width: 22, height: 22, borderRadius: '50%', flexShrink: 0,
                border: `2px solid ${isSelected(item) ? theme.coral : theme.border}`, background: isSelected(item) ? theme.coral : 'transparent',
                display: 'flex', alignItems: 'center', justifyContent: 'center',
              }}>{isSelected(item) && <Check size={13} color="white" />}</div>
            </div>
          ))}
        </div>

        {selected.length > 0 && (
          <div style={{
            position: 'sticky', bottom: 0, background: theme.panelBg, borderTop: `1px solid ${theme.border}`,
            padding: '10px 18px', paddingBottom: 'calc(10px + env(safe-area-inset-bottom))', display: 'flex', gap: 8, alignItems: 'center',
          }}>
            <input value={note} onChange={(e) => setNote(e.target.value.slice(0, 500))} placeholder="Write a message"
              style={{ ...inputStyle(theme), padding: '10px 14px', fontSize: 14, borderRadius: 22 }} />
            <button onClick={send} disabled={sending} style={{
              padding: '10px 18px', borderRadius: 22, border: 'none', background: theme.coral, color: 'white',
              fontWeight: 700, fontSize: 13.5, cursor: sending ? 'default' : 'pointer', fontFamily: FONT, flexShrink: 0,
            }}>{sending ? <Spinner size={13} /> : (selected.length > 1 ? `Send (${selected.length})` : 'Send')}</button>
          </div>
        )}

        {toast && (
          <div style={{
            position: 'sticky', bottom: selected.length ? 70 : 16, margin: '0 auto', width: 'fit-content',
            background: theme.ink, color: theme.panelBg, fontSize: 12.5, fontWeight: 700, padding: '8px 14px', borderRadius: 20,
          }} className="zchat-fade">{toast}</div>
        )}
      </div>
    </div>
  );
}

function PosterIconButton({ onClick, children, label }) {
  return (
    <div role="button" aria-label={label} onClick={onClick} style={{
      width: 38, height: 38, borderRadius: '50%', background: 'rgba(0,0,0,0.38)',
      backdropFilter: 'blur(8px)', WebkitBackdropFilter: 'blur(8px)',
      display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer', color: 'white', flexShrink: 0,
    }}>{children}</div>
  );
}

const visitMem = new Map();
function recordProfileVisit(profileId) {
  if (!profileId) return;
  const last = visitMem.get(profileId) || 0;
  if (Date.now() - last < 30 * 60000) return;
  visitMem.set(profileId, Date.now());
  supabase.rpc('zchat_visit_profile', { p_profile: profileId }).then(() => {}, () => {});
}
function visitAgoText(iso) {
  const m = Math.max(0, Math.round((Date.now() - new Date(iso).getTime()) / 60000));
  if (m < 2) return 'Just now';
  if (m < 60) return `${m} min ago`;
  const h = Math.round(m / 60);
  if (h < 24) return `${h} h ago`;
  const d = Math.round(h / 24);
  return d === 1 ? 'Yesterday' : `${d} days ago`;
}
function ProfileVisitorsPage({ myId, me, onClose, onOpenProfile, onToggle }) {
  useBackClose(true, onClose);
  const { theme } = useTheme();
  const on = !me || me.visitors_on !== false;
  const [rows, setRows] = useState(null);
  const [busy, setBusy] = useState(false);
  useEffect(() => {
    if (!on) { setRows([]); return undefined; }
    let alive = true;
    (async () => {
      const since = new Date(Date.now() - 30 * 86400000).toISOString();
      const { data } = await supabase.from('profile_visits').select('viewer_id, viewed_at, n').eq('profile_id', myId).gt('viewed_at', since).order('viewed_at', { ascending: false }).limit(200);
      const list = data || [];
      if (!list.length) { if (alive) setRows([]); return; }
      const { data: profs } = await supabase.from('profiles').select('id, name, username, avatar, avatar_frame, nameplate, verified, custom_badge, is_deleted').in('id', list.map((r) => r.viewer_id));
      const byId = {};
      sanitizeAvatarList(profs || [], myId).forEach((pr) => { if (!pr.is_deleted) byId[pr.id] = pr; });
      if (alive) setRows(list.map((r) => ({ ...r, profile: byId[r.viewer_id] })).filter((r) => r.profile));
    })();
    return () => { alive = false; };
  }, [on]);
  const week = (rows || []).filter((r) => Date.now() - new Date(r.viewed_at).getTime() < 7 * 86400000).length;
  const toggle = async () => { if (busy) return; setBusy(true); await onToggle(!on); setBusy(false); };
  return (
    <FullPage title="Profile visitors" subtitle={on ? (rows ? `${rows.length} in the last 30 days` : 'Loading') : 'Off'} onBack={onClose} zIndex={72} pad={false}>
      {!on ? (
        <EmptyState art="insights" title="Profile visitors is off" text="Turn it on to see who viewed your profile in the last 30 days. While it is off, you also stay hidden on other people's visitor lists." action={<PillButton primary label={busy ? 'Turning on' : 'Turn on'} disabled={busy} onClick={toggle} />} />
      ) : rows === null ? (
        <div style={{ display: 'flex', justifyContent: 'center', padding: 40 }}><Spinner color={theme.muted} /></div>
      ) : !rows.length ? (
        <EmptyState art="insights" title="No visitors yet" text="When someone opens your profile, they show up here for 30 days." />
      ) : (
        <>
          <div style={{ display: 'flex', gap: 10, padding: '12px 16px 6px' }}>
            {[[rows.length, 'last 30 days'], [week, 'this week'], [rows.reduce((a, r) => a + (Number(r.n) || 1), 0), 'visits']].map(([n, l]) => (
              <div key={l} style={{ flex: 1, padding: '12px 10px', borderRadius: 14, background: theme.rowBg, textAlign: 'center' }}>
                <div style={{ fontSize: 20, fontWeight: 800, color: theme.ink, letterSpacing: '-0.02em' }}>{formatCount(n)}</div>
                <div style={{ fontSize: 12, color: theme.muted, fontWeight: 600, marginTop: 1 }}>{l}</div>
              </div>
            ))}
          </div>
          <div role="list" aria-label="Profile visitors" style={{ padding: '6px 0 10px' }}>
            {rows.map((r) => (
              <div key={r.viewer_id} role="listitem" aria-label={`Visitor ${r.profile.name}`} onClick={() => onOpenProfile(r.profile)} className="zchat-row-press" style={{ display: 'flex', alignItems: 'center', gap: 12, padding: '9px 16px', cursor: 'pointer' }}>
                <Avatar emoji={r.profile.avatar} name={r.profile.name} size={50} />
                <div style={{ flex: 1, minWidth: 0 }}>
                  <div style={{ fontSize: 15.5, fontWeight: 700, color: theme.ink, minWidth: 0 }}><NameBadge name={r.profile.name} verified={r.profile.verified} custom={r.profile.custom_badge} size={13} /></div>
                  <div style={{ fontSize: 13, color: theme.muted, marginTop: 1 }}>{visitAgoText(r.viewed_at)}{Number(r.n) > 1 ? `, ${r.n} visits` : ''}</div>
                </div>
                <ChevronRight size={18} color={theme.muted} />
              </div>
            ))}
          </div>
          <div style={{ fontSize: 12.5, color: theme.muted, lineHeight: 1.5, padding: '4px 16px 20px' }}>People who turned off Profile visitors do not show here, and they cannot see their own visitors either. Change this in Settings.</div>
        </>
      )}
    </FullPage>
  );
}

function GiftIcon({ size = 20, color = 'currentColor', strokeWidth = 1.9, style }) {
  return (
    <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke={color} strokeWidth={strokeWidth} strokeLinecap="round" strokeLinejoin="round" style={style} aria-hidden="true">
      <rect x="3.5" y="8.5" width="17" height="4" rx="1" /><path d="M5 12.5v7a1 1 0 0 0 1 1h12a1 1 0 0 0 1-1v-7" /><path d="M12 8.5v12" />
      <path d="M12 8.5c-1.6-3-5.6-4.2-5.6-1.6 0 1.6 3 1.6 5.6 1.6Z" /><path d="M12 8.5c1.6-3 5.6-4.2 5.6-1.6 0 1.6-3 1.6-5.6 1.6Z" />
    </svg>
  );
}

function MutualFollowersLine({ profileId, myId, iFollowIds, total, onOpen, center }) {
  const { theme } = useTheme();
  const [people, setPeople] = useState(null);
  useEffect(() => {
    let alive = true;
    const mine = iFollowIds ? [...iFollowIds].filter((id) => id !== profileId && id !== myId) : [];
    if (!mine.length) { setPeople([]); return undefined; }
    (async () => {
      const { data } = await supabase.from('follows').select('follower_id').eq('following_id', profileId).eq('status', 'accepted').in('follower_id', mine.slice(0, 400)).limit(40);
      const ids = [...new Set((data || []).map((r) => r.follower_id))];
      if (!ids.length) { if (alive) setPeople([]); return; }
      const { data: profs } = await supabase.from('profiles').select('id, username, name, avatar').in('id', ids.slice(0, 3));
      if (alive) setPeople({ list: sanitizeAvatarList(profs || [], myId), count: Math.max(ids.length, total || 0) });
    })();
    return () => { alive = false; };
  }, [profileId]);
  if (!people || !people.list || !people.list.length) return null;
  const names = people.list.slice(0, 2).map((p) => p.username || p.name);
  const rest = people.count - names.length;
  return (
    <div role="button" aria-label="Mutual followers" onClick={onOpen} style={{ display: 'flex', alignItems: 'center', justifyContent: center ? 'center' : 'flex-start', gap: 8, padding: '8px 20px 0', cursor: 'pointer' }}>
      <span style={{ display: 'flex', flexShrink: 0 }}>
        {people.list.slice(0, 3).map((p, i) => (
          <span key={p.id} style={{ marginLeft: i ? -7 : 0, borderRadius: '50%', boxShadow: `0 0 0 2px ${theme.bgGradient}`, display: 'flex' }}><Avatar emoji={p.avatar} name={p.name} size={22} /></span>
        ))}
      </span>
      <span style={{ fontSize: 13, color: theme.muted, lineHeight: 1.35, minWidth: 0 }}>
        Followed by {names.map((n, i) => <React.Fragment key={n}>{i ? ', ' : ''}<b style={{ color: theme.ink, fontWeight: 700 }}>{n}</b></React.Fragment>)}{rest > 0 ? <> and {rest} {rest === 1 ? 'other' : 'others'}</> : null}
      </span>
    </div>
  );
}

const achMem = new Map();
async function loadAchievements(uid, force) {
  const hit = achMem.get(uid);
  if (hit && !force && Date.now() - hit.at < 5 * 60000) return hit.list;
  const { data, error } = await supabase.from('achievements').select('key, earned_at').eq('user_id', uid).order('earned_at', { ascending: false }).limit(100);
  const list = error ? [] : (data || []).filter((r) => ACH_BY_KEY[r.key]);
  achMem.set(uid, { at: Date.now(), list });
  return list;
}
async function checkMyAchievements(uid, extra) {
  try {
    const { data, error } = await supabase.rpc('zchat_check_achievements', { p_extra: { tz: localTz(), ...(extra || {}) } });
    if (error) return [];
    achMem.delete(uid);
    return Array.isArray(data) ? data.filter((k) => ACH_BY_KEY[k]) : [];
  } catch { return []; }
}
function AchievementsLine({ userId, onOpen, center }) {
  const { theme } = useTheme();
  const [list, setList] = useState(() => (achMem.get(userId) || {}).list || null);
  useEffect(() => {
    let alive = true;
    loadAchievements(userId).then((l) => { if (alive) setList(l); });
    const on = () => loadAchievements(userId, true).then((l) => { if (alive) setList(l); });
    window.addEventListener('zchat-achievements', on);
    return () => { alive = false; window.removeEventListener('zchat-achievements', on); };
  }, [userId]);
  if (!list || !list.length) return null;
  return (
    <div role="button" aria-label={`${list.length} achievements`} onClick={onOpen} style={{ display: 'flex', alignItems: 'center', justifyContent: center ? 'center' : 'flex-start', gap: 6, padding: '10px 20px 0', cursor: 'pointer' }}>
      {list.slice(0, 4).map((a) => <AchievementArt key={a.key} k={a.key} size={28} />)}
      <span style={{ fontSize: 13, color: theme.muted, marginLeft: 4 }}>{list.length} {list.length === 1 ? 'achievement' : 'achievements'}</span>
    </div>
  );
}
function AchievementsPage({ userId, isSelf, name, onClose }) {
  useBackClose(true, onClose);
  const { theme } = useTheme();
  const [list, setList] = useState(null);
  useEffect(() => { loadAchievements(userId, true).then(setList); }, [userId]);
  const earned = new Map((list || []).map((r) => [r.key, r.earned_at]));
  const items = isSelf ? ACHIEVEMENTS : ACHIEVEMENTS.filter((a) => earned.has(a.key));
  return (
    <FullPage title="Achievements" subtitle={list ? `${earned.size} of ${ACHIEVEMENTS.length}` : undefined} onBack={onClose} zIndex={760} pad={false}>
      {list === null ? (
        <div style={{ display: 'flex', justifyContent: 'center', padding: 40 }}><Spinner color={theme.muted} /></div>
      ) : !items.length ? (
        <EmptyState art="nothing" title="No achievements yet" text={`${name || 'They'} will show achievements here as they use ZChat.`} />
      ) : (
        <div role="list" aria-label="Achievements" style={{ display: 'grid', gridTemplateColumns: 'repeat(3, minmax(0, 1fr))', gap: 10, padding: '14px 16px 30px' }}>
          {items.map((a) => {
            const at = earned.get(a.key);
            return (
              <div key={a.key} role="listitem" aria-label={`${a.title}${at ? '' : ', locked'}`} style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', textAlign: 'center', gap: 6, padding: '14px 6px 12px', borderRadius: 16, background: theme.soft, opacity: at ? 1 : 0.6 }}>
                <AchievementArt k={a.key} size={58} locked={!at} />
                <div style={{ fontSize: 13.5, fontWeight: 800, color: theme.ink, lineHeight: 1.2 }}>{a.title}</div>
                <div style={{ fontSize: 11.5, color: theme.muted, lineHeight: 1.3 }}>{a.desc}</div>
                {at && <div style={{ fontSize: 11, color: theme.coral, fontWeight: 700 }}>{new Date(at).toLocaleDateString(undefined, { month: 'short', day: 'numeric', year: 'numeric' })}</div>}
              </div>
            );
          })}
        </div>
      )}
    </FullPage>
  );
}

