function SmartMenu({ anchorEl, open, onClose, children, width = 170 }) {
  useBackClose(!!open, onClose);
  const [pos, setPos] = useState(null);
  const boxRef = useRef(null);
  useLayoutEffect(() => {
    if (!open || !anchorEl) { setPos(null); return undefined; }
    const compute = () => {
      const r = anchorEl.getBoundingClientRect();
      const vw = window.innerWidth;
      const vh = window.innerHeight;
      const maxH = Math.max(120, vh - 16);
      const h = Math.min(boxRef.current ? boxRef.current.scrollHeight : 170, maxH);
      let top = r.bottom + 6;
      if (top + h > vh - 8) top = r.top - h - 6 >= 8 ? r.top - h - 6 : Math.max(8, vh - 8 - h);
      let left = r.right - width;
      if (left < 8) left = 8;
      if (left + width > vw - 8) left = Math.max(8, vw - width - 8);
      setPos({ top, left, maxH });
    };
    const onScroll = (e) => { if (boxRef.current && e.target && e.target.nodeType === 1 && boxRef.current.contains(e.target)) return; onClose(); };
    compute();
    window.addEventListener('resize', compute);
    window.addEventListener('scroll', onScroll, true);
    return () => { window.removeEventListener('resize', compute); window.removeEventListener('scroll', onScroll, true); };
  }, [open, anchorEl, onClose]);

  if (!open || !anchorEl) return null;
  return ReactDOM.createPortal(
    <>
      <div onClick={onClose} style={{ position: 'fixed', inset: 0, zIndex: 998 }} />
      <div ref={boxRef} style={{ position: 'fixed', top: pos ? pos.top : 0, left: pos ? pos.left : 0, width, zIndex: 999, maxHeight: pos ? pos.maxH : undefined, overflowY: 'auto', overscrollBehavior: 'contain', visibility: pos ? 'visible' : 'hidden', borderRadius: 14 }} onClick={(e) => e.stopPropagation()} className="zchat-fade">
        {children}
      </div>
    </>,
    document.body
  );
}

function friendlyError(error, fallback = 'Something went wrong. Try again.') {
  const msg = String((error && error.message) || error || '').toLowerCase();
  if (!msg) return fallback;
  if (msg.includes('failed to fetch') || msg.includes('network') || msg.includes('load failed')) return "You're offline. Check your connection and try again.";
  if (msg.includes('rate limit') || msg.includes('too many')) return 'Too many tries. Wait a minute and try again.';
  if (msg.includes('already registered') || msg.includes('already been registered') || msg.includes('user already exists')) return 'That email already has an account. Sign in instead.';
  if (msg.includes('duplicate') || msg.includes('unique')) return 'That name is already taken. Try another one.';
  if (msg.includes('invalid login') || msg.includes('invalid credentials')) return 'Incorrect email or password.';
  if (msg.includes('same password') || msg.includes('different from the old')) return 'Choose a password you have not used before.';
  if (msg.includes('password') && (msg.includes('characters') || msg.includes('short') || msg.includes('weak'))) return 'Use a stronger password with at least 6 characters.';
  if (msg.includes('expired') || msg.includes('otp') || msg.includes('token')) return 'That code expired. Ask for a new one.';
  if (msg.includes('email') && msg.includes('invalid')) return 'Enter a valid email address.';
  if (msg.includes('too large') || msg.includes('exceeded the maximum')) return 'That file is too big.';
  if (msg.includes('permission') || msg.includes('policy') || msg.includes('not allowed') || msg.includes('jwt') || msg.includes('unauthorized')) return "You don't have permission to do that.";
  return fallback;
}

function formatListTime(value) {
  if (!value) return '';
  const d = new Date(value);
  if (Number.isNaN(d.getTime())) return '';
  const now = new Date();
  if (d.toDateString() === now.toDateString()) return fmtHM(d);
  const yesterday = new Date(now);
  yesterday.setDate(now.getDate() - 1);
  if (d.toDateString() === yesterday.toDateString()) return 'Yesterday';
  if (now.getTime() - d.getTime() < 6 * 86400000) return fmtDate(d, { weekday: 'short' });
  return fmtDate(d, d.getFullYear() === now.getFullYear() ? { day: 'numeric', month: 'short' } : { day: 'numeric', month: 'short', year: 'numeric' });
}

function ReplyQuote({ m, label, onClick, bar, dim, compact }) {
  const { theme } = useTheme();
  const gs = m && m.type === 'text' ? parseGameMessage(m.content) : null;
  const loc = m && m.type === 'text' && !gs ? parseLocationMessage(m.content) : null;
  const isStickerImg = m && m.type === 'sticker' && m.content && (m.content.startsWith('/') || /^https?:/i.test(m.content));
  const muted = dim || theme.muted;
  let icon = null;
  let text = quoteTextFor(m);
  if (gs) icon = gs.g === 'score' ? <TrophyIcon size={13} color="#F59E0B" /> : <GamepadIcon size={13} color={theme.coral} />;
  else if (loc) icon = <Compass size={13} color={theme.coral} />;
  else if (m && m.type === 'text' && parsePoll(m.content)) icon = <PollIcon size={13} color={theme.coral} />;
  else if (m && m.type === 'text' && parseEventMsg(m.content)) icon = <CalendarIcon size={13} color={theme.coral} />;
  else if (m && m.type === 'audio') icon = <Mic size={13} color={theme.coral} />;
  else if (m && m.type === 'image') icon = <Camera size={13} color={theme.coral} />;
  else if (m && m.type === 'video') icon = <VideoIcon size={13} color={theme.coral} />;
  const thumb = m && (m.type === 'image' || m.type === 'video') && m.media_url && !parseOnce(m) ? (
    <div style={{ width: compact ? 34 : 40, height: compact ? 34 : 40, borderRadius: 8, overflow: 'hidden', flexShrink: 0, background: 'rgba(0,0,0,0.25)', position: 'relative' }}>
      {m.type === 'image'
        ? <MediaImg src={m.media_url} draggable={false} style={{ width: '100%', height: '100%', objectFit: 'cover', display: 'block' }} />
        : <VideoThumb src={m.media_url} style={{ width: '100%', height: '100%', objectFit: 'cover', display: 'block' }} />}
      {m.type === 'video' && <div style={{ position: 'absolute', inset: 0, display: 'flex', alignItems: 'center', justifyContent: 'center' }}><Play size={14} color="white" fill="white" /></div>}
    </div>
  ) : isStickerImg ? (
    <img src={m.content} alt="" draggable={false} style={{ width: compact ? 30 : 36, height: compact ? 30 : 36, objectFit: 'contain', flexShrink: 0 }} />
  ) : null;
  const textStyle = m && m.type === 'text' && !gs && !loc && !isSpecialContent(m.content) ? { ...fontStyleCss(m.text_font), ...(m.text_color ? { color: m.text_color } : {}) } : {};
  return (
    <div onClick={onClick} style={{ display: 'flex', alignItems: 'stretch', gap: 8, borderRadius: 10, overflow: 'hidden', background: 'rgba(0,0,0,0.06)', cursor: onClick ? 'pointer' : 'default', minWidth: 0 }}>
      <div style={{ width: 3, flexShrink: 0, background: bar || theme.coral }} />
      <div style={{ flex: 1, minWidth: 0, padding: compact ? '4px 0' : '5px 0', display: 'flex', alignItems: 'center', gap: 8 }}>
        <div style={{ flex: 1, minWidth: 0 }}>
          {label && <div style={{ fontWeight: 700, color: bar || theme.coralDeep, fontSize: 10.5, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{label}</div>}
          <div style={{ display: 'flex', alignItems: 'center', gap: 5, fontSize: 11.5, color: muted, lineHeight: 1.35, minWidth: 0 }}>
            {icon && <span style={{ display: 'flex', flexShrink: 0 }}>{icon}</span>}
            <span style={{ ...textStyle, overflow: 'hidden', textOverflow: 'ellipsis', display: '-webkit-box', WebkitLineClamp: compact ? 1 : 2, WebkitBoxOrient: 'vertical', wordBreak: 'break-word' }}>{text}</span>
          </div>
        </div>
        {thumb && <div style={{ paddingRight: 6, display: 'flex' }}>{thumb}</div>}
      </div>
    </div>
  );
}
const SPECIAL_PREFIXES = ['zpoll:', 'zevent:', 'zdice:', 'zlist:', 'zbill:', 'zcount:', 'zlive:', 'zfocus:', 'zwatch:', 'zalbum:', 'zpack:', 'zchan:', 'zfile:', 'zsnd:', 'zdraw:', 'zbomb:', 'zask:'];
function isSpecialContent(content) {
  return typeof content === 'string' && SPECIAL_PREFIXES.some((p) => content.indexOf(p) === 0);
}
function quoteTextFor(m) {
  if (!m) return '';
  if (m.type === 'text') {
    const gs = parseGameMessage(m.content);
    if (gs) return gs.g === 'score' ? `High score in ${gameTitle(gs)}` : gameTitle(gs);
    const qp = parsePoll(m.content);
    if (qp) return `Poll: ${qp.q}`;
    const qe = parseEventMsg(m.content);
    if (qe) return `Event: ${qe.t}`;
    const qd = parseDice(m.content);
    if (qd) return diceSummary(qd);
    const qx = extraCardSummary(m.content);
    if (qx) return qx;
    if (parseLocationMessage(m.content)) return 'Location';
    if (parseProfileLink(m.content)) return 'Profile';
    if (parsePostLink(m.content)) return 'Post';
    const qw = parseWrapped(m.content);
    if (qw) return qw.k === 'sec' ? (openedSecretMem.get(m.id) || 'Secret message') : qw.text;
    return stripSilent(m.content || '');
  }
  if (parseOnce(m)) return m.type === 'video' ? 'View once video' : m.type === 'audio' ? 'Voice message, plays once' : 'View once photo';
  if (parseBlur(m)) return m.type === 'video' ? 'Hidden video' : 'Hidden photo';
  if (m.type === 'image') return isGifUrl(m.media_url) ? 'GIF' : 'Photo';
  if (m.type === 'audio' || m.type === 'voice') return 'Voice message';
  if (m.type === 'sticker') return 'Sticker';
  if (m.type === 'system') return 'Message';
  return isRoundVideo(m) ? 'Video message' : 'Video';
}
function plainPreviewText(text) {
  return String(text || '')
    .replace(/\|\|[^|\n]+?\|\|/g, '\u2022\u2022\u2022\u2022')
    .replace(/```[a-zA-Z0-9]*\n?([\s\S]*?)```/g, '$1')
    .replace(/`([^`]*)`/g, '$1')
    .replace(/\*\*([^*]+)\*\*/g, '$1')
    .replace(/__([^_]+)__/g, '$1')
    .replace(/(^|\s)[*_]([^*_]+)[*_](?=\s|$)/g, '$1$2')
    .replace(/^#{1,6}\s+/gm, '')
    .replace(/^\s*[-*]\s+/gm, '')
    .replace(/\s*\n+\s*/g, ' ')
    .trim();
}
function describeMessage(m) {
  if (!m) return { kind: 'none', text: '' };
  if (m.deleted) return { kind: 'deleted', text: 'This message was deleted' };
  if (m.story_id) {
    if (m.content === STORY_MENTION_TEXT || m.content === STORY_GROUP_MENTION_TEXT || m.content === STORY_SHARE_TEXT) return { kind: 'story', text: m.content };
    return { kind: 'story', text: `Story reply: ${m.content || ''}` };
  }
  switch (m.type) {
    case 'image': return parseBlur(m) ? { kind: 'hidden', text: 'Hidden photo' } : { kind: 'image', text: parseOnce(m) ? 'View once photo' : (m.content || (isGifUrl(m.media_url) ? 'GIF' : 'Photo')) };
    case 'video': return isRoundVideo(m) ? { kind: 'video', text: 'Video message' } : parseBlur(m) ? { kind: 'hidden', text: 'Hidden video' } : { kind: 'video', text: parseOnce(m) ? 'View once video' : (m.content || 'Video') };
    case 'audio': return { kind: 'audio', text: 'Voice message' };
    case 'sticker': return { kind: 'sticker', text: 'Sticker' };
    case 'system': {
      const log = parseCallLog(m.content);
      if (log) {
        const Kind = log.k === 'video' ? 'Video' : 'Voice';
        const text = log.s === 'group' ? `${Kind} group call` : (log.s === 'missed' || log.s === 'declined') ? `Missed ${Kind.toLowerCase()} call` : `${Kind} call, ${formatCallDuration((log.d || 0) * 1000)}`;
        return { kind: log.s === 'missed' || log.s === 'declined' ? 'callmissed' : 'call', text };
      }
      const note = systemNoteFor(m, null);
      return { kind: 'system', text: note ? note.text : (m.content || '') };
    }
    default: {
      const dw = parseWrapped(m.content);
      if (dw) return { kind: dw.k === 'sec' ? 'secret' : 'text', text: wrappedSummary(m.content) };
      const gs = parseGameMessage(m.content);
      if (gs) return { kind: 'game', text: gs.g === 'score' ? `High score in ${gameTitle(gs)}` : gameTitle(gs) };
      const dp = parsePoll(m.content);
      if (dp) return { kind: 'poll', text: `Poll: ${dp.q}` };
      const de = parseEventMsg(m.content);
      if (de) return { kind: 'event', text: `Event: ${de.t}` };
      const ddc = parseDice(m.content);
      if (ddc) return { kind: 'text', text: diceSummary(ddc) };
      const dxc = parseExtraCard(m.content);
      if (dxc) return { kind: dxc.k, text: extraCardSummary(m.content) };
      if (parseLocationMessage(m.content)) return { kind: 'location', text: 'Location' };
      if (parseProfileLink(m.content)) return { kind: 'contact', text: 'Shared a profile' };
      return { kind: 'text', text: parsePostLink(m.content) ? 'Shared a post' : plainPreviewText(m.content || '') };
    }
  }
}

const PREVIEW_ICONS = { image: Camera, video: VideoIcon, audio: Mic, sticker: Smile, deleted: Ban, story: StatusIcon, call: Phone, callmissed: PhoneMissedIcon, game: GamepadIcon, location: Compass, poll: PollIcon, event: CalendarIcon, list: ChecklistIcon, bill: BillIcon, count: CountdownIcon, live: Compass, contact: ContactCardIcon, hidden: HiddenPhotoIcon, secret: Lock, focus: FocusIcon, watch: WatchIcon, album: AlbumIcon, pack: PackIcon, chan: ChannelIcon };
function PhoneMissedIcon({ size = 14, style }) { return <Phone size={size} color="#FF3B30" style={style} />; }

function PreviewLine({ preview, prefix, color, weight = 400, size = 12 }) {
  const Icon = preview ? PREVIEW_ICONS[preview.kind] : null;
  return (
    <span style={{ display: 'flex', alignItems: 'center', gap: 4, minWidth: 0, fontSize: size, color, fontWeight: weight, fontStyle: preview && preview.kind === 'deleted' ? 'italic' : 'normal' }}>
      {prefix ? <span style={{ flexShrink: 0 }}>{prefix}</span> : null}
      {Icon ? <Icon size={size + 1} style={{ flexShrink: 0 }} /> : null}
      <span style={{ whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis', minWidth: 0 }}>{preview ? preview.text : ''}</span>
    </span>
  );
}

function activityLabel(kind) {
  const labels = {
    typing: 'typing',
    sticker: 'choosing a sticker',
    photo: 'selecting a photo',
    video: 'selecting a video',
    voice: 'recording a voice message',
  };
  return `${labels[kind] || 'typing'}\u2026`;
}

function InAppMessageToast({ toast, top, onOpen, onDismiss }) {
  const { theme } = useTheme();
  const startRef = useRef(null);
  const suppressRef = useRef(false);
  const holdRef = useRef(false);
  const [dragY, setDragY] = useState(0);

  useEffect(() => {
    setDragY(0);
    let left = 6000;
    const t = setInterval(() => {
      if (!holdRef.current) left -= 250;
      if (left <= 0) { clearInterval(t); onDismiss(); }
    }, 250);
    return () => clearInterval(t);
  }, [toast.key]);

  return (
    <div key={toast.key} className="zchat-toast-in"
      onPointerDown={(e) => { e.stopPropagation(); holdRef.current = true; startRef.current = { y: e.clientY, moved: false }; }}
      onPointerMove={(e) => {
        const s = startRef.current;
        if (!s) return;
        const dy = e.clientY - s.y;
        if (Math.abs(dy) > 12) s.moved = true;
        if (s.moved) setDragY(Math.min(0, dy));
      }}
      onPointerUp={(e) => {
        e.stopPropagation();
        holdRef.current = false;
        const s = startRef.current;
        startRef.current = null;
        if (s && s.moved) {
          suppressRef.current = true;
          setTimeout(() => { suppressRef.current = false; }, 80);
          if (dragY < -28) onDismiss(); else setDragY(0);
        }
      }}
      onPointerCancel={() => { holdRef.current = false; startRef.current = null; setDragY(0); }}
      onClick={(e) => { e.stopPropagation(); e.preventDefault(); if (suppressRef.current) return; onOpen(); }}
      style={{
        position: 'fixed', top, left: 10, right: 10, zIndex: 300, maxWidth: 420, margin: '0 auto',
        display: 'flex', alignItems: 'center', gap: 11, padding: '11px 14px 11px 11px', borderRadius: 20,
        background: theme.dark ? '#1A1C24' : '#FFFFFF',
        border: `1px solid ${theme.border}`, borderLeft: toast.accent === 'missed' ? '4px solid #FF3B30' : `1px solid ${theme.border}`, boxShadow: '0 12px 32px rgba(0,0,0,0.3)',
        transform: `translateY(${dragY}px)`, transition: startRef.current ? 'none' : 'transform 0.2s ease',
        cursor: 'pointer', touchAction: 'pan-x', userSelect: 'none', WebkitTapHighlightColor: 'transparent',
      }}>
      <div style={{ position: 'relative', flexShrink: 0, pointerEvents: 'none' }}>
        {toast.kind === 'notice' ? (
          toast.icon ? <MailBadgeIcon type={toast.icon === 'warning' ? 'report_warning' : toast.icon === 'mention' ? 'mention' : toast.icon === 'update' ? 'update' : toast.icon === 'badge' ? 'badge' : 'mail'} badgeTier={toast.badgeTier} size={42} />
            : toast.isGroupIcon ? <GroupAvatar avatar={toast.groupAvatar} name={toast.title} size={42} /> : <Avatar emoji={toast.avatar} name={toast.avatarName} size={42} />
        ) : toast.kind === 'group'
          ? <GroupAvatar avatar={toast.groupAvatar} name={toast.title} size={42} />
          : <Avatar emoji={toast.avatar} name={toast.avatarName} size={42} />}
        {toast.kind === 'group' && (
          <div style={{ position: 'absolute', right: -4, bottom: -4, borderRadius: '50%', border: `2px solid ${theme.panelBg}` }}>
            <Avatar emoji={toast.avatar} name={toast.avatarName} size={20} />
          </div>
        )}
      </div>
      <div style={{ flex: 1, minWidth: 0, pointerEvents: 'none' }}>
        <div style={{ display: 'flex', alignItems: 'baseline', gap: 6 }}>
          <span style={{ fontSize: 13.5, fontWeight: 800, color: theme.ink, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}><NameBadge name={toast.title} verified={toast.verified} custom={toast.customBadge} size={12} /></span>
          <span style={{ fontSize: 10.5, color: theme.muted, flexShrink: 0 }}>now</span>
        </div>
        {toast.kind !== 'notice' && prefOn('zchat-hide-previews')
          ? <PreviewLine preview={{ kind: 'text', text: 'New message' }} color={theme.muted} size={12.5} />
          : <PreviewLine preview={toast.preview} prefix={toast.prefix} color={theme.muted} size={12.5} />}
      </div>
    </div>
  );
}

function ChatRowSheet({ title, subtitle, avatar, actions, onClose, zIndex = 94, portal = false, peek = null }) {
  useBackClose(true, onClose);
  const { theme } = useTheme();
  const drag = useSheetDrag(onClose);
  const body = (
    <div onClick={onClose} className="zchat-fade" style={{
      position: 'fixed', inset: 0, zIndex, display: 'flex', alignItems: 'flex-end', justifyContent: 'center', fontFamily: FONT,
      background: 'rgba(0,0,0,0.45)',
    }}>
      <div onClick={(e) => e.stopPropagation()} className="zchat-sheet-up" style={{ transform: drag.sheetStyle.transform, transition: drag.sheetStyle.transition,
        width: '100%', maxWidth: 460, maxHeight: 'min(86vh, calc(100% - 24px))', display: 'flex', flexDirection: 'column', background: theme.panelBg, borderRadius: '24px 24px 0 0', overflow: 'hidden',
        paddingBottom: 'calc(8px + env(safe-area-inset-bottom))', boxShadow: '0 -10px 40px rgba(0,0,0,0.25)',
      }}>
        <div {...drag.sheetProps} style={{ touchAction: 'none', flexShrink: 0 }}>
          <div style={{ display: 'flex', justifyContent: 'center', padding: '10px 0 2px' }}>
            <div style={{ width: 38, height: 4, borderRadius: 2, background: theme.border }} />
          </div>
          {(title || avatar) && (
            <div style={{ display: 'flex', alignItems: 'center', gap: 12, padding: '10px 18px 12px', borderBottom: `1px solid ${theme.border}` }}>
              {avatar}
              <div style={{ minWidth: 0 }}>
                <div style={{ fontWeight: 800, fontSize: 15, color: theme.ink, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{title}</div>
                {subtitle && <div style={{ fontSize: 12, color: theme.muted, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{subtitle}</div>}
              </div>
            </div>
          )}
        </div>
        <div data-sheet-scroll="true" style={{ overflowY: 'auto', minHeight: 0, WebkitOverflowScrolling: 'touch', touchAction: 'pan-y', paddingTop: peek ? 0 : 4 }}>
          {peek}
          {actions.filter(Boolean).map((a) => (
            <div key={a.label} role="button" aria-label={a.label} onClick={() => { if (!a.keepOpen) onClose(); a.onClick(); }} className="zchat-row-press" style={{
              display: 'flex', alignItems: 'center', gap: 14, padding: a.hint ? '9px 20px' : '14px 20px', cursor: 'pointer', boxSizing: 'border-box', minHeight: 52,
              fontSize: 15, fontWeight: 600, color: a.danger ? theme.danger : theme.ink,
            }}>
              <span style={{ display: 'flex', width: 24, justifyContent: 'center', color: a.danger ? theme.danger : theme.muted, flexShrink: 0 }}>{a.icon}</span>
              <span style={{ flex: 1, minWidth: 0 }}>
                {a.label}
                {a.hint && <span style={{ display: 'block', fontSize: 12, color: theme.muted, fontWeight: 500, marginTop: 1, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{a.hint}</span>}
              </span>
              {a.right}
            </div>
          ))}
        </div>
      </div>
    </div>
  );
  return portal ? <Portal>{body}</Portal> : body;
}

function ConfirmSheet({ title, text, confirmLabel = 'Confirm', danger = true, onConfirm, onCancel, busy = false, zIndex = 95 }) {
  useBackClose(true, onCancel);
  const { theme } = useTheme();
  return (
    <div onClick={() => !busy && onCancel()} className="zchat-fade" style={{ position: 'fixed', inset: 0, zIndex, display: 'flex', alignItems: 'flex-end', justifyContent: 'center', fontFamily: FONT, background: 'rgba(0,0,0,0.45)' }}>
      <div onClick={(e) => e.stopPropagation()} className="zchat-sheet-up" style={{ width: '100%', maxWidth: 460, background: theme.panelBg, borderRadius: '24px 24px 0 0', padding: '18px 16px', paddingBottom: 'calc(14px + env(safe-area-inset-bottom))', boxShadow: '0 -10px 40px rgba(0,0,0,0.25)' }}>
        <div style={{ textAlign: 'center', padding: '4px 10px 14px' }}>
          <div style={{ fontSize: 17, fontWeight: 800, color: theme.ink }}>{title}</div>
          {text && <div style={{ fontSize: 13.5, color: theme.muted, lineHeight: 1.55, marginTop: 6 }}>{text}</div>}
        </div>
        <button onClick={() => !busy && onConfirm()} disabled={busy} className="zchat-press" style={{ width: '100%', height: 50, borderRadius: 16, border: 'none', background: danger ? theme.danger : theme.coral, color: 'white', fontWeight: 800, fontSize: 15.5, fontFamily: FONT, cursor: 'pointer', opacity: busy ? 0.6 : 1, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>{busy ? <Spinner size={16} /> : confirmLabel}</button>
        <button onClick={() => !busy && onCancel()} className="zchat-press" style={{ width: '100%', height: 50, borderRadius: 16, border: 'none', background: theme.rowBg, color: theme.ink, fontWeight: 700, fontSize: 15.5, fontFamily: FONT, cursor: 'pointer', marginTop: 8 }}>Cancel</button>
      </div>
    </div>
  );
}

function MessageContextMenu({ onThread, onReplyPrivately, onAddToAlbum, onTranslate, onTranscribe, onReadAloud, onRemind, message, isMine, canEditText, canModerate, anchorRect, bubble, isPinned, onPin, onUnpin, onClose, onReact, onReply, onCopy, onEdit, onForward, onReport, onDeleteForMe, onDeleteForEveryone, onSelectMultiple, onSave, onToggleSave, isSaved, onInfo, onEditArt, onShareImage }) {
  useBackClose(true, onClose);
  const { theme } = useTheme();
  const [showFullEmoji, setShowFullEmoji] = useState(false);
  const [favKeys, setFavKeys] = useState(() => getFavoriteStickerKeys());
  const [measured, setMeasured] = useState({ menu: 0, bubble: 0 });
  const [more, setMore] = useState(false);
  const menuRef = useRef(null);
  const bubbleRef = useRef(null);
  const openedAtRef = useRef(Date.now());
  const guard = (fn) => (...args) => { if (Date.now() - openedAtRef.current < 450) return; if (fn) fn(...args); };
  const stickerMatch = message.type === 'sticker' ? STICKERS.find((s) => s.file === message.content) : null;

  useEffect(() => {
    setMeasured({ menu: menuRef.current ? menuRef.current.scrollHeight : 0, bubble: bubbleRef.current ? bubbleRef.current.offsetHeight : 0 });
  }, []);
  useLayoutEffect(() => {
    if (!more || !menuRef.current) return;
    const h = menuRef.current.scrollHeight;
    setMeasured((m) => (m.menu === h ? m : { ...m, menu: h }));
  }, [more]);

  const vh = window.visualViewport ? window.visualViewport.height : window.innerHeight;
  const vw = window.innerWidth;
  const rect = anchorRect || { top: vh * 0.3, left: Math.max(0, (vw - Math.min(vw, 560)) / 2), width: Math.min(vw, 560), height: 60 };
  const maxBubble = Math.round(vh * 0.38);
  const barH = 50;
  const gap = 10;
  const minTop = 52 + barH + gap;
  const room = vh - 14 - minTop;
  const menuNat = measured.menu || 300;
  const bubbleNat = Math.min(measured.bubble || rect.height, maxBubble);
  const bubbleH = Math.max(Math.min(bubbleNat, 96), Math.min(bubbleNat, room - menuNat - gap));
  const menuMax = Math.max(160, room - bubbleH - gap);
  const menuH = Math.min(menuNat, menuMax);
  const maxTop = vh - 14 - menuH - gap - bubbleH;
  const top = Math.max(minTop, Math.min(rect.top, Math.max(minTop, maxTop)));
  const special = message.type === 'text' && !!(parseGameMessage(message.content) || isSpecialContent(message.content));
  const onceMsg = !!parseOnce(message);
  const sideStyle = isMine
    ? { right: Math.max(10, vw - (rect.left + rect.width) + 14) }
    : { left: Math.max(10, rect.left + 14) };
  const ready = measured.menu > 0;

  const row = (icon, label, onClick, danger, key, fresh) => (
    <div key={key || label} role="button" aria-label={label} onClick={guard(onClick)} className={fresh ? 'zchat-row-press zchat-tab-in' : 'zchat-row-press'} style={{
      display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 16, padding: '12px 16px', cursor: 'pointer',
      fontSize: 14.5, fontWeight: 600, color: danger ? theme.danger : theme.ink, borderTop: `1px solid ${theme.border}`,
    }}>
      <span>{label}</span>
      <span style={{ display: 'flex' }}>{icon}</span>
    </div>
  );
  const nd = !message.deleted;
  const plainText = message.type === 'text' && !special;
  const paintImg = message.type === 'image' && !!onEditArt && !onceMsg && isPaintUrl(message.media_url);
  const allRows = [
    nd && { k: 'reply', main: true, icon: <Reply size={18} />, label: 'Reply', on: onReply },
    nd && onReplyPrivately && { k: 'privreply', main: true, icon: <MessageSquare size={18} />, label: 'Reply privately', on: onReplyPrivately },
    nd && onThread && { k: 'thread', icon: <ThreadIcon size={18} />, label: 'Reply in thread', on: onThread },
    nd && plainText && { k: 'copy', main: true, icon: <Copy size={18} />, label: 'Copy', on: onCopy },
    nd && !onceMsg && (message.type === 'image' || message.type === 'video') && { k: 'save', main: true, icon: <Download size={18} />, label: 'Save', on: onSave },
    nd && canEditText && !special && { k: 'edit', main: true, icon: <Edit3 size={18} />, label: 'Edit', on: onEdit },
    nd && !onceMsg && message.type === 'image' && onEditArt && { k: 'art', main: paintImg, icon: <PaintToolIcon k="brush" size={18} />, label: paintImg ? 'Edit this art' : 'Draw on it', on: onEditArt },
    nd && !onceMsg && !(message.type === 'text' && parseGameMessage(message.content)) && { k: 'fwd', main: true, icon: <Forward size={18} />, label: 'Forward', on: onForward },
    nd && stickerMatch && { k: 'fav', main: true, icon: <Star_ size={18} color="#FFB800" filled={favKeys.has(stickerMatch.key)} />, label: favKeys.has(stickerMatch.key) ? 'Remove from favorites' : 'Add to favorites', on: () => { setFavKeys(new Set(toggleFavoriteSticker(stickerMatch.key))); onClose(); } },
    isMine && nd && { k: 'unsend', main: true, icon: <Trash2 size={18} />, label: 'Unsend', on: onDeleteForEveryone, danger: true },
    nd && plainText && onReadAloud && { k: 'read', icon: <Volume2 size={18} />, label: 'Read aloud', on: onReadAloud },
    nd && plainText && onShareImage && { k: 'img', icon: <ImageIcon size={18} />, label: 'Share as image', on: onShareImage },
    nd && plainText && onTranslate && { k: 'tr', icon: <TranslateIcon size={18} />, label: 'Translate', on: onTranslate },
    nd && onTranscribe && !onceMsg && (message.type === 'audio' || message.type === 'voice') && { k: 'stt', main: true, icon: <FileText size={18} />, label: 'Voice to text', on: onTranscribe },
    nd && !onceMsg && onAddToAlbum && (message.type === 'image' || message.type === 'video') && !isRoundVideo(message) && { k: 'album', icon: <AlbumIcon size={18} />, label: 'Add to album', on: onAddToAlbum },
    nd && !onceMsg && message.type !== 'system' && onToggleSave && { k: 'saved', icon: <Bookmark size={18} fill={isSaved ? 'currentColor' : 'none'} />, label: isSaved ? 'Remove from Saved' : 'Add to Saved', on: onToggleSave },
    nd && message.type !== 'system' && onPin && { k: 'pin', icon: <Pin_ size={18} color={theme.ink} />, label: isPinned ? 'Unpin' : 'Pin', on: isPinned ? onUnpin : onPin },
    nd && message.type !== 'system' && onRemind && { k: 'remind', icon: <Clock size={18} />, label: 'Remind me', on: onRemind },
    { k: 'select', icon: <CheckCheck size={18} />, label: 'Select', on: onSelectMultiple },
    onInfo && message.type !== 'system' && { k: 'info', icon: <HelpCircle size={18} />, label: 'Info', on: onInfo },
    !isMine && nd && { k: 'report', icon: <Flag size={18} />, label: 'Report', on: onReport, danger: true },
    { k: 'delme', icon: <Trash2 size={18} />, label: 'Delete for me', on: onDeleteForMe, danger: true },
    !isMine && canModerate && nd && { k: 'delall', icon: <Trash2 size={18} />, label: 'Delete for everyone', on: onDeleteForEveryone, danger: true },
  ].filter(Boolean);
  const mainRows = allRows.filter((r) => r.main);
  const extraRows = allRows.filter((r) => !r.main);
  const collapse = extraRows.length > 1 && mainRows.length > 0;
  const shownRows = !collapse || more ? [...mainRows, ...extraRows] : mainRows;
  const moveT = 'top 0.24s cubic-bezier(0.2, 0.8, 0.2, 1)';

  return (
    <div onClick={guard(onClose)} onContextMenu={(e) => e.preventDefault()} style={{ position: 'fixed', inset: 0, zIndex: 95 }}>
      <div className="zchat-fade" style={{
        position: 'absolute', inset: 0,
        background: theme.dark ? 'rgba(0,0,0,0.6)' : 'rgba(18,18,26,0.38)',
      }} />
      {!message.deleted && !onceMsg && !(message.type === 'text' && isSpecialContent(message.content)) && (
        <div onClick={(e) => e.stopPropagation()} className={ready ? 'zchat-pop' : ''} style={{
          position: 'absolute', top: top - barH - gap, ...sideStyle, height: barH, boxSizing: 'border-box', transition: ready ? moveT : 'none',
          display: 'flex', alignItems: 'center', gap: 6, padding: '0 10px', borderRadius: 26,
          background: theme.panelBg, boxShadow: '0 8px 28px rgba(0,0,0,0.28)', opacity: ready ? 1 : 0,
        }}>
          {getQuickReactions().map((e) => (
            <div key={e} onClick={guard(() => onReact(e))} style={{ fontSize: 25, cursor: 'pointer', padding: '0 2px', lineHeight: 1 }}>{e}</div>
          ))}
          <div onClick={() => setShowFullEmoji(true)} style={{
            width: 30, height: 30, borderRadius: '50%', background: theme.rowBg, display: 'flex',
            alignItems: 'center', justifyContent: 'center', cursor: 'pointer', flexShrink: 0, color: theme.muted, fontSize: 18, fontWeight: 800,
          }}>+</div>
        </div>
      )}
      <div ref={bubbleRef} data-zclone="1" style={{
        position: 'absolute', top, left: rect.left, width: rect.width, paddingLeft: 18, paddingRight: 18, boxSizing: 'border-box',
        maxHeight: measured.bubble ? bubbleH : maxBubble, overflow: 'hidden', pointerEvents: 'none', opacity: ready ? 1 : 0,
        WebkitMaskImage: measured.bubble && bubbleNat > bubbleH ? 'linear-gradient(180deg, #000 78%, transparent)' : 'none', maskImage: measured.bubble && bubbleNat > bubbleH ? 'linear-gradient(180deg, #000 78%, transparent)' : 'none',
        transform: ready ? 'scale(1)' : 'scale(0.97)', transition: `transform 0.18s ease, opacity 0.12s ease${ready ? `, ${moveT}` : ''}`,
      }}>{bubble}</div>
      <div ref={menuRef} onClick={(e) => e.stopPropagation()} className={ready ? 'zchat-pop' : ''} style={{
        position: 'absolute', top: top + bubbleH + gap, ...sideStyle, width: 236, borderRadius: 16, overflowX: 'hidden', overflowY: ready && menuNat > menuMax ? 'auto' : 'hidden', transition: ready ? moveT : 'none',
        maxHeight: ready ? menuMax : undefined, WebkitOverflowScrolling: 'touch', overscrollBehavior: 'contain',
        background: theme.panelBg, boxShadow: '0 10px 32px rgba(0,0,0,0.3)', opacity: ready ? 1 : 0,
      }}>
        <div style={{ marginTop: -1 }}>
          {shownRows.map((r) => row(r.icon, r.label, r.on, r.danger, r.k, more && !r.main))}
          {collapse && !more && (
            <div key="more" role="button" aria-label="More actions" onClick={guard(() => { hapticTap(); setMore(true); })} className="zchat-row-press" style={{
              display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 16, padding: '12px 16px', cursor: 'pointer',
              fontSize: 14.5, fontWeight: 600, color: theme.ink, borderTop: `1px solid ${theme.border}`,
            }}>
              <span>More</span>
              <svg width="18" height="18" viewBox="0 0 24 24" aria-hidden="true" style={{ display: 'block' }}><circle cx="5" cy="12" r="1.9" fill="currentColor" /><circle cx="12" cy="12" r="1.9" fill="currentColor" /><circle cx="19" cy="12" r="1.9" fill="currentColor" /></svg>
            </div>
          )}
        </div>
      </div>
      {showFullEmoji && (
        <FullEmojiPicker onClose={() => setShowFullEmoji(false)} onPick={(e) => { onReact(e); setShowFullEmoji(false); }} />
      )}
    </div>
  );
}

function loadImageElement(url) {
  return new Promise((resolve, reject) => {
    const img = new Image();
    img.onload = () => resolve(img);
    img.onerror = reject;
    img.src = url;
  });
}

function PhotoCropEditor({ file, onCancel, onConfirm }) {
  useBackClose(true, onCancel);
  const { theme } = useTheme();
  const [url, setUrl] = useState(null);
  const [natural, setNatural] = useState(null);
  const [zoom, setZoom] = useState(1);
  const [offset, setOffset] = useState({ x: 0, y: 0 });
  const [saving, setSaving] = useState(false);
  const pointersRef = useRef(new Map());
  const pinchRef = useRef(null);
  const imgRef = useRef(null);
  const size = Math.max(220, Math.min((typeof window !== 'undefined' ? window.innerWidth : 360) - 48, 340));

  useEffect(() => {
    const u = URL.createObjectURL(file);
    setUrl(u);
    loadImageElement(u).then((img) => { imgRef.current = img; setNatural({ w: img.naturalWidth, h: img.naturalHeight }); }).catch(() => onCancel());
    return () => URL.revokeObjectURL(u);
  }, [file]);

  const base = natural ? Math.max(size / natural.w, size / natural.h) : 1;
  const dispW = natural ? natural.w * base * zoom : size;
  const dispH = natural ? natural.h * base * zoom : size;
  const clampOffset = (o, z) => {
    if (!natural) return o;
    const w = natural.w * base * z;
    const h = natural.h * base * z;
    const mx = Math.max(0, (w - size) / 2);
    const my = Math.max(0, (h - size) / 2);
    return { x: Math.max(-mx, Math.min(mx, o.x)), y: Math.max(-my, Math.min(my, o.y)) };
  };
  const setZoomSafe = (z) => {
    const nz = Math.max(1, Math.min(5, z));
    setZoom(nz);
    setOffset((o) => clampOffset(o, nz));
  };

  const onDown = (e) => {
    e.currentTarget.setPointerCapture?.(e.pointerId);
    pointersRef.current.set(e.pointerId, { x: e.clientX, y: e.clientY });
    if (pointersRef.current.size === 2) {
      const [a, b] = [...pointersRef.current.values()];
      pinchRef.current = { dist: Math.hypot(a.x - b.x, a.y - b.y), zoom };
    }
  };
  const onMove = (e) => {
    const prev = pointersRef.current.get(e.pointerId);
    if (!prev) return;
    pointersRef.current.set(e.pointerId, { x: e.clientX, y: e.clientY });
    if (pointersRef.current.size >= 2 && pinchRef.current) {
      const [a, b] = [...pointersRef.current.values()];
      const dist = Math.hypot(a.x - b.x, a.y - b.y);
      setZoomSafe(pinchRef.current.zoom * (dist / Math.max(1, pinchRef.current.dist)));
      return;
    }
    const dx = e.clientX - prev.x;
    const dy = e.clientY - prev.y;
    setOffset((o) => clampOffset({ x: o.x + dx, y: o.y + dy }, zoom));
  };
  const onUp = (e) => {
    pointersRef.current.delete(e.pointerId);
    if (pointersRef.current.size < 2) pinchRef.current = null;
  };

  const confirm = () => {
    if (!natural || !imgRef.current || saving) return;
    setSaving(true);
    const scale = base * zoom;
    const sw = size / scale;
    const sx = (dispW / 2 - size / 2 - offset.x) / scale;
    const sy = (dispH / 2 - size / 2 - offset.y) / scale;
    const out = 640;
    const canvas = document.createElement('canvas');
    canvas.width = out;
    canvas.height = out;
    const ctx = canvas.getContext('2d');
    ctx.drawImage(imgRef.current, sx, sy, sw, sw, 0, 0, out, out);
    canvas.toBlob((blob) => { setSaving(false); if (blob) onConfirm(blob); }, 'image/jpeg', 0.92);
  };

  return (
    <div style={{
      position: 'fixed', inset: 0, background: '#000', zIndex: 150, display: 'flex', flexDirection: 'column',
      paddingTop: 'env(safe-area-inset-top)', paddingBottom: 'env(safe-area-inset-bottom)', color: 'white',
    }} className="zchat-fade">
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '12px 16px' }}>
        <span onClick={onCancel} style={{ fontSize: 15, fontWeight: 600, cursor: 'pointer', padding: 6 }}>Cancel</span>
        <span style={{ fontSize: 15, fontWeight: 800 }}>Move and scale</span>
        <span onClick={confirm} style={{ fontSize: 15, fontWeight: 800, cursor: 'pointer', padding: 6, color: theme.gold }}>{saving ? <Spinner size={15} /> : 'Done'}</span>
      </div>
      <div style={{ flex: 1, minHeight: 0, display: 'flex', alignItems: 'center', justifyContent: 'center', overflow: 'hidden', position: 'relative' }}
        onWheel={(e) => setZoomSafe(zoom * (1 - e.deltaY * 0.0015))}>
        <div
          onPointerDown={onDown} onPointerMove={onMove} onPointerUp={onUp} onPointerCancel={onUp}
          style={{ position: 'relative', width: size, height: size, touchAction: 'none', cursor: 'grab' }}>
          {url && natural ? (
            <img src={url} alt="" draggable={false} style={{
              position: 'absolute', left: 0, top: 0, width: dispW, height: dispH, maxWidth: 'none', userSelect: 'none', pointerEvents: 'none',
              transform: `translate(${size / 2 - dispW / 2 + offset.x}px, ${size / 2 - dispH / 2 + offset.y}px)`,
            }} />
          ) : (
            <div style={{ position: 'absolute', inset: 0, display: 'flex', alignItems: 'center', justifyContent: 'center' }}><Spinner size={24} /></div>
          )}
          <div style={{ position: 'absolute', inset: 0, borderRadius: '50%', boxShadow: '0 0 0 2000px rgba(0,0,0,0.6)', border: '2px solid rgba(255,255,255,0.85)', pointerEvents: 'none' }} />
        </div>
      </div>
      <div style={{ padding: '14px 28px 22px', display: 'flex', alignItems: 'center', gap: 14 }}>
        <ImageIcon size={14} color="rgba(255,255,255,0.7)" />
        <input type="range" min="1" max="5" step="0.01" value={zoom} onChange={(e) => setZoomSafe(parseFloat(e.target.value))} style={{ flex: 1, accentColor: theme.coral }} />
        <ImageIcon size={20} color="rgba(255,255,255,0.9)" />
      </div>
    </div>
  );
}

const EDITOR_COLORS = ['#FFFFFF', '#111111', '#FF3B30', '#FF9500', '#FFCC00', '#34C759', '#2E7CF6', '#AF52DE', '#FF2D92'];
