    if (kinds.includes('frame') || (kinds.includes('effect') && after.frame && after.plate)) patch.avatar_frame = set.key;
    if (kinds.includes('nameplate') || (kinds.includes('effect') && after.frame && after.plate)) patch.nameplate = set.key;
