    localStorage.setItem(`zchat-folders-${uid}`, JSON.stringify(z.list.filter((f) => f && f.id && f.name)));
    if (z.tabs && typeof z.tabs === 'object') localStorage.setItem('zchat-chat-tabs', JSON.stringify(z.tabs));
