      <path d="M5.5 15.5c.3 1.6 1.1 2.4 2.7 2.7c-1.6.3-2.4 1.1-2.7 2.7c-.3-1.6-1.1-2.4-2.7-2.7c1.6-.3 2.4-1.1 2.7-2.7Z" />
