                    {!activeGroup && <span style={{ marginLeft: 4, verticalAlign: 'middle', display: 'inline-flex' }}><FriendEmoji rank={friendRanks[activeProfile.id]} streak={streaks[activeProfile.id]} size={12} /></span>}
