function ActiveStrip({ items }) {
  const { theme } = useTheme();
  const lp = useRef({});
  if (!items || !items.length) return null;
  const anyNote = items.some((it) => it.note != null);
  return (
    <div style={{ display: 'flex', gap: lk(14), overflowX: 'auto', padding: `4px ${lk(20)}px ${lk(10)}px`, flexShrink: 0, scrollbarWidth: 'none', WebkitOverflowScrolling: 'touch' }}>
      {items.map((it) => (
        <div key={it.key} role="button" aria-label={it.label} onClick={() => { if (lp.current.fired === it.key) { lp.current.fired = false; return; } it.onClick(); }} {...storyLongPress(lp.current, it.key, it.onLong || null)} className="zchat-press" style={{ width: lk(70), flexShrink: 0, display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 5, cursor: 'pointer', WebkitTouchCallout: 'none', userSelect: 'none' }}>
          {anyNote && (
            <div style={{ height: lk(36), width: lk(84), display: 'flex', alignItems: 'flex-end', justifyContent: 'center', marginBottom: -4, position: 'relative', zIndex: 8 }}>
              {it.note != null && <NoteBubble text={it.note || '+ Note'} muted={!it.note} song={it.note ? it.noteSong : null} label={it.noteLabel || 'Note'} onClick={it.onNote} />}
            </div>
          )}
          <div style={{ position: 'relative' }}>
            <StoryAvatar profile={it.profile} size={lk(68)} ring={it.ring || 'none'} badgePlus={!!it.plus} segments={it.segments || null} uploading={!!it.uploading} dim={!!it.muted} close={!!it.close} />
            {it.online && <span style={{ position: 'absolute', right: 3, bottom: 3, width: 15, height: 15, borderRadius: '50%', background: '#22C55E', border: `2.5px solid ${theme.bgGradient}`, zIndex: 7 }} />}
          </div>
          <div style={{ fontSize: lf(12), color: it.ring === 'unseen' ? theme.ink : theme.ink2, fontWeight: it.ring === 'unseen' ? 600 : 500, maxWidth: lk(70), whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{it.uploading ? 'Sharing' : it.name}</div>
        </div>
      ))}
    </div>
  );
}

function ActionSheet({ title, items, onClose, zIndex = 640 }) {
  useBackClose(true, onClose);
  const { theme } = useTheme();
  const drag = useSheetDrag(onClose);
  return (
    <Portal>
      <div onClick={onClose} className="zchat-fade" style={{ position: 'fixed', inset: 0, zIndex, background: 'rgba(0,0,0,0.5)', display: 'flex', alignItems: 'flex-end', justifyContent: 'center', fontFamily: FONT }}>
        <div onClick={(e) => e.stopPropagation()} className="zchat-sheet-up" {...drag.sheetProps} style={{ ...drag.sheetStyle, width: '100%', maxWidth: 480, maxHeight: 'min(86vh, calc(100% - 24px))', overflowY: 'auto', background: theme.panelBg, borderRadius: '20px 20px 0 0', paddingBottom: 'calc(10px + env(safe-area-inset-bottom))' }}>
          <div data-sheet-handle="true" style={{ display: 'flex', justifyContent: 'center', padding: '8px 0 6px', touchAction: 'none' }}><div style={{ width: 36, height: 4, borderRadius: 2, background: theme.border }} /></div>
          {title && <div data-sheet-handle="true" style={{ fontSize: 15, fontWeight: 800, color: theme.ink, textAlign: 'center', padding: '6px 16px 10px', touchAction: 'none' }}>{title}</div>}
          {items.filter(Boolean).map((it) => (
            <div key={it.k} role="button" aria-label={it.label} onClick={() => { if (it.busy) return; playUiSound('tap'); it.on(); }} className="zchat-row-press" style={{ display: 'flex', alignItems: 'center', gap: 16, padding: '0 20px', height: 54, cursor: 'pointer', color: it.danger ? theme.danger : theme.ink }}>
              <span style={{ width: 26, display: 'flex', justifyContent: 'center', flexShrink: 0 }}>{it.busy ? <Spinner size={18} color={theme.muted} /> : React.isValidElement(it.icon) ? React.cloneElement(it.icon, { size: 24, strokeWidth: 1.8, color: it.danger ? theme.danger : theme.ink }) : it.icon}</span>
              <span style={{ flex: 1, fontSize: 16, fontWeight: 500 }}>{it.label}</span>
              {it.right}
            </div>
          ))}
        </div>
      </div>
    </Portal>
  );
}

