    const off = 34 / st.current.view.s;
    const cx = (cs[0][0] + cs[2][0]) / 2;
    const cy = (cs[0][1] + cs[2][1]) / 2;
    const tx = (cs[0][0] + cs[1][0]) / 2;
    const ty = (cs[0][1] + cs[1][1]) / 2;
    const len = Math.hypot(tx - cx, ty - cy) || 1;
