const BOT_MONO = 'ui-monospace, SFMono-Regular, Menlo, Consolas, monospace';

function BotCodeBlock({ lang, code }) {
  const [copied, setCopied] = useState(false);
  const doCopy = async (e) => {
    e.stopPropagation();
    const ok = await copyTextToClipboard(code);
    if (ok) { setCopied(true); setTimeout(() => setCopied(false), 1600); }
  };
  return (
    <div onClick={(e) => e.stopPropagation()} style={{ margin: '7px 0', borderRadius: 12, overflow: 'hidden', background: '#0D1117', border: '1px solid rgba(255,255,255,0.1)', whiteSpace: 'normal', maxWidth: '100%' }}>
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '6px 8px 6px 12px', background: '#161B22', color: '#9BA7B4', fontSize: 11.5, fontWeight: 700 }}>
        <span style={{ textTransform: 'lowercase', letterSpacing: 0.3 }}>{lang || 'code'}</span>
        <div role="button" aria-label="Copy code" onClick={doCopy} style={{ display: 'flex', alignItems: 'center', gap: 5, padding: '4px 8px', borderRadius: 8, cursor: 'pointer', color: copied ? '#3FB950' : '#C9D1D9', background: 'rgba(255,255,255,0.07)', WebkitTapHighlightColor: 'transparent' }}>
          {copied ? <Check size={13} /> : <Copy size={13} />}
          <span>{copied ? 'Copied' : 'Copy code'}</span>
        </div>
      </div>
      <pre style={{ margin: 0, padding: '10px 12px', overflowX: 'auto', fontSize: 12.5, lineHeight: 1.55, color: '#E6EDF3', fontFamily: BOT_MONO, whiteSpace: 'pre', WebkitOverflowScrolling: 'touch', userSelect: 'text', WebkitUserSelect: 'text' }}><code>{code}</code></pre>
    </div>
  );
}

function renderBotInline(str, onMention) {
  return String(str).split(/(\*\*[^*\n]+\*\*|`[^`\n]+`)/g).map((p, i) => {
    if (!p) return null;
    if (p.length > 4 && p.startsWith('**') && p.endsWith('**')) return <strong key={i}><RichText text={p.slice(2, -2)} onMention={onMention} /></strong>;
    if (p.length > 2 && p.startsWith('`') && p.endsWith('`')) return <code key={i} style={{ background: 'rgba(128,128,128,0.22)', padding: '1px 5px', borderRadius: 5, fontSize: '0.92em', fontFamily: BOT_MONO }}>{p.slice(1, -1)}</code>;
    return <RichText key={i} text={p} onMention={onMention} />;
  });
}

function BotRichText({ text, onMention }) {
  const { theme } = useTheme();
  const src = String(text || '');
  const chunks = [];
  const fence = /```([^\n`]*)\n?([\s\S]*?)(?:```|$)/g;
  let last = 0;
  let hit;
  while ((hit = fence.exec(src))) {
    if (hit.index > last) chunks.push({ t: 'md', v: src.slice(last, hit.index) });
    chunks.push({ t: 'code', lang: hit[1].trim(), v: hit[2].replace(/\n$/, '') });
    last = fence.lastIndex;
    if (hit[0].length === 0) fence.lastIndex++;
  }
  if (last < src.length) chunks.push({ t: 'md', v: src.slice(last) });
  return (
    <div style={{ whiteSpace: 'normal' }}>
      {chunks.map((c, ci) => {
        if (c.t === 'code') return <BotCodeBlock key={ci} lang={c.lang} code={c.v} />;
        const lines = c.v.replace(/^\s*\n/, '').replace(/\s+$/, '').split('\n');
        return (
          <React.Fragment key={ci}>
            {lines.map((ln, li) => {
              if (!ln.trim()) return <div key={li} style={{ height: 7 }} />;
              if (/^\s*(---+|\*\*\*+)\s*$/.test(ln)) return <div key={li} style={{ height: 1, background: theme.border, margin: '8px 0' }} />;
              const h = ln.match(/^\s*(#{1,4})\s+(.*)$/);
              if (h) return <div key={li} style={{ fontWeight: 800, fontSize: h[1].length === 1 ? 17 : 15.5, margin: '6px 0 2px', lineHeight: 1.3 }}>{renderBotInline(h[2], onMention)}</div>;
              const b = ln.match(/^(\s*)[-*•]\s+(.*)$/);
              if (b) return (
                <div key={li} style={{ display: 'flex', gap: 8, paddingLeft: Math.min(b[1].length, 8) * 5, margin: '2px 0', whiteSpace: 'pre-wrap' }}>
                  <span style={{ flexShrink: 0, color: theme.coral, fontWeight: 900 }}>{'•'}</span>
                  <span style={{ minWidth: 0, flex: 1 }}>{renderBotInline(b[2], onMention)}</span>
                </div>
              );
              const n = ln.match(/^(\s*)(\d+)[.)]\s+(.*)$/);
              if (n) return (
                <div key={li} style={{ display: 'flex', gap: 7, paddingLeft: Math.min(n[1].length, 8) * 5, margin: '2px 0', whiteSpace: 'pre-wrap' }}>
                  <span style={{ flexShrink: 0, minWidth: 18, color: theme.coral, fontWeight: 800 }}>{n[2]}.</span>
                  <span style={{ minWidth: 0, flex: 1 }}>{renderBotInline(n[3], onMention)}</span>
                </div>
              );
              return <div key={li} style={{ whiteSpace: 'pre-wrap', margin: '1px 0' }}>{renderBotInline(ln, onMention)}</div>;
            })}
          </React.Fragment>
        );
      })}
    </div>
  );
}

function BotTypingBubble() {
  const { theme } = useTheme();
  return (
    <div className="zchat-pop" style={{ display: 'flex', alignItems: 'flex-end', gap: 8, padding: '4px 0 10px' }}>
      <img src="/bot-avatar.jpg" alt="" draggable={false} style={{ width: 28, height: 28, borderRadius: '50%', objectFit: 'cover', flexShrink: 0 }} />
      <div style={{ background: theme.bubbleThem, borderRadius: 19, borderBottomLeftRadius: 5, padding: '14px 16px', display: 'flex', gap: 5, alignItems: 'center', border: `1px solid ${theme.dark ? 'rgba(255,255,255,0.06)' : 'rgba(0,0,0,0.04)'}` }}>
        {[0, 1, 2].map((i) => (
          <span key={i} style={{ width: 7, height: 7, borderRadius: '50%', background: theme.muted, animation: 'zchat-dots 1.2s infinite ease-in-out', animationDelay: `${i * 0.18}s` }} />
        ))}
      </div>
    </div>
  );
}

function BotBackdrop() {
  const { theme } = useTheme();
  return <div aria-hidden="true" style={{ position: 'absolute', inset: 0, zIndex: -1, pointerEvents: 'none', background: theme.dark ? '#121117' : '#F5F3EE' }} />;
}

function BotMessageActions({ m, onRegenerate, onSave, saved }) {
  const { theme } = useTheme();
  const storeKey = `zchat-botfeedback-${m.id}`;
  const [fb, setFb] = useState(() => { try { return localStorage.getItem(storeKey) || ''; } catch { return ''; } });
  const [copied, setCopied] = useState(false);
  const pick = (val) => {
    const next = fb === val ? '' : val;
    setFb(next);
    try { if (next) localStorage.setItem(storeKey, next); else localStorage.removeItem(storeKey); } catch {}
  };
  const doCopy = async () => {
    const ok = await copyTextToClipboard(m.content);
    if (ok) { setCopied(true); setTimeout(() => setCopied(false), 1600); }
  };
  const doShare = async () => {
    try {
      if (navigator.share) { await navigator.share({ text: m.content }); return; }
    } catch { return; }
    doCopy();
  };
  const btn = (label, onClick, icon, active) => (
    <div role="button" aria-label={label} title={label} onClick={onClick} style={{
      width: 32, height: 32, borderRadius: 16, display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer',
      color: active ? theme.coral : theme.muted, background: active ? `${theme.coral}1F` : 'transparent', WebkitTapHighlightColor: 'transparent',
    }}>{icon}</div>
  );
  return (
    <div style={{ display: 'flex', alignItems: 'center', gap: 2, padding: '0 16px 6px 20px', marginTop: -2 }}>
      {btn(copied ? 'Copied' : 'Copy', doCopy, copied ? <Check size={16} /> : <Copy size={16} />, copied)}
      {btn('Good reply', () => pick('like'), <ThumbsUp size={16} fill={fb === 'like' ? 'currentColor' : 'none'} />, fb === 'like')}
      {btn('Bad reply', () => pick('dislike'), <ThumbsDown size={16} fill={fb === 'dislike' ? 'currentColor' : 'none'} />, fb === 'dislike')}
      {onSave && btn(saved ? 'Saved' : 'Save', onSave, <Bookmark size={16} fill={saved ? 'currentColor' : 'none'} />, saved)}
      {btn('Share', doShare, <Share2 size={16} />, false)}
      {onRegenerate && btn('Regenerate', onRegenerate, <Repeat size={16} />, false)}
      {copied && <span style={{ fontSize: 12, fontWeight: 700, color: theme.muted, marginLeft: 4 }}>Copied</span>}
    </div>
  );
}

function adminLog(action, target, detail) {
  try { Promise.resolve(supabase.rpc('admin_log_action', { p_action: action, p_target: target ? String(target) : null, p_detail: detail || null })).catch(() => {}); } catch {}
}

function AdminSheet({ title, body, confirmLabel, danger, busy, onConfirm, onClose, children }) {
  const { theme } = useTheme();
  return (
    <div onClick={() => !busy && onClose()} style={{ position: 'absolute', inset: 0, zIndex: 30, background: 'rgba(0,0,0,0.55)', display: 'flex', alignItems: 'flex-end' }}>
      <div onClick={(e) => e.stopPropagation()} style={{ width: '100%', background: theme.panelBg, borderRadius: '24px 24px 0 0', padding: '14px 18px', paddingBottom: 'calc(20px + env(safe-area-inset-bottom))', maxHeight: '85%', overflowY: 'auto' }}>
        <div style={{ width: 38, height: 4, borderRadius: 2, background: theme.border, margin: '0 auto 14px' }} />
        <div style={{ fontWeight: 900, fontSize: 17, color: theme.ink, marginBottom: 6 }}>{title}</div>
        {body && <div style={{ fontSize: 13.5, color: theme.muted, lineHeight: 1.55, marginBottom: 14 }}>{body}</div>}
        {children}
        {onConfirm && (
          <button disabled={busy} onClick={onConfirm} style={{ ...primaryBtn(theme, busy), background: danger ? theme.danger : theme.coral, boxShadow: 'none' }}>{busy ? <Spinner /> : confirmLabel}</button>
        )}
        <div onClick={() => !busy && onClose()} style={{ textAlign: 'center', padding: '14px 0 2px', fontWeight: 700, color: theme.muted, cursor: 'pointer' }}>Cancel</div>
      </div>
    </div>
  );
}

function AdminStatus({ tone = 'muted', children }) {
  const { theme } = useTheme();
  const color = tone === 'danger' ? theme.danger : tone === 'live' ? '#FF3B5C' : tone === 'accent' ? kitOnInk(theme) : tone === 'good' ? '#16A34A' : theme.muted;
  return (
    <span style={{ display: 'inline-flex', alignItems: 'center', gap: 6, fontSize: 12.5, fontWeight: 700, color, whiteSpace: 'nowrap', flexShrink: 0 }}>
      <span aria-hidden="true" style={{ width: 7, height: 7, borderRadius: '50%', background: color, flexShrink: 0 }} />
      {children}
    </span>
  );
}
function AdminTextBtn({ label, onClick, tone, disabled, icon, ariaLabel }) {
  const { theme } = useTheme();
  const color = tone === 'danger' ? theme.danger : tone === 'main' ? kitOnInk(theme) : theme.ink2;
  return (
    <div role="button" aria-label={ariaLabel} aria-disabled={disabled || undefined} onClick={disabled ? undefined : onClick} className={disabled ? undefined : 'zchat-press'}
      style={{ display: 'inline-flex', alignItems: 'center', gap: 6, minHeight: 36, padding: '0 2px', fontSize: 14, fontWeight: 700, color, cursor: disabled ? 'default' : 'pointer', opacity: disabled ? 0.45 : 1, whiteSpace: 'nowrap', flexShrink: 0, WebkitTapHighlightColor: 'transparent' }}>
      {icon}{label}
    </div>
  );
}
function AdminNote({ text }) {
  const { theme } = useTheme();
  return <div role="status" className="zchat-fade" style={{ padding: '6px 2px 12px', fontSize: 13.5, fontWeight: 600, color: theme.ink, lineHeight: 1.45 }}>{text}</div>;
}
function adminHair(theme, on) {
  return on ? `inset 0 -0.5px 0 ${theme.hair}` : 'none';
}
function adminWords(v) {
  return String(v == null ? '' : v).replace(/_/g, ' ');
}

function AdminPeople({ onManage }) {
  const { theme } = useTheme();
  const [filter, setFilter] = useState('all');
  const [query, setQuery] = useState('');
  const [rows, setRows] = useState(null);
  const [more, setMore] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const PAGE = 25;
  const FILTERS = [['all', 'Everyone'], ['new', 'New'], ['banned', 'Banned'], ['paused', 'Paused'], ['verified', 'Badged'], ['bots', 'Bots'], ['private', 'Private']];

  const fetchPage = async (offset) => {
    setLoading(true);
    try {
      let ids = null;
      if (filter === 'paused') {
        const { data: rs } = await supabase.from('user_restrictions').select('user_id').eq('lifted', false).gt('until', new Date().toISOString());
        ids = [...new Set((rs || []).map((r) => r.user_id))];
        if (!ids.length) { setRows([]); setMore(false); setLoading(false); return; }
      }
      let req = supabase.from('profiles').select('*').order('created_at', { ascending: false }).range(offset, offset + PAGE - 1);
      const q = query.trim().replace(/[%,()]/g, '');
      if (q) req = req.or(`name.ilike.%${q}%,username.ilike.%${q}%`);
      if (filter === 'banned') req = req.eq('banned', true);
      if (filter === 'verified') req = req.not('verified', 'is', null);
      if (filter === 'bots') req = req.eq('is_bot', true);
      if (filter === 'private') req = req.eq('is_private', true);
      if (filter === 'new') req = req.gte('created_at', new Date(Date.now() - 7 * 86400000).toISOString());
      if (ids) req = req.in('id', ids);
      const { data, error: e } = await req;
      if (e) { setError(friendlyError(e, 'Could not load people.')); setLoading(false); return; }
      setError('');
      const list = sanitizeAvatarList(data || [], '');
      setRows((prev) => (offset === 0 ? list : [...(prev || []), ...list]));
      setMore((data || []).length === PAGE);
    } catch { setError('Could not load people.'); }
    setLoading(false);
  };
  useEffect(() => {
    const t = setTimeout(() => fetchPage(0), 280);
    return () => clearTimeout(t);
  }, [filter, query]);

  return (
    <>
      <div style={{ position: 'relative', marginBottom: 4 }}>
        <Search size={16} color={theme.muted} style={{ position: 'absolute', left: 14, top: 15 }} />
        <input style={{ ...inputStyle(theme), paddingLeft: 40 }} placeholder="Search name or username" aria-label="Search people" value={query} onChange={(e) => setQuery(e.target.value)} />
      </div>
      <KitTabs label="Filter people" value={filter} onChange={setFilter} options={FILTERS} style={{ margin: '0 -16px 6px', padding: '0 8px' }} />
      {error && <div style={{ background: `${theme.danger}18`, color: theme.danger, borderRadius: 12, padding: '9px 12px', fontSize: 12.5, fontWeight: 700, margin: '6px 0 10px' }}>{error}</div>}
      {rows === null ? <div style={{ display: 'flex', justifyContent: 'center', padding: 40 }}><Spinner size={22} color={theme.ink} /></div>
        : rows.length === 0 ? <div style={{ textAlign: 'center', padding: '44px 20px', color: theme.muted, fontSize: 13.5 }}>Nobody matches this.</div>
        : rows.map((p, i) => (
          <div key={p.id} role="button" onClick={() => onManage(p)} className="zchat-row-press" style={{ display: 'flex', alignItems: 'center', gap: 12, minHeight: 64, padding: '8px 0', cursor: 'pointer', boxShadow: adminHair(theme, i < rows.length - 1) }}>
            <div style={{ position: 'relative', zIndex: 0, isolation: 'isolate', flexShrink: 0 }}><Avatar emoji={p.avatar} name={p.name} size={44} /></div>
            <div style={{ minWidth: 0, flex: 1 }}>
              <div style={{ fontWeight: 700, fontSize: 15, color: theme.ink, display: 'flex', alignItems: 'center', minWidth: 0 }}>
                <span style={{ overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{p.name}</span>
                <VerifiedBadge tier={p.verified} custom={p.custom_badge} size={13} />
              </div>
              <div style={{ fontSize: 12.5, color: theme.muted, marginTop: 1, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>@{p.username} {p.created_at ? `joined ${adminDate(p.created_at).split(',')[0]}` : ''}</div>
            </div>
            {p.banned && <AdminStatus tone="danger">Banned</AdminStatus>}
            {p.is_bot && <AdminStatus tone="accent">Bot</AdminStatus>}
            <ChevronRight size={17} color={theme.muted} style={{ flexShrink: 0 }} />
          </div>
        ))}
      {!loading && more && <div role="button" onClick={() => fetchPage(rows.length)} style={{ textAlign: 'center', padding: 14, fontWeight: 700, color: kitOnInk(theme), cursor: 'pointer' }}>Load more</div>}
      {loading && rows && rows.length > 0 && <div style={{ display: 'flex', justifyContent: 'center', padding: 16 }}><Spinner size={18} color={theme.ink} /></div>}
    </>
  );
}

const ADMIN_CONTENT = {
  posts: { label: 'Posts', who: 'user_id' },
  stories: { label: 'Stories', who: 'user_id' },
  messages: { label: 'Messages', who: 'sender_id' },
  post_comments: { label: 'Comments', who: 'user_id' },
  groups: { label: 'Groups', who: 'created_by' },
};

function AdminContent({ onOpenProfile }) {
  const { theme } = useTheme();
  const [kind, setKind] = useState('posts');
  const [search, setSearch] = useState('');
  const [rows, setRows] = useState(null);
  const [people, setPeople] = useState({});
  const [more, setMore] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [delFor, setDelFor] = useState(null);
  const [delBusy, setDelBusy] = useState(false);
  const PAGE = 20;
  const cfg = ADMIN_CONTENT[kind];

  const fetchPage = async (offset) => {
    setLoading(true);
    const { data, error: e } = await supabase.rpc('admin_table_rows', { p_table: kind, p_search: search.trim(), p_limit: PAGE, p_offset: offset });
    if (e) { setError(friendlyError(e, 'Could not load this. Run the admin SQL first.')); setLoading(false); setRows((prev) => prev || []); return; }
    setError('');
    const list = data || [];
    const ids = [...new Set(list.map((r) => r[cfg.who]).filter(Boolean))].filter((id) => !people[id]);
    if (ids.length) {
      const { data: profs } = await supabase.from('profiles').select('id, name, username, avatar, avatar_frame, nameplate, verified, custom_badge').in('id', ids);
      setPeople((prev) => { const next = { ...prev }; sanitizeAvatarList(profs || [], '').forEach((p) => { next[p.id] = p; }); return next; });
    }
    setRows((prev) => (offset === 0 ? list : [...(prev || []), ...list]));
    setMore(list.length === PAGE);
    setLoading(false);
  };
  useEffect(() => {
    setRows(null);
    const t = setTimeout(() => fetchPage(0), 280);
    return () => clearTimeout(t);
  }, [kind, search]);

  const doDelete = async () => {
    if (!delFor) return;
    setDelBusy(true);
    const { error: e } = await supabase.rpc('admin_delete_content', { p_table: kind, p_id: String(delFor.id) });
    setDelBusy(false);
    if (e) { setError(friendlyError(e, 'Could not delete that.')); setDelFor(null); return; }
    setRows((prev) => (prev || []).filter((r) => r.id !== delFor.id));
    setDelFor(null);
  };

  const media = (r) => {
    if (!r.media_url) return null;
    const isVideo = r.media_type === 'video' || /\.(mp4|mov|webm)(\?|$)/i.test(r.media_url);
    const st = { width: '100%', maxHeight: 220, borderRadius: 12, objectFit: 'cover', background: '#000', display: 'block', marginTop: 10 };
    return isVideo ? <MediaVideo src={r.media_url} controls playsInline preload="metadata" style={st} /> : <MediaImg live src={r.media_url} style={st} loading="lazy" />;
  };

  return (
    <>
      <KitTabs label="Content type" value={kind} onChange={(k) => { setKind(k); setSearch(''); }} options={Object.entries(ADMIN_CONTENT).map(([k, c]) => [k, c.label])} style={{ margin: '0 -16px 12px', padding: '0 8px' }} />
      <div style={{ position: 'relative', marginBottom: 6 }}>
        <Search size={16} color={theme.muted} style={{ position: 'absolute', left: 14, top: 15 }} />
        <input style={{ ...inputStyle(theme), paddingLeft: 40 }} placeholder={`Search ${cfg.label.toLowerCase()}`} aria-label={`Search ${cfg.label.toLowerCase()}`} value={search} onChange={(e) => setSearch(e.target.value)} />
      </div>
      {error && <div style={{ background: `${theme.danger}18`, color: theme.danger, borderRadius: 12, padding: '9px 12px', fontSize: 12.5, fontWeight: 700, margin: '6px 0 10px' }}>{error}</div>}
      {rows === null ? <div style={{ display: 'flex', justifyContent: 'center', padding: 40 }}><Spinner size={22} color={theme.ink} /></div>
        : rows.length === 0 ? <div style={{ textAlign: 'center', padding: '44px 20px', color: theme.muted, fontSize: 13.5 }}>Nothing here.</div>
        : rows.map((r, i) => {
          const who = people[r[cfg.who]];
          const text = kind === 'groups' ? r.name : (r.caption || r.content || '');
          return (
            <div key={r.id} style={{ padding: '12px 0 14px', boxShadow: adminHair(theme, i < rows.length - 1) }}>
              <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
                {who ? (
                  <div role="button" onClick={() => onOpenProfile(who)} style={{ display: 'flex', alignItems: 'center', gap: 10, minWidth: 0, flex: 1, cursor: 'pointer' }}>
                    <div style={{ position: 'relative', zIndex: 0, isolation: 'isolate', flexShrink: 0 }}><Avatar emoji={who.avatar} name={who.name} size={34} /></div>
                    <div style={{ minWidth: 0 }}>
                      <div style={{ fontWeight: 700, fontSize: 14, color: theme.ink, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{who.name}</div>
                      <div style={{ fontSize: 12, color: theme.muted }}>{adminDate(r.created_at)}</div>
                    </div>
                  </div>
                ) : <div style={{ flex: 1, fontSize: 12.5, color: theme.muted }}>{adminDate(r.created_at)}</div>}
                {kind === 'messages' && <span style={{ fontSize: 12, fontWeight: 600, color: theme.muted, flexShrink: 0 }}>{`${r.type || 'text'}${r.group_id ? ', group' : ''}`}</span>}
                <div role="button" aria-label="Delete" onClick={() => setDelFor(r)} className="zchat-press" style={{ width: 38, height: 38, marginRight: -8, display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer', color: theme.danger, flexShrink: 0 }}><Trash2 size={18} strokeWidth={1.8} /></div>
              </div>
              {text ? <div style={{ fontSize: 14, color: theme.ink, marginTop: 8, lineHeight: 1.45, wordBreak: 'break-word' }}>{r.deleted ? 'Deleted message' : String(text).slice(0, 400)}</div> : null}
              {media(r)}
            </div>
          );
        })}
      {!loading && more && <div role="button" onClick={() => fetchPage(rows.length)} style={{ textAlign: 'center', padding: 14, fontWeight: 700, color: kitOnInk(theme), cursor: 'pointer' }}>Load more</div>}
      {loading && rows && rows.length > 0 && <div style={{ display: 'flex', justifyContent: 'center', padding: 16 }}><Spinner size={18} color={theme.ink} /></div>}
      {delFor && <AdminSheet title={`Delete this ${cfg.label.toLowerCase().replace(/s$/, '')}?`} body="It is removed for everyone and cannot be brought back." confirmLabel="Delete it" danger busy={delBusy} onConfirm={doDelete} onClose={() => setDelFor(null)} />}
    </>
  );
}

function AdminKnowledge() {
  const { theme } = useTheme();
  const [rows, setRows] = useState(null);
  const [names, setNames] = useState({});
  const [query, setQuery] = useState('');
  const [status, setStatus] = useState('approved');
  const [topic, setTopic] = useState('');
  const [fact, setFact] = useState('');
  const [busy, setBusy] = useState(false);
  const [note, setNote] = useState('');
  const [error, setError] = useState('');
  const [delFor, setDelFor] = useState(null);
  const [more, setMore] = useState(false);
  const [loading, setLoading] = useState(false);
  const PAGE = 25;

  const fetchPage = async (offset) => {
    setLoading(true);
    const { data, error: e } = await supabase.rpc('admin_table_rows', { p_table: 'bot_knowledge', p_search: query.trim(), p_limit: PAGE, p_offset: offset });
    setLoading(false);
    if (e) { setError(friendlyError(e, 'Could not load what the bot has learned. Run the bot knowledge SQL first.')); setRows((p) => p || []); return; }
    setError('');
    const list = data || [];
    const extra = await adminResolveNames(list, names);
    setNames((prev) => ({ ...prev, ...extra }));
    setRows((prev) => (offset === 0 ? list : [...(prev || []), ...list]));
    setMore(list.length === PAGE);
  };
  useEffect(() => {
    setRows(null);
    const t = setTimeout(() => fetchPage(0), 280);
    return () => clearTimeout(t);
  }, [query]);

  const teach = async () => {
    if (!topic.trim() || fact.trim().length < 8 || busy) return;
    setBusy(true);
    const { error: e } = await supabase.rpc('admin_add_knowledge', { p_topic: topic.trim(), p_fact: fact.trim() });
    setBusy(false);
    if (e) { setNote(friendlyError(e, 'Could not save that.')); return; }
    setNote('The bot learned it.');
    setTopic(''); setFact('');
    setRows(null); fetchPage(0);
  };
  const setRowStatus = async (r, next) => {
    const { error: e } = await supabase.rpc('admin_update_row', { p_table: 'bot_knowledge', p_id: String(r.id), p_patch: { status: next } });
    if (e) { setNote(friendlyError(e, 'Could not change that.')); return; }
    adminLog(next === 'rejected' ? 'Rejected bot fact' : 'Restored bot fact', r.id, r.topic);
    setRows((prev) => prev.map((x) => (x.id === r.id ? { ...x, status: next } : x)));
  };
  const doDelete = async () => {
    setBusy(true);
    const { error: e } = await supabase.rpc('admin_delete_row', { p_table: 'bot_knowledge', p_id: String(delFor.id) });
    setBusy(false);
    if (e) { setNote(friendlyError(e, 'Could not delete that.')); setDelFor(null); return; }
    setRows((prev) => prev.filter((x) => x.id !== delFor.id));
    setDelFor(null);
  };

  const shown = (rows || []).filter((r) => (r.status || 'approved') === status);
  const countOf = (k) => (rows || []).filter((r) => (r.status || 'approved') === k).length;
  const cantTeach = busy || !topic.trim() || fact.trim().length < 8;

  return (
    <>
      <div style={{ padding: '6px 0 2px' }}>
        <div style={{ fontWeight: 800, fontSize: 19, color: theme.ink, letterSpacing: '-0.01em' }}>What ZChat Bot has learned</div>
        <div style={{ fontSize: 13, color: theme.muted, marginTop: 6, lineHeight: 1.5 }}>People teach it in chat. It shares what it learned with others who ask, without saying who taught it. Private details, links and anything unsafe are filtered out before they are saved.</div>
      </div>
      {note && <div style={{ marginTop: 10 }}><AdminNote text={note} /></div>}
      <KitSection title="Teach it something yourself" style={{ marginTop: 22 }}>
        <input style={inputStyle(theme)} placeholder="Topic, like Sri Lanka tea" aria-label="Topic" maxLength={60} value={topic} onChange={(e) => setTopic(e.target.value)} />
        <div style={{ height: 10 }} />
        <textarea style={{ ...inputStyle(theme), minHeight: 80, resize: 'vertical', fontFamily: FONT }} placeholder="One clear fact" aria-label="Fact" maxLength={300} value={fact} onChange={(e) => setFact(e.target.value)} />
        <button style={{ ...primaryBtn(theme, cantTeach), marginTop: 10 }} disabled={cantTeach} onClick={teach}>{busy ? <Spinner /> : 'Teach the bot'}</button>
      </KitSection>
      <KitTabs key={`${countOf('approved')}:${countOf('rejected')}`} label="Facts" value={status} onChange={setStatus} options={[['approved', 'Learned', countOf('approved')], ['rejected', 'Rejected', countOf('rejected')]]} style={{ margin: '26px -16px 12px', padding: '0 8px' }} />
      <div style={{ position: 'relative', marginBottom: 6 }}>
        <Search size={16} color={theme.muted} style={{ position: 'absolute', left: 14, top: 15 }} />
        <input style={{ ...inputStyle(theme), paddingLeft: 40 }} placeholder="Search what it knows" aria-label="Search what it knows" value={query} onChange={(e) => setQuery(e.target.value)} />
      </div>
      {error && <div style={{ background: `${theme.danger}18`, color: theme.danger, borderRadius: 12, padding: '9px 12px', fontSize: 12.5, fontWeight: 700, margin: '6px 0 10px' }}>{error}</div>}
      {rows === null ? <div style={{ display: 'flex', justifyContent: 'center', padding: 30 }}><Spinner size={20} color={theme.ink} /></div>
        : shown.length === 0 ? <div style={{ textAlign: 'center', color: theme.muted, fontSize: 13, padding: 28 }}>{status === 'approved' ? 'It has not learned anything yet.' : 'Nothing rejected.'}</div>
        : shown.map((r, i) => (
          <div key={r.id} style={{ padding: '12px 0 6px', boxShadow: adminHair(theme, i < shown.length - 1) }}>
            <div style={{ fontSize: 12.5, fontWeight: 700, color: kitOnInk(theme) }}>{r.topic}</div>
            <div style={{ fontSize: 14.5, color: theme.ink, lineHeight: 1.45, marginTop: 3, wordBreak: 'break-word' }}>{r.fact}</div>
            <div style={{ fontSize: 12, color: theme.muted, marginTop: 6 }}>{`Taught by ${(r.taught_by && names[r.taught_by]) || 'unknown'}, ${adminDate(r.created_at)}`}</div>
            <div style={{ display: 'flex', gap: 20, marginTop: 2 }}>
              {status === 'approved' ? <AdminTextBtn label="Reject" onClick={() => setRowStatus(r, 'rejected')} /> : <AdminTextBtn label="Restore" tone="main" onClick={() => setRowStatus(r, 'approved')} />}
              <AdminTextBtn label="Delete" tone="danger" onClick={() => setDelFor(r)} />
            </div>
          </div>
        ))}
      {!loading && more && <div role="button" onClick={() => fetchPage(rows.length)} style={{ textAlign: 'center', padding: 14, fontWeight: 700, color: kitOnInk(theme), cursor: 'pointer' }}>Load more</div>}
      {delFor && <AdminSheet title="Delete this fact?" body="The bot forgets it for good." confirmLabel="Delete it" danger busy={busy} onConfirm={doDelete} onClose={() => setDelFor(null)} />}
    </>
  );
}

function AdminNewest({ onManage }) {
  const { theme } = useTheme();
  const [list, setList] = useState(null);
  useEffect(() => {
    supabase.from('profiles').select('*').order('created_at', { ascending: false }).limit(12).then(({ data }) => setList(sanitizeAvatarList(data || [], '')));
  }, []);
  if (!list || !list.length) return null;
  return (
    <KitSection title="Newest people" style={{ marginTop: 26 }}>
      <div style={{ display: 'flex', gap: 14, overflowX: 'auto', margin: '0 -16px', padding: '2px 16px 4px', scrollbarWidth: 'none' }}>
        {list.map((p) => (
          <div key={p.id} role="button" aria-label={`Manage ${p.name}`} onClick={() => onManage(p)} className="zchat-press" style={{ flexShrink: 0, width: 64, textAlign: 'center', cursor: 'pointer' }}>
            <div style={{ position: 'relative', zIndex: 0, isolation: 'isolate', display: 'inline-block' }}><Avatar emoji={p.avatar} name={p.name} size={56} /></div>
            <div style={{ fontSize: 12, fontWeight: 600, color: theme.ink2, marginTop: 5, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{(p.name || '').split(' ')[0]}</div>
          </div>
        ))}
      </div>
    </KitSection>
  );
}

function AdminPanel({ myId, onClose, onOpenProfile, onOpenReports }) {
  useBackClose(true, onClose);
  const { theme } = useTheme();
  const c = igPalette(theme);
  const [tab, setTab] = useState('home');
  const [stats, setStats] = useState(null);
  const [statsError, setStatsError] = useState('');
  const [log, setLog] = useState([]);
  const [manageFor, setManageFor] = useState(null);
  const [peopleKey, setPeopleKey] = useState(0);
  const [knowCount, setKnowCount] = useState(null);
  const [bTitle, setBTitle] = useState('');
  const [bBody, setBBody] = useState('');
  const [bBusy, setBBusy] = useState(false);
  const [bConfirm, setBConfirm] = useState(false);
  const [note, setNote] = useState('');

  const loadHome = async () => {
    setStatsError('');
    const { data, error } = await supabase.rpc('admin_stats');
    if (error) { setStats(null); setStatsError(friendlyError(error, 'Could not load the numbers. Run the admin SQL files first.')); } else setStats(data || {});
    const { data: l } = await supabase.rpc('admin_recent_log', { p_limit: 8 });
    setLog(l || []);
    const { data: kc } = await supabase.rpc('admin_bot_knowledge_count');
    setKnowCount(typeof kc === 'number' ? kc : null);
  };
  useEffect(() => { loadHome(); }, []);

  const sendBroadcast = async () => {
    if (!bTitle.trim() || !bBody.trim() || bBusy) return;
    setBBusy(true);
    const { data, error } = await supabase.rpc('admin_broadcast', { p_title: bTitle.trim(), p_body: bBody.trim() });
    setBBusy(false);
    setBConfirm(false);
    if (error) { setNote(friendlyError(error, 'Could not send the announcement.')); return; }
    adminLog('Announcement', null, bTitle.trim());
    setNote(`Announcement sent to ${formatCount(Number(data) || 0)} people.`);
    setBTitle(''); setBBody('');
    loadHome();
  };

  const num = (v) => (v == null ? '—' : formatCount(Number(v) || 0));
  const openReports = stats && Number(stats.open_reports) > 0 ? Number(stats.open_reports) : 0;
  const tiles = [
    [UserPlus, 'Joined this week', stats && stats.new_week],
    [Clock, 'Active in 24 hours', stats && stats.active_day],
    [Mail, 'All messages', stats && stats.messages],
    [ImageIcon, 'Posts', stats && stats.posts],
    [Camera, 'Live stories', stats && stats.stories_live],
    [Users, 'Groups', stats && stats.groups],
    [MessageSquare, 'Bot messages', stats && stats.bot_messages],
    [FileText, 'Bot facts', knowCount, () => setTab('bot')],
    [ShieldAlert, 'Open reports', stats && stats.open_reports, onOpenReports],
    [Ban, 'Banned', stats && stats.banned, () => setTab('people')],
    [Timer, 'Paused right now', stats && stats.paused, () => setTab('people')],
  ];
  const tools = [
    [<ShieldAlert />, 'Reports', openReports ? String(openReports) : '', onOpenReports],
    [<Activity />, 'Crash reports', '', () => setTab('errors')],
    [<FileText />, 'App files', '', () => setTab('files')],
    [<GiftBoxIcon />, 'Drops', '', () => setTab('drops')],
    [<Megaphone />, 'Announce', '', () => setTab('announce')],
    [<MessageSquare />, 'Teach the bot', '', () => setTab('bot')],
    [<Database />, 'Browse data', '', () => setTab('data')],
  ];
  const signups = (stats && stats.signups) || [];
  const maxN = Math.max(1, ...signups.map((d) => Number(d.n) || 0));
  const TABS = [['home', 'Home', LayoutDashboard], ['people', 'People', Users], ['content', 'Content', ImageIcon], ['bot', 'Bot', MessageSquare], ['announce', 'Announce', Megaphone], ['data', 'Data', Database]];
  const cantSend = bBusy || !bTitle.trim() || !bBody.trim();

  return (
    <div style={{ position: 'fixed', inset: 0, zIndex: 40, background: c.bg, color: c.fg, display: 'flex', flexDirection: 'column', fontFamily: FONT, isolation: 'isolate' }} className="zchat-panel-open">
      <IgTopBar title="Admin" subtitle="ZChat control room" onBack={onClose} right={(
        <div role="button" aria-label="Report queue" onClick={onOpenReports} className="zchat-press" style={{ position: 'relative', width: 44, height: 44, display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer', color: theme.ink }}>
          <ShieldAlert size={22} strokeWidth={1.8} />
          {openReports > 0 && <span style={{ position: 'absolute', top: 5, right: 3, minWidth: 18, height: 18, borderRadius: 9, background: theme.danger, color: '#FFFFFF', fontSize: 10.5, fontWeight: 800, display: 'flex', alignItems: 'center', justifyContent: 'center', padding: '0 5px', boxSizing: 'border-box', boxShadow: `0 0 0 2px ${c.bg}` }}>{stats.open_reports}</span>}
        </div>
      )} />

      <div style={{ flex: 1, overflowY: 'auto', WebkitOverflowScrolling: 'touch', overscrollBehavior: 'contain', padding: '4px 16px 28px' }}>
        {note && <AdminNote text={note} />}

        {tab === 'home' && (
          <>
            {statsError && <div style={{ background: `${theme.danger}18`, color: theme.danger, borderRadius: 12, padding: '9px 12px', fontSize: 12.5, fontWeight: 700, marginBottom: 10 }}>{statsError}</div>}
            <div style={{ display: 'flex', padding: '10px 0 4px' }}>
              {[['online now', stats && stats.online_now, true], ['people', stats && stats.users], ['messages today', stats && stats.messages_today]].map(([label, v, live], i) => (
                <div key={label} style={{ flex: 1, minWidth: 0, paddingLeft: i ? 14 : 0, boxShadow: i ? `inset 0.5px 0 0 ${theme.hair}` : 'none' }}>
                  <div style={{ fontSize: 30, fontWeight: 800, letterSpacing: '-0.03em', color: theme.ink, lineHeight: 1.1, fontVariantNumeric: 'tabular-nums', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{num(v)}</div>
                  <div style={{ display: 'flex', alignItems: 'center', gap: 6, fontSize: 12.5, fontWeight: 600, color: theme.muted, marginTop: 5, whiteSpace: 'nowrap' }}>
                    {live && <span aria-hidden="true" style={{ width: 7, height: 7, borderRadius: '50%', background: '#22C55E', flexShrink: 0 }} />}{label}
                  </div>
                </div>
              ))}
            </div>
            <KitSection title="Tools" style={{ marginTop: 24 }}>
              {tools.map(([icon, label, value, go]) => <IgRow key={label} inset={false} icon={icon} label={label} value={value} onClick={go} />)}
            </KitSection>
            <KitSection title="Numbers" style={{ marginTop: 22 }}>
              <div style={{ display: 'grid', gridTemplateColumns: 'repeat(2, minmax(0, 1fr))' }}>
                {tiles.map(([Icon, label, value, go], i) => (
                  <div key={label} role={go ? 'button' : undefined} onClick={go} className={go ? 'zchat-press' : undefined}
                    style={{ gridColumn: i === tiles.length - 1 && i % 2 === 0 ? '1 / -1' : undefined, minWidth: 0, padding: `12px ${i % 2 ? 0 : 14}px 12px ${i % 2 ? 14 : 0}px`, cursor: go ? 'pointer' : 'default', boxShadow: [i >= 2 ? `inset 0 0.5px 0 ${theme.hair}` : '', i % 2 ? `inset 0.5px 0 0 ${theme.hair}` : ''].filter(Boolean).join(', ') || 'none' }}>
                    <div style={{ display: 'flex', alignItems: 'center', gap: 6, fontSize: 12.5, fontWeight: 600, color: theme.muted, minWidth: 0 }}>
                      <Icon size={15} strokeWidth={1.8} style={{ flexShrink: 0 }} />
                      <span style={{ minWidth: 0, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{label}</span>
                      {go && <ChevronRight size={14} style={{ flexShrink: 0, marginLeft: 'auto' }} />}
                    </div>
                    <div style={{ fontSize: 24, fontWeight: 800, color: theme.ink, letterSpacing: '-0.02em', marginTop: 5, fontVariantNumeric: 'tabular-nums' }}>{num(value)}</div>
                  </div>
                ))}
              </div>
            </KitSection>
            <AdminNewest onManage={(p) => { setTab('people'); setManageFor(p); }} />
            <KitSection title="New people, last 7 days" style={{ marginTop: 26 }}>
              <div style={{ display: 'flex', alignItems: 'flex-end', gap: 8, height: 104, paddingTop: 6 }}>
                {signups.length === 0 ? <div style={{ color: theme.muted, fontSize: 12.5 }}>No data yet.</div> : signups.map((d, i) => (
                  <div key={i} style={{ flex: 1, display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 5, height: '100%', justifyContent: 'flex-end' }}>
                    <div style={{ fontSize: 11, fontWeight: 700, color: i === signups.length - 1 ? theme.ink : theme.muted, fontVariantNumeric: 'tabular-nums' }}>{d.n}</div>
                    <div style={{ width: '100%', maxWidth: 30, height: `${Math.max(6, Math.round(((Number(d.n) || 0) / maxN) * 62))}px`, borderRadius: 7, background: theme.coral, opacity: i === signups.length - 1 ? 1 : 0.45 }} />
                    <div style={{ fontSize: 11, color: theme.muted, fontWeight: 600 }}>{fmtDate(new Date(`${d.day}T12:00:00`), { weekday: 'short' }).slice(0, 3)}</div>
                  </div>
                ))}
              </div>
            </KitSection>
            <KitSection title="Recent admin activity" right={<span role="button" aria-label="Refresh admin activity" onClick={loadHome} style={{ fontSize: 13.5, fontWeight: 700, color: kitOnInk(theme), cursor: 'pointer' }}>Refresh</span>} style={{ marginTop: 26 }}>
              {log.length === 0 ? <div style={{ color: theme.muted, fontSize: 13, padding: '4px 0' }}>Nothing yet. Bans, gifts, pauses and deletes show up here.</div> : log.map((l, i) => (
                <div key={l.id} style={{ padding: '10px 0', boxShadow: adminHair(theme, i < log.length - 1) }}>
                  <div style={{ fontSize: 14, fontWeight: 700, color: theme.ink }}>{l.action}{l.detail ? <span style={{ color: theme.muted, fontWeight: 500 }}>{`, ${l.detail}`}</span> : null}</div>
                  <div style={{ fontSize: 12, color: theme.muted, marginTop: 2 }}>{`${l.admin_name || 'Admin'}, ${adminDate(l.created_at)}`}</div>
                </div>
              ))}
            </KitSection>
          </>
        )}

        {tab === 'people' && <AdminPeople key={peopleKey} onManage={setManageFor} />}
        {tab === 'content' && <AdminContent onOpenProfile={onOpenProfile} />}
        {tab === 'bot' && <AdminKnowledge />}
        {tab === 'data' && <AdminDataBrowser />}
        {tab === 'errors' && <AdminErrors />}
        {tab === 'files' && <AdminFiles />}
        {tab === 'drops' && <AdminDrops />}

        {tab === 'announce' && (
          <KitSection title="Announcement to everyone" style={{ marginTop: 8 }}>
            <div style={{ fontSize: 13, color: theme.muted, margin: '0 0 14px', lineHeight: 1.5 }}>It lands in every person's Mail, sent from you.</div>
            <input style={inputStyle(theme)} placeholder="Title" aria-label="Announcement title" maxLength={80} value={bTitle} onChange={(e) => setBTitle(e.target.value)} />
            <div style={{ height: 10 }} />
            <textarea style={{ ...inputStyle(theme), minHeight: 130, resize: 'vertical', fontFamily: FONT }} placeholder="Message" aria-label="Announcement message" maxLength={1000} value={bBody} onChange={(e) => setBBody(e.target.value)} />
            <button style={primaryBtn(theme, cantSend)} disabled={cantSend} onClick={() => setBConfirm(true)}>{bBusy ? <Spinner /> : 'Send announcement'}</button>
          </KitSection>
        )}
      </div>

      <div style={{ display: 'flex', borderTop: `1px solid ${theme.border}`, background: c.bg, paddingBottom: 'env(safe-area-inset-bottom)' }}>
        {TABS.map(([k, label, Icon]) => (
          <div key={k} role="button" aria-current={tab === k ? 'page' : undefined} onClick={() => { setTab(k); setNote(''); }} style={{ flex: 1, padding: '9px 0 8px', display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 3, cursor: 'pointer', color: tab === k ? theme.coral : theme.muted }}>
            <Icon size={21} strokeWidth={tab === k ? 2.1 : 1.8} />
            <span style={{ fontSize: 10.5, fontWeight: tab === k ? 700 : 600 }}>{label}</span>
          </div>
        ))}
      </div>

      {manageFor && <AdminUserPanel person={manageFor} myId={myId} onClose={() => { setManageFor(null); setPeopleKey((k) => k + 1); }} onChanged={(fields) => setManageFor((cur) => (cur ? { ...cur, ...fields } : cur))} onOpenProfile={onOpenProfile} />}
      {bConfirm && <AdminSheet title="Send to everyone?" body="This cannot be taken back. Every account will get it in Mail." confirmLabel="Send now" busy={bBusy} onConfirm={sendBroadcast} onClose={() => setBConfirm(false)} />}
    </div>
  );
}

function localInputValue(d) {
  const pad = (n) => String(n).padStart(2, '0');
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}`;
}
function AdminDrops() {
  const { theme } = useTheme();
  const [list, setList] = useState(null);
  const [err, setErr] = useState('');
  const [edit, setEdit] = useState(null);
  const [busy, setBusy] = useState(false);
  const [ask, setAsk] = useState(null);
  const load = async () => {
    const { data, error } = await supabase.from('drops').select('*').order('starts_at', { ascending: false }).limit(40);
    if (error) { setErr('Drops switch on once the latest ZChat setup is finished.'); setList([]); return; }
    setErr('');
    setList(data || []);
  };
  useEffect(() => { dropArtMem.clear(); load(); }, []);
  const [artMissing, setArtMissing] = useState({});
  useEffect(() => {
    if (!list) return undefined;
    let off = false;
    list.filter((d) => d.kind === 'set').forEach((d) => { dropArtReady(d.item_key).then((ok) => { if (!off) setArtMissing((m) => (m[d.item_key] === !ok ? m : { ...m, [d.item_key]: !ok })); }); });
    return () => { off = true; };
  }, [list]);
  const fresh = () => {
    const start = new Date(Date.now() + 86400000);
    start.setMinutes(0, 0, 0);
    return { id: null, kind: 'set', item_key: DECOR_DROPS[0] ? DECOR_DROPS[0].key : DECOR_SETS[0].key, title: DECOR_DROPS[0] ? DECOR_DROPS[0].name : '', blurb: '', price: 600, start: localInputValue(start), days: 7 };
  };
  const open = (d) => setEdit(d ? { id: d.id, kind: d.kind, item_key: d.item_key, title: d.title, blurb: d.blurb || '', price: d.price, start: localInputValue(new Date(d.starts_at)), days: Math.max(1, Math.round((Date.parse(d.ends_at) - Date.parse(d.starts_at)) / 86400000)) } : fresh());
  const save = async () => {
    if (!edit || busy) return;
    const startAt = new Date(edit.start);
    if (!edit.title.trim() || Number.isNaN(startAt.getTime()) || !(Number(edit.price) > 0)) { setErr('Add a title, a start time and a price.'); return; }
    setBusy(true);
    const row = { kind: edit.kind, item_key: edit.item_key, title: edit.title.trim().slice(0, 60), blurb: edit.blurb.trim().slice(0, 200) || null, price: Math.round(Number(edit.price)), starts_at: startAt.toISOString(), ends_at: new Date(startAt.getTime() + Number(edit.days) * 86400000).toISOString() };
    const { error } = edit.id ? await supabase.from('drops').update(row).eq('id', edit.id) : await supabase.from('drops').insert(row);
    setBusy(false);
    if (error) { setErr(friendlyError(error, 'Could not save the drop.')); return; }
    adminLog(edit.id ? 'Drop changed' : 'Drop added', null, row.title);
    setEdit(null);
    loadDrops(null, true);
    load();
  };
  const endNow = async (d) => {
    setAsk(null);
    const { error } = await supabase.from('drops').update({ ends_at: new Date(Math.max(Date.parse(d.starts_at) + 60000, Date.now())).toISOString() }).eq('id', d.id);
    if (error) { setErr(friendlyError(error, 'Could not end the drop.')); return; }
    adminLog('Drop ended', null, d.title);
    load();
  };
  const remove = async (d) => {
    setAsk(null);
    const { error } = await supabase.from('drops').delete().eq('id', d.id);
    if (error) { setErr(friendlyError(error, 'Could not delete the drop.')); return; }
    adminLog('Drop deleted', null, d.title);
    load();
  };
  const field = { display: 'block', fontSize: 12.5, fontWeight: 600, color: theme.muted };
  const items = edit && edit.kind === 'bubble' ? CHAR_BUBBLE_KEYS.map((k) => [k, CHAR_BUBBLES[k].label]) : DECOR_ALL.map((st) => [st.key, st.drop ? `${st.name}, drop only` : st.name]);
  return (
    <div>
      {err && <div style={{ background: `${theme.danger}18`, color: theme.danger, borderRadius: 12, padding: '9px 12px', fontSize: 12.5, fontWeight: 700, marginBottom: 10 }}>{err}</div>}
      {edit ? (
        <KitSection title={edit.id ? 'Change drop' : 'New drop'} style={{ marginTop: 8 }}>
          <SegmentedControl value={edit.kind} onChange={(k) => setEdit((e) => ({ ...e, kind: k, item_key: k === 'bubble' ? CHAR_BUBBLE_KEYS[0] : (DECOR_DROPS[0] || DECOR_SETS[0]).key }))} options={[['set', 'Frame and nameplate'], ['bubble', 'Chat bubble']]} style={{ margin: '2px 0 12px' }} />
          <select aria-label="Item" value={edit.item_key} onChange={(e) => setEdit((x) => ({ ...x, item_key: e.target.value }))} style={inputStyle(theme)}>
            {items.map(([k, l]) => <option key={k} value={k}>{l}</option>)}
          </select>
          <div style={{ height: 10 }} />
          <input aria-label="Title" style={inputStyle(theme)} placeholder="Title" maxLength={60} value={edit.title} onChange={(e) => setEdit((x) => ({ ...x, title: e.target.value }))} />
          <div style={{ height: 10 }} />
          <textarea aria-label="About" style={{ ...inputStyle(theme), minHeight: 70, resize: 'vertical', fontFamily: FONT }} placeholder="A short line about it" maxLength={200} value={edit.blurb} onChange={(e) => setEdit((x) => ({ ...x, blurb: e.target.value }))} />
          <div style={{ display: 'flex', gap: 10, marginTop: 12 }}>
            <label style={{ ...field, flex: 1 }}>Price in coins<input type="number" min={1} max={100000} value={edit.price} onChange={(e) => setEdit((x) => ({ ...x, price: e.target.value }))} style={{ ...inputStyle(theme), marginTop: 5 }} /></label>
            <label style={{ ...field, flex: 1 }}>Days live<select value={edit.days} onChange={(e) => setEdit((x) => ({ ...x, days: Number(e.target.value) }))} style={{ ...inputStyle(theme), marginTop: 5 }}>{[1, 2, 3, 5, 7, 10, 14, 30].map((n) => <option key={n} value={n}>{n === 1 ? '1 day' : `${n} days`}</option>)}</select></label>
          </div>
          <label style={{ ...field, marginTop: 12 }}>Opens at<input type="datetime-local" value={edit.start} onChange={(e) => setEdit((x) => ({ ...x, start: e.target.value }))} style={{ ...inputStyle(theme), marginTop: 5 }} /></label>
          <div style={{ display: 'flex', gap: 10, marginTop: 16 }}>
            <button style={{ ...primaryBtn(theme, false), marginTop: 0, background: theme.soft, color: theme.ink }} onClick={() => setEdit(null)}>Cancel</button>
            <button style={{ ...primaryBtn(theme, busy), marginTop: 0 }} disabled={busy} onClick={save}>{busy ? <Spinner /> : 'Save drop'}</button>
          </div>
          <div style={{ fontSize: 12.5, color: theme.muted, marginTop: 12, lineHeight: 1.5 }}>People who tapped Remind me get a notification when it opens. Anyone who already has one part pays half.</div>
        </KitSection>
      ) : (
        <button style={{ ...primaryBtn(theme, false), marginTop: 4, marginBottom: 8 }} onClick={() => open(null)}>New drop</button>
      )}
      {!edit && (list === null ? <div style={{ display: 'flex', justifyContent: 'center', padding: 20 }}><Spinner /></div> : list.length === 0 ? <div style={{ color: theme.muted, fontSize: 13, padding: '8px 2px' }}>No drops yet.</div> : list.map((d, i) => {
        const ph = dropPhase(d);
        return (
          <div key={d.id} style={{ padding: '12px 0 4px', boxShadow: adminHair(theme, i < list.length - 1) }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
              <div style={{ flex: 1, minWidth: 0, fontWeight: 700, fontSize: 15, color: theme.ink, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{d.title}</div>
              <AdminStatus tone={ph === 'live' ? 'live' : ph === 'soon' ? 'accent' : 'muted'}>{ph === 'live' ? 'Live' : ph === 'soon' ? 'Coming' : 'Ended'}</AdminStatus>
            </div>
            <div style={{ fontSize: 12.5, color: theme.muted, marginTop: 4, lineHeight: 1.45 }}>{`${d.price} coins, ${adminDate(d.starts_at)} to ${adminDate(d.ends_at)}`}</div>
            {d.kind === 'set' && artMissing[d.item_key] && <div style={{ fontSize: 12.5, fontWeight: 700, color: theme.danger, marginTop: 4, lineHeight: 1.45 }}>Hidden from people until its frame and nameplate files are on the site</div>}
            <div style={{ display: 'flex', gap: 20, marginTop: 2 }}>
              <AdminTextBtn label="Change" tone="main" onClick={() => open(d)} />
              {ph === 'live' && <AdminTextBtn label="End now" onClick={() => setAsk({ k: 'end', d })} />}
              <AdminTextBtn label="Delete" tone="danger" onClick={() => setAsk({ k: 'del', d })} />
            </div>
          </div>
        );
      }))}
      {ask && <AdminSheet title={ask.k === 'end' ? 'End this drop now?' : 'Delete this drop?'} body={ask.k === 'end' ? 'People keep what they already got. Nobody can get it after this.' : 'People keep what they already got. The drop and its reminders are removed.'} confirmLabel={ask.k === 'end' ? 'End now' : 'Delete'} danger onConfirm={() => (ask.k === 'end' ? endNow(ask.d) : remove(ask.d))} onClose={() => setAsk(null)} />}
    </div>
  );
}

function adminDate(v) {
  if (!v) return 'never';
  const d = new Date(v);
  if (Number.isNaN(d.getTime())) return String(v);
  return d.toLocaleString([], { day: 'numeric', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit' });
}

const ADMIN_RESTRICT_KINDS = [['chat', 'Chat'], ['status', 'Status'], ['post', 'Posts']];
const ADMIN_RESTRICT_HOURS = [[1, '1 hour'], [24, '24 hours'], [72, '3 days'], [168, '7 days'], [720, '30 days']];
const ADMIN_GRANT_DAYS = [[0, 'Forever'], [7, '7 days'], [30, '30 days'], [90, '90 days']];

const ADMIN_ACTIVITY_KINDS = [['posts', 'Posts'], ['stories', 'Stories'], ['follows', 'Follows'], ['group_members', 'Groups'], ['highlights', 'Highlights'], ['user_devices', 'Devices'], ['calls', 'Calls'], ['blocks', 'Blocks'], ['message_reports', 'Reports'], ['saved_messages', 'Saved']];

function AdminUserPanel({ person, myId, onClose, onChanged, onOpenProfile }) {
  useBackClose(true, onClose);
  const { theme } = useTheme();
  const c = igPalette(theme);
  const [data, setData] = useState(null);
  const [error, setError] = useState('');
  const [note, setNote] = useState('');
  const [busy, setBusy] = useState(false);
  const [section, setSection] = useState('info');
  const [giftKind, setGiftKind] = useState('frame');
  const [giftDays, setGiftDays] = useState(0);
  const [equipNow, setEquipNow] = useState(true);
  const [rKind, setRKind] = useState('chat');
  const [rHours, setRHours] = useState(24);
  const [rReason, setRReason] = useState('');
  const [msgs, setMsgs] = useState(null);
  const [eName, setEName] = useState(person.name || '');
  const [eUser, setEUser] = useState(person.username || '');
  const [eBio, setEBio] = useState(person.bio || '');
  const [mTitle, setMTitle] = useState('');
  const [mBody, setMBody] = useState('');
  const [isAdminUser, setIsAdminUser] = useState(false);
  const [actKind, setActKind] = useState('posts');
  const [actPick, setActPick] = useState(false);
  const [confirmDo, setConfirmDo] = useState(null);
  const [multi, setMulti] = useState(false);
  const [picked, setPicked] = useState(() => new Set());
  const togglePick = (k) => setPicked((prev) => { const n = new Set(prev); if (n.has(k)) n.delete(k); else n.add(k); return n; });

  const load = async () => {
    const { data: d, error: e } = await supabase.rpc('admin_user_overview', { p_user_id: person.id });
    if (e) { setError(friendlyError(e, 'Could not load this person. Run the admin SQL files first.')); return; }
    setError('');
    setData(d || {});
  };
  useEffect(() => { load(); }, []);
  useEffect(() => {
    supabase.rpc('admin_table_rows', { p_table: 'admins', p_search: person.id, p_limit: 5, p_offset: 0 }).then(({ data: d }) => setIsAdminUser(!!(d && d.length)));
  }, [person.id]);
  useEffect(() => {
    if (section !== 'messages' || msgs) return;
    supabase.rpc('admin_user_messages', { p_user_id: person.id, p_limit: 60 }).then(({ data: d, error: e }) => {
      if (e) { setNote(friendlyError(e, 'Could not load messages.')); setMsgs([]); return; }
      setMsgs(d || []);
    });
  }, [section]);

  const act = async (fn, okText, after) => {
    if (busy) return;
    setBusy(true);
    const res = await fn();
    setBusy(false);
    if (res && res.error) { setNote(friendlyError(res.error, 'That did not work.')); return; }
    setNote(okText);
    adminLog(String(okText).replace(/\.$/, ''), person.id, profile.name);
    if (after) after(res);
    load();
  };

  const profile = (data && data.profile) || person;
  const rewards = ((data && data.rewards) || []).filter(rewardActive);
  const restrictions = ((data && data.restrictions) || []).filter((r) => !r.lifted && new Date(r.until).getTime() > Date.now());
  const ownedKey = (kind, key) => rewards.find((r) => r.kind === kind && r.reward_key === key);
  const equippedKey = giftKind === 'frame' ? profile.avatar_frame : giftKind === 'nameplate' ? profile.nameplate : profile.custom_badge;
  const catalog = giftKind === 'frame' ? DECOR_FRAME_CATALOG : giftKind === 'nameplate' ? DECOR_PLATE_CATALOG : CUSTOM_BADGES;
  const fieldOf = (kind) => (kind === 'frame' ? 'avatar_frame' : kind === 'nameplate' ? 'nameplate' : 'custom_badge');
  const isSelf = person.id === myId;

  const code = { background: theme.rowBg, border: `1px solid ${theme.border}`, borderRadius: 14, padding: 12 };
  const line = (label, value) => (
    <div key={label} style={{ display: 'flex', gap: 12, padding: '10px 0', boxShadow: `inset 0 0.5px 0 ${theme.hair}`, fontSize: 13.5 }}>
      <div style={{ width: 118, flexShrink: 0, color: theme.muted, fontWeight: 600 }}>{label}</div>
      <div style={{ flex: 1, minWidth: 0, color: theme.ink, wordBreak: 'break-word' }}>{value == null || value === '' ? 'none' : String(value)}</div>
    </div>
  );
  const pickMark = (on) => (
    <span aria-hidden="true" style={{ width: 24, height: 24, borderRadius: 12, flexShrink: 0, boxSizing: 'border-box', border: on ? 'none' : `1.6px solid ${theme.muted2}`, background: on ? theme.coral : 'transparent', display: 'flex', alignItems: 'center', justifyContent: 'center', transition: 'background 150ms ease' }}>
      {on && <Check size={14} color="#FFFFFF" strokeWidth={3} />}
    </span>
  );
  const switchRow = (label, sub, on, flip) => (
    <div role="button" aria-label={label} aria-pressed={!!on} onClick={flip} className="zchat-row-press" style={{ display: 'flex', alignItems: 'center', gap: 12, minHeight: 54, padding: '4px 0', cursor: 'pointer' }}>
      <div style={{ flex: 1, minWidth: 0 }}>
        <div style={{ fontSize: 15, fontWeight: 600, color: theme.ink }}>{label}</div>
        {sub && <div style={{ fontSize: 12.5, color: theme.muted, marginTop: 1 }}>{sub}</div>}
      </div>
      <IgToggle on={!!on} />
    </div>
  );
  const rarityColor = (spec) => (RARITY_STYLE[spec.rarity] || RARITY_STYLE.epic).color;

  const giveMany = async () => {
    if (busy || !picked.size) return;
    setBusy(true);
    const keys = [...picked].map((x) => x.split(':'));
    let ok = 0;
    let fail = null;
    const lastOf = {};
    keys.forEach(([kind, key]) => { lastOf[kind] = key; });
    for (const [kind, key] of keys) {
      const res = await supabase.rpc('admin_grant_reward', { p_user_id: person.id, p_kind: kind, p_key: key, p_days: giftDays, p_equip: equipNow && lastOf[kind] === key });
      if (res && res.error) fail = res.error; else ok += 1;
    }
    setBusy(false);
    setNote(fail ? `${ok} given. ${friendlyError(fail, 'Some did not go through.')}` : `${ok} ${ok === 1 ? 'item' : 'items'} given.`);
    if (ok) adminLog(`Gave ${ok} items`, person.id, profile.name);
    if (equipNow && ok) { const patch = {}; Object.entries(lastOf).forEach(([kind, key]) => { patch[fieldOf(kind)] = key; }); onChanged(patch); }
    setPicked(new Set());
    setMulti(false);
    load();
  };
  const ban = () => act(() => supabase.rpc('admin_ban', { p_user_id: person.id, p_reason: 'Banned by admin panel' }), 'Account banned.', () => onChanged({ banned: true }));
  const unban = () => act(() => supabase.rpc('admin_unban', { p_user_id: person.id }), 'Account unbanned.', () => onChanged({ banned: false }));
  const actions = [
    profile.banned ? [ShieldCheck, 'Unban account', unban, 'main'] : [Ban, 'Ban account', ban, 'danger'],
    [LogOut, 'Sign out everywhere', () => setConfirmDo({ title: 'Sign them out everywhere?', body: 'Every phone and browser they are logged in on is logged out.', label: 'Sign out', run: () => act(() => supabase.rpc('admin_sign_out_user', { p_user_id: person.id }), 'Signed out everywhere.') }), null],
    [isAdminUser ? ShieldOff : ShieldAlert, isAdminUser ? 'Remove admin' : 'Make admin', () => setConfirmDo({ title: isAdminUser ? 'Remove admin access?' : 'Make them an admin?', body: isAdminUser ? 'They lose the admin panel.' : 'They get this whole panel, including private messages and data.', label: isAdminUser ? 'Remove' : 'Make admin', danger: !isAdminUser, run: () => act(() => supabase.rpc('admin_set_admin', { p_user_id: person.id, p_on: !isAdminUser }), isAdminUser ? 'Admin removed.' : 'Admin added.', () => setIsAdminUser(!isAdminUser)) }), null],
    [Trash2, 'Delete account', () => setConfirmDo({ title: `Delete ${profile.name} for good?`, body: 'Their login and profile are removed. This cannot be undone.', label: 'Delete account', danger: true, run: () => act(() => supabase.rpc('admin_delete_user', { p_user_id: person.id }), 'Account deleted.', () => onClose()) }), 'danger'],
  ];
  const pauseBlocked = busy || isSelf || !!profile.is_bot;

  return (
    <div style={{ position: 'absolute', inset: 0, zIndex: 20, background: c.bg, display: 'flex', flexDirection: 'column', isolation: 'isolate' }} className="zchat-panel-open">
      <div style={{ display: 'flex', alignItems: 'center', gap: 10, padding: '4px 12px 6px 4px', paddingTop: 'calc(4px + env(safe-area-inset-top))' }}>
        <div role="button" aria-label="Back" onClick={onClose} className="zchat-press" style={{ width: 44, height: 44, display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer', color: theme.ink, flexShrink: 0 }}><ArrowLeft size={24} strokeWidth={2} /></div>
        <div style={{ position: 'relative', zIndex: 0, isolation: 'isolate', flexShrink: 0 }}><Avatar emoji={profile.avatar} name={profile.name} size={34} /></div>
        <div style={{ minWidth: 0, flex: 1 }}>
          <div style={{ fontWeight: 700, fontSize: 16, color: theme.ink, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{profile.name}</div>
          <div style={{ fontSize: 12.5, color: theme.muted, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>@{profile.username}{profile.banned ? ', banned' : ''}</div>
        </div>
        <AdminTextBtn label="Profile" tone="main" onClick={() => onOpenProfile(profile)} />
      </div>
      <KitTabs label="Account sections" value={section} onChange={(k) => { setSection(k); setNote(''); }} options={[['info', 'Info'], ['gifts', 'Gifts'], ['restrict', 'Restrict'], ['activity', 'Activity'], ['edit', 'Edit'], ['messages', 'Messages'], ['raw', 'Raw']]} style={{ padding: '0 8px', flexShrink: 0 }} />
      <div style={{ flex: 1, overflowY: 'auto', WebkitOverflowScrolling: 'touch', overscrollBehavior: 'contain', padding: '8px 16px 0', paddingBottom: 'calc(28px + env(safe-area-inset-bottom))' }}>
        {note && <AdminNote text={note} />}
        {error && <div style={{ background: `${theme.danger}18`, color: theme.danger, borderRadius: 12, padding: '9px 12px', fontSize: 12.5, fontWeight: 700, marginBottom: 10 }}>{error}</div>}
        {!data && !error && <div style={{ display: 'flex', justifyContent: 'center', padding: 40 }}><Spinner size={22} color={theme.ink} /></div>}

        {data && (section === 'info' || section === 'gifts') && (
          <div style={{ padding: '6px 0 14px', textAlign: 'center', overflow: 'hidden' }}>
            {isDecorKey(profile.avatar_frame) || isDecorKey(profile.nameplate) ? (
              <div style={{ position: 'relative', zIndex: 0, isolation: 'isolate' }}><ProfileDecorHero profile={profile} photo={profile.avatar} frameKey={isDecorKey(profile.avatar_frame) ? profile.avatar_frame : null} plateKey={isDecorKey(profile.nameplate) ? profile.nameplate : null} maxWidth={320} gapColor={c.bg} /></div>
            ) : (
              <>
                <div style={{ display: 'inline-block', position: 'relative', zIndex: 0, isolation: 'isolate' }}><Avatar emoji={profile.avatar} name={profile.name} size={104} /></div>
                <div style={{ marginTop: 10, fontWeight: 800, fontSize: 19, color: theme.ink, display: 'flex', justifyContent: 'center' }}><NameBadge name={profile.name} verified={profile.verified} custom={profile.custom_badge} size={18} style={{ justifyContent: 'center' }} /></div>
              </>
            )}
            <div style={{ fontSize: 12.5, color: theme.muted, marginTop: 6 }}>This is exactly how they look in ZChat right now.</div>
          </div>
        )}

        {data && section === 'info' && (
          <>
            <div style={{ boxShadow: `inset 0 -0.5px 0 ${theme.hair}` }}>
              {line('Email', data.auth && data.auth.email)}
              {line('Phone', data.auth && data.auth.phone)}
              {line('User id', profile.id)}
              {line('Joined', adminDate(data.auth && data.auth.created_at))}
              {line('Last sign in', adminDate(data.auth && data.auth.last_sign_in_at))}
              {line('Last seen', adminDate(profile.last_seen))}
              {line('Messages sent', data.messages_sent)}
              {line('Posts', data.posts)}
              {line('Stories', data.stories)}
              {line('Reports against', data.reports_against)}
              {line('Badge', profile.verified)}
              {line('Private account', profile.is_private ? 'yes' : 'no')}
            </div>
            {!isSelf && !profile.is_bot && (
              <KitSection title="Actions" style={{ marginTop: 24 }}>
                {actions.map(([Icon, label, fn, tone], i) => (
                  <div key={label} role="button" aria-disabled={busy || undefined} onClick={busy ? undefined : fn} className={busy ? undefined : 'zchat-row-press'}
                    style={{ display: 'flex', alignItems: 'center', gap: 14, minHeight: 50, cursor: busy ? 'default' : 'pointer', opacity: busy ? 0.5 : 1, color: tone === 'danger' ? theme.danger : tone === 'main' ? kitOnInk(theme) : theme.ink, boxShadow: adminHair(theme, i < actions.length - 1) }}>
                    <Icon size={20} strokeWidth={1.8} style={{ flexShrink: 0 }} />
                    <span style={{ fontSize: 15, fontWeight: 600 }}>{label}</span>
                  </div>
                ))}
              </KitSection>
            )}
          </>
        )}

        {data && section === 'gifts' && (
          <>
            <SegmentedControl value={giftKind} onChange={setGiftKind} options={[['frame', 'Frames'], ['nameplate', 'Nameplates'], ['charm', 'Charms'], ['badge', 'Badges']]} style={{ margin: '2px 0 8px' }} />
            {giftKind !== 'badge' && (
              <>
                {switchRow('Give several', multi ? `${picked.size} picked` : 'Pick a few, then give them all at once', multi, () => { setMulti((v) => !v); setPicked(new Set()); })}
                {multi && (
                  <div style={{ display: 'flex', alignItems: 'center', gap: 22, padding: '0 0 4px' }}>
                    <AdminTextBtn label="Select all here" tone="main" onClick={() => setPicked((prev) => { const n = new Set(prev); Object.keys(catalog).forEach((key) => n.add(`${giftKind}:${key}`)); return n; })} />
                    {picked.size > 0 && <AdminTextBtn label="Clear" onClick={() => setPicked(new Set())} />}
                  </div>
                )}
                <KitSection title="How long" style={{ marginTop: 12 }}>
                  <SegmentedControl value={giftDays} onChange={setGiftDays} options={ADMIN_GRANT_DAYS} />
                </KitSection>
                <div style={{ marginTop: 6 }}>{switchRow('Wear it right away', null, equipNow, () => setEquipNow((v) => !v))}</div>
                <div style={{ height: 1, background: theme.hair, margin: '6px 0 0' }} />
              </>
            )}
            {giftKind === 'badge' ? (
              [['', 'No badge', theme.muted], ...Object.entries(VERIFIED_TIERS).map(([k, t]) => [k, t.label, t.color])].map(([k, label], i, arr) => (
                <div key={k || 'none'} style={{ display: 'flex', alignItems: 'center', gap: 10, minHeight: 56, padding: '6px 0', boxShadow: adminHair(theme, i < arr.length - 1) }}>
                  <span style={{ flex: 1, fontWeight: 700, fontSize: 15, color: theme.ink, display: 'flex', alignItems: 'center', minWidth: 0 }}><NameBadge name={profile.name} verified={k || null} size={20} /><span style={{ fontSize: 12.5, color: theme.muted, fontWeight: 600, marginLeft: 8, flexShrink: 0 }}>{label}</span></span>
                  {(profile.verified || '') === k
                    ? <span style={{ display: 'inline-flex', alignItems: 'center', gap: 5, fontSize: 13.5, fontWeight: 700, color: kitOnInk(theme), flexShrink: 0 }}><Check size={16} strokeWidth={2.8} />Active</span>
                    : <AdminTextBtn label="Set" tone="main" disabled={busy} onClick={() => act(() => supabase.rpc('admin_set_verified', { p_user_id: person.id, p_tier: k || null }), 'Badge updated.', () => onChanged({ verified: k || null }))} />}
                </div>
              ))
            ) : Object.entries(catalog).map(([key, spec], i, arr) => {
              const own = ownedKey(giftKind, key);
              const worn = equippedKey === key;
              const sel = picked.has(`${giftKind}:${key}`);
              const status = worn ? 'Worn now' : own ? (own.expires_at ? `Owned until ${adminDate(own.expires_at)}` : 'Owned forever') : 'Not owned';
              const preview = giftKind === 'frame'
                ? <div style={{ position: 'relative', zIndex: 0, isolation: 'isolate', flexShrink: 0 }}><DecorFrameBadge setKey={key} size={76} photo={profile.avatar} name={profile.name} lazy /></div>
                : giftKind === 'charm'
                  ? <div style={{ flex: 1, minWidth: 0, fontWeight: 700, fontSize: 15, color: theme.ink, display: 'flex', alignItems: 'center' }}><NameBadge name={profile.name} verified={profile.verified} custom={key} size={30} /></div>
                  : null;
              return (
                <div key={key} role={multi ? 'button' : undefined} aria-label={multi ? `Pick ${spec.label}` : undefined} aria-pressed={multi ? sel : undefined} onClick={multi ? () => togglePick(`${giftKind}:${key}`) : undefined} className={multi ? 'zchat-row-press' : undefined}
                  style={{ padding: '12px 0', cursor: multi ? 'pointer' : 'default', boxShadow: adminHair(theme, i < arr.length - 1) }}>
                  {giftKind === 'nameplate' && (
                    <div style={{ display: 'flex', justifyContent: 'center', overflow: 'hidden', borderRadius: 12, marginBottom: 10, background: '#101119' }}>
                      <DecorPlateOnly setKey={key} width={260} name={profile.name} username={profile.username} verified={profile.verified} custom={profile.custom_badge} lazy />
                    </div>
                  )}
                  <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
                    {preview}
                    {giftKind !== 'charm' && (
                      <div style={{ flex: 1, minWidth: 0 }}>
                        <div style={{ fontWeight: 700, fontSize: 14.5, color: theme.ink, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{spec.label}</div>
                        <div style={{ fontSize: 12.5, marginTop: 1, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}><span style={{ color: rarityColor(spec), fontWeight: 700, textTransform: 'capitalize' }}>{spec.rarity || 'epic'}</span><span style={{ color: theme.muted }}>{`, ${status.toLowerCase()}`}</span></div>
                      </div>
                    )}
                    {multi ? pickMark(sel) : (
                      <div style={{ display: 'flex', gap: 16, flexShrink: 0 }}>
                        {own && <AdminTextBtn label="Remove" tone="danger" disabled={busy} onClick={() => act(() => supabase.rpc('admin_revoke_reward', { p_user_id: person.id, p_kind: giftKind, p_key: key }), 'Removed.', () => { if (worn) onChanged({ [fieldOf(giftKind)]: null }); })} />}
                        <AdminTextBtn label={own ? 'Renew' : 'Give'} tone="main" disabled={busy} onClick={() => act(() => supabase.rpc('admin_grant_reward', { p_user_id: person.id, p_kind: giftKind, p_key: key, p_days: giftDays, p_equip: equipNow }), 'Given.', () => { if (equipNow) onChanged({ [fieldOf(giftKind)]: key }); })} />
                      </div>
                    )}
                  </div>
                  {giftKind === 'charm' && <div style={{ fontSize: 12.5, color: theme.muted, marginTop: 4 }}>{`${spec.label}, ${status.toLowerCase()}`}</div>}
                </div>
              );
            })}
            {multi && picked.size > 0 && (
              <div style={{ position: 'sticky', bottom: 0, padding: '10px 0 6px', background: c.bg, zIndex: 4 }}>
                <BigButton label={busy ? 'Giving' : `Give ${picked.size} ${picked.size === 1 ? 'item' : 'items'}`} disabled={busy} onClick={giveMany} />
              </div>
            )}
          </>
        )}

        {data && section === 'restrict' && (
          <>
            <KitSection title="Pause something for a while" style={{ marginTop: 6 }}>
              <div style={{ fontSize: 13, color: theme.muted, lineHeight: 1.5, marginBottom: 12 }}>They get a Mail telling them when it ends. The database enforces it, so it cannot be skipped.</div>
              <SegmentedControl value={rKind} onChange={setRKind} options={ADMIN_RESTRICT_KINDS} />
            </KitSection>
            <KitSection title="How long" style={{ marginTop: 20 }}>
              <ChoiceList label="How long" value={rHours} onChange={setRHours} options={ADMIN_RESTRICT_HOURS.map(([h, l]) => ({ k: h, label: l }))} />
            </KitSection>
            <input style={{ ...inputStyle(theme), marginTop: 14 }} placeholder="Reason, they will see it" aria-label="Reason" value={rReason} onChange={(e) => setRReason(e.target.value)} />
            <button style={primaryBtn(theme, pauseBlocked, theme.danger)} disabled={pauseBlocked} onClick={() => act(() => supabase.rpc('admin_restrict', { p_user_id: person.id, p_kind: rKind, p_hours: rHours, p_reason: rReason }), 'Pause applied.', () => setRReason(''))}>{busy ? <Spinner /> : 'Apply pause'}</button>
            <KitSection title="Active pauses" style={{ marginTop: 28 }}>
              {restrictions.length === 0 ? <div style={{ color: theme.muted, fontSize: 13.5, padding: '2px 0' }}>None right now.</div> : restrictions.map((r, i) => (
                <div key={r.id} style={{ display: 'flex', alignItems: 'center', gap: 10, minHeight: 56, padding: '6px 0', boxShadow: adminHair(theme, i < restrictions.length - 1) }}>
                  <div style={{ flex: 1, minWidth: 0 }}>
                    <div style={{ fontWeight: 700, fontSize: 14.5, color: theme.ink }}>{(ADMIN_RESTRICT_KINDS.find((x) => x[0] === r.kind) || [0, r.kind])[1]} paused</div>
                    <div style={{ fontSize: 12.5, color: theme.muted, marginTop: 1 }}>Until {adminDate(r.until)}{r.reason ? `, ${r.reason}` : ''}</div>
                  </div>
                  <AdminTextBtn label="Lift" tone="main" disabled={busy} onClick={() => act(() => supabase.rpc('admin_lift_restriction', { p_id: r.id }), 'Pause lifted.')} />
                </div>
              ))}
            </KitSection>
          </>
        )}

        {data && section === 'edit' && (
          <>
            <KitSection title="Edit profile" style={{ marginTop: 6 }}>
              <input style={inputStyle(theme)} placeholder="Name" aria-label="Name" value={eName} onChange={(e) => setEName(e.target.value)} />
              <div style={{ height: 10 }} />
              <input style={inputStyle(theme)} placeholder="Username" aria-label="Username" value={eUser} onChange={(e) => setEUser(e.target.value.toLowerCase().replace(/[^a-z0-9._]/g, ''))} />
              <div style={{ height: 10 }} />
              <textarea style={{ ...inputStyle(theme), minHeight: 90, resize: 'vertical', fontFamily: FONT }} placeholder="Bio" aria-label="Bio" value={eBio} onChange={(e) => setEBio(e.target.value)} />
              <button style={primaryBtn(theme, busy)} disabled={busy} onClick={() => act(() => supabase.rpc('admin_update_profile', { p_user_id: person.id, p_name: eName.trim(), p_username: eUser.trim(), p_bio: eBio }), 'Profile saved.', () => onChanged({ name: eName.trim() || person.name, username: eUser.trim() || person.username, bio: eBio }))}>{busy ? <Spinner /> : 'Save changes'}</button>
            </KitSection>
            <KitSection title="Send a Mail to this person" style={{ marginTop: 30 }}>
              <div style={{ fontSize: 13, color: theme.muted, marginBottom: 12 }}>Only they will see it.</div>
              <input style={inputStyle(theme)} placeholder="Title" aria-label="Mail title" maxLength={80} value={mTitle} onChange={(e) => setMTitle(e.target.value)} />
              <div style={{ height: 10 }} />
              <textarea style={{ ...inputStyle(theme), minHeight: 90, resize: 'vertical', fontFamily: FONT }} placeholder="Message" aria-label="Mail message" maxLength={1000} value={mBody} onChange={(e) => setMBody(e.target.value)} />
              <button style={primaryBtn(theme, busy || !mTitle.trim() || !mBody.trim())} disabled={busy || !mTitle.trim() || !mBody.trim()} onClick={() => act(() => supabase.rpc('admin_send_mail', { p_user_id: person.id, p_title: mTitle.trim(), p_body: mBody.trim() }), 'Mail sent.', () => { setMTitle(''); setMBody(''); })}>{busy ? <Spinner /> : 'Send mail'}</button>
            </KitSection>
          </>
        )}

        {section === 'activity' && (
          <>
            <div role="button" aria-label="Choose what to show" onClick={() => setActPick(true)} className="zchat-row-press" style={{ display: 'flex', alignItems: 'center', gap: 10, minHeight: 50, cursor: 'pointer', boxShadow: `inset 0 -0.5px 0 ${theme.hair}`, marginBottom: 4 }}>
              <span style={{ flex: 1, fontSize: 15, fontWeight: 600, color: theme.ink }}>Show</span>
              <span style={{ fontSize: 14.5, color: theme.muted }}>{(ADMIN_ACTIVITY_KINDS.find((x) => x[0] === actKind) || ADMIN_ACTIVITY_KINDS[0])[1]}</span>
              <ChevronRight size={17} color={theme.muted} />
            </div>
            <AdminRowList key={actKind} table={actKind} search={person.id} empty="Nothing found for this person." />
            {actPick && <ChoiceSheet title="Show activity" options={ADMIN_ACTIVITY_KINDS} value={actKind} onPick={(k) => { setActKind(k); setActPick(false); }} onClose={() => setActPick(false)} />}
          </>
        )}

        {section === 'messages' && (
          msgs === null ? <div style={{ display: 'flex', justifyContent: 'center', padding: 40 }}><Spinner size={22} color={theme.ink} /></div>
          : msgs.length === 0 ? <div style={{ color: theme.muted, fontSize: 13, textAlign: 'center', padding: 30 }}>No messages found.</div>
          : msgs.map((m, i) => (
            <div key={m.id} style={{ padding: '11px 0', boxShadow: adminHair(theme, i < msgs.length - 1) }}>
              <div style={{ fontSize: 12, color: theme.muted, fontWeight: 600 }}>{`${m.sender_id === person.id ? 'Sent' : 'Received'}, ${adminWords(m.type)}${m.group_id ? ', group' : ''}, ${adminDate(m.created_at)}`}</div>
              <div style={{ fontSize: 14, color: theme.ink, marginTop: 4, wordBreak: 'break-word', lineHeight: 1.4 }}>{m.deleted ? 'Deleted message' : String(m.content || m.media_url || '').slice(0, 400)}</div>
            </div>
          ))
        )}

        {data && section === 'raw' && (
          <pre style={{ ...code, fontSize: 11.5, color: theme.ink, whiteSpace: 'pre-wrap', wordBreak: 'break-word', margin: '4px 0 0' }}>{JSON.stringify(data, null, 2)}</pre>
        )}
      </div>
      {confirmDo && <AdminSheet title={confirmDo.title} body={confirmDo.body} confirmLabel={confirmDo.label} danger={confirmDo.danger} busy={busy} onConfirm={async () => { const run = confirmDo.run; setConfirmDo(null); await run(); }} onClose={() => setConfirmDo(null)} />}
    </div>
  );
}

async function adminResolveNames(rows, known) {
  const ids = new Set();
  const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
  rows.forEach((r) => Object.keys(r).forEach((k) => { if (/(_id|_by)$/.test(k) && k !== 'id' && typeof r[k] === 'string' && uuid.test(r[k]) && !(known && known[r[k]])) ids.add(r[k]); }));
  const list = [...ids].slice(0, 120);
  if (!list.length) return {};
  const { data } = await supabase.from('profiles').select('id, name, username').in('id', list);
  const out = {};
  (data || []).forEach((p) => { out[p.id] = `${p.name} (@${p.username})`; });
  return out;
}

function AdminRowCard({ table, row, names, onDeleted, onSaved }) {
  const { theme } = useTheme();
  const [open, setOpen] = useState(false);
  const [editing, setEditing] = useState(false);
  const [text, setText] = useState('');
  const [confirm, setConfirm] = useState(false);
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState('');
  const canAct = row.id !== undefined && row.id !== null && table !== 'admins' && table !== 'admin_log';
  const keys = Object.keys(row);
  const shown = open ? keys : keys.slice(0, 4);
  const show = (k, v) => {
    if (v === null || v === undefined) return 'none';
    if (typeof v === 'string' && names && names[v]) return names[v];
    return typeof v === 'object' ? JSON.stringify(v) : String(v);
  };
  const isVideo = row.media_type === 'video' || /\.(mp4|mov|webm)(\?|$)/i.test(String(row.media_url || ''));
  const save = async () => {
    let parsed;
    try { parsed = JSON.parse(text); } catch { setErr('That is not valid JSON.'); return; }
    const patch = {};
    Object.keys(parsed).forEach((k) => { if (k !== 'id' && JSON.stringify(parsed[k]) !== JSON.stringify(row[k])) patch[k] = parsed[k]; });
    if (!Object.keys(patch).length) { setEditing(false); return; }
    setBusy(true);
    const { error } = await supabase.rpc('admin_update_row', { p_table: table, p_id: String(row.id), p_patch: patch });
    setBusy(false);
    if (error) { setErr(friendlyError(error, 'Could not save that.')); return; }
    setEditing(false); setErr('');
    if (onSaved) onSaved({ ...row, ...patch });
  };
  const del = async () => {
    setBusy(true);
    const { error } = await supabase.rpc('admin_delete_row', { p_table: table, p_id: String(row.id) });
    setBusy(false);
    setConfirm(false);
    if (error) { setErr(friendlyError(error, 'Could not delete that.')); return; }
    if (onDeleted) onDeleted();
  };
  return (
    <div style={{ padding: '12px 0 6px', boxShadow: `inset 0 -0.5px 0 ${theme.hair}` }}>
      <div role="button" aria-expanded={open} onClick={() => setOpen((v) => !v)} style={{ cursor: 'pointer' }}>
        {shown.map((k) => (
          <div key={k} style={{ display: 'flex', gap: 10, fontSize: 13, padding: '2px 0' }}>
            <div style={{ width: 104, flexShrink: 0, color: theme.muted, fontWeight: 600, wordBreak: 'break-word' }}>{adminWords(k)}</div>
            <div style={{ flex: 1, minWidth: 0, color: theme.ink, wordBreak: 'break-word' }}>{show(k, row[k]).slice(0, open ? 2000 : 90)}</div>
          </div>
        ))}
        {!open && keys.length > 4 && <div style={{ fontSize: 12.5, color: kitOnInk(theme), fontWeight: 700, marginTop: 4 }}>{`Tap for all ${keys.length} fields`}</div>}
      </div>
      {row.media_url && typeof row.media_url === 'string' && (isVideo
        ? <MediaVideo src={row.media_url} controls playsInline preload="metadata" style={{ width: '100%', maxHeight: 220, borderRadius: 12, marginTop: 8, background: '#000' }} />
        : <MediaImg live src={row.media_url} loading="lazy" style={{ width: '100%', maxHeight: 220, objectFit: 'cover', borderRadius: 12, marginTop: 8 }} />)}
      {err && <div style={{ color: theme.danger, fontSize: 12.5, fontWeight: 700, marginTop: 8 }}>{err}</div>}
      {canAct && (
        <div style={{ display: 'flex', gap: 20, marginTop: 2 }}>
          <AdminTextBtn label="Edit" tone="main" onClick={() => { setText(JSON.stringify(row, null, 2)); setErr(''); setEditing(true); }} />
          <AdminTextBtn label="Delete" tone="danger" onClick={() => setConfirm(true)} />
        </div>
      )}
      {editing && (
        <AdminSheet title={`Edit row in ${adminWords(table)}`} body="Change the values you want. Only changed fields are saved." confirmLabel="Save changes" busy={busy} onConfirm={save} onClose={() => setEditing(false)}>
          <textarea value={text} onChange={(e) => setText(e.target.value)} spellCheck={false} style={{ ...inputStyle(theme), minHeight: 260, fontFamily: 'ui-monospace, Menlo, monospace', fontSize: 12.5, resize: 'vertical' }} />
          {err && <div style={{ color: theme.danger, fontSize: 12.5, fontWeight: 700, marginTop: 8 }}>{err}</div>}
        </AdminSheet>
      )}
      {confirm && <AdminSheet title="Delete this row?" body={`It is removed from ${adminWords(table)} for good.`} confirmLabel="Delete it" danger busy={busy} onConfirm={del} onClose={() => setConfirm(false)} />}
    </div>
  );
}

function AdminRowList({ table, search, empty }) {
  const { theme } = useTheme();
  const [rows, setRows] = useState(null);
  const [names, setNames] = useState({});
  const [more, setMore] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const PAGE = 25;
  const fetchPage = async (offset) => {
    setLoading(true);
    const { data, error: e } = await supabase.rpc('admin_table_rows', { p_table: table, p_search: search || '', p_limit: PAGE, p_offset: offset });
    if (e) { setError(friendlyError(e, 'Could not load this.')); setRows((p) => p || []); setLoading(false); return; }
    setError('');
    const list = data || [];
    const extra = await adminResolveNames(list, names);
    setNames((prev) => ({ ...prev, ...extra }));
    setRows((prev) => (offset === 0 ? list : [...(prev || []), ...list]));
    setMore(list.length === PAGE);
    setLoading(false);
  };
  useEffect(() => { setRows(null); fetchPage(0); }, [table, search]);
  return (
    <>
      {error && <div style={{ background: `${theme.danger}18`, color: theme.danger, borderRadius: 12, padding: '9px 12px', fontSize: 12.5, fontWeight: 700, margin: '8px 0 10px' }}>{error}</div>}
      {rows === null ? <div style={{ display: 'flex', justifyContent: 'center', padding: 30 }}><Spinner size={20} color={theme.ink} /></div>
        : rows.length === 0 ? <div style={{ textAlign: 'center', color: theme.muted, fontSize: 13, padding: 28 }}>{empty || 'Nothing here.'}</div>
        : rows.map((r, i) => (
          <AdminRowCard key={r.id !== undefined ? r.id : i} table={table} row={r} names={names}
            onDeleted={() => setRows((prev) => prev.filter((x) => x !== r))}
            onSaved={(nr) => setRows((prev) => prev.map((x) => (x === r ? nr : x)))} />
        ))}
      {!loading && more && <div role="button" onClick={() => fetchPage(rows.length)} style={{ textAlign: 'center', padding: 14, fontWeight: 700, color: kitOnInk(theme), cursor: 'pointer' }}>Load more</div>}
    </>
  );
}

function AdminDataBrowser() {
  const { theme } = useTheme();
  const [tables, setTables] = useState(null);
  const [error, setError] = useState('');
  const [table, setTable] = useState(null);
  const [search, setSearch] = useState('');
  const [rows, setRows] = useState([]);
  const [loading, setLoading] = useState(false);
  const [more, setMore] = useState(false);
  const [names, setNames] = useState({});
  const PAGE = 30;

  useEffect(() => {
    supabase.rpc('admin_list_tables').then(({ data, error: e }) => {
      if (e) { setError(friendlyError(e, 'Could not list tables. Run the admin SQL files first.')); return; }
      setTables(data || []);
    });
  }, []);

  const fetchRows = async (name, text, offset) => {
    setLoading(true);
    const { data, error: e } = await supabase.rpc('admin_table_rows', { p_table: name, p_search: text, p_limit: PAGE, p_offset: offset });
    setLoading(false);
    if (e) { setError(friendlyError(e, 'Could not read that table.')); return; }
    setError('');
    const list = data || [];
    const extra = await adminResolveNames(list, names);
    setNames((prev) => ({ ...prev, ...extra }));
    setRows((prev) => (offset === 0 ? list : [...prev, ...list]));
    setMore(list.length === PAGE);
  };
  useEffect(() => {
    if (!table) return undefined;
    const t = setTimeout(() => { fetchRows(table, search, 0); }, 300);
    return () => clearTimeout(t);
  }, [table, search]);

  const errBox = error ? <div style={{ background: `${theme.danger}18`, color: theme.danger, borderRadius: 12, padding: '9px 12px', fontSize: 12.5, fontWeight: 700, marginBottom: 10 }}>{error}</div> : null;

  if (!table) {
    const list = tables || [];
    return (
      <>
        {errBox}
        {tables === null && !error ? <div style={{ display: 'flex', justifyContent: 'center', padding: 40 }}><Spinner size={22} color={theme.ink} /></div> : (
          <KitSection title="Tables" right={list.length ? `${list.length}` : null} style={{ marginTop: 6 }}>
            {list.map((t, i) => (
              <div key={t.name} role="button" onClick={() => { setTable(t.name); setSearch(''); setRows([]); }} className="zchat-row-press" style={{ display: 'flex', alignItems: 'center', gap: 14, minHeight: 50, cursor: 'pointer', boxShadow: adminHair(theme, i < list.length - 1) }}>
                <Database size={18} strokeWidth={1.8} color={theme.muted} style={{ flexShrink: 0 }} />
                <div style={{ flex: 1, minWidth: 0, fontWeight: 600, fontSize: 15, color: theme.ink, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{adminWords(t.name)}</div>
                <div style={{ fontSize: 13.5, color: theme.muted, fontVariantNumeric: 'tabular-nums' }}>{t.rows == null ? '' : formatCount(Number(t.rows) || 0)}</div>
                <ChevronRight size={16} color={theme.muted} style={{ flexShrink: 0 }} />
              </div>
            ))}
          </KitSection>
        )}
      </>
    );
  }
  return (
    <>
      <div style={{ display: 'flex', alignItems: 'center', gap: 6, margin: '0 0 10px -10px' }}>
        <div role="button" aria-label="Back to tables" onClick={() => { setTable(null); setRows([]); setError(''); }} className="zchat-press" style={{ width: 40, height: 40, display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer', color: theme.ink, flexShrink: 0 }}><ArrowLeft size={20} /></div>
        <div style={{ fontWeight: 800, fontSize: 17, color: theme.ink, minWidth: 0, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{adminWords(table)}</div>
      </div>
      <div style={{ position: 'relative', marginBottom: 6 }}>
        <Search size={16} color={theme.muted} style={{ position: 'absolute', left: 14, top: 15 }} />
        <input style={{ ...inputStyle(theme), paddingLeft: 40 }} placeholder="Search inside this table" aria-label="Search inside this table" value={search} onChange={(e) => setSearch(e.target.value)} />
      </div>
      {errBox}
      {rows.map((r, i) => (
        <AdminRowCard key={r.id !== undefined ? r.id : i} table={table} row={r} names={names}
          onDeleted={() => setRows((prev) => prev.filter((x) => x !== r))}
          onSaved={(nr) => setRows((prev) => prev.map((x) => (x === r ? nr : x)))} />
      ))}
      {loading && <div style={{ display: 'flex', justifyContent: 'center', padding: 20 }}><Spinner size={20} color={theme.ink} /></div>}
      {!loading && rows.length === 0 && !error && <div style={{ textAlign: 'center', color: theme.muted, fontSize: 13, padding: 30 }}>Nothing here.</div>}
      {!loading && more && <div role="button" onClick={() => fetchRows(table, search, rows.length)} style={{ textAlign: 'center', padding: 14, fontWeight: 700, color: kitOnInk(theme), cursor: 'pointer' }}>Load more</div>}
    </>
  );
}

function ReportQueuePanel({ onClose, onOpenProfile }) {
  useBackClose(true, onClose);
  const { theme } = useTheme();
  const [items, setItems] = useState(null);
  const [people, setPeople] = useState({});
  const [problems, setProblems] = useState([]);
  const [tab, setTab] = useState('open');
  const [states, setStates] = useState(() => readReportStates());
  const [banFor, setBanFor] = useState(null);
  const [banReason, setBanReason] = useState('');
  const [banBusy, setBanBusy] = useState(false);
  const [banError, setBanError] = useState('');
  const [bannedIds, setBannedIds] = useState(() => new Set());

  const fetchByIds = async (table, columns, ids) => {
    const out = [];
    for (let i = 0; i < ids.length; i += 60) {
      const { data } = await supabase.from(table).select(columns).in('id', ids.slice(i, i + 60));
      if (data) out.push(...data);
    }
    return out;
  };

  const load = async () => {
    setItems(null);
    const issues = [];
    let mr = { data: [], error: null };
    let rq = { data: [], error: null };
    try {
      [mr, rq] = await Promise.all([
        supabase.from('message_reports').select('*').limit(300),
        supabase.from('report_queue').select('*').limit(300),
      ]);
    } catch (thrown) {
      issues.push("Couldn't reach the server.");
    }
    if (mr.error) issues.push(friendlyError(mr.error, "Couldn't read message reports."));
    if (rq.error) issues.push(friendlyError(rq.error, "Couldn't read the report queue."));
    const fromMessages = (mr.data || []).map((r) => normalizeReport(r, 'message_reports'));
    const fromQueue = (rq.data || []).map((r) => normalizeReport(r, 'report_queue'));
    const linked = new Set(fromQueue.map((r) => (r.linkedId != null ? String(r.linkedId) : null)).filter(Boolean));
    const seenSig = new Set(fromQueue.filter((r) => r.messageId).map((r) => `${r.reporterId}|${r.messageId}|${r.reason}`));
    const rows = [
      ...fromQueue,
      ...fromMessages.filter((r) => !(r.id != null && linked.has(String(r.id))) && !seenSig.has(`${r.reporterId}|${r.messageId}|${r.reason}`)),
    ];
    const msgIds = [...new Set(rows.map((r) => r.messageId).filter(Boolean))];
    if (msgIds.length) {
      const msgs = await fetchByIds('messages', 'id, sender_id, receiver_id, group_id, type, content, media_url, story_id, deleted', msgIds);
      const byId = {};
      msgs.forEach((m) => { byId[m.id] = m; });
      rows.forEach((r) => {
        const m = byId[r.messageId];
        if (m) { r.message = m; if (!r.targetId) r.targetId = m.sender_id; }
      });
    }
    const pids = [...new Set(rows.flatMap((r) => [r.reporterId, r.targetId]).filter(Boolean))];
    const profs = pids.length ? await fetchByIds('profiles', '*', pids) : [];
    const map = {};
    sanitizeAvatarList(profs, '').forEach((p) => { map[p.id] = p; });
    rows.sort((x, y) => new Date(y.createdAt || 0).getTime() - new Date(x.createdAt || 0).getTime());
    setPeople(map);
    setProblems(issues);
    setItems(rows);
  };
  useEffect(() => { load(); }, []);

  const isHandled = (it) => (states[it.key] !== undefined ? states[it.key] === 'handled' : it.dbHandled);
  const setHandled = async (it, handled) => {
    const next = { ...states, [it.key]: handled ? 'handled' : 'open' };
    setStates(next);
    writeReportStates(next);
    if (it.id != null) {
      try { await supabase.from(it.source).update({ status: handled ? 'handled' : 'open' }).eq('id', it.id); } catch {}
    }
  };

  const doBan = async () => {
    if (!banFor || banBusy) return;
    setBanBusy(true);
    setBanError('');
    const { error } = await supabase.rpc('admin_ban', { p_user_id: banFor.target.id, p_reason: banReason || `Report: ${banFor.item.reason}` });
    setBanBusy(false);
    if (error) { setBanError(friendlyError(error, 'Could not ban this account.')); return; }
    setBannedIds((prev) => new Set([...prev, banFor.target.id]));
    setHandled(banFor.item, true);
    setBanFor(null);
    setBanReason('');
  };

  const list = (items || []).filter((it) => (tab === 'open' ? !isHandled(it) : isHandled(it)));
  const openCount = (items || []).filter((it) => !isHandled(it)).length;
  const doneCount = (items || []).length - openCount;

  const person = (label, p) => (
    <div role="button" onClick={() => p && onOpenProfile(p)} style={{ display: 'flex', alignItems: 'center', gap: 8, marginTop: 8, cursor: p ? 'pointer' : 'default' }}>
      <div style={{ fontSize: 12.5, color: theme.muted, width: 92, flexShrink: 0, fontWeight: 600 }}>{label}</div>
      {p ? (
        <>
          <Avatar emoji={p.avatar} name={p.name} size={24} />
          <div style={{ fontSize: 13.5, fontWeight: 700, color: theme.ink, minWidth: 0, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
            {p.name} <span style={{ color: theme.muted, fontWeight: 500 }}>@{p.username}</span>
          </div>
          {(p.banned || bannedIds.has(p.id)) && <AdminStatus tone="danger">Banned</AdminStatus>}
        </>
      ) : <div style={{ fontSize: 13.5, color: theme.muted }}>Unknown account</div>}
    </div>
  );

  return (
    <>
    <WideDim onClose={onClose} z={40} />
    <div style={{ position: 'fixed', inset: 0, zIndex: 40, background: theme.bgGradient, display: 'flex', flexDirection: 'column', fontFamily: FONT }} className="zchat-panel-open zchat-wide-page">
      <IgTopBar title="Report queue" onBack={onClose} right={<div role="button" aria-label="Refresh reports" onClick={load} style={{ fontSize: 14, fontWeight: 700, color: kitOnInk(theme), cursor: 'pointer', padding: '0 10px', height: 44, display: 'flex', alignItems: 'center' }}>Refresh</div>} />
      <KitTabs key={`${openCount}:${doneCount}`} label="Reports" value={tab} onChange={setTab} options={[['open', 'Open', openCount], ['handled', 'Handled', doneCount]]} style={{ padding: '0 8px', flexShrink: 0 }} />
      <div style={{ flex: 1, overflowY: 'auto', WebkitOverflowScrolling: 'touch', overscrollBehavior: 'contain', padding: '4px 16px 0', paddingBottom: 'calc(24px + env(safe-area-inset-bottom))' }}>
        {problems.map((p, i) => (
          <div key={i} style={{ background: `${theme.danger}18`, color: theme.danger, borderRadius: 12, padding: '9px 12px', fontSize: 12.5, fontWeight: 700, margin: '8px 0' }}>{p}</div>
        ))}
        {items === null ? (
          <div style={{ display: 'flex', justifyContent: 'center', padding: 40 }}><Spinner size={22} color={theme.ink} /></div>
        ) : list.length === 0 ? (
          <div style={{ textAlign: 'center', padding: '50px 20px', color: theme.muted }}>
            <div style={{ fontWeight: 700, fontSize: 15.5, color: theme.ink }}>{tab === 'open' ? 'No open reports' : 'Nothing handled yet'}</div>
            <div style={{ fontSize: 13, marginTop: 6 }}>{tab === 'open' ? 'New abuse reports show up here.' : 'Reports you mark as handled move here.'}</div>
          </div>
        ) : list.map((it, i) => {
          const reporter = people[it.reporterId];
          const target = people[it.targetId];
          const preview = it.message ? describeMessage(it.message).text : null;
          const targetBanned = !!target && (target.banned || bannedIds.has(target.id));
          return (
            <div key={it.key} style={{ padding: '14px 0 6px', boxShadow: adminHair(theme, i < list.length - 1) }}>
              <div style={{ display: 'flex', alignItems: 'baseline', justifyContent: 'space-between', gap: 10 }}>
                <div style={{ fontWeight: 800, fontSize: 15.5, color: theme.ink, minWidth: 0 }}>{it.reason}</div>
                {it.createdAt && <div style={{ fontSize: 12, color: theme.muted, flexShrink: 0 }}>{timeAgoLong(it.createdAt)}</div>}
              </div>
              {person('Reported by', reporter)}
              {person('Account', target)}
              {(it.message || it.messageId) && (
                <div style={{ marginTop: 10, padding: '9px 12px', borderRadius: 12, background: theme.dark ? 'rgba(255,255,255,0.06)' : 'rgba(0,0,0,0.04)', fontSize: 13.5, color: theme.ink, lineHeight: 1.4, wordBreak: 'break-word' }}>
                  {preview ? String(preview).slice(0, 220) : 'That message is no longer available.'}
                </div>
              )}
              {it.details && <div style={{ marginTop: 8, fontSize: 13, color: theme.muted, lineHeight: 1.45 }}>{String(it.details).slice(0, 300)}</div>}
              <div style={{ display: 'flex', gap: 20, flexWrap: 'wrap', marginTop: 4 }}>
                {target && <AdminTextBtn label="Open profile" onClick={() => onOpenProfile(target)} />}
                {target && !targetBanned && <AdminTextBtn label="Ban" tone="danger" onClick={() => { setBanFor({ item: it, target }); setBanError(''); }} />}
                {isHandled(it) ? <AdminTextBtn label="Reopen" onClick={() => setHandled(it, false)} /> : <AdminTextBtn label="Mark handled" tone="main" icon={<Check size={16} strokeWidth={2.6} />} onClick={() => setHandled(it, true)} />}
              </div>
            </div>
          );
        })}
      </div>
      {banFor && (
        <div onClick={() => !banBusy && setBanFor(null)} style={{ position: 'absolute', inset: 0, background: 'rgba(0,0,0,0.5)', display: 'flex', alignItems: 'flex-end' }}>
          <div onClick={(e) => e.stopPropagation()} style={{ width: '100%', background: theme.panelBg, borderRadius: '22px 22px 0 0', padding: '20px 18px', paddingBottom: 'calc(20px + env(safe-area-inset-bottom))' }}>
            <div style={{ fontWeight: 900, fontSize: 17, color: theme.ink, marginBottom: 8 }}>Ban @{banFor.target.username} from ZChat?</div>
            <div style={{ fontSize: 13.5, color: theme.muted, lineHeight: 1.6, marginBottom: 14 }}>
              This blocks their login, their email and their phone, and removes every message they sent.
            </div>
            <input style={inputStyle(theme)} placeholder="Reason, for your records" value={banReason} onChange={(e) => setBanReason(e.target.value)} />
            {banError && <div style={{ color: theme.danger, fontSize: 12.5, marginTop: 8 }}>{banError}</div>}
            <button style={{ ...primaryBtn(theme, banBusy), background: theme.danger, marginTop: 14 }} disabled={banBusy} onClick={doBan}>
              {banBusy ? <Spinner /> : 'Ban this account'}
            </button>
            <div onClick={() => !banBusy && setBanFor(null)} style={{ textAlign: 'center', padding: '14px 0 2px', fontWeight: 700, color: theme.muted, cursor: 'pointer' }}>Cancel</div>
          </div>
        </div>
      )}
    </div>
    </>
  );
}

const DISAPPEAR_OPTIONS = [[0, 'Off'], [86400, '24 hours'], [604800, '7 days'], [7776000, '90 days']];
function disappearLabel(secs) {
  const found = DISAPPEAR_OPTIONS.find(([v]) => v === Number(secs || 0));
  return found ? found[1] : 'Off';
}

function DisappearSheet({ value, canEdit = true, subject = 'this chat', onPick, onClose }) {
  useBackClose(true, onClose);
  const { theme } = useTheme();
  const current = Number(value || 0);
  const sheet = (
    <div onClick={onClose} className="zchat-fade" style={{ position: 'fixed', inset: 0, zIndex: 700, background: 'rgba(0,0,0,0.5)', display: 'flex', alignItems: 'flex-end', fontFamily: FONT }}>
      <div onClick={(e) => e.stopPropagation()} className="zchat-sheet-up" style={{ width: '100%', background: theme.panelBg, borderRadius: '22px 22px 0 0', padding: '20px 18px', paddingBottom: 'calc(20px + env(safe-area-inset-bottom))' }}>
        <div style={{ fontWeight: 900, fontSize: 17, color: theme.ink }}>Disappearing messages</div>
        <div style={{ fontSize: 12.5, color: theme.muted, lineHeight: 1.5, margin: '6px 0 12px' }}>
          New messages in {subject} disappear for everyone after the time you choose. Messages already sent stay.
        </div>
        {DISAPPEAR_OPTIONS.map(([secs, label]) => (
          <div key={secs} role="button" onClick={() => { if (!canEdit) return; if (secs !== current) onPick(secs); onClose(); }} style={{
            display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '13px 4px', borderTop: `1px solid ${theme.border}`,
            cursor: canEdit ? 'pointer' : 'default', opacity: canEdit || secs === current ? 1 : 0.5,
          }}>
            <span style={{ fontSize: 14.5, fontWeight: 700, color: theme.ink }}>{label}</span>
            <span style={{ width: 20, height: 20, borderRadius: 10, border: `2px solid ${current === secs ? theme.coral : theme.border}`, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
              {current === secs && <span style={{ width: 10, height: 10, borderRadius: 5, background: theme.coral }} />}
            </span>
          </div>
        ))}
        {!canEdit && <div style={{ fontSize: 12, color: theme.muted, marginTop: 10 }}>Only group admins can change this.</div>}
      </div>
    </div>
  );
  return ReactDOM.createPortal(sheet, document.body);
}

function jwtSessionId(tok) {
  try {
    const part = String(tok || '').split('.')[1] || '';
    const o = JSON.parse(atob(part.replace(/-/g, '+').replace(/_/g, '/')));
    return o && /^[0-9a-f-]{36}$/i.test(String(o.session_id || '')) ? o.session_id : null;
  } catch { return null; }
}
function getDeviceId() {
  try {
    let id = localStorage.getItem('zchat-device-id');
    if (!id) {
      id = (typeof crypto !== 'undefined' && crypto.randomUUID) ? crypto.randomUUID() : `d${Date.now().toString(36)}${Math.random().toString(36).slice(2, 10)}`;
      localStorage.setItem('zchat-device-id', id);
    }
    return id;
  } catch { return 'unknown'; }
}

function deviceLabelNow() {
  const ua = (typeof navigator !== 'undefined' && navigator.userAgent) || '';
  let os = 'the web';
  if (/iPhone/.test(ua)) os = 'iPhone';
  else if (/iPad/.test(ua)) os = 'iPad';
  else if (/Android/.test(ua)) os = 'Android';
  else if (/Windows/.test(ua)) os = 'Windows';
  else if (/Mac OS X|Macintosh/.test(ua)) os = 'Mac';
  else if (/Linux/.test(ua)) os = 'Linux';
  let browser = 'Browser';
  if (/Edg\//.test(ua)) browser = 'Edge';
  else if (/OPR\/|Opera/.test(ua)) browser = 'Opera';
  else if (/Firefox|FxiOS/.test(ua)) browser = 'Firefox';
  else if (/CriOS|Chrome/.test(ua)) browser = 'Chrome';
  else if (/Safari/.test(ua)) browser = 'Safari';
  let standalone = false;
  try { standalone = (window.matchMedia && window.matchMedia('(display-mode: standalone)').matches) || navigator.standalone === true; } catch {}
  return standalone ? `ZChat app on ${os}` : `${browser} on ${os}`;
}

function TwoFactorSection() {
  const { theme } = useTheme();
  const [phase, setPhase] = useState('loading');
  const [factor, setFactor] = useState(null);
  const [setup, setSetup] = useState(null);
  const [code, setCode] = useState('');
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState('');
  const [copied, setCopied] = useState(false);
  const mfa = supabase.auth && supabase.auth.mfa;

  const refresh = async () => {
    if (!mfa || !mfa.listFactors) { setErr('Two factor is not available right now.'); setPhase('off'); return; }
    try {
      const { data, error } = await mfa.listFactors();
      if (error) throw error;
      const verified = ((data && data.totp) || []).find((f) => f.status === 'verified') || null;
      setFactor(verified);
      setPhase(verified ? 'on' : 'off');
    } catch (e) {
      setErr(friendlyError(e, "Couldn't check two factor. Try again."));
      setPhase('off');
    }
  };
  useEffect(() => { refresh(); }, []);

  const startSetup = async () => {
    if (busy) return;
    setBusy(true); setErr('');
    try {
      const { data: listed } = await mfa.listFactors();
      const stale = ((listed && listed.all) || []).filter((f) => f.factor_type === 'totp' && f.status !== 'verified');
      for (const f of stale) await mfa.unenroll({ factorId: f.id });
      const { data, error } = await mfa.enroll({ factorType: 'totp', friendlyName: `ZChat ${Math.random().toString(36).slice(2, 7)}`, issuer: 'ZChat' });
      if (error) throw error;
      setSetup({ id: data.id, qr: data.totp && data.totp.qr_code, secret: data.totp && data.totp.secret });
      setCode('');
      setPhase('setup');
    } catch (e) {
      setErr(friendlyError(e, "Couldn't start two factor setup. Try again."));
    }
    setBusy(false);
  };

  const confirmSetup = async () => {
    if (busy || code.length !== 6 || !setup) return;
    setBusy(true); setErr('');
    try {
      const { error } = await mfa.challengeAndVerify({ factorId: setup.id, code });
      if (error) throw error;
      setSetup(null); setCode('');
      await refresh();
    } catch (e) {
      setErr(/invalid|expired|incorrect/i.test(String((e && e.message) || e)) ? 'That code is not right. Try the newest code.' : friendlyError(e, "Couldn't check that code. Try again."));
      setCode('');
    }
    setBusy(false);
  };

  const cancelSetup = async () => {
    const pending = setup;
    setSetup(null); setCode(''); setErr(''); setPhase('off');
    if (pending) { try { await mfa.unenroll({ factorId: pending.id }); } catch {} }
  };

  const turnOff = async () => {
    if (busy || code.length !== 6 || !factor) return;
    setBusy(true); setErr('');
    try {
      const { error: verifyErr } = await mfa.challengeAndVerify({ factorId: factor.id, code });
      if (verifyErr) throw verifyErr;
      const { error } = await mfa.unenroll({ factorId: factor.id });
      if (error) throw error;
      setCode('');
      await refresh();
    } catch (e) {
      setErr(/invalid|expired|incorrect/i.test(String((e && e.message) || e)) ? 'That code is not right. Try the newest code.' : friendlyError(e, "Couldn't turn it off. Try again."));
      setCode('');
    }
    setBusy(false);
  };

  const copySecret = async () => {
    try { await navigator.clipboard.writeText(setup.secret); setCopied(true); setTimeout(() => setCopied(false), 1600); } catch {}
  };

  const codeInput = (
    <input value={code} inputMode="numeric" autoComplete="one-time-code" maxLength={6} placeholder="6 digit code"
      onChange={(e) => setCode(e.target.value.replace(/\D/g, '').slice(0, 6))}
      style={{ ...inputStyle(theme), textAlign: 'center', letterSpacing: 6, fontSize: 20, fontWeight: 800 }} />
  );

  if (phase === 'loading') return <div style={{ display: 'flex', justifyContent: 'center', padding: 30 }}><Spinner size={20} color={theme.ink} /></div>;

  return (
    <div>
      {phase === 'off' && (
        <>
          <div style={{ fontSize: 12.5, color: theme.muted, lineHeight: 1.55, marginBottom: 14 }}>
            Add a second lock to your account. After you turn this on, ZChat asks for a 6 digit code from an authenticator app each time you log in.
          </div>
          <button style={primaryBtn(theme, busy)} disabled={busy} onClick={startSetup}>{busy ? <Spinner /> : 'Turn on'}</button>
        </>
      )}
      {phase === 'setup' && setup && (
        <>
          <div style={{ fontSize: 12.5, color: theme.muted, lineHeight: 1.55, marginBottom: 12 }}>
            Scan this code with Google Authenticator, Authy or 1Password, then enter the 6 digit code it shows.
          </div>
          <div style={{ display: 'flex', justifyContent: 'center', marginBottom: 12 }}>
            {setup.qr ? <img src={setup.qr} alt="Two factor setup code" style={{ width: 176, height: 176, background: 'white', borderRadius: 14, padding: 8 }} /> : null}
          </div>
          <div style={{ fontSize: 11.5, color: theme.muted, textAlign: 'center', marginBottom: 6 }}>Cannot scan? Enter this key instead</div>
          <div role="button" onClick={copySecret} style={{ textAlign: 'center', fontWeight: 800, fontSize: 13, letterSpacing: 1.5, color: theme.ink, background: theme.rowBg, border: `1px solid ${theme.border}`, borderRadius: 12, padding: '10px 8px', wordBreak: 'break-all', cursor: 'pointer', marginBottom: 14 }}>
            {copied ? 'Copied' : setup.secret}
          </div>
          {codeInput}
          {err && <div style={{ color: theme.danger, fontSize: 12.5, marginTop: 8 }}>{err}</div>}
          <button style={{ ...primaryBtn(theme, busy || code.length !== 6), marginTop: 12 }} disabled={busy || code.length !== 6} onClick={confirmSetup}>{busy ? <Spinner /> : 'Verify and turn on'}</button>
          <div role="button" onClick={cancelSetup} style={{ textAlign: 'center', padding: '14px 0 2px', fontWeight: 700, color: theme.muted, cursor: 'pointer' }}>Cancel</div>
        </>
      )}
      {phase === 'on' && (
        <>
          <div role="status" style={{ display: 'flex', alignItems: 'center', gap: 14, padding: '8px 2px 14px' }}>
            <ShieldCheck size={26} color={theme.teal} strokeWidth={1.8} style={{ flexShrink: 0 }} />
            <div style={{ fontWeight: 700, fontSize: 15.5, color: theme.ink }}>Two factor is on</div>
          </div>
          <div style={{ fontSize: 12.5, color: theme.muted, lineHeight: 1.55, marginBottom: 14 }}>
            You need a code from your authenticator app to log in. To turn this off, enter a current code.
          </div>
          {codeInput}
          {err && <div style={{ color: theme.danger, fontSize: 12.5, marginTop: 8 }}>{err}</div>}
          <button style={{ ...primaryBtn(theme, busy || code.length !== 6), background: theme.danger, marginTop: 12 }} disabled={busy || code.length !== 6} onClick={turnOff}>{busy ? <Spinner /> : 'Turn off'}</button>
        </>
      )}
      {phase === 'off' && err && <div style={{ color: theme.danger, fontSize: 12.5, marginTop: 10 }}>{err}</div>}
    </div>
  );
}

function MfaChallengeScreen({ onPassed, onCancel }) {
  const { theme } = useTheme();
  const [code, setCode] = useState('');
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState('');
  const submit = async () => {
    if (code.length !== 6 || busy) return;
    setBusy(true); setErr('');
    try {
      const mfa = supabase.auth.mfa;
      const { data: listed, error: listErr } = await mfa.listFactors();
      if (listErr) throw listErr;
      const factor = ((listed && listed.totp) || []).find((f) => f.status === 'verified');
      if (!factor) { onPassed(); return; }
      const { error } = await mfa.challengeAndVerify({ factorId: factor.id, code });
      if (error) throw error;
      onPassed();
      return;
    } catch (e) {
      setErr(/invalid|expired|incorrect/i.test(String((e && e.message) || e)) ? 'That code is not right. Try the newest code.' : friendlyError(e, "Couldn't check that code. Try again."));
      setCode('');
    }
    setBusy(false);
  };
  return (
    <AuthShell onBack={onCancel}>
      <AuthArt kind="lock" height={180} />
      <AuthTitle title="Enter your code" sub="Open your authenticator app and type the 6 digit code it shows for ZChat." />
      <input autoFocus className="zauth-input" value={code} inputMode="numeric" autoComplete="one-time-code" maxLength={6} placeholder="000000" aria-label="6 digit code"
        onChange={(e) => setCode(e.target.value.replace(/\D/g, '').slice(0, 6))} onKeyDown={(e) => e.key === 'Enter' && submit()}
        style={authInputStyle(theme, { textAlign: 'center', letterSpacing: 8, fontSize: 22, fontWeight: 800, height: 58 })} />
      <AuthError text={err} />
      <button type="button" style={authPrimaryStyle(theme, busy || code.length !== 6, { marginTop: 16 })} disabled={busy || code.length !== 6} onClick={submit}>{busy ? <Spinner /> : 'Continue'}</button>
      <div style={{ textAlign: 'center', marginTop: 18 }}>
        <button type="button" onClick={onCancel} style={authLinkStyle(theme)}>Use a different account</button>
      </div>
    </AuthShell>
  );
}

function SavedMessagesPanel({ myId, me, onClose, onChanged, onOpenChat }) {
  useBackClose(true, onClose);
  const edgeBack = useEdgeSwipeBack(true);
  const { theme } = useTheme();
  const [savedTab, setSavedTab] = useState('messages');
  const [rows, setRows] = useState(null);
  const [q, setQ] = useState('');
  const [note, setNote] = useState('');
  const [busy, setBusy] = useState(false);
  const [problem, setProblem] = useState('');
  const [lightbox, setLightbox] = useState(null);
  const load = async () => {
    const { data, error } = await supabase.from('saved_messages').select('*').eq('user_id', myId).order('created_at', { ascending: false }).limit(300);
    if (error) { setProblem(friendlyError(error, "Couldn't load saved messages.")); setRows([]); return; }
    setProblem('');
    setRows(data || []);
  };
  useEffect(() => { load(); }, []);
  const addNote = async () => {
    const text = note.trim();
    if (!text || busy) return;
    setBusy(true);
    const { data, error } = await supabase.from('saved_messages').insert({ user_id: myId, kind: 'note', content: text.slice(0, 2000), from_name: 'You', chat_label: 'Note to self' }).select().single();
    setBusy(false);
    if (error || !data) { setProblem(friendlyError(error, "Couldn't save that note. Try again.")); return; }
    setProblem('');
    setNote('');
    setRows((prev) => [data, ...(prev || [])]);
  };
  const remove = async (row) => {
    setRows((prev) => (prev || []).filter((r) => r.id !== row.id));
    await supabase.from('saved_messages').delete().eq('id', row.id).eq('user_id', myId);
    if (onChanged && row.source_message_id) onChanged(row.source_message_id, false);
  };
  const term = q.trim().toLowerCase();
  const shown = (rows || []).filter((r) => !term || (r.content || '').toLowerCase().includes(term) || (r.from_name || '').toLowerCase().includes(term) || (r.chat_label || '').toLowerCase().includes(term));
  return (
    <>
    <WideDim onClose={onClose} z={40} />
    <div {...edgeBack} style={{ position: 'fixed', inset: 0, zIndex: 40, background: theme.bgGradient, display: 'flex', flexDirection: 'column', fontFamily: FONT }} className="zchat-panel-open zchat-wide-page">
      <IgTopBar title="Saved" onBack={onClose} />
      <div style={{ display: 'flex', margin: '0 16px 10px', padding: 3, borderRadius: 12, background: theme.rowBg }}>
        {[['messages', 'Messages'], ['posts', 'Posts']].map(([k, label]) => (
          <div key={k} role="button" aria-label={`Saved ${label.toLowerCase()}`} aria-pressed={savedTab === k} onClick={() => { hapticTap(); setSavedTab(k); }}
            style={{ flex: 1, height: 34, borderRadius: 10, display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 14, fontWeight: 700, cursor: 'pointer', background: savedTab === k ? theme.panelBg : 'transparent', color: savedTab === k ? theme.ink : theme.muted, boxShadow: savedTab === k ? '0 1px 3px rgba(0,0,0,0.12)' : 'none' }}>{label}</div>
        ))}
      </div>
      {savedTab === 'posts' ? (
        <div style={{ flex: 1, minHeight: 0, overflowY: 'auto', WebkitOverflowScrolling: 'touch', padding: '0 16px calc(16px + env(safe-area-inset-bottom))' }}><SavedPostsGrid me={me} myId={myId} /></div>
      ) : (
      <>
      <div style={{ padding: '0 16px 10px' }}>
        <div style={{ position: 'relative' }}>
          <Search size={15} color={theme.muted} style={{ position: 'absolute', left: 12, top: 12 }} />
          <input value={q} onChange={(e) => setQ(e.target.value)} placeholder="Search saved messages" style={{ ...inputStyle(theme), padding: '9px 12px 9px 34px', fontSize: 13.5 }} />
        </div>
      </div>
      <div style={{ flex: 1, minHeight: 0, overflowY: 'auto', WebkitOverflowScrolling: 'touch', padding: '0 16px' }}>
        {problem && <div style={{ background: `${theme.danger}18`, color: theme.danger, borderRadius: 12, padding: '9px 12px', fontSize: 12.5, fontWeight: 700, marginBottom: 8 }}>{problem}</div>}
        {rows === null ? (
          <div style={{ display: 'flex', justifyContent: 'center', padding: 40 }}><Spinner size={22} color={theme.ink} /></div>
        ) : shown.length === 0 ? (
          <EmptyState art={term ? 'nothing' : 'saved'} title={term ? 'Nothing found' : 'Nothing saved yet'} text={term ? 'Try a different word.' : 'Press and hold any message in a chat and choose Add to Saved. You can also write a note to yourself below.'} />
        ) : shown.map((r) => (
          <div key={r.id} style={{ background: theme.rowBg, border: `1px solid ${theme.border}`, borderRadius: 18, padding: 12, marginBottom: 10 }}>
            <div style={{ display: 'flex', alignItems: 'baseline', justifyContent: 'space-between', gap: 8, marginBottom: 8 }}>
              <div
                role={(onOpenChat && (r.dm_user_id || r.group_id)) ? 'button' : undefined}
                onClick={(onOpenChat && (r.dm_user_id || r.group_id)) ? () => onOpenChat(r) : undefined}
                style={{
                  fontSize: 12, fontWeight: 800, color: theme.coralDeep, minWidth: 0, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap',
                  cursor: (onOpenChat && (r.dm_user_id || r.group_id)) ? 'pointer' : 'default',
                  textDecoration: (onOpenChat && (r.dm_user_id || r.group_id)) ? 'underline' : 'none', textUnderlineOffset: 2,
                }}>
                {r.from_name || 'Someone'}{r.chat_label && r.kind !== 'note' ? ` in ${r.chat_label}` : ''}
              </div>
              <div style={{ fontSize: 11, color: theme.muted, flexShrink: 0 }}>{timeAgoLong(r.message_created_at || r.created_at)}</div>
            </div>
            {r.kind === 'image' && r.media_url && <MediaImg src={r.media_url} onClick={() => setLightbox(r.media_url)} style={{ width: '100%', maxHeight: 280, objectFit: 'cover', borderRadius: 12, cursor: 'pointer', display: 'block' }} />}
            {r.kind === 'video' && r.media_url && <MediaVideo src={r.media_url} controls playsInline preload="metadata" style={{ width: '100%', maxHeight: 280, borderRadius: 12, background: '#000', display: 'block' }} />}
            {r.kind === 'audio' && r.media_url && <MediaAudio src={r.media_url} controls preload="none" style={{ width: '100%' }} />}
            {r.kind === 'sticker' && r.content && <img src={r.content} alt="" style={{ width: 110, height: 110, objectFit: 'contain' }} />}
            {(r.kind === 'text' || r.kind === 'note' || ((r.kind === 'image' || r.kind === 'video') && r.content)) && r.content && (
              <div style={{ fontSize: 14, color: theme.ink, lineHeight: 1.45, wordBreak: 'break-word', marginTop: r.media_url ? 8 : 0 }}><RichText text={r.content} /></div>
            )}
            <div style={{ display: 'flex', gap: 14, justifyContent: 'flex-end', marginTop: 10 }}>
              {r.content && r.kind !== 'sticker' && (
                <div role="button" aria-label="Copy" onClick={() => { try { navigator.clipboard.writeText(r.content); } catch {} }} style={{ cursor: 'pointer', color: theme.muted, display: 'flex' }}><Copy size={16} /></div>
              )}
              <div role="button" aria-label="Remove" onClick={() => remove(r)} style={{ cursor: 'pointer', color: theme.muted, display: 'flex' }}><Trash2 size={16} /></div>
            </div>
          </div>
        ))}
      </div>
      <div style={{ display: 'flex', gap: 8, alignItems: 'flex-end', padding: '10px 14px', paddingBottom: 'calc(10px + env(safe-area-inset-bottom))', borderTop: `1px solid ${theme.border}` }}>
        <textarea value={note} onChange={(e) => setNote(e.target.value.slice(0, 2000))} rows={1} placeholder="Write a note to yourself"
          style={{ ...inputStyle(theme), flex: 1, resize: 'none', maxHeight: 96, padding: '11px 14px', fontSize: 14 }} />
        <div role="button" aria-label="Save note" onClick={addNote} style={{ width: 42, height: 42, borderRadius: '50%', background: note.trim() ? theme.coral : theme.rowBg, display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: note.trim() ? 'pointer' : 'default', flexShrink: 0 }}>
          {busy ? <Spinner size={16} /> : <Bookmark size={18} color={note.trim() ? 'white' : theme.muted} />}
        </div>
      </div>
      </>
      )}
      {lightbox && (
        <div onClick={() => setLightbox(null)} style={{ position: 'fixed', inset: 0, zIndex: 250, background: 'rgba(0,0,0,0.94)', display: 'flex', alignItems: 'center', justifyContent: 'center', padding: 16 }}>
          <MediaImg src={lightbox} style={{ maxWidth: '100%', maxHeight: '100%', objectFit: 'contain', borderRadius: 8 }} />
        </div>
      )}
    </div>
    </>
  );
}

const GROUP_ACCENTS = ['#FF6B4A', '#29C7B3', '#7C5CFC', '#F3B54C', '#FF4D8D', '#3DA5F5', '#4CC98A', '#B45CFF'];
function groupAccent(group) { return (group && group.accent) || colorForName((group && group.name) || 'group'); }
function isMemberOnline(m) {
  return !!(m && m.profile && !m.profile.hide_activity && m.profile.last_seen && Date.now() - new Date(m.profile.last_seen).getTime() < 3 * 60 * 1000);
}

function GroupHeaderLine({ members }) {
  const online = members.filter(isMemberOnline).length;
  const faces = members.filter((m) => m.profile).slice(0, 3);
  return (
    <span style={{ display: 'inline-flex', alignItems: 'center', gap: 6, minWidth: 0, maxWidth: '100%' }}>
      <span style={{ display: 'inline-flex', flexShrink: 0 }}>
        {faces.map((m, i) => (
          <span key={m.user_id} style={{ marginLeft: i ? -6 : 0, display: 'inline-flex', borderRadius: '50%', boxShadow: '0 0 0 1.5px rgba(0,0,0,0.25)' }}>
            <Avatar emoji={m.profile.avatar} name={m.profile.name} size={16} />
          </span>
        ))}
      </span>
      <span style={{ minWidth: 0, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{members.length} {members.length === 1 ? 'member' : 'members'}{online > 0 ? `, ${online} online` : ''}</span>
    </span>
  );
}

function ReelVideo({ post, rootRef, onDoubleTap }) {
  const wrapRef = useRef(null);
  const videoRef = useRef(null);
  const barRef = useRef(null);
  const tapAtRef = useRef(0);
  const tapTimerRef = useRef(null);
  const flashTimerRef = useRef(null);
  const pausedByUserRef = useRef(false);
  const [muted, setMuted] = useState(true);
  const [flash, setFlash] = useState(null);
  const [portrait, setPortrait] = useState(false);
  const showFlash = (kind) => {
    setFlash(kind);
    clearTimeout(flashTimerRef.current);
    flashTimerRef.current = setTimeout(() => setFlash(null), 550);
  };
  useEffect(() => {
    const el = videoRef.current;
    const wrap = wrapRef.current;
    if (!el || !wrap) return undefined;
    const start = () => { const p = el.play(); if (p && p.catch) p.catch(() => {}); };
    if (typeof IntersectionObserver === 'undefined') { start(); return undefined; }
    const io = new IntersectionObserver((entries) => {
      entries.forEach((en) => {
        if (en.isIntersecting && en.intersectionRatio >= 0.6) {
          if (!pausedByUserRef.current) start();
        } else {
          el.pause();
          if (!en.isIntersecting) { pausedByUserRef.current = false; try { el.currentTime = 0; } catch {} }
        }
      });
    }, { root: (rootRef && rootRef.current) || null, threshold: [0, 0.6, 1] });
    io.observe(wrap);
    return () => io.disconnect();
  }, []);
  useEffect(() => { if (videoRef.current) videoRef.current.muted = muted; }, [muted]);
  useEffect(() => () => { clearTimeout(tapTimerRef.current); clearTimeout(flashTimerRef.current); }, []);
  const togglePause = () => {
    const el = videoRef.current;
    if (!el) return;
    if (el.paused) {
      pausedByUserRef.current = false;
      const p = el.play(); if (p && p.catch) p.catch(() => {});
      showFlash('play');
    } else {
      pausedByUserRef.current = true;
      el.pause();
      showFlash('pause');
    }
  };
  const onTap = () => {
    const now = Date.now();
    if (now - tapAtRef.current < 280) {
      clearTimeout(tapTimerRef.current);
      tapAtRef.current = 0;
      if (onDoubleTap) onDoubleTap();
      return;
    }
    tapAtRef.current = now;
    tapTimerRef.current = setTimeout(() => { tapAtRef.current = 0; togglePause(); }, 280);
  };
  return (
    <div ref={wrapRef} onClick={onTap} data-reel-video={post.id} style={{ position: 'absolute', inset: 0 }}>
      <video ref={videoRef} src={post.media_url} playsInline loop muted preload="auto"
        onLoadedMetadata={(e) => setPortrait(e.currentTarget.videoHeight >= e.currentTarget.videoWidth)}
        onTimeUpdate={(e) => { const v = e.currentTarget; if (barRef.current && v.duration) barRef.current.style.width = `${Math.min(100, (v.currentTime / v.duration) * 100)}%`; }}
        style={{ width: '100%', height: '100%', objectFit: portrait ? 'cover' : 'contain' }} />
      {flash && (
        <div className="zchat-pop" style={{ position: 'absolute', left: '50%', top: '50%', marginLeft: -32, marginTop: -32, width: 64, height: 64, borderRadius: '50%', background: 'rgba(0,0,0,0.5)', display: 'flex', alignItems: 'center', justifyContent: 'center', pointerEvents: 'none' }}>
          {flash === 'pause' ? <Pause size={30} color="white" fill="white" /> : <Play size={30} color="white" fill="white" />}
        </div>
      )}
      <div role="button" aria-label={muted ? 'Turn sound on' : 'Turn sound off'} onClick={(e) => { e.stopPropagation(); setMuted((m) => !m); }}
        style={{ position: 'absolute', top: 'calc(64px + env(safe-area-inset-top))', right: 12, width: 36, height: 36, borderRadius: '50%', background: 'rgba(0,0,0,0.45)', display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer', zIndex: 4 }}>
        {muted ? <VolumeX size={18} color="white" /> : <Volume2 size={18} color="white" />}
      </div>
      <div style={{ position: 'absolute', left: 0, right: 0, bottom: 0, height: 2, background: 'rgba(255,255,255,0.18)', pointerEvents: 'none' }}>
        <div ref={barRef} style={{ height: '100%', width: 0, background: 'white' }} />
      </div>
    </div>
  );
}

function parseShareLanding() {
  if (typeof window === 'undefined') return null;
  const p = new URLSearchParams(window.location.search);
  const safe = /^[A-Za-z0-9_-]{1,64}$/;
  const join = p.get('join');
  if (join && safe.test(join)) return { kind: 'group', key: join };
  const post = p.get('post');
  if (post && safe.test(post)) return { kind: 'post', key: post };
  const story = p.get('story');
  if (story && safe.test(story)) return { kind: 'story', key: story };
  const profile = p.get('profile');
  if (profile && safe.test(profile)) return { kind: 'profile', key: profile };
  return null;
}

function stashPendingLink() {
  try { localStorage.setItem('zchat-pending-link', JSON.stringify({ search: window.location.search, at: Date.now() })); } catch {}
}

function SharePreviewScreen({ landing: initialLanding, onAuth }) {
  const [landing, setLanding] = useState(initialLanding);
  const [data, setData] = useState(null);
  const [more, setMore] = useState(null);
  const openPost = (id) => {
    if (!id) return;
    try { window.history.pushState({}, '', `/?post=${id}`); } catch {}
    setData(null);
    setMore(null);
    setLanding({ kind: 'post', key: id });
    try { window.scrollTo(0, 0); } catch {}
  };
  const [deferred, setDeferred] = useState(null);
  const [decor, setDecor] = useState(null);
  const [showHelp, setShowHelp] = useState(false);
  const [standalone] = useState(() => {
    try { return !!((window.matchMedia && window.matchMedia('(display-mode: standalone)').matches) || window.navigator.standalone === true); } catch { return false; }
  });
  const BG = '#07080d';
  const CARD = '#12141c';
  const LINE = 'rgba(255,255,255,0.09)';
  const MUTED = 'rgba(232,234,240,0.62)';
  const BRAND = 'linear-gradient(135deg, #7C5CFC, #A78BFA)';

  useEffect(() => {
    const onPrompt = (e) => { e.preventDefault(); setDeferred(e); };
    window.addEventListener('beforeinstallprompt', onPrompt);
    return () => window.removeEventListener('beforeinstallprompt', onPrompt);
  }, []);

  useEffect(() => {
    let alive = true;
    (async () => {
      let result = null;
      try {
        const fn = landing.kind === 'group' ? 'public_group_preview' : landing.kind === 'post' ? 'public_post_preview' : 'public_profile_preview';
        const args = landing.kind === 'group' ? { p_code: landing.key } : { p_id: landing.key };
        const { data: res, error } = await supabase.rpc(fn, args);
        if (!error && res) result = res;
      } catch {}
      if (alive) setData(result || { found: false, unavailable: true });
      if (alive && result && result.found && (landing.kind === 'profile' || landing.kind === 'story')) {
        if (isDecorKey(result.avatar_frame) || isDecorKey(result.nameplate)) setDecor({ frame: isDecorKey(result.avatar_frame) ? result.avatar_frame : null, plate: isDecorKey(result.nameplate) ? result.nameplate : null });
        else {
          try {
            const { data: dc } = await supabase.rpc('public_profile_decor', { p_id: landing.key });
            const row = Array.isArray(dc) ? dc[0] : dc;
            if (alive && row && (isDecorKey(row.frame) || isDecorKey(row.plate))) setDecor({ frame: isDecorKey(row.frame) ? row.frame : null, plate: isDecorKey(row.plate) ? row.plate : null });
          } catch {}
        }
      }
      if (alive && result && landing.kind === 'post' && result.owner && result.owner.id && !result.restricted) {
        try {
          const { data: ownerRes } = await supabase.rpc('public_profile_preview', { p_id: result.owner.id });
          if (alive && ownerRes && ownerRes.found && !ownerRes.is_private) setMore((ownerRes.posts || []).filter((p) => p.id !== landing.key));
        } catch {}
      }
    })();
    return () => { alive = false; };
  }, [landing.kind, landing.key]);
  useEffect(() => {
    const onPop = () => {
      const next = parseShareLanding();
      if (next) { setData(null); setMore(null); setLanding(next); }
    };
    window.addEventListener('popstate', onPop);
    return () => window.removeEventListener('popstate', onPop);
  }, []);

  const getApp = async () => {
    if (!deferred) { setShowHelp(true); return; }
    try { deferred.prompt(); await deferred.userChoice; } catch {}
    setDeferred(null);
  };
  const login = (note) => onAuth('login', note || '');
  const signup = (note) => onAuth('register', note || '');

  const primaryBtn = { display: 'block', width: '100%', boxSizing: 'border-box', padding: '14px 16px', borderRadius: 14, border: 'none', background: BRAND, color: 'white', fontWeight: 800, fontSize: 15, fontFamily: FONT, cursor: 'pointer', textAlign: 'center' };
  const ghostBtn = { display: 'block', width: '100%', boxSizing: 'border-box', padding: '13px 16px', borderRadius: 14, border: `1px solid ${LINE}`, background: 'transparent', color: '#e8eaf0', fontWeight: 800, fontSize: 14.5, fontFamily: FONT, cursor: 'pointer', textAlign: 'center' };
  const stat = (n, label) => (
    <div style={{ flex: 1, textAlign: 'center' }}>
      <div style={{ fontWeight: 900, fontSize: 18 }}>{formatCount(n || 0)}</div>
      <div style={{ fontSize: 12, color: MUTED, marginTop: 1 }}>{label}</div>
    </div>
  );
  const nameLine = (name, verified, custom, size = 20) => (
    <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 6, fontWeight: 900, fontSize: size, wordBreak: 'break-word' }}>
      <span>{name}</span><VerifiedBadge tier={verified} custom={custom} size={size - 5} />
    </div>
  );

  let body = null;
  if (data === null) {
    body = <div style={{ display: 'flex', justifyContent: 'center', padding: '80px 0' }}><Spinner size={26} color="white" /></div>;
  } else if (!data.found) {
    body = (
      <div style={{ textAlign: 'center', padding: '50px 8px' }}>
        <div style={{ display: 'flex', justifyContent: 'center', marginBottom: 16 }}><ZMark size={64} /></div>
        <div style={{ fontWeight: 900, fontSize: 19 }}>{data.unavailable ? 'Open this in ZChat' : 'This link is not available'}</div>
        <div style={{ color: MUTED, fontSize: 13.5, marginTop: 8, lineHeight: 1.5 }}>
          {data.unavailable ? 'Log in to see it.' : 'It may have been removed, or the person made it private.'}
        </div>
      </div>
    );
  } else if (landing.kind === 'group') {
    const faces = data.faces || [];
    body = (
      <div style={{ textAlign: 'center', paddingTop: 26 }}>
        <div style={{ display: 'inline-block' }}><GroupAvatar avatar={data.avatar} name={data.name} size={104} /></div>
        <div style={{ fontWeight: 900, fontSize: 22, marginTop: 16, wordBreak: 'break-word' }}>{data.name}</div>
        <div style={{ color: MUTED, fontSize: 13.5, marginTop: 4 }}>Group with {data.member_count} {data.member_count === 1 ? 'member' : 'members'}</div>
        {faces.length > 0 && (
          <div style={{ display: 'flex', justifyContent: 'center', marginTop: 14 }}>
            {faces.map((f, i) => (
              <span key={i} style={{ marginLeft: i ? -10 : 0, display: 'inline-flex', borderRadius: '50%', boxShadow: `0 0 0 2px ${BG}` }}><Avatar emoji={f.avatar} name={f.name || '?'} size={34} /></span>
            ))}
          </div>
        )}
        {data.bio && <div style={{ color: '#d5d8e0', fontSize: 14, lineHeight: 1.5, marginTop: 16 }}>{data.bio}</div>}
        <div style={{ marginTop: 22 }}><button style={primaryBtn} onClick={() => login(`Log in to join ${data.name}`)}>Join group</button></div>
      </div>
    );
  } else if (landing.kind === 'post') {
    const o = data.owner || {};
    body = (
      <div style={{ paddingTop: 14 }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: 10, marginBottom: 12 }}>
          <Avatar emoji={o.avatar} name={o.name || '?'} size={42} />
          <div style={{ minWidth: 0 }}>
            <div style={{ display: 'flex', alignItems: 'center', fontWeight: 800, fontSize: 15 }}><NameBadge name={o.name} verified={o.verified} custom={o.custom_badge} size={14} /></div>
            <div style={{ color: MUTED, fontSize: 12.5 }}>@{o.username}</div>
          </div>
        </div>
        {data.restricted ? (
          <div style={{ background: CARD, border: `1px solid ${LINE}`, borderRadius: 18, padding: '34px 18px', textAlign: 'center' }}>
            <Lock size={26} color={MUTED} />
            <div style={{ fontWeight: 800, marginTop: 10 }}>This post is from a private account</div>
            <div style={{ color: MUTED, fontSize: 13, marginTop: 6 }}>Log in and follow {o.name} to see it.</div>
          </div>
        ) : (
          <>
            <div style={{ borderRadius: 18, overflow: 'hidden', background: '#000', border: `1px solid ${LINE}` }}>
              {data.media_type === 'video'
                ? <video src={data.media_url} muted playsInline loop autoPlay style={{ width: '100%', maxHeight: '62vh', objectFit: 'contain', display: 'block' }} />
                : <img src={data.media_url} alt="" draggable={false} style={{ width: '100%', maxHeight: '62vh', objectFit: 'contain', display: 'block' }} />}
            </div>
            <div style={{ display: 'flex', alignItems: 'center', gap: 18, marginTop: 12, color: '#e8eaf0', fontWeight: 800, fontSize: 14 }}>
              <span style={{ display: 'flex', alignItems: 'center', gap: 6 }}><Heart size={20} />{formatCount(data.likes || 0)}</span>
              <span style={{ display: 'flex', alignItems: 'center', gap: 6 }}><InstaCommentIcon size={19} />{formatCount(data.comments || 0)}</span>
            </div>
            {data.caption && <div style={{ marginTop: 10, fontSize: 14.5, lineHeight: 1.5, wordBreak: 'break-word' }}>{data.caption}</div>}
            <div style={{ color: MUTED, fontSize: 12, marginTop: 6 }}>{timeAgoLong(data.created_at)}</div>
          </>
        )}
        <div style={{ marginTop: 18 }}><button style={ghostBtn} onClick={() => login(data.restricted ? `Log in to follow ${o.name}` : 'Log in to like and comment')}>{data.restricted ? 'Log in to follow' : 'Log in to like and comment'}</button></div>
        {more && more.length > 0 && (
          <>
            <div style={{ fontWeight: 900, fontSize: 14.5, marginTop: 24, marginBottom: 8 }}>More from {o.name}</div>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: 3, borderRadius: 12, overflow: 'hidden' }}>
              {more.map((p) => (
                <div key={p.id} role="button" onClick={() => openPost(p.id)} style={{ position: 'relative', aspectRatio: '3 / 4', background: CARD, cursor: 'pointer', overflow: 'hidden' }}>
                  {p.media_type === 'video'
                    ? <VideoThumb src={p.media_url} style={{ width: '100%', height: '100%', objectFit: 'cover', pointerEvents: 'none' }} />
                    : <img src={p.media_url} alt="" loading="lazy" draggable={false} style={{ width: '100%', height: '100%', objectFit: 'cover' }} />}
                  {p.media_type === 'video' && <Play size={15} color="white" style={{ position: 'absolute', top: 6, right: 6, filter: 'drop-shadow(0 1px 3px rgba(0,0,0,0.6))' }} />}
                </div>
              ))}
            </div>
          </>
        )}
      </div>
    );
  } else {
    const isStory = landing.kind === 'story';
    const posts = data.posts || [];
    const first = String(data.name || '').split(' ')[0] || 'them';
    const heroW = Math.min(360, (typeof window !== 'undefined' ? window.innerWidth : 390) - 36);
    body = (
      <div style={{ textAlign: 'center', paddingTop: 18 }}>
        {decor && !isStory ? (
          <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center' }}>
            <DecorHero frameKey={decor.frame} plateKey={decor.plate} width={heroW} photo={data.avatar} name={data.name} username={data.username} verified={data.verified} custom={data.custom_badge} gapColor={BG} />
            {!decor.plate && (
              <>
                <div style={{ marginTop: 4 }}>{nameLine(data.name, data.verified, data.custom_badge)}</div>
                <div style={{ color: MUTED, fontSize: 14, marginTop: 3 }}>@{data.username}</div>
              </>
            )}
          </div>
        ) : (
          <>
            <div style={{ display: 'inline-flex', borderRadius: '50%', padding: isStory ? 4 : 0, background: isStory ? 'linear-gradient(135deg, #f59e0b, #ec4899, #8b5cf6)' : 'transparent' }}>
              <div style={{ borderRadius: '50%', boxShadow: isStory ? `0 0 0 3px ${BG}` : '0 0 0 4px rgba(139, 108, 255, 0.18)', display: 'inline-flex' }}>
                <Avatar emoji={data.avatar} name={data.name || '?'} size={104} />
              </div>
            </div>
            <div style={{ marginTop: 14 }}>{nameLine(data.name, data.verified, data.custom_badge)}</div>
            <div style={{ color: MUTED, fontSize: 14, marginTop: 3 }}>@{data.username}</div>
          </>
        )}
        {isStory && <div style={{ marginTop: 12, fontWeight: 700, color: '#d5d8e0' }}>{first} shared a story</div>}
        {!isStory && data.bio && <div style={{ color: '#d5d8e0', fontSize: 14, lineHeight: 1.5, margin: '12px 6px 0', wordBreak: 'break-word' }}>{data.bio}</div>}
        {!isStory && (
          <div style={{ display: 'flex', margin: '18px 0 4px', padding: '12px 0', borderRadius: 18, background: CARD, boxShadow: `inset 0 0 0 1px ${LINE}` }}>
            {stat(data.posts_count, 'Posts')}{stat(data.followers_count, 'Followers')}{stat(data.following_count, 'Following')}
          </div>
        )}
        <div style={{ display: 'flex', gap: 10, marginTop: 16 }}>
          {isStory
            ? <button style={primaryBtn} onClick={() => login(`Log in to watch ${first}'s story`)}>Watch story</button>
            : (
              <>
                <button style={primaryBtn} onClick={() => login(`Log in to follow ${data.name}`)}>Follow</button>
                <button style={ghostBtn} onClick={() => login(`Log in to message ${data.name}`)}>Message</button>
              </>
            )}
        </div>
        {!isStory && data.is_private && (
          <div style={{ marginTop: 22, background: CARD, border: `1px solid ${LINE}`, borderRadius: 18, padding: '26px 18px' }}>
            <Lock size={24} color={MUTED} />
            <div style={{ fontWeight: 800, marginTop: 8 }}>This account is private</div>
            <div style={{ color: MUTED, fontSize: 13, marginTop: 5 }}>Log in and send a follow request to see their posts.</div>
          </div>
        )}
        {!isStory && !data.is_private && posts.length > 0 && (
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: 3, marginTop: 20, borderRadius: 12, overflow: 'hidden' }}>
            {posts.map((p) => (
              <div key={p.id} role="button" onClick={() => openPost(p.id)} style={{ position: 'relative', aspectRatio: '3 / 4', background: CARD, cursor: 'pointer', overflow: 'hidden' }}>
                {p.media_type === 'video'
                  ? <VideoThumb src={p.media_url} style={{ width: '100%', height: '100%', objectFit: 'cover', pointerEvents: 'none' }} />
                  : <img src={p.media_url} alt="" loading="lazy" draggable={false} style={{ width: '100%', height: '100%', objectFit: 'cover' }} />}
                {p.media_type === 'video' && <Play size={15} color="white" style={{ position: 'absolute', top: 6, right: 6, filter: 'drop-shadow(0 1px 3px rgba(0,0,0,0.6))' }} />}
              </div>
            ))}
          </div>
        )}
      </div>
    );
  }

  return (
    <div style={{ position: 'fixed', inset: 0, background: BG, color: '#e8eaf0', fontFamily: FONT, overflowY: 'auto', WebkitOverflowScrolling: 'touch' }}>
      <div style={{ position: 'sticky', top: 0, zIndex: 5, background: 'rgba(7,8,13,0.85)', backdropFilter: 'blur(14px)', WebkitBackdropFilter: 'blur(14px)', borderBottom: `1px solid ${LINE}` }}>
        <div style={{ maxWidth: 480, margin: '0 auto', padding: '10px 16px', paddingTop: 'calc(10px + env(safe-area-inset-top))', display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
            <ZMark size={30} />
            <div style={{ fontWeight: 900, fontSize: 17 }}>ZChat</div>
          </div>
          <div role="button" onClick={() => login('')} style={{ fontWeight: 800, fontSize: 14, color: '#8ab4ff', cursor: 'pointer' }}>Log in</div>
        </div>
      </div>
      <div style={{ maxWidth: 480, margin: '0 auto', padding: '4px 18px', paddingBottom: 'calc(190px + env(safe-area-inset-bottom))' }}>{body}</div>
      <div style={{ position: 'fixed', left: 0, right: 0, bottom: 0, zIndex: 8, background: 'rgba(12,14,22,0.96)', backdropFilter: 'blur(16px)', WebkitBackdropFilter: 'blur(16px)', borderTop: `1px solid ${LINE}` }}>
        <div style={{ maxWidth: 480, margin: '0 auto', padding: '14px 18px', paddingBottom: 'calc(14px + env(safe-area-inset-bottom))' }}>
          <div style={{ fontWeight: 900, fontSize: 15.5, textAlign: 'center' }}>{standalone ? 'Join ZChat' : 'Get the ZChat app'}</div>
          <div style={{ color: MUTED, fontSize: 12.5, textAlign: 'center', margin: '3px 0 12px' }}>Chat, share posts and stay close to the people you love.</div>
          {standalone ? (
            <div style={{ display: 'flex', gap: 10 }}>
              <button style={primaryBtn} onClick={() => signup('')}>Sign up</button>
              <button style={ghostBtn} onClick={() => login('')}>Log in</button>
            </div>
          ) : (
            <div style={{ display: 'flex', gap: 10 }}>
              <button style={primaryBtn} onClick={getApp}>Get the app</button>
              <button style={ghostBtn} onClick={() => login('')}>Continue in browser</button>
            </div>
          )}
        </div>
      </div>
      {showHelp && <InstallAppHelpModal onClose={() => setShowHelp(false)} />}
    </div>
  );
}

function JoinGroupSheet({ group, count, busy, onJoin, onClose, requested, onCancelRequest }) {
  useBackClose(true, onClose);
  const { theme } = useTheme();
  const accent = groupAccent(group);
  const sheet = (
    <div onClick={onClose} className="zchat-fade" style={{ position: 'fixed', inset: 0, zIndex: 700, background: 'rgba(0,0,0,0.55)', display: 'flex', alignItems: 'flex-end', fontFamily: FONT }}>
      <div onClick={(e) => e.stopPropagation()} className="zchat-sheet-up" style={{ width: '100%', background: theme.panelBg, borderRadius: '24px 24px 0 0', padding: '26px 20px', paddingBottom: 'calc(22px + env(safe-area-inset-bottom))', textAlign: 'center' }}>
        <div style={{ display: 'inline-block', borderRadius: 32, boxShadow: `0 0 0 3px ${accent}, 0 12px 34px ${accent}55` }}><GroupAvatar avatar={group.avatar} name={group.name} size={92} /></div>
        <div style={{ fontWeight: 900, fontSize: 21, color: theme.ink, marginTop: 16, wordBreak: 'break-word' }}>Join {group.name}?</div>
        <div style={{ fontSize: 13, color: theme.muted, fontWeight: 700, marginTop: 4 }}>Group with {count} {count === 1 ? 'member' : 'members'}</div>
        {group.bio && <div style={{ fontSize: 14, color: theme.ink, lineHeight: 1.5, marginTop: 12 }}>{group.bio}</div>}
        {group.join_approval && <div style={{ fontSize: 13, color: theme.muted, lineHeight: 1.45, marginTop: 12 }}>{requested ? 'Your request is waiting for an admin.' : 'An admin approves new members before they can see the chat.'}</div>}
        <button disabled={busy || requested} onClick={onJoin} style={{ display: 'block', width: '100%', marginTop: 20, padding: '14px 16px', borderRadius: 14, border: 'none', background: requested ? theme.rowBg : accent, color: requested ? theme.muted : 'white', fontWeight: 800, fontSize: 15, fontFamily: FONT, cursor: requested ? 'default' : 'pointer', opacity: busy ? 0.7 : 1 }}>
          {busy ? <Spinner size={16} /> : requested ? 'Request sent' : group.join_approval ? 'Ask to join' : 'Join group'}
        </button>
        {requested ? (
          <div role="button" onClick={onCancelRequest} style={{ padding: '14px 0 2px', fontWeight: 700, color: theme.danger, cursor: 'pointer' }}>Cancel request</div>
        ) : (
          <div role="button" onClick={onClose} style={{ padding: '14px 0 2px', fontWeight: 700, color: theme.muted, cursor: 'pointer' }}>Not now</div>
        )}
      </div>
    </div>
  );
  return ReactDOM.createPortal(sheet, document.body);
}

function LikersSheet({ post, meId, onClose, onOpenProfile }) {
  useBackClose(true, onClose);
  const [rows, setRows] = useState(null);
  useEffect(() => {
    let alive = true;
    (async () => {
      const { data: likes } = await supabase.from('post_likes').select('user_id, created_at').eq('post_id', post.id).order('created_at', { ascending: false }).limit(200);
      const ids = [...new Set((likes || []).map((l) => l.user_id))];
      let byId = {};
      if (ids.length) {
        const { data: profs } = await supabase.from('profiles').select('*').in('id', ids);
        sanitizeAvatarList(profs, meId).forEach((p) => { byId[p.id] = p; });
      }
      if (alive) setRows((likes || []).map((l) => byId[l.user_id]).filter(Boolean));
    })();
    return () => { alive = false; };
  }, [post.id]);
  const sheet = (
    <div onClick={onClose} className="zchat-fade" style={{ position: 'fixed', inset: 0, zIndex: 720, background: 'rgba(0,0,0,0.55)', display: 'flex', alignItems: 'flex-end', fontFamily: FONT }}>
      <div onClick={(e) => e.stopPropagation()} className="zchat-sheet-up" style={{ width: '100%', maxHeight: 'min(70vh, calc(100% - 24px))', display: 'flex', flexDirection: 'column', background: '#12141c', color: 'white', borderRadius: '22px 22px 0 0', paddingBottom: 'env(safe-area-inset-bottom)' }}>
        <div style={{ textAlign: 'center', fontWeight: 800, fontSize: 15, padding: '16px 0 12px', borderBottom: '1px solid #22252e' }}>Likes</div>
        <div style={{ overflowY: 'auto', padding: '6px 16px 16px' }}>
          {rows === null && <div style={{ display: 'flex', justifyContent: 'center', padding: 24 }}><Spinner size={20} color="white" /></div>}
          {rows && rows.length === 0 && <div style={{ textAlign: 'center', padding: '18px 24px 26px', color: 'rgba(255,255,255,0.6)', fontSize: 13.5 }}><div style={{ maxWidth: 220, margin: '0 auto 12px' }}><SpotArt k="love" dark radius={18} /></div>No likes yet</div>}
          {(rows || []).map((p) => (
            <div key={p.id} role="button" onClick={() => onOpenProfile(p)} style={{ display: 'flex', alignItems: 'center', gap: 12, padding: '9px 0', cursor: 'pointer' }}>
              <Avatar emoji={p.avatar} name={p.name} size={42} />
              <div style={{ minWidth: 0 }}>
                <div style={{ display: 'flex', alignItems: 'center', fontWeight: 800, fontSize: 14 }}><NameBadge name={p.name} verified={p.verified} custom={p.custom_badge} size={12} /></div>
                <div style={{ fontSize: 12, color: 'rgba(255,255,255,0.6)' }}>@{p.username}</div>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
  return ReactDOM.createPortal(sheet, document.body);
}

function ResetPasswordScreen({ onDone }) {
  const { theme } = useTheme();
  const [pw, setPw] = useState('');
  const [pw2, setPw2] = useState('');
  const [err, setErr] = useState('');
  const [loading, setLoading] = useState(false);
  const [done, setDone] = useState(false);
  const okPw = pw.length >= 6 && pw === pw2;
  const submit = async () => {
    if (!okPw || loading) return;
    setLoading(true); setErr('');
    const { error } = await setPassword(pw);
    setLoading(false);
    if (error) { setErr(friendlyError(error, "Couldn't update your password. Try again.")); return; }
    setDone(true);
    setTimeout(onDone, 1400);
  };
  if (done) {
    return (
      <AuthShell>
        <AuthArt kind="lock" height={180} />
        <AuthTitle title="All set" sub="Your new password is saved. Taking you in." />
      </AuthShell>
    );
  }
  return (
    <AuthShell>
      <AuthArt kind="lock" height={180} />
      <AuthTitle title="New password" sub="Pick something you have not used before. 6 or more characters." />
      <PasswordInput value={pw} onChange={setPw} placeholder="New password" autoComplete="new-password" style={{ marginBottom: 10 }} />
      <PasswordInput value={pw2} onChange={setPw2} placeholder="Type it again" ariaLabel="Confirm new password" autoComplete="new-password" onEnter={submit} />
      {pw2 && pw !== pw2 && <div style={{ color: AUTH_C.danger, fontSize: 13.5, marginTop: 10, fontWeight: 600, fontFamily: AUTH_FONT }}>The two passwords are not the same</div>}
      <AuthError text={err} />
      <button type="button" style={authPrimaryStyle(theme, !okPw || loading, { marginTop: 16 })} disabled={!okPw || loading} onClick={submit}>
        {loading ? <Spinner /> : 'Save password'}
      </button>
    </AuthShell>
  );
}

function AppInner() {
  const bootRef = useRef(undefined);
  if (bootRef.current === undefined) bootRef.current = bootStoredSession() || null;
  const [session, setSession] = useState(bootRef.current || undefined);
  const [screen, setScreen] = useState('login');
  const [addingAccount, setAddingAccount] = useState(false);
  const addReturnRef = useRef(null);
  const [regStage, setRegStage] = useState(null);
  const authPushedRef = useRef(false);
  const authBackRef = useRef(null);
  const [needsProfile, setNeedsProfile] = useState(false);
  const [isPasswordRecovery, setIsPasswordRecovery] = useState(false);
  const [switchingAccountId, setSwitchingAccountId] = useState(null);
  const [registering, setRegistering] = useState(false);
  const [mfaGate, setMfaGate] = useState(() => (bootRef.current ? { uid: bootRef.current.user.id, state: localMfaState(bootRef.current) } : { uid: null, state: 'checking' }));
  const [shareLanding, setShareLanding] = useState(() => parseShareLanding());
  const [authRequested, setAuthRequested] = useState(false);
  const [authNote, setAuthNote] = useState('');

  useEffect(() => { if (session) setShareLanding(null); }, [!!session]);

  useEffect(() => {
    if (!session || needsProfile || registering) return;
    try {
      const raw = localStorage.getItem('zchat-pending-link');
      if (!raw) return;
      localStorage.removeItem('zchat-pending-link');
      const saved = JSON.parse(raw);
      if (!saved || !saved.search || Date.now() - Number(saved.at || 0) > 86400000) return;
      const cur = new URLSearchParams(window.location.search);
      if (['join', 'post', 'profile', 'story'].some((k) => cur.get(k))) return;
      window.history.replaceState(window.history.state, '', `${window.location.pathname}${saved.search}`);
    } catch {}
  }, [session && session.user && session.user.id, needsProfile, registering]);

  useEffect(() => {
    const uid = session && session.user ? session.user.id : null;
    if (!uid) return undefined;
    let alive = true;
    const slow = setTimeout(() => {
      if (alive) setMfaGate((prev) => (prev.uid === uid && prev.state !== 'checking' ? prev : { uid, state: localMfaState(session) }));
    }, 2500);
    (async () => {
      let next = 'clear';
      try {
        const mfa = supabase.auth && supabase.auth.mfa;
        if (mfa && mfa.getAuthenticatorAssuranceLevel) {
          const { data, error } = await mfa.getAuthenticatorAssuranceLevel();
          if (!error && data && data.nextLevel === 'aal2' && data.currentLevel !== 'aal2') next = 'need';
          else if (error) next = localMfaState(session);
        }
      } catch { next = localMfaState(session); }
      clearTimeout(slow);
      if (alive) setMfaGate((prev) => (prev.uid === uid && prev.state === next ? prev : { uid, state: next }));
    })();
    return () => { alive = false; };
  }, [session && session.user && session.user.id, session && session.access_token]);

  useEffect(() => {
    if (window.location.hash.includes('type=recovery')) setIsPasswordRecovery(true);
    let hasStoredLogin = false;
    try { hasStoredLogin = Object.keys(localStorage).some((k) => /^sb-.*-auth-token$/.test(k)); } catch {}
    let forgetting = false;
    try {
      const beat = Number(localStorage.getItem('zchat-live-beat') || 0);
      const viaLink = /access_token|type=recovery/.test(window.location.hash) || /[?&]code=/.test(window.location.search);
      forgetting = localStorage.getItem('zchat-remember') === '0' && !sessionStorage.getItem('zchat-live') && !(Date.now() - beat < 90000) && !viaLink;
    } catch {}
    const pause = (ms) => new Promise((r) => setTimeout(r, ms));
    if (!forgetting && typeof navigator !== 'undefined' && navigator.onLine === false) {
      const storedNow = readStoredAuth();
      if (storedNow) setSession((prev) => (prev === undefined ? storedNow : prev));
    }
    (async () => {
      if (forgetting) {
        try {
          const r = await getSession();
          const s = r && r.user ? r : (r && r.data ? r.data.session : null);
          if (s && s.user) {
            try { localStorage.removeItem(`zchat-session-${s.user.id}`); } catch {}
            removeAccountEntry(s.user.id);
            await supabase.auth.signOut({ scope: 'local' });
          }
        } catch {}
        forgetting = false;
        setSession((prev) => (prev === undefined ? null : prev));
        return;
      }
      let found = null;
      for (let attempt = 0; attempt < (hasStoredLogin && !(typeof navigator !== 'undefined' && navigator.onLine === false) ? 4 : 1) && !found; attempt++) {
        if (attempt > 0) await pause(1200 * attempt);
        try {
          const r = await getSession();
          found = r && r.user ? r : (r && r.data && r.data.session ? r.data.session : null);
        } catch {}
        if (!found && hasStoredLogin) {
          try {
            const r = await supabase.auth.refreshSession();
            found = r && r.data && r.data.session ? r.data.session : null;
          } catch {}
        }
      }
      setSession((prev) => (found || (prev === undefined ? null : prev)));
    })();
    const unstickTimer = setTimeout(() => {
      setSession((prev) => (prev === undefined ? null : prev));
    }, hasStoredLogin ? 25000 : 10000);
    const { data: listener } = supabase.auth.onAuthStateChange((event, sess) => {
      if (forgetting) return;
      if (event === 'PASSWORD_RECOVERY') setIsPasswordRecovery(true);
      if (event === 'SIGNED_OUT') { setSession(null); return; }
      if (!sess) {
        supabase.auth.refreshSession()
          .then(({ data }) => { if (data && data.session) setSession(data.session); })
          .catch(() => {});
        return;
      }
      setSession(sess);
    });
    return () => { clearTimeout(unstickTimer); listener.subscription.unsubscribe(); };
  }, []);

  useEffect(() => {
    if (session?.user) {
      getProfile(session.user.id).then(({ data }) => {
        if (data) saveAccountEntry({ id: session.user.id, name: data.name, avatar: data.avatar, email: session.user.email, verified: data.verified || null });
      });
    }
  }, [session?.user?.id]);

  const handleAddAccount = () => {
    addReturnRef.current = session;
    setAddingAccount(true);
    setSession(null);
    setScreen('login');
  };
  const cancelAddAccount = () => {
    const back = addReturnRef.current;
    addReturnRef.current = null;
    setAddingAccount(false);
    setScreen('login');
    if (back) setSession(back);
  };
  useEffect(() => { if (session && addingAccount) { addReturnRef.current = null; setAddingAccount(false); } }, [session]);

  const handleSwitchAccount = async (account) => {
    setSwitchingAccountId(account.id);
    const previousUserId = session?.user?.id;
    const savedSessionRaw = (() => { try { return localStorage.getItem(`zchat-session-${account.id}`); } catch { return null; } })();
    if (savedSessionRaw) {
      try {
        const savedSession = JSON.parse(savedSessionRaw);
        const { data, error } = await supabase.auth.setSession({ access_token: savedSession.access_token, refresh_token: savedSession.refresh_token });
        if (!error && data.session) { setSession(data.session); setSwitchingAccountId(null); return; }
      } catch {}
    }
    setSwitchingAccountId(null);
    if (previousUserId && previousUserId !== account.id) {
      const previousRaw = (() => { try { return localStorage.getItem(`zchat-session-${previousUserId}`); } catch { return null; } })();
      if (previousRaw) {
        try {
          const previousSaved = JSON.parse(previousRaw);
          const { data, error } = await supabase.auth.setSession({ access_token: previousSaved.access_token, refresh_token: previousSaved.refresh_token });
          if (!error && data.session) {
            setSession(data.session);
            appAlert("That account's saved session expired. Remove it and sign in again to reconnect it. You're still on your current account.");
            return;
          }
        } catch {}
      }
    }
    appAlert("Couldn't switch to that account automatically. Please sign in again.");
    setSession(null);
    setScreen('login');
  };

  useEffect(() => {
    if (session?.user) {
      try {
        if (localStorage.getItem('zchat-remember') === '0') localStorage.removeItem(`zchat-session-${session.user.id}`);
        else localStorage.setItem(`zchat-session-${session.user.id}`, JSON.stringify({ access_token: session.access_token, refresh_token: session.refresh_token }));
      } catch {}
    }
  }, [session?.access_token]);

  useEffect(() => {
    if (!session) return undefined;
    let off = false;
    try { off = localStorage.getItem('zchat-remember') === '0'; } catch {}
    if (!off) return undefined;
    const beat = () => { try { localStorage.setItem('zchat-live-beat', String(Date.now())); sessionStorage.setItem('zchat-live', '1'); } catch {} };
    beat();
    const t = setInterval(beat, 20000);
    return () => clearInterval(t);
  }, [session && session.user && session.user.id]);

  const handleRemoveAccount = (id) => {
    removeAccountEntry(id);
    try { localStorage.removeItem(`zchat-session-${id}`); } catch {}
    forgetLocalUser(id);
  };

  const handleLogout = async () => {
    if (session?.user) { try { localStorage.removeItem(`zchat-session-${session.user.id}`); } catch {} removeAccountEntry(session.user.id); forgetLocalUser(session.user.id); }
    await signOut();
    setSession(null);
    setScreen('login');
  };

  const leaveAuth = () => {
    if (shareLanding && authRequested) { setAuthRequested(false); setAuthNote(''); return; }
    setScreen('login');
  };
  const authBackFn = registering ? 'block' : screen === 'forgot' ? () => setScreen('login') : (shareLanding && authRequested) ? leaveAuth : screen === 'register' ? () => setScreen('login') : (addingAccount && screen === 'login') ? cancelAddAccount : null;
  const onAuthPage = !session && !needsProfile && (screen !== 'login' || !!(shareLanding && authRequested) || addingAccount);
  authBackRef.current = onAuthPage || registering ? authBackFn : null;
  useEffect(() => {
    if (session && !registering) return undefined;
    const onPop = () => {
      if (navCtl.silent > 0) { navCtl.silent -= 1; return; }
      const fn = authBackRef.current;
      authPushedRef.current = false;
      if (fn === 'block') { try { window.history.pushState({ zauth: 1 }, ''); authPushedRef.current = true; } catch {} return; }
      if (typeof fn === 'function') fn();
    };
    window.addEventListener('popstate', onPop);
    return () => window.removeEventListener('popstate', onPop);
  }, [!!session && !registering]);
  useEffect(() => {
    if (onAuthPage || registering) {
      if (authPushedRef.current) return;
      try { window.history.pushState({ zauth: 1 }, ''); authPushedRef.current = true; } catch {}
      return;
    }
    if (authPushedRef.current && !session) {
      authPushedRef.current = false;
      navCtl.silent += 1;
      try { window.history.back(); } catch { navCtl.silent = Math.max(0, navCtl.silent - 1); }
    }
  }, [onAuthPage, registering, screen]);
  const uiAuthBack = (fn) => {
    if (!fn || fn === 'block') return null;
    return () => {
      if (authPushedRef.current) { try { window.history.back(); return; } catch {} }
      fn();
    };
  };

  if (isPasswordRecovery) {
    return <ResetPasswordScreen onDone={() => { setIsPasswordRecovery(false); window.location.hash = ''; }} />;
  }

  if (session === undefined) return <BootScreen />;

  if (!session || needsProfile || registering) {
    if (needsProfile) {
      const isGoogleUser = ['google', 'apple'].includes(session?.user?.app_metadata?.provider);
      const leave = () => { setRegistering(false); setNeedsProfile(false); supabase.auth.signOut(); setSession(null); setScreen('login'); };
      const canLeave = regStage === 'email' || regStage === 'otp' || (isGoogleUser && regStage === 'username');
      return (
        <AuthShell onBack={canLeave ? leave : null}>
          <RegisterFlow
            initialStage={isGoogleUser ? 'username' : 'email'}
            onStageChange={setRegStage}
            onStart={() => setRegistering(true)}
            onDone={() => { setRegistering(false); setNeedsProfile(false); }}
            onBack={leave}
          />
        </AuthShell>
      );
    }
    if (!session && !registering && shareLanding && !authRequested) {
      return (
        <SharePreviewScreen landing={shareLanding} onAuth={(mode, note) => {
          stashPendingLink();
          setAuthNote(note || '');
          setScreen(mode === 'register' ? 'register' : 'login');
          setAuthRequested(true);
        }} />
      );
    }
    const shownScreen = screen;
    return (
      <AuthShell onBack={uiAuthBack(authBackFn)} top={shownScreen === 'login' ? <AuthBrand /> : null}>
        {shareLanding && authNote && shownScreen === 'login' && (
          <div style={{ background: '#EEF2F7', color: AUTH_C.navy, borderRadius: 14, padding: '11px 14px', fontSize: 13.5, fontWeight: 600, marginBottom: 14, fontFamily: AUTH_FONT }}>{authNote}</div>
        )}
        {shownScreen === 'login' && (
          <LoginStep onSuccess={setSession} onForgot={() => setScreen('forgot')} onGoRegister={() => setScreen('register')} />
        )}
        {shownScreen === 'forgot' && <ForgotStep onBack={() => setScreen('login')} />}
        {shownScreen === 'register' && (
          <RegisterFlow onStageChange={setRegStage} onStart={() => setRegistering(true)} onDone={() => { setRegistering(false); setScreen('login'); }} onBack={() => setScreen('login')} />
        )}
      </AuthShell>
    );
  }

  const mfaState = mfaGate.uid === session.user.id ? mfaGate.state : 'checking';
  if (mfaState === 'checking') return <BootScreen />;
  if (mfaState === 'need') {
    return <MfaChallengeScreen onPassed={() => setMfaGate({ uid: session.user.id, state: 'clear' })} onCancel={handleLogout} />;
  }

  return (
    <ChatApp
      key={session.user.id}
      session={session}
      onLogout={handleLogout}
      onNeedsProfile={() => setNeedsProfile(true)}
      savedAccounts={getSavedAccounts()}
      onSwitchAccount={handleSwitchAccount}
      onAddAccount={handleAddAccount}
      onRemoveAccount={handleRemoveAccount}
      switchingAccountId={switchingAccountId}
    />
  );
}

